window.ACUPOINTS = {"category":"acupoints","title":"Huyệt vị – Châm cứu","labels":{"noiDung":"Mô tả huyệt","phoiHuyet":"Phối huyệt","ghiChu":"Ghi chú","thamKhao":"Tham khảo"},"count":1058,"records":[{"id":1,"ten":"A Thị Huyệt","sections":[{"h":"VỊ TRÍ","body":"Huyệt không có vị trí nhất định, có thể nằm trên hoặc ngoài đường kinh."},{"h":"CHỦ TRỊ","body":"Thông kinh, hoạt lạc, làm máu huyết lưu thông, sơ thông kinh khí, giảm đau cục bộ."},{"h":"CHÂM CỨU","body":"Tùy vị trí từng huyệt."}]},{"id":2,"ten":"Á Huyệt 1","sections":[{"h":"VỊ TRÍ","body":"Giữa huyệt Nhân Nghênh (Vi 9) và Thủy Đột (Vi 10), hơi chếch ra ngoài 0,2 thốn."},{"h":"CHỦ TRỊ","body":"Trị câm, bệnh ở thanh đới."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 thốn, tránh động mạch cổ."}]},{"id":3,"ten":"Á Huyệt 2","sections":[{"h":"VỊ TRÍ","body":"Ở phía sau gáy, trên huyệt Phong Trì (Đ 20) khoảng 0,4 thốn."},{"h":"CHỦ TRỊ","body":"Trị câm, bệnh ở thanh đới."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 1,5 thốn.,=\nY"}]},{"id":4,"ten":"Á Minh","sections":[{"h":"VỊ TRÍ","body":"Ở phía trước huyệt Phong Trì (Đ 20) khoảng 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị câm, điếc, họng viêm, thanh quản viêm."},{"h":"CHÂM CỨU","body":"Châm sâu 1 – 1,5 thốn, hướng mũi kim về phía chóp mũi."}]},{"id":5,"ten":"Á Môn","sections":[{"h":"VỊ TRÍ","body":"Nếu có chân tóc gáy, lấy huyệt ở chỗ lõm giữa gáy và trên chân tóc 0,5 thốn. Nếu không có chân tóc gáy, huyệt ở chỗ lõm giữa gáy, dưới huyệt Phong Phủ 0,5 thốn. Phía dưới mỏm gai của đốt sống cổ 1."},{"h":"CHỦ TRỊ","body":"Trị vùng gáy đau, cột sống cứng đau, chảy máu mũi không cầm, điên cuồng, mất tiếng đột ngột, câm, lưỡi cứng, lưỡi rụt, lưỡi teo, nói không rõ tiếng."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,3 – 2 thốn. Mũi kim hướng tới phía miệng của người bệnh, ngang với trái tai. Không cứu."},{"h":"GIẢI PHẪU","body":"Dưới da là gân cơ thang, cơ bán gai hoặc cơ rối to, cơ thẳng sau đầu to, màng đội trục sau, ống sống. Thần kinh vận động cơ do ngành sau của 3 dây thần kinh sống cổ trên và nhánh của dây thần kinh sọ não số XI."}]},{"id":6,"ten":"Ách Nghịch","sections":[{"h":"VỊ TRÍ","body":"Tại giao điểm của đường thẳng từ núm vú xuống với đường ngang giữa xương sườn 7."},{"h":"CHỦ TRỊ","body":"Trị nấc cụt, cơ hoành co thắt, ngực đau."},{"h":"CHÂM CỨU","body":"Châm xiên, sâu 0,3 – 0,7 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."}]},{"id":7,"ten":"An Miên 1","sections":[{"h":"VỊ TRÍ","body":"Tại điểm giữa đường nối huyệt Ế Phong và Ế Minh."},{"h":"CHỦ TRỊ","body":"Trị mất ngủ, chóng mặt, nửa đầu đau, tai ù, tâm thần phân liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 1,5 thốn."}]},{"id":8,"ten":"An Miên 2","sections":[{"h":"VỊ TRÍ","body":"Tại điểm giữa đường nối huyệt Phong Trì (Đ 20) và Ế Minh."},{"h":"CHỦ TRỊ","body":"Trị mất ngủ, hồi hộp, huyết áp cao, tâm thần phân liệt, Hysteria."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 1,5 thốn."}]},{"id":9,"ten":"An Miên 3","sections":[{"h":"VỊ TRÍ","body":"Khe giữa đốt sống lưng 7 – 8 ra ngang 2 thốn (tức từ huyệt Cách Du [Bq 17] ra 0,5 thốn)"},{"h":"CHỦ TRỊ","body":"Trị mất ngủ, phiền muộn."},{"h":"CHÂM CỨU","body":"Châm xiên, sâu 0,5 – 1 thốn."}]},{"id":10,"ten":"An Miên 4","sections":[{"h":"VỊ TRÍ","body":"Đỉnh mắt cá chân trong lên 4,5 thốn (tức từ huyệt Tam Âm Giao [Ty 6] lên 1,5 thốn)"},{"h":"CHỦ TRỊ","body":"Trị mất ngủ, phiền muộn."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1,5 – 2 thốn."}]},{"id":11,"ten":"Áp Huyết Điểm","sections":[{"h":"VỊ TRÍ","body":"Dưới huyệt Túc Tam Lý 1,5 thốn, giữa huyệt Túc Tam Lý (Vi 36) và huyệt Thượng Cự Hư (Vi 37)"},{"h":"CHỦ TRỊ","body":"Trị huyết áp cao."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 1,5 thốn."}]},{"id":12,"ten":"Âm Bao","sections":[{"h":"VỊ TRÍ","body":"Ở cách lồi cầu trên trong xương đùi 4 thốn, hoặc từ huyệt Khúc Tuyền (C 8) đo lên 4 thốn, giữa cơ rộng trong và cơ may."},{"h":"CHỦ TRỊ","body":"Trị thắt lưng đau, cơ đùi trong viêm, bụng dưới đau, kinh nguyệt không đều, tiểu khó."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa cơ may và cơ thẳng trong, cơ khép lớn, cơ rộng trong, mặt trong xương đùi.\nThần kinh vận động cơ là các nhánh của dây thần kinh đùi để các nhánh của dây thần kinh bịt.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L3."}]},{"id":13,"ten":"Âm Biên","sections":[{"h":"VỊ TRÍ","body":"Bờ dưới xương mu ra 0,5 thốn (tức từ huyệt Long Môn ra 0,5 thốn)"},{"h":"CHỦ TRỊ","body":"Trị chức năng của bàng quang bị rối loạn do di chứng bại liệt."},{"h":"CHÂM CỨU","body":"Châm xiên hướng đến giữa xương mu, sâu 0,5 – 1 thốn."}]},{"id":14,"ten":"Âm Cốc","sections":[{"h":"VỊ TRÍ","body":"Ngồi thõng chân hoặc hơi co gối để nổi gân lên, huyệt ở đầu trong nếp gấp nhượng chân, sau lồi cầu trong xương chầy, trong khe của gân cơ bán gân (gân chắc, nhỏ) và gân cơ bán mạc (gân mềm, lớn hơn, nằm ở trên)"},{"h":"CHỦ TRỊ","body":"Trị khớp gối viêm, mặt trong khớp gối sưng đau, vùng bụng dưới đau, tiểu gắt, tiểu buốt, băng lậu, liệt dương, thoát vị."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 1,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa gân cơ bán gân và gân cơ bán mạc, đầu trên cơ sinh đôi trong, khe khớp nhượng chân.\nThần kinh vận động cơ là các nhánh của dây thần kinh hông và dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh"}]},{"id":15,"ten":"Âm Dương","sections":[{"h":"VỊ TRÍ","body":"Hơi gấp ngón chân cái lại, huyệt ở 2 bên lằn chỉ khớp 1, giáp ranh da thịt trắng – đỏ."},{"h":"CHỦ TRỊ","body":"Trị bạch đới, rong kinh."},{"h":"CHÂM CỨU","body":"Cứu 5 – 10 phút."}]},{"id":16,"ten":"Âm Đô","sections":[{"h":"VỊ TRÍ","body":"Trên rốn 4 thốn, cách tuyến giữa bụng 0,5 thốn, ngang huyệt Trung Quản (Nh 12)"},{"h":"CHỦ TRỊ","body":"Trị bụng đau, bụng sôi, bụng đầy tức, hông sườn đau nóng."},{"h":"CHÂM CỨU","body":"Châm thẳng, 1 – 1,5 thốn. Cứu 5 – 7 tráng – Ôn cứu 10 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ chéo to của bụng, bờ trong cơ thẳng to, mạc ngang, phúc mạc, khung tá tràng.\nThần kinh vận động cơ là nhánh thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D8."}]},{"id":17,"ten":"Âm Độc","sections":[{"h":"VỊ TRÍ","body":"Trên kẽ ngón chân thứ 4 và 5, dưới huyệt Hiệp Khê 0,5 thốn, ngay dưới huyệt Bát Phong."},{"h":"CHỦ TRỊ","body":"Trị bàn chân sưng đau, kinh nguyệt không đều."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,3 – 0,5 thốn.W\n."}]},{"id":18,"ten":"Âm Giao","sections":[{"h":"VỊ TRÍ","body":"Thẳng dưới lỗ rốn 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị bụng và quanh rốn đau, bệnh hệ sinh dục ngoài, bệnh về kinh nguyệt, đau do thoát vị, tử cung sa."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 1,5 thốn. Cứu 10 – 40 phút."},{"h":"GIẢI PHẪU","body":"Huyệt ở trên đường trắng, sau đường trắng là mạc ngang, phúc mạc. Vào sâu có ruột non hoặc tử cung khi có thai 5 – 6 tháng.\nKhông châm khi có thai."}]},{"id":19,"ten":"Âm Kháng","sections":[{"h":"VỊ TRÍ","body":"Giữa lằn chỉ nếp mông (huyệt Thừa Phò – Bq 36) đo vào trong 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị di chứng bại liệt nơi trẻ nhỏ, thần kinh tọa đau."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 3 thốn. Cứu 5 – 10 phút."}]},{"id":20,"ten":"Âm Khích","sections":[{"h":"VỊ TRÍ","body":"Mặt trước trong cẳng tay, trên nếp gấp cổ tay 0,5 thốn, ở trong khe gân cơ trụ trước và gân cơ gấp chung nông các ngón tay."},{"h":"CHỦ TRỊ","body":"Trị hồi hộp, vùng tim đau, ngực đau, tim đập mạnh, hồi hộp, ra mồ hôi trộm, chảy máu mũi, nôn ra máu."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 0,8 thốn. Cứu 1 – 3 tráng, Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa gân cơ trụ trước và gân cơ gấp chung nông các ngón tay, bờ trong gân cơ gấp chung sâu các ngón tay, cơ sấp vuông, xương trụ.\nThần kinh vận động cơ là các nhánh của dây thần kinh giữa và dây thần kinh trụ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D1. thai nhiều tháng không châm sâu."}]},{"id":21,"ten":"Âm Lăng Tuyền","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm làm thành bởi bờ sau trong đầu trên xương chầy với đường ngang qua nơi lồi cao nhất của củ cơ cẳng chân trước xương chầy, ở mặt trong đầu gối.\nHoặc dùng ngón tay lần theo bờ trong xương ống chân, đến ngay dưới chỗ lồi xương cao nhất, đó là huyệt."},{"h":"CHỦ TRỊ","body":"Trị khớp gối viêm, kinh nguyệt không đều, ruột viêm, di tinh, cổ trướng, tiểu không thông, tiểu dầm."},{"h":"CHÂM CỨU","body":"Châm thẳng (theo mé bờ sau xương ống chân), sâu 1 – 2 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ sau – trong và mặt sau đầu xương chầy, chỗ bám của cơ kheo, dưới chỗ bám của cơ bán mạc, mặt trước cơ sinh đôi trong.\nThần kinh vận động cơ là các nhánh của dây thần kinh chầy sau và nhánh của dây thần kinh hông kheo.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L3."}]},{"id":22,"ten":"Âm Liêm","sections":[{"h":"VỊ TRÍ","body":"Để bệnh nhân ở tư thế nằm ngửa, sờ động mạch nhảy ở bẹn, huyệt nằm sát bờ trong động mạch đùi, hoặc dưới nếp nhăn của bẹn 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị thần kinh đùi đau, vùng thắt lưng và đùi đau, mặt trong đùi đau, chi dưới liệt, kinh nguyệt rối loạn, phụ nữ không con."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 2 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa cơ lược và cơ khép nhỡ, cơ khép bé và các cơ bịt.\nThần kinh vận động cơ là các nhánh của dây thần kinh bịt.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L2."}]},{"id":23,"ten":"Yêu Thống III","sections":[{"h":"VỊ TRÍ","body":"Ở lưng bàn tay, nơi giao tiếp của xương bàn tay 4 và 5."},{"h":"CHỦ TRỊ","body":"Trị chấn thương ở tứ chi, vùng thắt lưng."},{"h":"CHÂM CỨU","body":"Châm xiên tới phía khớp cổ tay, sâu 1 – 1,5 thốn."}]},{"id":24,"ten":"Âm Nang Phùng","sections":[{"h":"VỊ TRÍ","body":"Tại chính giữa nếp dưới âm nang."},{"h":"CHỦ TRỊ","body":"Trị điên cuồng."},{"h":"CHÂM CỨU","body":"Cứu."}]},{"id":25,"ten":"Âm Thị","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm trên góc trên ngoài xương bánh chè 3 thốn, sát bờ ngoài gân cơ thẳng trước đùi."},{"h":"CHỦ TRỊ","body":"Trị chi dưới liệt, khớp gối viêm, hàn sán."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 1 thốn, cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa cơ thẳng trước và cơ rộng ngoài, cơ rộng giữa, xương đùi.\nThần kinh vận động cơ là các nhánh của dây thần kinh đùi.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L3.d\tZ+CM92"}]},{"id":26,"ten":"Âm Trì","sections":[{"h":"VỊ TRÍ","body":"Giữa nếp gấp cổ tay (huyệt Đại Lăng – Tb.7), đo xuống 1 thốn (Nội Dương Trì) rồi đo ngang 1 thốn, về phía ngón tay cái."},{"h":"CHỦ TRỊ","body":"Trị ho ra máu, khan tiếng, họng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 thốn. Cứu 3 – 5 tráng."}]},{"id":27,"ten":"Âm Ủy 1","sections":[{"h":"VỊ TRÍ","body":"Mặt ngoài cẳng chân, phía ngoài nếp gấp nhượng chân đo lên 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị liệt do Hysteria, bệnh tâm thần."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 2 – 3 thốn."}]},{"id":28,"ten":"Âm Ủy 2","sections":[{"h":"VỊ TRÍ","body":"Mặt ngoài cẳng chân, phía ngoài nếp gấp nhượng chân đo lên 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị liệt do Hysteria, bệnh tâm thần."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 2 – 3 thốn."}]},{"id":29,"ten":"Âm Ủy 3","sections":[{"h":"VỊ TRÍ","body":"Mặt ngoài cẳng chân, phía ngoài nếp gấp nhượng chân đo lên 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị liệt do Hysteria, bệnh tâm thần."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 2 – 3 thốn."}]},{"id":30,"ten":"Ẩm Khích","sections":[{"h":"VỊ TRÍ","body":"Tại thực môn (Ngoại Đài Bí Yếu).\nDưới khe xương khích trung (chấn thủy) 1 thốn (Châm cứu Khổng Huyệt Cập Kỳ Liệu Pháp Tiện Lãm).\nGiữa khe sườn thứ 6 đo ngang ra 6 thốn (Châm cứu Học Từ Điển)"},{"h":"CHỦ TRỊ","body":"Trị bụng đầy, bụng sôi, bụng kêu, bụng óc ách nước, bụng đau lan đến quanh rốn, ngực và sườn đau, phế viêm, màng ngực viêm, đau do Can phong."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,3 – 0,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút.?\n.'\nE"}]},{"id":31,"ten":"Ân Hạ","sections":[{"h":"VỊ TRÍ","body":"Tại trung điểm của đường nối 2 huyệt Thừa Phò (Bq 36) và Ủy Trung (Bq 40)"},{"h":"CHỦ TRỊ","body":"Trị thần kinh tọa đau, chi dưới liệt, vai lưng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 3 thốn."}]},{"id":32,"ten":"Ân Môn","sections":[{"h":"VỊ TRÍ","body":"Dưới nếp mông 6 thốn, mặt sau xương đùi, điểm giữa khe của cơ bám gân và cơ nhị đầu đùi."},{"h":"CHỦ TRỊ","body":"Trị lưng và đùi đau, thoát vị đĩa đệm, chi dưới liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 1,5 thốn. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ trong cơ 2 đầu đùi, bờ ngoài cơ bán gân và cơ bán mạc, cơ khép lớn, mặt sau đùi.\nThần kinh vận động cơ là các nhánh của dây thần kinh hông và nhánh của dây thần kinh bịt.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S2."}]},{"id":33,"ten":"Ân Thượng","sections":[{"h":"VỊ TRÍ","body":"Dưới nếp mông 4 thốn, mặt sau xương đùi, trên huyệt Ân Môn 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, thắt lưng đau lan xuống đùi, thần kinh tọa đau."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 3 thốn."}]},{"id":34,"ten":"Ẩn Bạch","sections":[{"h":"VỊ TRÍ","body":"Ở góc trong móng ngón chân cái, cách chân móng 1mm."},{"h":"CHỦ TRỊ","body":"Trị bụng trướng, mất ngủ, mộng mị, động kinh, điên cuồng, kinh nguyệt rối loạn, ngất [dùng cứu] (Châm cứu Nhật Bản)"},{"h":"CHÂM CỨU","body":"Châm xiên, sâu 0,1 – 0,2 thốn hoặc châm nặn ra máu. Cứu 3 – 7 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là xương đốt 2 ngón chân cái.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5."}]},{"id":35,"ten":"Ấn Đường","sections":[{"h":"VỊ TRÍ","body":"Tại chính giữa đường nối 2 đầu lông mày và đường thẳng giữa sống mũi."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, mũi nghẹt, cảm, động kinh, sốt cao co giật, chóng mặt, ói mửa, mất ngủ, xoang mũi viêm, chảy máu cam, mắt đau, xương chân mày đau,"},{"h":"CHÂM CỨU","body":"Châm xiên từ trên xuống. Khi châm, bóp 2 bên huyệt Toàn Trúc lại để châm xuống hoặc hướng kim về bên phải hoặc trái hoặc xuyên thẳng xuống huyệt Tinh Minh. Hoặc châm nặn máu. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là chỗ bám của 2 cơ tháp, chỗ tiếp khớp của 2 xương sống mũi và xương trán.\nThần kinh vận động cơ là nhánh của dây thần kinh mặt.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số\n!"}]},{"id":36,"ten":"Bá Hội Thập Tự Thích","sections":[{"h":"VỊ TRÍ","body":"Từ huyệt Tiền Đỉnh đến huyệt Bá hội là một huyệt. Từ huyệt Cường gian qua Hậu đỉnh đến Bá hội là một huyệt. Hai bên huyệt Chính dinh đến Bá hội là hai huyệt. Các huyệt trên lập thành 1 nhóm huyệt và xếp thành hình giống cây thập tự ngang qua huyệt Bá hội, vì vậy được gọi là Bá Hội Thập Tự."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, thần kinh suy nhược, động kinh, trực trường sa."},{"h":"CHÂM CỨU","body":"Châm từ huyệt Tiền đỉnh, luồn theo da đến huyệt Bá hội. Từ huyệt Cường gian châm luồn theo da, qua huyệt Hậu đỉnh đến huyệt Bá Hội. Từ huyệt Chính dinh, châm luồn da đến huyệt Bá hội."}]},{"id":37,"ten":"Bách Chủng Phong","sections":[{"h":"VỊ TRÍ","body":"Khe đốt sống cổ 7 và đốt sống lưng 1 (C7–D1, tức là huyệt Đại Chùy) ra ngang mỗi bên 2,3 thốn."},{"h":"CHỦ TRỊ","body":"Trị trúng phong, phong ngứa, mề đay, vai và cánh tay đau."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 1 thốn."}]},{"id":38,"ten":"Bách Hội","sections":[{"h":"VỊ TRÍ","body":"Gấp 2 vành tai về phía trước, huyệt ở điểm gặp nhau của đường thẳng dọc giữa đầu và đường ngang qua đỉnh vành tai, sờ vào đó thấy 1 khe xương lõm xuống."},{"h":"CHỦ TRỊ","body":"Trị đỉnh đầu nhức, trực tràng sa, mũi nghẹt, đầu nặng, hay quên, điên cuồng, hôn mê, lạnh người, tai ù, mắt hoa, hồi hộp, mất ngủ."},{"h":"CHÂM CỨU","body":"Châm luồn kim dưới da, sâu 0,2 – 1 thốn. Cứu 10 – 20 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân sọ, dưới cân sọ là xương sọ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C2."}]},{"id":39,"ten":"Bách Lao","sections":[{"h":"VỊ TRÍ","body":"Khe đốt sống cổ 7 và đốt sống lưng 1 (C7 – D1, tức là huyệt Đại Chùy) đo lên 2 thốn rồi đo ngang mỗi bên 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị cổ vẹo, gáy cứng đau, lao hạch cổ, lao phổi, thần kinh suy nhược.:q\nFY"}]},{"id":40,"ten":"Bách Trùng Sào","sections":[{"h":"VỊ TRÍ","body":"Tại chỗ lõm trên góc trong bờ xương bánh chè lên 3 thốn (tức là huyệt Huyết Hải lên 1 thốn)"},{"h":"CHỦ TRỊ","body":"Trị phong thấp, ngứa, mề đay, thấp chẩn, lở ngứa ở hạ bộ."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 2 – 3 thốn."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa cơ may và cơ rộng trong, cơ rộng giữa, xương đùi.\nThần kinh vận động cơ là các nhánh của dây thần kinh đùi.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L3."}]},{"id":41,"ten":"Bách Tức","sections":[{"h":"VỊ TRÍ","body":"Ở mu bàn chân, giữa ngón cái, từ đỉnh móng đo lên 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị động kinh, túi mật viêm, trong bụng khó chịu."},{"h":"CHÂM CỨU","body":"Châm xiên, sâu 0,1 – 0,2 thốn."}]},{"id":42,"ten":"Bạch Hoàn Du","sections":[{"h":"VỊ TRÍ","body":"Ngang đốt xương thiêng 4, cách tuyến giữa lưng 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị kinh nguyệt không đều, khí hư, thoát vị ruột, sa trực tràng, vùng thắt lưng đau, háng sưng, thần kinh tọa đau."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 1,5 thốn."},{"h":"GIẢI PHẪU","body":"Dưới da là cân của cơ lưng to, chỗ bám của cơ mông to, phía ngoài khối cơ chung của các cơ ở rãnh cột sống, xương cùng.\nThần kinh vận động cơ là nhánh của đám rối cánh tay, thần kinh mông trên, nhánh dây thần kinh sống cùng 4.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S3 hoặc S4."}]},{"id":43,"ten":"Bản Môn","sections":[{"h":"VỊ TRÍ","body":"Từ huyệt Ngư Tế (P 10) đo vào phía trong 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị suyễn, amiđan viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,3 – 0,5 thốn."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ ngoài cơ dạng ngắn ngón tay cái, cơ đốt ngón tay cái, bó ngoài cơ gấp ngắn ngón tay cái, xương bàn tay 1.\nThần kinh vận động cơ là các nhánh của dây thần kinh giữa.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C6.1\n x;2"}]},{"id":44,"ten":"Bản Thần","sections":[{"h":"VỊ TRÍ","body":"Trong chân tóc 0,5 thốn, từ khóe mắt ngoài kéo lên chân tóc."},{"h":"CHỦ TRỊ","body":"Trị động kinh, cơ gáy cứng."},{"h":"CHÂM CỨU","body":"Châm xiên dưới da, sâu 0,3 – 0,5 thốn. Cứu 1 – 3 tráng. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là chỗ cơ trán dính vào cân sọ, xương trán.\nThần kinh vận động cơ là nhánh dây thần kinh mặt.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V."}]},{"id":45,"ten":"Bàng Cốc","sections":[{"h":"VỊ TRÍ","body":"Ở mu bàn chân, từ khe ngón chân 3 – 4 đo lên 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị di chứng bại liệt nơi trẻ nhỏ."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,3 – 0,4 thốn."}]},{"id":46,"ten":"Bàng Đình","sections":[{"h":"VỊ TRÍ","body":"Vú đo ngang ra 2 thốn, tại kẽ sườn thứ 4 và 5."},{"h":"CHỦ TRỊ","body":"Trị ngực đau, màng tim viêm, hông sườn đau."},{"h":"CHÂM CỨU","body":"Châm xiên, sâu 0,3 – 0,5 thốn. Cứu 5 – 10 phút./\n,"}]},{"id":47,"ten":"Bàng Hổ","sections":[{"h":"VỊ TRÍ","body":"Tại mu bàn tay, giữa phía sau khe khớp xương 1 – 2 bàn tay của ngón 2 và 3."},{"h":"CHỦ TRỊ","body":"Trị họng viêm, họng đau."},{"h":"CHÂM CỨU","body":"Cứu 5 – 10 phút."}]},{"id":48,"ten":"Bàng Lao Cung","sections":[{"h":"VỊ TRÍ","body":"Từ huyệt Lao Cung (Tb.8) ra ngang về phía ngón tay út khoảng 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị amiđan viêm, răng đau, ngón tay tê."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,3 – 0,5 thốn.E\n(d"}]},{"id":49,"ten":"Bàng Liêm Tuyền","sections":[{"h":"VỊ TRÍ","body":"Huyệt Liêm Tuyền (Nh 23) ở giữa cổ ra ngang 2 bên 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị bệnh ở thanh đới, lưỡi sưng."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 1 thốn."}]},{"id":50,"ten":"Bàng Quang Du","sections":[{"h":"VỊ TRÍ","body":"Ngang đốt xương thiêng 2, cách 1,5 thốn, chỗ lõm giữa gai chậu sau và xương cùng."},{"h":"CHỦ TRỊ","body":"Trị vùng thắt lưng và xương cùng đau, tiểu dầm, bệnh về đường tiểu."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 1,5 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân của cơ lưng to, khối cơ chung của các cơ ở rãnh cột sống xương cùng 2.\nThần kinh vận động cơ là nhánh của đám rối cánh tay, nhánh của dây thần kinh sống cùng 2.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S1 và S2."}]},{"id":51,"ten":"Bào Hoang","sections":[{"h":"VỊ TRÍ","body":"Tại điểm gặp nhau của đường ngang qua đầu mỏm gai đốt sống cùng 2, cách mạch Đốc 3 thốn, cách Khí Hải Du 1,5 thốn, nơi cơ mông to."},{"h":"CHỦ TRỊ","body":"Trị lưng đau, thắt lưng đau, vùng xương cùng đau, ruột viêm, tiểu bí, vùng bụng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 1,5 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ mông to, bờ dưới cơ mông nhỡ, bờ trên cơ tháp, bờ ngoài chỗ bám cân cơ lưng to.\nThần kinh vận động cơ là các nhánh của dây thần kinh mông trên và dây thần kinh mông dưới, nhánh của đám rối cùng, nhánh của đám rối cánh tay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L3."}]},{"id":52,"ten":"Bát Chùy Hạ","sections":[{"h":"VỊ TRÍ","body":"Khe giữa đốt sống lưng 8 – 9 (D8–D9)"},{"h":"CHỦ TRỊ","body":"Trị sốt rét, thần kinh sườn đau, tiểu đường, gan viêm."},{"h":"CHÂM CỨU","body":"Châm xiên, sâu 0,5 – 1 thốn."}]},{"id":53,"ten":"Bát Diệu","sections":[{"h":"VỊ TRÍ","body":"Từ huyệt Đại Chùy (Đc 14) và huyệt Thân Trụ (Đc 12) đo ra mỗi bên 0,5 thốn, lên trên và xuống dưới thành tổng cộng 8 huyệt."},{"h":"CHỦ TRỊ","body":"Trị dạ dầy đau gây ra nôn mửa, cột sống đau."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 0,8 thốn. Cứu 5 – 10 phút."}]},{"id":54,"ten":"Bát Du","sections":[{"h":"VỊ TRÍ","body":"Khe giữa đốt sống lưng 8 – 9 (huyệt Bát Chùy Hạ) ra ngang 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị thần kinh sườn đau, dạ dầy đau, tiểu đường."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,5 – 1 thốn."}]},{"id":55,"ten":"Bát Hoa","sections":[{"h":"VỊ TRÍ","body":"Chia đường giữa của 2 xương đòn gánh thành 8 phần. Lấy 2 phần làm cạnh của hình tam giác đều. Đem đỉnh hình tam giác đó đặt trên huyệt Đại Chùy, 2 góc cạnh kia là 2 huyệt. Đặt tiếp đỉnh tam giác trên điểm giữa của cạnh đáy trên sẽ được 2 huyệt khác. làm 4 lần sẽ được 8 huyệt, gọi là Bát Hoa (Châm cứu Học Thượng Hải).\nHoặc: Dùng 1 sợi dây, đo bề ngang 2 đầu vú, cắt bỏ đi 1/4, chỉ lấy 3/4 khúc dây việc lại, làm thành 1 tam giác đều. Đặt đỉnh của tam giác này tại huyệt Đại Chùy, 2 đầu của cạnh dưới tam giác là 2 huyệt Bát Hoa đầu tiên. Đặt đỉnh của tam giác đó tại giữa đường nối 2 huyệt Bát Hoa đầu sẽ được 2 huyệt Bát Hoa tiếp. Đến lần thứ tư sẽ được 8 huyệt Bát Hoa (Châm cứu Học HongKong).\nVị trí của 8 huyệt này thay đổi tùy từng cơ thể nên không có trên hình vẽ."},{"h":"CHỦ TRỊ","body":"Trị khí quản viêm, hen suyễn, lao phổi, thiếu máu, suy nhược cơ thể do bệnh mạn tính."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,5 – 1 thốn. Bệnh mạn tính thường dùng cứu 5–10 phút."}]},{"id":56,"ten":"Bát Liêu","sections":[{"h":"VỊ TRÍ","body":"Gồm 8 huyệt:\nThượng Liêu (Bq 31), Thứ Liêu (Bq 32), Trung Liêu (Bq 33), Hạ Liêu (Bq 34). [Xem chi tiết từng huyệt]"},{"h":"CHỦ TRỊ","body":"Trị bệnh ở bàng quang, bệnh ở bộ phận sinh dục, bệnh đường tiểu, vùng xương cùng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 2 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 20 phút."}]},{"id":57,"ten":"Bát Phong","sections":[{"h":"VỊ TRÍ","body":"Ép sát các ngón chân lại với nhau, huyệt ở đầu 4 kẽ chân, giữa các ngón, chỗ tiếp da mu chân và da gan chân."},{"h":"CHỦ TRỊ","body":"Trị mu bàn chân sưng đỏ, đau, mu bàn chân tê, thấp chẩn, đầu đau, răng đau, dạ dầy đau, kinh nguyệt không đều, sốt rét, rắn cắn."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,1–0,2 thốn. Nếu chân sưng, khi rút kim có thể nặn cho ra 1 giọt máu."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa các gân duỗi ngón chân, cơ gian cốt mu chân.\nThần kinh vận động cơ do các nhánh của dây thần kinh chầy trước và dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5 và S1."}]},{"id":58,"ten":"Bát Tà","sections":[{"h":"VỊ TRÍ","body":"Ở kẽ 5 ngón tay, trên đường tiếp giáp da gan tay – mu tay, ngang với khe khớp xương bàn tay – ngón tay. Tên của từng vị trí huyệt theo sách Châm cứu Đại Thành là:\nỞ hổ khẩu, giữa ngón 1 và ngón 2, chỗ tiếp giáp da gan tay – mu tay là huyệt Đại Đô.\nKẽ ngón 2 và ngón 3 là huyệt Thượng Đô (nắm tay lại để lấy huyệt).\nKẽ ngón 3 và ngón 4 là huyệt Trung Đô.\nKẽ ngón 4 và 5 là huyệt Hạ Đô."},{"h":"CHỦ TRỊ","body":"Trị bàn tay sưng, tê, ngón tay liệt do trúng phong.\nĐầu đau, răng đau (Đại Đô).\nCánh tay sưng đau (Thượng Đô, Trung Đô, Hạ Đô)"},{"h":"CHÂM CỨU","body":"Hơi nắm tay lại, châm thẳng dọc theo phía xương lòng bàn tay sâu chừng 1 thốn. Có thể châm nặn máu. Cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da huyệt Đại Đô là các cơ liên cốt, cơ khép ngón cái. Các huyệt khác là cơ gian cốt và cơ giun.\nThần kinh vận động cơ ở huyệt Thượng Đô do 1 nhánh dây thần kinh giữa 2 nhánh dây thần kinh trụ. Các huyệt khác do các nhánh của dây thần kinh trụ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C7 (Đại Đô), C6 (Thượng Đô, Trung Đô), C8 hoặc D1 (Hạ Đô).\n3ud1\nChâm đắc khí thấy có cảm giác căng tức ở vùng sống cùng, có khi lan xuống chi dưới.\nKhi châm, nên nằm sấp cho dễ lấy huyệt và dễ châm."}]},{"id":59,"ten":"Bát Tự Châm","sections":[{"h":"VỊ TRÍ","body":"Gồm 4 huyệt của kinh Đởm ở vùng đầu là Hàm yến, Huyền Lư, Huyền Ly và Khúc tân."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, nửa đầu đau, chóng mặt, thần kinh suy nhược, liệt mặt, thần kinh mặt co giật, chóng mặt do rối loạn tiền đình, đa thần kinh viêm."},{"h":"CHÂM CỨU","body":"Từ huyệt Hàm yến châm kim hơi chếch lên phía trên, luồn dưới da qua huyệt Huyền lư, qua Huyền Ly đến huyết Khúc tân."}]},{"id":60,"ten":"Bần Huyết Linh","sections":[{"h":"VỊ TRÍ","body":"Dưới đốt sống cùng thứ 4 (huyệt Ngọc Điền) xuống 0,3 thốn."},{"h":"CHỦ TRỊ","body":"Trị thiếu máu."},{"h":"CHÂM CỨU","body":"Chỉ cứu, không châm."}]},{"id":61,"ten":"Bận Cốt","sections":[{"h":"VỊ TRÍ","body":"Bờ trên xương bánh chè lên 2 thốn (huyệt Lương Khâu) rồi ra ngang 2 bên 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị khớp gối viêm, chi dưới liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5–1 thốn. Cứu 3–7 tráng. Ôn cứu 5–15 phút."}]},{"id":62,"ten":"Bận Cửu","sections":[{"h":"VỊ TRÍ","body":"Đỉnh mấu chuyển lớn thẳng lên 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị khớp đùi bị dãn do di chứng bại liệt trẻ nhỏ."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 1 thốn.(2Châm đắc khí thấy có cảm giác căng tức, có khi có cảm giác như điện giật hướng ra ngón tay."}]},{"id":63,"ten":"Bất Dung","sections":[{"h":"VỊ TRÍ","body":"Từ rốn đo lên 6 thốn, ngang ra 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị thần kinh liên sườn đau, dạ dầy đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn, cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ chéo to, cơ thẳng to, mạc ngang, phúc mạc, trong ổ bụng là gan.\nThần kinh vận động cơ là 6 dây thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D6."}]},{"id":64,"ten":"Bễ Quan","sections":[{"h":"VỊ TRÍ","body":"Trong vùng phễu đùi (scarpa), nơi gặp nhau của đường kẻ ngang qua xương mu và đường thẳng qua gai chậu trước trên, nơi bờ trong cơ may và cơ căng cân đùi, trên lằn gối chân 13 thốn, ngang huyệt Hội Âm (Nh 1)"},{"h":"CHỦ TRỊ","body":"Trị chi dưới liệt, nửa người liệt, cơ đái chậu viêm, đùi đau, háng đau, co duỗi chân khó khăn."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn, Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là góc của cơ may và cơ căng cân đùi, cơ thẳng trước đùi, khe của cơ rộng giữa đùi và cơ đái – chậu, xương đùi.\nThần kinh vận động cơ là các nhánh của dây thần kinh đùi, nhánh của dây thần kinh mông trên, các ngành ngang của đám rối thắt lưng.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L2."}]},{"id":65,"ten":"Bế Khổng","sections":[{"h":"VỊ TRÍ","body":"Đầu chót cuối của xương cùng đo ngang ra 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị thần kinh tọa đau, chi dưới liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 2 thốn."}]},{"id":66,"ten":"Bỉ Căn","sections":[{"h":"VỊ TRÍ","body":"Từ mỏm gai đốt sống thắt lưng 1 (L1) đo ra ngang 3,5 thốn hoặc từ huyệt Tam Tiêu Du (Bq 22) ra ngang 2 thốn hoặc huyệt Hoang Môn ra 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị gan lách lớn (hội chứng Banti), thận viêm, thận sa, ruột viêm, dạ dầy viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5–0,8 thốn."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ lưng to, cơ răng cưa bé sau – dưới, cơ chậu sườn – thắt lưng, cân lưng – thắt lưng, cơ vuông thắt lưng, niệu quản.\nThần kinh vận động cơ là nhánh của đám rối cánh tay, nhánh của dây sống thắt lưng 1.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D11.:\nPU3Không châm sâu quá vì có thể vào gan gây xuất huyết bên trong."}]},{"id":67,"ten":"Biên Đào","sections":[{"h":"VỊ TRÍ","body":"Tại bờ dưới góc hàm dưới, cách góc hàm 1 ngang ngón tay, ngang trước động mạch cổ, dưới huyệt Thiên Đỉnh 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị amiđan viêm, họng viêm, thanh quản viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 1,5 thốn.6q\n-"}]},{"id":68,"ten":"Bỉnh Phong","sections":[{"h":"VỊ TRÍ","body":"Bảo người bệnh giơ tay lên, huyệt ở chỗ lõm trên gai xương bả vai, phía thẳng với chỗ dầy nhất của gai xương sống bả vai, trên huyệt Thiên Tông (Ttr 11), giữa huyệt Cự Cốt (Đtr 16) và Khúc Viên (Ttr 13)"},{"h":"CHỦ TRỊ","body":"Trị khớp vai đau, bả vai đau, vùng chi trên đau tê."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 1 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ thang, cơ trên gai, xương bả vai.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não XI, nhánh của đám rối cổ sâu và nhánh của dây thần kinh trên vai.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C6."}]},{"id":69,"ten":"Bộ Lang","sections":[{"h":"VỊ TRÍ","body":"Ở vùng ngực, nơi khoảng gian sườn 5, cách đường giữa ngực 2 thốn, ngang huyệt Trung Đình (Nh 16)"},{"h":"CHỦ TRỊ","body":"Trị ho, suyễn, khí quản viêm, thần kinh gian sườn đau, màng ngực viêm."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 0,8 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ ngực to, các cơ thẳng to, các cơ gian sườn 5, cơ ngang ngực, mặt trên gan hoặc phổi (bên phải) và tim (bên trái).\nThần kinh vận động cơ là dây ngực to của đám rối thần kinh nách, dây thần kinh gian sườn 5.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D5."}]},{"id":70,"ten":"Bộc Tham","sections":[{"h":"VỊ TRÍ","body":"Xác định bờ trên mặt ngoài xương gót chân, huyệt ở sát bờ trên xương gót, thẳng dưới huyệt Côn Lôn, trên đường tiếp giáp lằn da đổi màu."},{"h":"CHỦ TRỊ","body":"Trị gót chân đau, chi dưới yếu liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là gân cơ mác bên dái và gân cơ mác bên ngắn ở phía trước, gân gót chân ở phía sau, bờ trên xương gót.\nThần kinh vận động cơ là các nhánh của dây thần kinh cơ – da và dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S1."}]},{"id":71,"ten":"Bối Giám","sections":[{"h":"VỊ TRÍ","body":"Giữa đốt sống lưng 6 và 7 (D6 – D7) tức là giữa huyệt Linh Đài (Đc 10) và Chí Dương (Đc 9)"},{"h":"CHỦ TRỊ","body":"Trị sốt rét."},{"h":"CHÂM CỨU","body":"Cứu 10 – 15 phút trước khi lên cơn."}]},{"id":72,"ten":"Bối Giáp Trung Gian","sections":[{"h":"VỊ TRÍ","body":"Phía ngoài điểm giữa xương khớp vai."},{"h":"CHỦ TRỊ","body":"Trị điên cuồng."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,3 – 0,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."}]},{"id":73,"ten":"Bối Lam","sections":[{"h":"VỊ TRÍ","body":"Bảo người bệnh đứng thẳng, 2 bàn chân để sát nhau, dùng 1 sợi dây quấn vòng quanh 2 bàn chân đến đầu ngón chân cái, lấy dao cắt lấy khúc dây đó. Đem dây đó quàng vào đằng trước cổ, cho 2 đầu dây thòng về phía sau lưng, nối 2 đầu dây vào cho chạm vào giữa xương sống chỗ nào thì đó là huyệt."},{"h":"CHỦ TRỊ","body":"Trị sốt rét."},{"h":"CHÂM CỨU","body":"Khi lên cơn, cứu 3 tráng."}]},{"id":74,"ten":"Bối Phùng","sections":[{"h":"VỊ TRÍ","body":"Xương đầu vai thẳng xuống, ngay dưới đầu chót xương vai, phía trên đỉnh nếp nách phía sau lên, ngang với huyệt Cao Hoang (Bq 43)"},{"h":"CHỦ TRỊ","body":"Trị vai lưng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 0,8 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 10 phút."}]},{"id":75,"ten":"Bối Tam Châm","sections":[{"h":"VỊ TRÍ","body":"Lấy huyệt Đại Chùy (Đc 14) và 2 huyệt Định Suyễn làm thành Bối Tam Châm."},{"h":"CHỦ TRỊ","body":"Trị ho, suyễn, sốt cao, nhiễm trùng đường hô hấp trên."},{"h":"CHÂM CỨU","body":"Đại Chùy: châm thẳng, hơi xiên lên phía trên, sâu 1 – 1,5 thốn.\nĐịnh Suyễn: châm xiên xuống cột sống sâu 1 – 1,5 thốn.I\n76+"}]},{"id":76,"ten":"Các Môn","sections":[{"h":"VỊ TRÍ","body":"Tại chùm lông ngọc hành đo ngang ra 2 bên mỗi bên 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị chứng âm hãn, âm nang sưng."},{"h":"CHÂM CỨU","body":"Châm 1,5 thốn. Cứu 5 – 7 tráng. Ôn cứu 5 – 10 phút.\t:\n C"}]},{"id":77,"ten":"Cách Du","sections":[{"h":"VỊ TRÍ","body":"Dưới gai đốt sống lưng 7, đo ngang ra 1,5 thốn, ngang huyệt Chí Dương (Đc 9)"},{"h":"CHỦ TRỊ","body":"Trị các bệnh có xuất huyết, máu thiếu, nấc cụt, nôn mửa do thần kinh, co thắt cơ hoành, thắt lưng đau, mồ hôi ra nhiều, mồ hôi trộm, kém ăn."},{"h":"CHÂM CỨU","body":"Châm xiên về cột sống 0,5 – 0,8 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ thang, cơ lưng to, cơ lưng dài, cơ bán gai của ngực, cơ ngang – gai, cơ ngang – sườn, vào trong là phổi.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não XI, nhánh của đám rối cổ sâu, nhánh của đám rối cánh tay, nhánh của dây thần kinh gian sườn 7 và nhánh của dây sống lưng 7.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D7."}]},{"id":78,"ten":"Cách Quan","sections":[{"h":"VỊ TRÍ","body":"Dưới gai sống lưng 7, đo ngang 3 thốn, cách huyệt Cách Du 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị thần kinh gian sườn đau, nấc cụt, nôn mửa, cột sống lưng đau."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 0,8 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ dưới cơ thang, cơ lưng to, cơ chậu – sườn – ngực, cơ gian sườn 7, vào trong là phổi.\nThần kinh vận động cơ là nhánh dây thần kinh sọ não XI, nhánh đám rối cổ sâu, nhánh đám rối cánh tay, nhánh dây thần kinh gian sườn 7 và nhánh dây sống lưng 7.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D7."}]},{"id":79,"ten":"Cách Thượng","sections":[{"h":"VỊ TRÍ","body":"Gai đốt sống thắt lưng 4 (L 4) đo ngang ra mỗi bên 4 thốn (huyệt Đại Trường Du (Bq 25) ra ngang 2,5 thốn)"},{"h":"CHỦ TRỊ","body":"Trị thần kinh toạ đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn.k\nM"}]},{"id":80,"ten":"Cách Tiền Hạ","sections":[{"h":"VỊ TRÍ","body":"Sát tận phía dưới cơ mông lớn, dưới gai trên – trước xương chậu 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị di chứng bại liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn."}]},{"id":81,"ten":"Can Du","sections":[{"h":"VỊ TRÍ","body":"Dưới gai sống lưng 9, đo ngang ra 1,5 thốn, ngang huyệt Cân Súc (Đc 8)"},{"h":"CHỦ TRỊ","body":"Trị các bệnh về mắt mạn tính, mộng thịt ở mắt, mắt sưng đau, hoa mắt, mắt có màng, hoàng đản, túi mật viêm, gan viêm, lưng đau, cuồng, chảy máu mũi."},{"h":"CHÂM CỨU","body":"Châm xiên về cột sống 0,5 – 0,8 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ thang, cơ lưng to, cơ lưng dài, cơ bán gai của ngực, cơ ngang – gai, cơ ngang – sườn, vào trong là phổi.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não XI, nhánh của đám rối cổ sâu, nhánh của đám rối cánh tay, nhánh của dây thần kinh gian sườn 9 và nhánh của dây sống lưng 9.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D9."}]},{"id":82,"ten":"Can Nhiệt Huyệt","sections":[{"h":"VỊ TRÍ","body":"Trên gai đốt sống lưng 5 (D5) ra ngang mỗi bên nửa (0,5) thốn."},{"h":"CHỦ TRỊ","body":"Trị khí quản viêm, túi mật viêm, thần kinh gian sườn đau."},{"h":"CHÂM CỨU","body":"Châm xiên, sâu 0,5 – 1 thốn. Cứu 5 – 10 phút.?\t:.Không châm sâu vì có thể đụng phổi."}]},{"id":83,"ten":"Can Tam Châm","sections":[{"h":"VỊ TRÍ","body":"Ở sau lưng, tại điểm ấn vào thấy đau ở vùng gan và 2 bên phải trái điểm đó đo ra 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị vùng gan đau, gan sưng lớn."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,5 – 1 thốn."}]},{"id":84,"ten":"Cảnh Trung","sections":[{"h":"VỊ TRÍ","body":"Lấy điểm giữa huyệt Phong Trì và Ế Minh (huyệt An Miên 2) xuống 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị liệt nửa người."},{"h":"CHÂM CỨU","body":"Châm thẳng hoặc xiên lên sâu 0,5 – 0,8 thốn. Cứu 5 – 10 phút."}]},{"id":85,"ten":"Cảnh Tý","sections":[{"h":"VỊ TRÍ","body":"Tại trước tĩnh mạch nông 2 bên cổ, giữa huyệt Khí Xá (Vi 11) và Khuyết Bồn (Vi 12)"},{"h":"CHỦ TRỊ","body":"Trị cánh tay tê, thần kinh cánh tay đau, bắp tay teo, cơ cánh tay teo, bàn tay teo, tay và vai đau."},{"h":"CHÂM CỨU","body":"Hơi nghiêng đầu về 1 bên, nằm ngửa, châm thẳng sâu 1 thốn, vê nhẹ cho có cảm giác lan đến tay. Nếu cảm giác lan đến ngực thì đổi hướng cho đến khi thấy lan xuống tay. Cứu 5 – 10 phút."}]},{"id":86,"ten":"Cao Cốt","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm cuối lằn chỉ cổ tay ngoài (Huyệt Thái Uyên – P.9) đo lên 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị cổ tay đau."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,5 – 1 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 10 phút."}]},{"id":87,"ten":"Cao Hoang","sections":[{"h":"VỊ TRÍ","body":"Ngay dưới gai sống lưng 4, đo ngang 3 thốn, cách huyệt Quyết Âm Du (Bq 14) 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị lao phổi, phế quản và màng ngực viêm, thần kinh suy nhược. Có tác dụng nâng cao chính khí và phòng bệnh tật."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn. Cứu 7 – 15 tráng đến 100 tráng. Ôn cứu 20 – 30 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ thang, cơ trám, cơ răng cưa bé sau – trên, cơ chậu – sườn – ngực, cơ gian sườn 4, phổi.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số XI, nhánh của đám rối cổ sâu, nhánh của đám rối cánh tay, nhánh thần kinh sống lưng 4 và dây thần kinh gian sườn 4.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D4."}]},{"id":88,"ten":"Cát Lâm","sections":[{"h":"VỊ TRÍ","body":"Rốn đo lên 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị dạ dầy dư chất chua, nôn ra nước chua."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 0,8 thốn. Cứu 5 – 10 phút."}]},{"id":89,"ten":"Cân Bình","sections":[{"h":"VỊ TRÍ","body":"Trên gân xương gót, chỗ đường thẳng từ mắt cá chân trong và mắt cá chân ngoài gặp nhau."},{"h":"CHỦ TRỊ","body":"Trị di chứng bại liệt trẻ nhỏ."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn.X\nO"}]},{"id":90,"ten":"Cân Khẩn","sections":[{"h":"VỊ TRÍ","body":"Từ giữa nếp gấp khoeo chân (huyệt Ủy Trung – Bq 40) đo xuống 9,5 thốn hoặc từ giữa gân gót đo lên 6,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị di chứng bại liệt trẻ nhỏ."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 0,8 thốn. Cứu 5 – 10 phút."}]},{"id":91,"ten":"Cân Súc","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm dưới đầu mỏm gai đốt sống lưng 9 (D9)"},{"h":"CHỦ TRỊ","body":"Trị lưng đau, thắt lưng đau, động kinh, uốn ván, Hysteria, mắt giật, dạ dầy đau."},{"h":"CHÂM CỨU","body":"Châm chếch kim lên trên, luồn dưới mỏm gai, hướng vào khoảng gian đốt sống lưng 9 – 10, sâu 0,3 – 1 thốn. Cứu 10 – 30 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ thang, cân ngực – thắt lưng của cơ lưng to, cơ gai dài của lưng, cơ ngang gai, dây chằng trên gai, dây chằng gian gai, dây chằng vàng, ống sống.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số XI, nhánh đám rối cổ sâu và các nhánh của dây thần kinh sống.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D8."}]},{"id":92,"ten":"Cấp Mạch","sections":[{"h":"VỊ TRÍ","body":"Ở bờ trên xương mu 1 thốn, đo ngang ra 2,5 thốn nằm trên nếp lằn của bẹn, dưới cung đùi."},{"h":"CHỦ TRỊ","body":"Trị bụng dưới đau, mặt trong đùi đau, dương vật đau, tử cung sa."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 0,8 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cung đùi Fallope, khe cơ lược và cơ khép nhỡ, cơ khép bé và cơ bịt.\nThần kinh vận động cơ là các nhánh của dây thần kinh bịt.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L 2."}]},{"id":93,"ten":"Cầu Hậu","sections":[{"h":"VỊ TRÍ","body":"Bệnh nhân nhắm mắt, nhìn thẳng, bờ dưới phía ngoài tròng mắt, huyệt ở chỗ giao tiếp của 3/4 trong và 1/4 ngoài."},{"h":"CHỦ TRỊ","body":"Trị cận thị, thần kinh thị giác viêm, thần kinh thị giác teo, mắt lác, thủy tinh thể đục, mắt mờ."},{"h":"CHÂM CỨU","body":"Bảo bệnh nhân mắt nhìn thẳng, mũi kim hơi hướng lên phía trên, chỗ thần kinh thị giác, sâu 1 – 2 thốn."}]},{"id":94,"ten":"Châu Đính","sections":[{"h":"VỊ TRÍ","body":"Trên đỉnh nhọn của bình tai."},{"h":"CHỦ TRỊ","body":"Trị răng đau, tai đau."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,3 thốn."}]},{"id":95,"ten":"Châu Hoàn","sections":[{"h":"VỊ TRÍ","body":"Phía trước tai, ngang đầu trên chân bình tai, trên huyệt Nhĩ Môn 0,2 thốn."},{"h":"CHỦ TRỊ","body":"Trị tai đau, răng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,1 – 0,2 thốn. Cứu 5 – 10 phút."}]},{"id":96,"ten":"Chi Câu","sections":[{"h":"VỊ TRÍ","body":"Trên lằn cổ tay 3 thốn, giữa khe xương trụ và xương quay, trên huyệt Ngoại Quan (Ttu.5) 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị chi trên liệt, vai lưng đau, thần kinh gian sườn đau, họng đau, sốt cao, táo bón."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,8 – 1,2 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa các cơ duỗi chung ngón tay và cơ duỗi dài riêng ngón tay cái ở ngoài với các cơ duỗi riêng ngón tay út và cơ duỗi riêng ngón tay trỏ ở trong, giữa màng gian cốt.\nThần kinh vận động cơ là các nhánh của dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C7."}]},{"id":97,"ten":"Chi Chính","sections":[{"h":"VỊ TRÍ","body":"Tại sát bờ sau xương trụ, cách cổ tay 5 thốn, trên đường nối huyệt Dương Cốc và huyệt Tiểu Hải."},{"h":"CHỦ TRỊ","body":"Trị khuỷu tay đau, cánh tay đau, ngón tay và cổ tay sưng đau, thần kinh suy nhược, lo sợ."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 0,8 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa cơ trụ trước và cơ trụ sau, chỗ bám vào xương của cơ duỗi riêng ngón tay trỏ và cơ gấp chung sâu các ngón tay xương trụ.\nThần kinh vận động cơ là các nhánh của dây thần kinh trụ và dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D1.\nTránh làm tổn thương bó mạch thần kinh đùi."}]},{"id":98,"ten":"Chí Âm","sections":[{"h":"VỊ TRÍ","body":"Ở bờ ngoài ngón út, cách góc chân móng 0,2 thốn, trên đường tiếp giáp da gan chân – mu chân."},{"h":"CHỦ TRỊ","body":"Trị ngón chân thứ 5 đau, đầu đau, nghẹt mũi, mũi chảy máu, thai bị lệch (cứu)"},{"h":"CHÂM CỨU","body":"Châm xiên lên trên sâu 0,1 – 0,2 thốn, hoặc châm nặn ra ít máu. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là xương đốt 3 ngón chân thứ 5.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S1."}]},{"id":99,"ten":"Chí Dương","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm dưới đầu mỏm gai đốt sống lưng 7 hoặc tại điểm gặp nhau của đường nối 2 đầu mỏm xương bả vai và đường dọc giữa chính cột sống."},{"h":"CHỦ TRỊ","body":"Trị lưng đau, vàng da, bụng sôi, không muốn ăn, ho suyễn, ngực đau, túi mật viêm, gan viêm, màng ngực viêm."},{"h":"CHÂM CỨU","body":"Châm chếch lên, luồn dưới mỏm gai, hướng vào khoảng gian đốt sống lưng 7 – 8, sâu 0,3 – 0,8 thốn. Cứu 10 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là gân cơ thang, cân ngực – thắt lưng của cơ lưng to, cơ gai dài của lưng, cơ ngang – gai, dây chằng trên gai, dây chằng gian gai, dây chằng vàng, ống sống.\nThần kinh vận động cơ là các nhánh của dây thần kinh sọ não số XI, nhánh đám rối cổ sâu và các nhánh của dây thần kinh sống.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D8."}]},{"id":100,"ten":"Chí Dương Lục Cứu","sections":[{"h":"VỊ TRÍ","body":"Từ huyệt Chí Dương (Đc 9) đo lên – xuống và ra ngang 2 bên, mỗi bên đều 0,5 thốn, tổng cộng 6 huyệt."},{"h":"CHỦ TRỊ","body":"Trị dạ dầy đau lâu ngày."},{"h":"CHÂM CỨU","body":"Mỗi ngày cứu 5 – 10 phút, liên tục 1 tháng.e\n,"}]},{"id":101,"ten":"Chí Thất","sections":[{"h":"VỊ TRÍ","body":"Dưới gai sống thắt lưng 2, ngang ra 3 thốn, cách Thận Du 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị lưng và vùng thắt lưng cứng đau, tiểu tiện rối loạn, Thận viêm, suy nhược sinh dục, liệt dương, di mộng tinh, phù thũng."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 0,8 thốn. Khi trị vùng lưng bị tổn thương hoặc thận bị sa xuống thì châm xiên hướng về huyệt Thận Du.\nCứu 5 – 7 tráng. Ôn cứu 10 – 20 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ lưng to, cơ răng cưa bé sau – dưới, cơ chậu sườn – thắt lưng, cân lưng – thắt lưng, cơ vuông thắt lưng, niệu quản.\nThần kinh vận động cơ là nhánh đám rối cánh tay, nhánh của dây sống thắt lưng 2.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh"}]},{"id":102,"ten":"Chỉ Căn","sections":[{"h":"VỊ TRÍ","body":"Ngay giữa lằn chỉ cuối các ngón tay thứ 2, 3, 4 và 5. Hai tay có 8 huyệt."},{"h":"CHỦ TRỊ","body":"Trị nóng sốt, buồn phiền, xuất huyết."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,1 – 0,2 thốn. Hoặc dùng kim tam lăng châm cho ra máu. Cứu 5 – 10 phút."}]},{"id":103,"ten":"Chỉ Tả","sections":[{"h":"VỊ TRÍ","body":"Rốn thẳng xuống 2,5 thốn (giữa huyệt Quan Nguyên (Nh 4) và Thạch Môn – Nh."},{"h":"CHỦ TRỊ","body":"Trị tiêu chảy, ruột viêm, tiểu gắt, tiểu dầm."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 1,5 thốn.F\nN."}]},{"id":104,"ten":"Chỉ Trung Tiết Văn Đầu","sections":[{"h":"VỊ TRÍ","body":"Mu bàn tay, khi nắm bàn tay lại, huyệt ở hai đầu lằn chỉ của khớp ngón tay giữa của ngón trỏ, ngón giữa, ngón áp út và ngón út."},{"h":"CHỦ TRỊ","body":"Trị khớp ngón tay đau, ngón tay co quắp không duỗi ra được."}]},{"id":105,"ten":"Chiên Trung","sections":[{"h":"VỊ TRÍ","body":"Ở điểm gặp nhau của đường dọc giữa xương ức với đường ngang qua 2 đầu núm vú (đàn ông) hoặc ngang qua bờ trên 2 khớp xương ức thứ 5 (đàn bà)"},{"h":"CHỦ TRỊ","body":"Trị ngực đau, hen suyễn, thở kém, nấc, sữa ít, màng ngực viêm, thần kinh liên sườn đau."},{"h":"CHÂM CỨU","body":"Châm luồn kim dưới da, hướng lên huyệt Hoa Cái để trị suyễn, xiên ngang trị bịnh về vú, sâu 0,3 – 1,5 thốn. Cứu 5 – 20 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là xương ức.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D4."}]},{"id":106,"ten":"Chiếu Hải","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm ngay dưới mắt cá trong cách 01 thốn, khe giữa gân cơ cẳng chân sau và cơ gấp các ngón chân."},{"h":"CHỦ TRỊ","body":"Trị kinh nguyệt rối loạn, tử cung sa, thần kinh suy nhược, động kinh, họng viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa gân cơ cẳng chân sau và gân cơ gấp dài các ngón chân, sau mỏm chân đế, gót của xương gót.\nThần kinh vận động cơ là các nhánh của dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S1.\nPhàm tay có mụn nhọt, bất kể ở ngón nào, châm ở cuối lóng thứ 3, các mụn độc này đều có thể tiêu” (Trị Liệu Hối Yếu).\n“Có Kỳ Huyệt, tên là Chỉ Căn, ở giữa lằn chỉ cuối ngón tay thứ 2, 3, 4 và 5, tay bên phải và trái có 8 huyệt” (Trung Quốc Châm cứu Học).\n“Huyệt này có tên là Tứ Hoành Văn hoặc Hạ Tứ Phùng” (Tiểu Nhi Thôi Nã Phương Mạch Hoạt Anh Bí Chỉ Toàn Thư)"}]},{"id":107,"ten":"Chính Dinh","sections":[{"h":"VỊ TRÍ","body":"Ở trên đường nối huyệt Đầu Lâm Khấp và Phong Trì, sau huyệt Mục Song 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, mắt đau, răng đau, chóng mặt kèm theo nôn."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân sọ, xương đỉnh sọ.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V."}]},{"id":108,"ten":"Chu Vinh","sections":[{"h":"VỊ TRÍ","body":"Ở khoảng gian sườn 2, cách đường giữa bụng 6 thốn, từ huyệt Thiên Khê (Ty 18) đo lên 2 gian sườn, hoặc từ huyệt Trung Phủ (P 1) đo xuống 1 gian sườn."},{"h":"CHỦ TRỊ","body":"Trị thần kinh liên sườn đau, ho, màng ngực viêm."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5–10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ ngực to, cơ ngực bé, cơ răng cưa to, các cơ gian sườn 3, vào trong là phổi.\nThần kinh vận động cơ là dây thần kinh ngực to, dây thần kinh ngực bé và dây thần kinh gian sườn 3.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D2."}]},{"id":109,"ten":"Chú Thị","sections":[{"h":"VỊ TRÍ","body":"Vú đo ra 3 thốn rồi thẳng xuống kẽ sườn thứ 7."},{"h":"CHỦ TRỊ","body":"Trị ngực đau, hông sườn đau."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn. Cứu 5 – 10 phút."}]},{"id":110,"ten":"Chùy Hạ","sections":[{"h":"VỊ TRÍ","body":"Tại khe giữa đốt sống cổ thứ 6 – 7, huyệt Đại Chùy (Đc 16) lên 1 đốt sống."},{"h":"CHỦ TRỊ","body":"Trị sốt rét, mũi nghẹt, sổ mũi."},{"h":"CHÂM CỨU","body":"Hơi cúi đầu xuống, Châm xiên 0,3 – 0,5 thốn. Cứu 5 – 10 phút.8K\n Ò"}]},{"id":111,"ten":"Chuyển Cốc","sections":[{"h":"VỊ TRÍ","body":"Tại chỗ lõm kẽ gian sườn thứ 2, hoặc từ nách đo vào gian sườn 2."},{"h":"CHỦ TRỊ","body":"Trị ngực sườn đầy trướng, ăn uống không tiêu, nôn mửa, tiêu hóa không tốt."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,3 – 0,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút.A\nKE"}]},{"id":112,"ten":"Chương Môn","sections":[{"h":"VỊ TRÍ","body":"Ở đầu xương sườn tự do thứ 11."},{"h":"CHỦ TRỊ","body":"Trị vùng hông sườn đau, tiêu hóa kém, tiêu chảy, gan viêm, lách viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng hoặc xiên, sâu 0,5 – 0,8 thốn. Cứu 3–5 tráng. Ôn cứu 5–10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ chéo to của bụng, cơ chéo bé của bụng, cơ ngang bụng, mạc ngang, đầu xương sườn 11, phúc mạc, bờ dưới gan hoặc lách, đại trường lên hoặc xuống.\nThần kinh vận động cơ là 6 dây thần kinh gian sườn dưới cùng và dây thần kinh bụng–sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D10."}]},{"id":113,"ten":"Cổ Nội Thâu","sections":[{"h":"VỊ TRÍ","body":"Sát tận bên xương chầy – cơ mông lớn, dưới khớp xương mu – bờ trong cơ khép to."},{"h":"CHỦ TRỊ","body":"Trị di chứng bại liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 1 thốn."}]},{"id":114,"ten":"Côn Lôn","sections":[{"h":"VỊ TRÍ","body":"Tại giao điểm của bờ ngoài gót chân và đường kéo từ nơi cao nhất của mắt cá chân, chỗ lõm giữa khe gân cơ mác bên ngắn và gân cơ mác bên dài, trước gân gót chân, ở sau đầu dưới xương chầy."},{"h":"CHỦ TRỊ","body":"Trị khớp mắt cá và tổ chức mềm chung quanh bị sưng đau, thần kinh tọa đau, lưng đau, chi dưới liệt, nhau thai không xuống."},{"h":"CHÂM CỨU","body":"Châm thẳng tới Thái Khê hoặc 1 bên ngoài mắt cá, sâu 0,5–1 thốn.\nKhi trị tuyến giáp sưng, châm xiên hướng mũi kim đến huyệt Phụ Dương.\nCứu 3–5 tráng. Ôn cứu 5–10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa gân cơ mác bên ngắn và gân cơ mác bên dài ở trước gân gót chân, ở sau đầu dưới xương chầy.\nThần kinh vận động cơ là các nhánh của dây thần kinh cơ–da và dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S2 hoặc L5.\nKhông châm sâu vì có thể đụng phổi.\nHuyệt tại kẽ sườn 7 và 8” (Kinh Ngoại Kỳ Huyệt Đồ Phổ).\n“Đây tức là huyệt Bàng Đình” (Châm cứu Học Từ Điển)"}]},{"id":115,"ten":"Công Tôn","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm, nơi tiếp nối của thân và đầu sau xương bàn chân 1. Trên đường tiếp giáp da gan chân – mu chân, ở bờ trong bàn chân. Từ đỉnh cao nhất của xương mu bàn chân kéo xuống ngay dưới lõm xương."},{"h":"CHỦ TRỊ","body":"Trị gan bàn chân nóng hoặc đau, dạ dày đau do rối loạn thần kinh, ruột viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng, hướng tới huyệt Dũng Tuyền, sâu 0,5 – 1 thốn. Cứu 3 –5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ dạng ngón chân cái, cơ gấp ngắn ngón chân cái, gân cơ gấp dài ngón chân cái, mặt dưới đầu xương bàn chân 1.\nThần kinh vận động cơ là các nhánh của dây chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5."}]},{"id":116,"ten":"Cơ Môn","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm tạo nên bởi bờ ngoài cơ may, bờ trong cơ thẳng trước đùi và cơ rộng trong. Ngồi ngay, từ đầu gối đo lên 8 thốn, cách Huyết Hải 6 thốn, nơi có động mạch nhảy."},{"h":"CHỦ TRỊ","body":"Trị bụng dưới đau, tuyến hạch bẹn viêm, tiểu không tự chủ, niệu đạo viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe cơ may và cơ rộng trong, gần bờ trong cơ thẳng, trước đùi, cơ rộng giữa xương đùi.\nThần kinh vận động cơ là các nhánh của dây thần kinh đùi.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L3."}]},{"id":117,"ten":"Cơ Quan","sections":[{"h":"VỊ TRÍ","body":"Từ dái tai đo xuống 1 thốn, gần huyệt Giáp Xa."},{"h":"CHỦ TRỊ","body":"Trị liệt mặt, miệng không mở ra được."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn. Cứu 5 – 10 phút."}]},{"id":118,"ten":"Củ Ngoại Phiên","sections":[{"h":"VỊ TRÍ","body":"Đỉnh mắt cá chân trong lên 2,5 thốn (tức dưới huyệt Tam Âm Giao 0,5 thốn)"},{"h":"CHỦ TRỊ","body":"Trị chân lật ra ngoài do di chứng bại liệt nơi trẻ nhỏ."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 0,8 thốn. Cứu 5–10 phút."}]},{"id":119,"ten":"Củ Ngoại Phiên II","sections":[{"h":"VỊ TRÍ","body":"Đỉnh lõm hình chữ V ở bắp chân (Huyệt Thừa Sơn [Bq 57]) đo vào trong 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị chân lật ra ngoài do di chứng bại liệt ở trẻ nhỏ."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 0,8 thốn. Cứu 5–10 phút."}]},{"id":120,"ten":"Củ Nội Phiên","sections":[{"h":"VỊ TRÍ","body":"Chỗ trũng hình chữ V ở bắp chân (huyệt Thừa Sơn – Bq 57) đo ra ngoài 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị chân lật vào trong do di chứng bại liệt nơi trẻ nhỏ."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 0,8 thốn."}]},{"id":121,"ten":"Cung Trì","sections":[{"h":"VỊ TRÍ","body":"Ở trước và sau mu mắt cá chân trong, 2 bên đầu xương mắt cá."},{"h":"CHỦ TRỊ","body":"Trị băng huyết."},{"h":"CHÂM CỨU","body":"Cứu 10 – 15 phút. Không châm.=\nG"}]},{"id":122,"ten":"Cùng Cốt","sections":[{"h":"VỊ TRÍ","body":"Có ba huyệt. Trên xương cụt 1 thốn, tận phía dưới của rãnh mông đo ra mỗi bên 1 thốn. Có tất cả 3 huyệt."},{"h":"CHỦ TRỊ","body":"Trị thắt lưng đau, lâm lậu, táo bón, tiểu bí, trĩ, xương cùng đau, hậu môn co thắt."},{"h":"CHÂM CỨU","body":"Cứu 3 – 7 tráng.\ni\nTb"}]},{"id":123,"ten":"Cùng Cốt II","sections":[{"h":"VỊ TRÍ","body":"Tận đầu chót xương cùng, phía trên huyệt Trường Cường (Đc 1)"},{"h":"CHỦ TRỊ","body":"Trị điên cuồng, hoảng hốt, mất trí nhớ."},{"h":"CHÂM CỨU","body":"Cứu 14 tráng."}]},{"id":124,"ten":"Cư Liêu","sections":[{"h":"VỊ TRÍ","body":"Ở giữa đường nối gai chậu trước trên với điểm cao nhất của mấu chuyển lớn xương đùi, nơi cơ mông lớn và cơ mông bé."},{"h":"CHỦ TRỊ","body":"Trị khớp háng và tổ chức mềm chung quanh viêm, chi dưới đau, thần kinh tọa đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ mông nhỡ, cơ mông bé.\nThần kinh vận động cơ là các nhánh dây thần kinh mông trên.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L1 hoặc L2."}]},{"id":125,"ten":"Cử Tý","sections":[{"h":"VỊ TRÍ","body":"Đầu mỏm trong khớp xương vai xuống 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị tay thõng xuống do di chứng bại liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 2 thốn."}]},{"id":126,"ten":"Cự Cốt","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm giữa xương đòn với gai sống vai."},{"h":"CHỦ TRỊ","body":"Trị bệnh ở khớp vai, lưng, chi trên, lao hạch."},{"h":"CHÂM CỨU","body":"Châm thẳng hoặc hơi xiên xuống dưới bên ngoài, sâu 0,5 – 1,5 thốn, Cứu 3 – 7 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ thang, cơ trên gai.\nThần kinh vận động cơ là dây trên vai của đám rối thần kinh nách, nhánh ngoài của dây thần kinh sọ não số XI và 1 nhánh của đám rối cổ sâu.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C4."}]},{"id":127,"ten":"Cự Cốt Hạ","sections":[{"h":"VỊ TRÍ","body":"Từ khe giữa xương đòn với gai sống vai (huyệt Cự Cốt) đo xuống 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị bệnh ở khớp vai và tổ chức mềm quanh vai."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1–2 thốn."}]},{"id":128,"ten":"Cự Dương","sections":[]},{"id":129,"ten":"Cự Giác","sections":[{"h":"VỊ TRÍ","body":"Tại mé dưới bờ bên góc trên xương bả vai."},{"h":"CHỦ TRỊ","body":"Trị bả vai đau, Hysteria."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,3 – 0,5 thốn. Cứu 5 – 7 tráng."}]},{"id":130,"ten":"Cự Hư","sections":[]},{"id":131,"ten":"Cự Khuyết","sections":[{"h":"VỊ TRÍ","body":"Rốn thẳng lên 6 thốn, dưới huyệt Cưu Vĩ 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị bụng đau, nấc, nôn mửa, ợ chua, giữa ngực đau, điên cuồng, tim đập, kinh giật, hay quên."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 2 thốn. Cứu 5 – 45 phút."},{"h":"GIẢI PHẪU","body":"Huyệt ở trên đường trắng, sau đường trắng là mạc ngang, phúc mạc, sau thành bụng là thùy gan trái.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh"}]},{"id":132,"ten":"Cự Khuyết Du","sections":[{"h":"VỊ TRÍ","body":"Khe giữa gai đốt sống lưng thứ 4."},{"h":"CHỦ TRỊ","body":"Trị suyễn, khí quản viêm, bệnh tim, thần kinh suy nhược, bệnh dạ dầy."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,5 – 1 thốn."}]},{"id":133,"ten":"Cự Liêu","sections":[{"h":"VỊ TRÍ","body":"Tại nơi gặp nhau của đường giữa mắt kéo xuống và chân cánh mũi kéo ra, ngay dưới huyệt Tứ Bạch (Vi 2)"},{"h":"CHỦ TRỊ","body":"Trị liệt mặt, răng đau, môi và má sưng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng hoặc xiên 0,3 – 0,5 thốn, Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ gò má nhỏ, cơ nâng cánh mũi và môi trên (cơ vuông môi trên), vào sâu có cơ nanh, xương hàm trên.\nThần kinh vận động cơ là các nhánh của dây thần kinh sọ não số VII.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V."}]},{"id":134,"ten":"Cực Tuyền","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm ở giữa hố nách, khe giữa động mạch nách, sau gân cơ nhị đầu và gân cơ quạ cánh tay."},{"h":"CHỦ TRỊ","body":"Trị cánh tay đau, chi trên liệt, khớp vai viêm, quanh khớp vai viêm, tim đau thắt."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Cứu 1 – 3 tráng, Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa động mạch nách và mặt sau gân cơ quạ cánh tay, gân cơ 2 đầu (phần ngắn), trước nữa là mặt sau cơ ngực to, ở trên là đầu trên xương cánh tay.\nThần kinh vận động cơ là các nhánh của dây thần kinh cơ–da cánh tay và thần kinh ngực to của đám rối cánh tay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D3."}]},{"id":135,"ten":"Cường Gian","sections":[{"h":"VỊ TRÍ","body":"Giữa đoạn nối huyệt Phong Phủ (dưới chẩm) và huyệt Bá Hội (đỉnh giữa đầu)"},{"h":"CHỦ TRỊ","body":"Trị đầu đau, gáy cứng, điên cuồng."},{"h":"CHÂM CỨU","body":"Châm luồn kim dưới da sâu 0,2 – 1 thốn. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân sọ, dưới cân là xương sọ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C3."}]},{"id":136,"ten":"Cưu Kỷ","sections":[{"h":"VỊ TRÍ","body":"Dưới xương cùng 1."},{"h":"CHỦ TRỊ","body":"Trị băng lậu, bạch đới quá nhiều, băng huyết."},{"h":"CHÂM CỨU","body":"Cứu 10 – 15 phút."}]},{"id":137,"ten":"Cưu Vĩ","sections":[{"h":"VỊ TRÍ","body":"Ở sát đầu mũi ức, chỗ đầu trên của đường trắng, dưới mũi ức 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị bụng trên đau, ngực đau tức, nấc, khó thở, động kinh, cuồng, tâm thần, suyễn."},{"h":"CHÂM CỨU","body":"Châm xiên, mũi kim hơi hướng xuống dưới, sâu 0,5 – 1 thốn. Cứu 10 – 15 phút."},{"h":"GIẢI PHẪU","body":"Huyệt ở sát đầu mũi ức, chỗ đầu trên của đường trắng. Sau thành bụng là thùy gan trái.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D6."}]},{"id":138,"ten":"Cưu Vĩ Cốt Đoan","sections":[{"h":"VỊ TRÍ","body":"Ngay đỉnh xương ức."},{"h":"CHỦ TRỊ","body":"Trị trẻ nhỏ thóp đầu không kín, cam tích, gầy ốm, suy sinh dục."},{"h":"CHÂM CỨU","body":"Cứu 3–10 tráng."}]},{"id":139,"ten":"Cứu Điến Phong","sections":[{"h":"VỊ TRÍ","body":"Ở lòng bàn tay, giữa khớp đầu tiên của ngón tay thứ 3."},{"h":"CHỦ TRỊ","body":"Trị lang ben."},{"h":"CHÂM CỨU","body":"Cứu.K7\nt"}]},{"id":140,"ten":"Cứu Háo","sections":[{"h":"VỊ TRÍ","body":"Dùng 1 sợi dây đo vòng từ đốt sống cổ (C7) xuống huyệt Cưu Vĩ (Nh 10), từ Cưu Vĩ đo vòng ra sau lưng, chạm vào cột sống, lấy đầu dây làm chuẩn, đo ra 2 bên đốt sống lưng là huyệt."},{"h":"CHỦ TRỊ","body":"Trị suyễn lâu ngày."},{"h":"CHÂM CỨU","body":"Cứu 10 – 15 phút."}]},{"id":141,"ten":"Cứu Huyết Bệnh","sections":[{"h":"VỊ TRÍ","body":"Lỗ hổng xương cùng (huyệt Yêu Du – Đc 2) xuống 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị băng huyết, thiếu máu, trụy mạch, nôn ra máu, tiêu ra máu, chảy máu cam, các bệnh về huyết."},{"h":"CHÂM CỨU","body":"Cứu 5 – 7 tráng. Ôn cứu 10 – 15 phút."}]},{"id":142,"ten":"Cứu Lao","sections":[{"h":"VỊ TRÍ","body":"Tại chỗ cao nhất của đốt sống thắt lưng thứ ba."},{"h":"CHỦ TRỊ","body":"Trị trúng gió đột ngột, bệnh tâm thần, điên cuồng, mồ hôi trộm, ho ra máu, viêm khớp."},{"h":"CHÂM CỨU","body":"Cứu 3 – 10 tráng.0\nVG"}]},{"id":143,"ten":"Cứu Xỉ Thống","sections":[{"h":"VỊ TRÍ","body":"Để ngửa bàn tay, từ đầu ngón tay giữa đến giữa lằn cổ chia làm 4 phần, bỏ đi ¼, lấy ¾ còn lại đo tiếp từ giữa lằn chỉ cổ tay lên cẳng tay ở đâu, đó là huyệt, ở giữa hai gân cơ lớn."},{"h":"CHỦ TRỊ","body":"Trị răng đau."},{"h":"CHÂM CỨU","body":"Cứu 3 tráng. Đau bên phải cứu bên trái và ngược lại."}]},{"id":144,"ten":"Cửu Khúc Trung Phủ","sections":[{"h":"VỊ TRÍ","body":"Từ huyệt Chủ thị đo xuống 3 thốn, ra ngang 0,1 thốn."},{"h":"CHỦ TRỊ","body":"Trị tà khí ác phong, bên trong có tích, ngực sườn đau, bụng đau."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút.5\nAx"}]},{"id":145,"ten":"Cửu Liên Hoàn","sections":[{"h":"VỊ TRÍ","body":"Các huyệt dưới đốt sống lưng thứ 1, 3, 5, 7, 9, 11 (D1–1) và dưới đốt thắt lưng 1, 3, 5 (L11–5) cộng lại là 9 huyệt, gọi là Cửu Liên Hoàn."},{"h":"CHỦ TRỊ","body":"Trị suy nhược, xoay xẩm, lưng đau, chi dưới liệt."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn. Cứu 5 – 10 phút."}]},{"id":146,"ten":"Dạ Niệu Điểm","sections":[{"h":"VỊ TRÍ","body":"Rốn xuống 4,5 thốn (huyệt Hạ Trung Cực) đo ngang ra 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị tiểu dầm."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 1 – 1,5 thốn."}]},{"id":147,"ten":"Dần Môn","sections":[{"h":"VỊ TRÍ","body":"Giữa đỉnh đầu (huyệt Bá Hội) đo lên phía trước 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị vàng da."},{"h":"CHÂM CỨU","body":"Châm xiên 0,2 – 0,3 thốn. Không cứu."}]},{"id":148,"ten":"Di Du","sections":[{"h":"VỊ TRÍ","body":"Gai sống lưng thứ 8 đo ngang ra 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị tiểu đường, bệnh dạ dầy, thần kinh liên sườn đau."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 1 thốn."}]},{"id":149,"ten":"Di Đạo","sections":[{"h":"VỊ TRÍ","body":"Huyệt Ngọc Tuyền ra ngang 5 thốn."},{"h":"CHỦ TRỊ","body":"Trị tiểu nhiều."},{"h":"CHÂM CỨU","body":"Cứu."}]},{"id":150,"ten":"Di Niệu","sections":[{"h":"VỊ TRÍ","body":"Đỉnh mắt cá chân trong lên 4 thốn (Tam Âm Giao lên 1 thốn)"},{"h":"CHỦ TRỊ","body":"Trị tiểu dầm."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 1,5 thốn."}]},{"id":151,"ten":"Di Niệu Cứu","sections":[{"h":"VỊ TRÍ","body":"Ở mu bàn chân, hai bên huyệt Hành Gian."},{"h":"CHỦ TRỊ","body":"Trị đái dầm."},{"h":"CHÂM CỨU","body":"Cứu 5 – 7 tráng.(\n\nB"}]},{"id":152,"ten":"Di Tinh","sections":[{"h":"VỊ TRÍ","body":"Rốn xuống 3 thốn (huyệt Quan Nguyên – Nh.4) ra ngang 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị di tinh, mộng tinh, tiết tinh, liệt dương, chàm ở bìu dái."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 1,5 thốn.=\n?"}]},{"id":153,"ten":"Dịch Hạ","sections":[{"h":"VỊ TRÍ","body":"Chỗ trũng ngay dưới nếp lông nách."},{"h":"CHỦ TRỊ","body":"Trị chứng ế cách (ngăn nghẹn), lao hạch (loa lịch)"},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 0,8 thốn."}]},{"id":154,"ten":"Dịch Khí","sections":[{"h":"VỊ TRÍ","body":"Cạo lông nách, huyệt ở giữa hố nách."},{"h":"CHỦ TRỊ","body":"Trị hôi nách."},{"h":"CHÂM CỨU","body":"Cứu 10 – 15 phút."}]},{"id":155,"ten":"Dịch Linh","sections":[{"h":"VỊ TRÍ","body":"Khép cánh tay lại, cuối lằn chỉ nếp nách đo lên 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị vai và cánh tay đau, bệnh thần kinh."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 2 – 3 thốn.:\n)"}]},{"id":156,"ten":"Dịch Môn","sections":[{"h":"VỊ TRÍ","body":"Giữa xương bàn ngón tay thứ 4 và 5, nơi chỗ lõm ở kẽ ngón tay, ngang phần tiếp nối của thân với đầu trên xương đốt ngón tay."},{"h":"CHỦ TRỊ","body":"Trị bàn tay và ngón tay sưng đau, họng viêm, đầu đau, tai ù, điếc, sốt rét."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Cứu 1 – 3 tráng. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là chỗ bám của cơ gian cốt mu tay, bờ trong đầu trên đốt 1 xương ngón tay thứ 2.\nThần kinh vận động cơ là các nhánh của dây thần kinh trụ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C8 hoặc D1."}]},{"id":157,"ten":"Diện Nham","sections":[{"h":"VỊ TRÍ","body":"Tại giao điểm của đường dưới xương gò má với đường từ cánh mũi kéo ngang ra."},{"h":"CHỦ TRỊ","body":"Trị mụn nhọt ở đầu và mặt."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn."}]},{"id":158,"ten":"Diệu Trung","sections":[{"h":"VỊ TRÍ","body":"Ở trên xương cùng cụt, dưới đốt thứ 3."},{"h":"CHỦ TRỊ","body":"Trị sinh khó, băng huyết, rong kinh, kiết lỵ, trĩ."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,2 – 0,3 thốn, Cứu 3 – 5 tráng.'\n3;"}]},{"id":159,"ten":"Doanh Trì","sections":[{"h":"VỊ TRÍ","body":"Tại chỗ lõm trước và sau bờ dưới mắt cá chân trong."},{"h":"CHỦ TRỊ","body":"Trị di tinh, mộng tinh, tiết tinh, liệt dương, chàm ở bìu dái."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 1,5 thốn.\n4\n?"}]},{"id":160,"ten":"Du Phủ","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm giữa bờ dưới xương đòn và xương sườn 1, cách đường giữa ngực 2 thốn, ngang huyệt Toàn Cơ (Nh."},{"h":"CHỦ TRỊ","body":"Trị ho suyễn, nôn mửa, ngực đầy tức."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ bám da cổ, cơ ngực to, cơ dưới đòn, cơ ức – móng, cơ ức giáp, đỉnh phổi.\nThần kinh vận động cơ là các nhánh cơ bám da cổ của dây thần kinh mặt, dây ngực to và dây dưới đòn của đám rối thần kinh cánh tay, các nhánh của quai thần kinh sọ não số XII.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh niệu: cứu huyệt Di Đạo, ở ngang huyệt Ngọc Tuyền 5 thốn, cứu tùy theo tuổi” (Thiên Kim Phương).\n“Vị trí Kỳ huyệt này tương ứng với huyệt Quy Lai [Vi.29] (Châm cứu Học Từ Điển)"}]},{"id":161,"ten":"Dục Đoạn Sản","sections":[{"h":"VỊ TRÍ","body":"Đỉnh mắt cá chân trong lên 1 thốn, sát khe xương (dưới huyệt Tam Âm Giao 2 thốn)"},{"h":"CHỦ TRỊ","body":"Cai đẻ, thôi sinh."},{"h":"CHÂM CỨU","body":"Cứu 10 – 15 phút, không châm."}]},{"id":162,"ten":"Dung Hậu","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm sau tai (huyệt Ế Phong – Ttu 17) xuống 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, răng đau, điếc."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 1 thốn."}]},{"id":163,"ten":"Dũng Tuyền","sections":[{"h":"VỊ TRÍ","body":"Dưới lòng bàn chân, huyệt ở điểm nối 2/5 trước với 3/5 sau của đoạn đầu ngón chân thứ 2 và giữa bờ sau gót chân, chỗ lõm dưới bàn chân."},{"h":"CHỦ TRỊ","body":"Trị gan bàn chân đau hoặc nóng lạnh, kích ngất, động kinh, mất ngủ, đỉnh đầu đau, họng đau, nôn mửa, Hysteria."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 1 thốn. Cứu 1 – 3 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ gấp ngắn các ngón chân, gân cơ gấp dài các ngón chân, cơ giun, cơ gian cốt gan chân, cơ gian cốt mu chân, khoảng gian đốt bàn chân 2 – 3.\nThần kinh vận động cơ là các nhánh của dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5."}]},{"id":164,"ten":"Duy Bào","sections":[{"h":"VỊ TRÍ","body":"Rốn đo xuống 3 thốn (huyệt Quan Nguyên), đo ngang ra 6 thốn, chỗ lõm phía trong – trước gai trên cơ mào chậu."},{"h":"CHỦ TRỊ","body":"Trị tử cung sa, ruột đau thắt."},{"h":"CHÂM CỨU","body":"Châm xiên theo rãnh bụng – đùi, sâu 2 – 3 thốn."}]},{"id":165,"ten":"Duy Cung","sections":[{"h":"VỊ TRÍ","body":"Phía trước và dưới gai chậu trước – trên (huyệt Duy Đạo) xuống 2 thốn, hơi xiên vào phía trong."},{"h":"CHỦ TRỊ","body":"Trị tử cung sa."},{"h":"CHÂM CỨU","body":"Châm hướng vào phía trong sâu 1 – 2 thốn."}]},{"id":166,"ten":"Duy Đạo","sections":[{"h":"VỊ TRÍ","body":"Phía trước và dưới gai chậu trước trên, ở trước và dưới huyệt Ngũ Xu 0,5 thốn, dưới huyệt Chương Môn 5,3 thốn."},{"h":"CHỦ TRỊ","body":"Trị màng trong tử cung viêm, vùng bụng dưới thắt đau, táo bón kinh niên."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1,5 thốn, Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ dưới cơ chéo to và cơ chéo bé của bụng, cơ ngang bụng, mạc ngang, phúc mạc, đại trường.\nThần kinh vận động cơ là 6 dây thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D12."}]},{"id":167,"ten":"Dữ Long","sections":[{"h":"VỊ TRÍ","body":"Rốn đo lên 1 thốn (huyệt Thủy Phân – Nh.9) rồi đo ngang ra 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị khí lạnh từ dưới xông lên Tiểu Trường và Tâm."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút.(C\n2"}]},{"id":168,"ten":"Dương Bạch","sections":[{"h":"VỊ TRÍ","body":"Trước trán, trên đường thẳng qua chính giữa mắt và phía trên lông mày cách 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị liệt mặt, đầu và vùng trán đau, bệnh về mắt (loạn thị, quáng gà, thần kinh vành mắt đau)"},{"h":"CHÂM CỨU","body":"Châm xiên thấu Ngư Yêu hoặc Toàn Trúc, Ty Trúc Không. Cứu 1 – 3 tráng. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ trán, xương trán.\nThần kinh vận động cơ là nhánh của dây thần kinh mặt.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V."}]},{"id":169,"ten":"Dương Cốc","sections":[{"h":"VỊ TRÍ","body":"Ở bờ trong cổ ngón tay, nơi chỗ lõm giữa xương hạt đậu và đầu mỏm trâm xương trụ."},{"h":"CHỦ TRỊ","body":"Phía sau mặt trong cổ tay đau, tai ù, điếc, cổ gáy cứng, tâm thần phân liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa gân cơ trụ trước và gân cơ trụ sau, mỏm trâm xương trụ, khe giữa xương tháp và đầu dưới xương trụ.\nThần kinh vận động cơ là các nhánh dây thần kinh quay và trụ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D1."}]},{"id":170,"ten":"Dương Cương","sections":[{"h":"VỊ TRÍ","body":"Dưới gai sống lưng 10, đo ngang ra 3 thốn, huyệt Đởm Du (Bq.19) đo ra 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị gan và mật viêm, vàng da, tiêu chảy, bụng sôi, dạ dày viêm."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 0,8 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ lưng to, cơ răng cưa bé sau – dưới, cơ chậu sườn – ngực, cơ gian sườn 10, phổi hoặc gan.\nThần kinh vận động cơ là nhánh của đám rối cánh tay, nhánh của dây thần kinh gian sườn 10.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D9."}]},{"id":171,"ten":"Dương Giao","sections":[{"h":"VỊ TRÍ","body":"Nằm trên đường nối huyệt Dương Lăng Tuyền (Đ 34) và đỉnh cao mắt cá ngoài, trên mắt cá ngoài 7 thốn, bờ trước xương mác, trong khe cơ mác bên đùi và cơ mác bên ngắn."},{"h":"CHỦ TRỊ","body":"Trị thần kinh tọa đau, cẳng chân đau nhức, hen suyễn."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa cơ mác bên dài và cơ mác bên ngắn, xương mác.\nThần kinh vận động cơ là các nhánh của dây thần kinh cơ – da.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5."}]},{"id":172,"ten":"Dương Kháng","sections":[{"h":"VỊ TRÍ","body":"Giữa nếp mông (huyệt Thừa Phò – Bq.36) đo ra 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị thần kinh tọa đau, di chứng bại liệt trẻ nhỏ."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 3 thốn."}]},{"id":173,"ten":"Dương Khê","sections":[{"h":"VỊ TRÍ","body":"Nghiêng bàn tay, đưa ngón tay thẳng về mu bàn tay để hiện rõ hố lào giữa gân cơ duỗi và dạng ngón cái, huyệt ở sát đầu mỏm trâm xương quay."},{"h":"CHỦ TRỊ","body":"Trị cườm tay, bàn tay đau, bàn tay viêm, đầu đau, răng đau, mắt đau, tai ù, điếc, trẻ nhỏ tiêu hóa kém, sốt."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,3 – 0,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là đầu mỏm châm – xương quay, bờ trên xương thuyền, ngoài có gân cơ dạng dài và gân cơ duỗi ngón tay cái, trong có gân cơ duỗi dài ngón tay cái, gân cơ quay 1.\nThần kinh vận động cơ do các nhánh của dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C8."}]},{"id":174,"ten":"Dương Lăng Tuyền","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm phía trước và dưới đầu nhỏ của xương mác, nơi thân nối với đầu trên xương mác, khe giữa cơ mác bên dài và cơ duỗi chung các ngón chân."},{"h":"CHỦ TRỊ","body":"Trị khớp gối viêm, lưng đùi đau, thần kinh gian sườn đau, túi mật viêm, chóng mặt, hoa mắt, nôn chua, ợ chua, liệt nửa người."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa cơ mác bên dài và cơ duỗi chung các ngón chân, phía trước và trong đầu trên xương mác.\nThần kinh vận động cơ là nhánh của dây thần kinh cơ – da và dây thần kinh chầy trước.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5."}]},{"id":175,"ten":"Dương Phụ","sections":[{"h":"VỊ TRÍ","body":"Trên đỉnh mắt cá ngoài 4 thốn, ở bờ trước xương mác."},{"h":"CHỦ TRỊ","body":"Trị khớp gối viêm, lưng đau, toàn thân bồn chồn, mỏi mệt."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa cơ mác bên ngắn với bờ trước xương mác.\nThần kinh vận động cơ là nhánh của dây thần kinh cơ – da.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5.\nKhông châm sâu quá vì có thể đụng phổi."}]},{"id":176,"ten":"Dương Thỉ","sections":[{"h":"VỊ TRÍ","body":"Tại giữa nếp trong đùi, chỗ có hạch giống như phân dê."},{"h":"CHỦ TRỊ","body":"Trị anh lựu, khí công lên sườn, bụng dưới trướng cấp, sán khí, thiên trụy."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,3 – 0,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút.7\nKE"}]},{"id":177,"ten":"Dương Trì","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm trên lằn ngang khớp xương cổ tay, khe giữa gân cơ duỗi chung ngón tay và cơ duỗi riêng ngón tay trỏ, khe giữa đầu dưới xương quay và xương trụ."},{"h":"CHỦ TRỊ","body":"Trị khớp cổ tay và tổ chức mềm chung quanh viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Châm trị bịnh ở khớp cổ tay, hướng mũi kim qua 2 bên. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa gân cơ duỗi chung ngón tay và duỗi riêng ngón tay trỏ ở ngoài với gân cơ duỗi riêng ngón tay út ở trong, khe giữa đầu dưới xương quay và xương trụ, ở trên xương nguyệt.\nThần kinh vận động cơ là các nhánh của dây thần kinh trụ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C8 hoặc D1.V\n: 31v¼9:"}]},{"id":178,"ten":"Dương Ủy 1","sections":[{"h":"VỊ TRÍ","body":"Bờ trên mặt ngoài xương bánh chè đo lên 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị chi dưới liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 2 thốn."}]},{"id":179,"ten":"Dương Ủy 2","sections":[{"h":"VỊ TRÍ","body":"Bờ trên mặt ngoài xương bánh chè đo lên 5 thốn (trên Dương Ủy 1 khoảng 3 thốn)"},{"h":"CHỦ TRỊ","body":"Trị chi dưới bị tê liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1,5 – 2,5 thốn."}]},{"id":180,"ten":"Dương Ủy 3","sections":[{"h":"VỊ TRÍ","body":"Bờ trên mặt ngoài xương bánh chè đo lên 7 thốn."},{"h":"CHỦ TRỊ","body":"Trị chi dưới bị tê liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 2 – 3 thốn."}]},{"id":181,"ten":"Dương Yểu","sections":[{"h":"VỊ TRÍ","body":"Tại giữa nếp háng."},{"h":"CHỦ TRỊ","body":"Trị sán khí, bệnh ở bộ phận sinh dục ngoài."},{"h":"CHÂM CỨU","body":"Cứu 3 – 7 tráng."}]},{"id":182,"ten":"Dưỡng Lão","sections":[{"h":"VỊ TRÍ","body":"Co khuỷu tay với lòng bàn tay đặt vào ngực, huyệt ở chỗ mỏm trâm xương trụ, từ huyệt Dương Cốc (Ttr 5) đo lên 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị cổ tay đau, chi trên liệt, thần kinh thị giác teo, mắt mờ."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,3 – 0,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ trong của gân cơ trụ sau, phía trong mặt sau của đầu dưới xương trụ.\nThần kinh vận động là nhánh của dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D1."}]},{"id":183,"ten":"Đái Mạch","sections":[{"h":"VỊ TRÍ","body":"Tại trung điểm của đầu xương sườn thứ 11 và 12, ngang với rốn."},{"h":"CHỦ TRỊ","body":"Trị lưng và thắt lưng đau, thần kinh gian sườn đau, bàng quang viêm, màng trong tử cung viêm, kinh nguyệt rối loạn, bạch đái."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ chéo to, cơ chéo bé của bụng, cơ ngang bụng, mạc ngang, phúc mạc, Đại trường hoặc Thận.\nThần kinh vận động cơ là 6 dây thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D11.P\n\""}]},{"id":184,"ten":"Đài Kiên","sections":[{"h":"VỊ TRÍ","body":"Mỏm xương vai đo vào 1,5 thốn hoặc từ huyệt Trung Phủ (P 1) ra phía ngoài 1 thốn, giáp xương khớp vai trong."},{"h":"CHỦ TRỊ","body":"Trị chi trên bị liệt, tay không dơ lên được."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 2 thốn."}]},{"id":185,"ten":"Đài Thoái","sections":[{"h":"VỊ TRÍ","body":"Ở sát cuối bên cơ duỗi mông lớn, từ gai trên – trước xương chậu đo xuống 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị di chứng bại liệt, liệt chi dưới."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 2,5 – 3 thốn."}]},{"id":186,"ten":"Đại Bao","sections":[{"h":"VỊ TRÍ","body":"Tại điểm gặp nhau của đường nách giữa và bờ trên xương sườn 6, hoặc dưới ổ nách 6 thốn, dưới huyệt Uyên Dịch (Đ 22) 3 thốn, nơi bờ ngoài cơ lưng to."},{"h":"CHỦ TRỊ","body":"Trị thần kinh liên sườn đau, ngực tức, suyễn, toàn thân mỏi đau, nặng nề, tay chân uể oải, không muốn hoạt động."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ ngoài cơ lưng to, cơ răng cưa to, các cơ gian sườn 6, bên trong là phổi.\nThần kinh vận động cơ là các nhánh của đám rối cánh tay, dây thần kinh gian sườn 6.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D6.i\t!"}]},{"id":187,"ten":"Đại Chỉ Giáp Căn","sections":[{"h":"VỊ TRÍ","body":"Ở lưng bàn tay, ngay giữa ngón tay thứ 1, trên lằn chỉ ngang đầu tiên, dưới huyệt Trung Thương."},{"h":"CHỦ TRỊ","body":"Trị sốt, họng viêm."},{"h":"CHÂM CỨU","body":"Châm nặn máu."}]},{"id":188,"ten":"Đại Chỉ Giáp Hạ","sections":[{"h":"VỊ TRÍ","body":"Dưới móng chân cái, phía ngoài (sát dưới huyệt Ẩn Bạch – Ty."},{"h":"CHỦ TRỊ","body":"Trị điên cuồng."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,1 – 0,2 thốn."}]},{"id":189,"ten":"Đại Chỉ Tiết Hoành Văn","sections":[{"h":"VỊ TRÍ","body":"Ở lòng bàn tay, từ giữa nếp gấp ngón tay cái hơi lùi ra phía ngoài một ít là huyệt."},{"h":"CHỦ TRỊ","body":"Trị mắt có màng mây."},{"h":"CHÂM CỨU","body":"Cứu 3 tráng. Đau bên phải cứu bên trái và ngược lại. T\nT"}]},{"id":190,"ten":"Đại Chỉ Tụ Mao","sections":[{"h":"VỊ TRÍ","body":"Ở mu ngón chân cái, giữa khớp 1 – 2 ngón cái, ngang chỗ có lông thường mọc."},{"h":"CHỦ TRỊ","body":"Trị trúng phong bất tỉnh, đầu đau, chóng mặt, sán khí, dịch hoàn viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,1 – 0,2 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút.L\nGM"}]},{"id":191,"ten":"Đại Chung","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm tạo nên do gân gót bám vào bờ trên trong xương gót, dưới huyệt Thái Khê 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị gân gót chân đau, lưng đau, tiểu khó, suyễn, táo bón, thần kinh suy nhược, Hysteria."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ trong gân gót chân, phía trước cơ gân của cơ gấp dài ngón chân cái, gân cơ gấp dài các ngón chân, mặt trên xương gót chân.\nThần kinh vận động cơ là các nhánh của dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5."}]},{"id":192,"ten":"Đại Chùy","sections":[{"h":"VỊ TRÍ","body":"Ngồi ngay, hơi cúi đầu xuống một ít, phần dưới cổ nổi lên từ 1 – 3 u xương tròn, đặt lên mỗi u xương một ngón tay rồi bảo người bịnh quay đầu qua lại về bên phải, bên trái, cúi ngửa, u xương tròn nào cao nhất động đậy dưới ngón tay nhiều là đốt sống cổ 7, huyệt ở chỗ lõm ngay dưới đầu mỏm gai của đốt này."},{"h":"CHỦ TRỊ","body":"Trị cổ gáy đau cứng, mệt mỏi, sốt rét, cảm cúm, ho, sườn đau, ngực tức, đau, đờm dãi nhiều, phế quản tiết ứ dịch."},{"h":"CHÂM CỨU","body":"Châm chếch lên, luồn kim dưới mỏm gai, hướng vào khoảng gian đốt sống cổ 7 – lưng 1, sâu 0,5 – 1 thốn. Tùy yêu cầu, có thể làm cho cảm giác lan lên đầu hoặc sang 2 bên vai. Cứu 10 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là gân cơ thang, gân cơ trán, gân cơ răng bé sau – trên, cơ gối đầu, cơ gian gai, cơ ngang gai, dây chằng trên gai, dây chằng gian gai, dây chằng vàng, ống sống.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não XI, các nhánh của đám rối cổ, các nhánh của thần kinh sống.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh"}]},{"id":193,"ten":"Đại Chuỳ Tứ Huyệt","sections":[{"h":"VỊ TRÍ","body":"Giữa gai đốt sống lưng 2 và 3 đo ra mỗi bên 0,6 thốn. Tất cả có 4 huyệt."},{"h":"CHỦ TRỊ","body":"Trị ho gà."},{"h":"CHÂM CỨU","body":"Châm thẳng 0, 3 – 0,5 thốn. Cứu 3 tráng.0I\n)"}]},{"id":194,"ten":"Đại Cốt Không","sections":[{"h":"VỊ TRÍ","body":"Tại giữa khớp 1 và 2 ngón tay cái (gấp ngón tay lại sẽ thấy chỗ trũng)"},{"h":"CHỦ TRỊ","body":"Trị các bệnh về mắt."},{"h":"CHÂM CỨU","body":"Cứu 5 – 10 phút."}]},{"id":195,"ten":"Đại Cự","sections":[{"h":"VỊ TRÍ","body":"Rốn đo xuống 2 thốn (huyệt Thạch Môn (Nh.5), đo ngang ra 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị bàng quang viêm, bụng đau, lỵ, di tinh, mộng tinh."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 2 thốn. Cứu 10 – 20 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ chéo to, cơ thẳng to, mạc ngang, phúc mạc, trong ổ bụng là ruột non, tử cung khi có thai 5 – 6 tháng, bàng quang khi bị bí tiểu tiện vừa.\nThần kinh vận động cơ là 6 dây thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D11."}]},{"id":196,"ten":"Đại Đô","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm nơi khớp đầu xương ngón chân cái, gân xương gan bàn chân, trên đường tiếp giáp lằn da gan bàn chân, mu chân của bờ trong bàn chân."},{"h":"CHỦ TRỊ","body":"Trị bàn chân sưng đau, bụng trướng, dạ dầy đau, sốt cao."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là chỗ bám của gân cơ dạng ngón chân cái, bờ trong đầu sau đốt 1 ngón chân cái.\nThần kinh vận động cơ là nhánh của dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5."}]},{"id":197,"ten":"Đại Đô II","sections":[{"h":"VỊ TRÍ","body":"Tại khe ngón chân 1 và 2 (một trong Bát Phong)"},{"h":"CHỦ TRỊ","body":"Trị đầu đau do phong (đầu phong), răng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,1 – 0,3 thốn. Cứu 7 tráng.0\n,("}]},{"id":198,"ten":"Đại Đô III","sections":[{"h":"VỊ TRÍ","body":"Ở hổ khẩu, giữa ngón tay trỏ và ngón cái, nơi giáp da đỏ và trắng."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, răng đau."},{"h":"CHÂM CỨU","body":"Khép các ngón tay lại, châm thẳng sâu 0,1–0,5 thốn, Cứu 5 tráng.C\nA"}]},{"id":199,"ten":"Đại Đôn","sections":[{"h":"VỊ TRÍ","body":"Tại đốt thứ nhất ngón chân cái, cách bờ ngoài gốc móng khoảng 0,1 thốn (0,2cm)"},{"h":"CHỦ TRỊ","body":"Trị ngón chân cái đau, dịch hoàn viêm, tử cung sa, đau do thoái vị (sán khí), băng lậu, tiểu nhiều, tiểu gắt, đái dầm, tiểu ra máu, bụng dưới đau cơn dữ dội."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,1 – 0,2 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là chỗ bám của gân cơ duỗi dài riêng ngón chân cái vào đốt 2 ngón cái.\nThần kinh vận động cơ là nhánh của dây thần kinh chầy trước.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5."}]},{"id":200,"ten":"Đại Hách","sections":[{"h":"VỊ TRÍ","body":"Rốn đo xuống 4 thốn (huyệt Trung Cực – Nh.4), đo ngang ra 0,5 thốn, trên huyệt Hoành Cốt 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị bạch đới, di mộng tinh, bộ phận sinh dục ngoài đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ chéo to của bụng, cơ tháp, bờ trong cơ thẳng to, mạc ngang, phúc mạc, ruột non hoặc bàng quang khi căng, tử cung khi có thai 3 – 4 tháng.\nThần kinh vận động cơ là 6 nhánh dây thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục."}]},{"id":201,"ten":"Đại Hoành","sections":[{"h":"VỊ TRÍ","body":"Tại điểm gặp nhau của đường ngang qua rốn và đường dọc qua đầu vú."},{"h":"CHỦ TRỊ","body":"Trị quanh rốn đau, ruột liệt, phần phụ viêm, táo bón, tiêu chảy, ký sinh trùng đường ruột."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 5 – 7 tráng, Ôn cứu 5 – 10 phút.\nTrị giun sán, có thể châm xiên hướng kim về phía rốn."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là cơ chéo to, cơ chéo bé của bụng, cơ ngang bụng, mạc ngang, phúc mạc, đại trường lên hoặc xuống.\nThần kinh vận động cơ do 6 dây thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục."}]},{"id":202,"ten":"Đại Lăng","sections":[{"h":"VỊ TRÍ","body":"Ở ngay trên lằn nếp cổ tay, khe giữa gân cơ gan tay lớn và bé, hoặc gấp các ngón tay vào lòng bàn tay, đầu ngón tay giữa chạm vào lằn chỉ (văn) tay ở đâu, đó là huyệt."},{"h":"CHỦ TRỊ","body":"Trị cổ tay đau, khớp cổ tay viêm, hồi hộp, động kinh, mất ngủ."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Trị khớp xương cổ tay thì châm xiên. Cứu 1 – 3 tráng. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa gân cơ gan tay lớn và gân cơ gan tay bé, ở sâu là khe giữa gân cơ gấp dài ngón tay cái và cơ gấp chung ngón tay nông và sâu, khe khớp cổ tay.\nThần kinh vận động cơ là các nhánh của dây thần kinh giữa và dây thần kinh trụ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C7 hoặc C8.V'\n thai và bí tiểu: không châm."}]},{"id":203,"ten":"Đại Luân","sections":[{"h":"VỊ TRÍ","body":"Tại bờ trên gò khớp của xương đùi, phía trong đầu gối."},{"h":"CHỦ TRỊ","body":"Trị khớp gối viêm, trẻ nhỏ sốt cao."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 2 – 3 thốn."}]},{"id":204,"ten":"Đại Mẫu Chỉ Đầu","sections":[{"h":"VỊ TRÍ","body":"Tại sát bờ trên móng ngón tay cái, phía ngón thứ 2."},{"h":"CHỦ TRỊ","body":"Trị phù toàn thân."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,1 – 0,2 thốn. Cứu 5 – 10 phút."}]},{"id":205,"ten":"Đại Môn","sections":[{"h":"VỊ TRÍ","body":"Đường giữa đỉnh đầu, trên điểm cao nhất của ụ chẩm lớn một thốn (sau huyệt Cường Gian 0,5 thốn)"},{"h":"CHỦ TRỊ","body":"Trị liệt do tai biến mạch máu não."},{"h":"CHÂM CỨU","body":"Châm xiên 1 – 1,5 thốn."}]},{"id":206,"ten":"Đại Nghênh","sections":[{"h":"VỊ TRÍ","body":"Cắn chặt răng lại, huyệt ở sát bờ trước cơ cắn và trên bờ dưới xương hàm dưới, ngang một khoát ngón tay, ngay trên rãnh động mạch mặt."},{"h":"CHỦ TRỊ","body":"Trị răng đau, má sưng, mặt liệt, tuyến mang tai viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng hoặc xiên về huyệt Giáp Xa – Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ dưới cơ cười, cơ mút, sát bờ trước cơ cắn, rãnh động mạch mặt của xương hàm dưới.\nThần kinh vận động cơ là các nhánh của dây thần kinh sọ não số VII và dây thần kinh sọ não số V.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V."}]},{"id":207,"ten":"Đại Trử","sections":[{"h":"VỊ TRÍ","body":"Huyệt là điểm gặp nhau của đường ngang qua mỏm gai đốt sống lưng thứ nhất và đường thẳng đứng ngoài Đốc Mạch 1,5 thốn, ngang huyệt Đào Đạo (Đc 13)"},{"h":"CHỦ TRỊ","body":"Trị cổ vẹo, cổ gáy cứng, cơ vai lưng đau và co rút, ho, sốt."},{"h":"CHÂM CỨU","body":"Châm xiên, hướng mũi kim về phía đốt sống sâu 0,5 – 0,8 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ thang, cơ trám hoặc cơ thoi, cơ răng bé sau – trên, cơ gối cổ, cơ ngang sườn, rồi vào phổi.\nThần kinh vận động cơ là nhánh dây thần kinh sọ não số XI, nhánh đám rối cổ sâu, nhánh đám rối cánh tay, dây thần kinh sống lưng và dây thần kinh gian sườn 1.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C8.H)\"H5/=ci2Thất tinh, bộ phận sinh dục rút lên, trong ngọc hành đau: cứu Đại Hách” (Bị Cấp Cứu Pháp)"}]},{"id":208,"ten":"Đại Trường Du","sections":[{"h":"VỊ TRÍ","body":"Dưới gai sống thắt lưng 4, đo ngang ra 1,5 thốn, ngang huyệt Yêu Dương Quan (Đc 3)"},{"h":"CHỦ TRỊ","body":"Trị lưng đau, các cơ vùng lưng co giật, tiêu chảy, tiêu hóa kém, táo bón, chi dưới liệt, thần kinh tọa đau."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 1,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 15 phút.\nTrị thần kinh tọa đau: hướng mũi kim xiên ra bên ngoài.\nTrị khớp chậu, háng đau: mũi kim hướng về huyệt Tiểu Trường Du."},{"h":"GIẢI PHẪU","body":"Dưới da là cân ngực – thắt lưng của cơ lưng to, khối cơ chung của các cơ rãnh cột sống. Trước mỏm ngang có cơ vuông thắt lưng, cơ đái – chậu.\nThần kinh vận động cơ là nhánh của đám rối cánh tay, nhánh của dây sống thắt lưng 4, nhánh của đám rối thắt lưng.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L3 hoặc L4."}]},{"id":209,"ten":"Đại Tuyền","sections":[{"h":"VỊ TRÍ","body":"Tại điểm nếp nách trong chạm với ngực."},{"h":"CHỦ TRỊ","body":"Trị vai đau, tay đau, ngực đau, sườn đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn."}]},{"id":210,"ten":"Đàm Suyễn","sections":[{"h":"VỊ TRÍ","body":"Thẳng đầu vú lên đến bờ sườn thứ 4 (huyệt Ưng Song – Vi 16) ra ngang 1,8 thốn."},{"h":"CHỦ TRỊ","body":"Trị suyễn, khí quản viêm mạn."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,5 – 0,8 thốn.O\nR"}]},{"id":211,"ten":"Đào Đạo","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm dưới đầu mỏm gai đốt sống lưng 1, ngay dưới huyệt Đại Chùy một đốt sống."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, cột sống đau, lưng đau, cột sống yếu, sốt rét, cảm cúm, sốt âm, mồ hôi trộm, hoảng sợ."},{"h":"CHÂM CỨU","body":"Châm chếnh lên, luồn dưới mỏm gai, hướng vào khoảng gian đốt sống lưng 1 – 2, sâu 0,3 – 1 thốn. Cứu 10 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là gân cơ thang, gân cơ trám hoặc cơ thoi, gân cơ răng bé sau – trên, cơ gối đầu, cơ gai dài của lưng, cơ ngang gai, dây chằng trên gai, dây chằng gian gai, dây chằng vàng, ống sống.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số XI, các nhánh của đám rối cổ, các nhánh của dây thần kinh sống.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D1.\nTrị trúng phong bán thân bất toại: Trước tiên cứu huyệt Thiên Song (Ttr.16), kế đến là huyệt Đại Môn (trên điểm cao nhất của ụ chẩm lớn một thốn), rồi cứu huyệt Thừa Tương (Nh.24)...” (Thiên Kim Dực)"}]},{"id":212,"ten":"Đầu Duy","sections":[{"h":"VỊ TRÍ","body":"Nơi góc trán, cách bờ chân tóc 0,5 thốn, trên đường khớp đỉnh trán, từ huyệt Thần Đình (Đc 24) đo ra 4 thốn."},{"h":"CHỦ TRỊ","body":"Trị nửa đầu đau (Migraine), thần kinh trước trán đau, mí mắt rung giật."},{"h":"CHÂM CỨU","body":"Châm xiên dưới da 0,5 – 1 thốn. Không cứu (Giáp Ất Kinh)"},{"h":"GIẢI PHẪU","body":"Dưới da là chỗ cơ thái dương dính vào cân sọ, dưới cân sọ là xương sọ.\nThần kinh vận động cơ là nhánh dây thần kinh sọ não số V.\nDa vùng huyệt chi phối bởi thần kinh sọ não số V."}]},{"id":213,"ten":"Đầu Hạc Đính","sections":[{"h":"VỊ TRÍ","body":"Trên đường chính giữa đầu, từ chân tóc trước trán đo ra phía sau 3,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị đinh nhọt."},{"h":"CHÂM CỨU","body":"Cứu 3 – 5 tráng.0K\n+"}]},{"id":214,"ten":"Đầu Khiếu Âm","sections":[{"h":"VỊ TRÍ","body":"Tại trung điểm của đoạn nối hai huyệt Phù Bạch (Đ 10) và Hoàn Cốt (Đ 12)"},{"h":"CHỦ TRỊ","body":"Trị đầu đau, gáy đau, tai ù, điếc."},{"h":"CHÂM CỨU","body":"Châm xiên dưới da 0,3 – 0,5 thốn. Cứu 1 – 3 tráng, Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ tai sau, cơ chẩm, đường khớp xương thái dương chẩm.\nThần kinh vận động cơ là các nhánh của dây thần kinh mặt và nhánh của dây thần kinh chẩm lớn.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C2."}]},{"id":215,"ten":"Đầu Lâm Khấp","sections":[{"h":"VỊ TRÍ","body":"Từ huyệt Dương Bạch (Đ 14) đo thẳng lên trong chân tóc 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, răng đau."},{"h":"CHÂM CỨU","body":"Châm dưới da 0,3 – 0,5 thốn. Cứu 1 – 3 tráng. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là chỗ cơ trán dính vào cân sọ, xương trán.\nThần kinh vận động cơ là nhánh của dây thần kinh mặt.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V.J\nAA+A355"}]},{"id":216,"ten":"Đầu Phong","sections":[{"h":"VỊ TRÍ","body":"Đứng thẳng, thõng tay áp vào đùi, khe ngón tay cái và ngón trỏ chạm vào đùi ở đâu, đó là huyệt."},{"h":"CHỦ TRỊ","body":"Trị đầu phong, chóng mặt"},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút."}]},{"id":217,"ten":"Đầu Quang Minh","sections":[{"h":"VỊ TRÍ","body":"Giữa lông mày (huyệt Ngư Yêu) đo thẳng lên 0,3 thốn."},{"h":"CHỦ TRỊ","body":"Trị mi mắt sụp, mắt lé (lác), hố trên mắt đau."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,2 – 0,3 thốn.5\n/"}]},{"id":218,"ten":"Đầu Trửu","sections":[{"h":"VỊ TRÍ","body":"Hơi co tay vào ngực, huyệt ở phía trước và dưới lồi xương khuỷu tay."},{"h":"CHỦ TRỊ","body":"Trị khuỷu tay sưng đau, lao hạch (loa lịch)"},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn.E\n-a"}]},{"id":219,"ten":"Đệ Cửu Chùy Huyệt","sections":[{"h":"VỊ TRÍ","body":"Trên khe đốt sống lưng thứ 9."},{"h":"CHỦ TRỊ","body":"Trị mắt có màng mộng."},{"h":"CHÂM CỨU","body":"Cứu.7\nu"}]},{"id":220,"ten":"Đệ Nhị Thập Nhất Chùy Huyệt","sections":[{"h":"VỊ TRÍ","body":"Trên khe đốt sống thứ 21."},{"h":"CHỦ TRỊ","body":"Trị lưng và thắt lưng khó xoay trở, gân cơ co rút."},{"h":"CHÂM CỨU","body":"Cứu."}]},{"id":221,"ten":"Đệ Nhị Thập Nhị Chùy Huyệt","sections":[{"h":"VỊ TRÍ","body":"Trên khe đốt sống thứ 22."},{"h":"CHỦ TRỊ","body":"Trị lưng và thắt lưng khó xoay trở, gân cơ co rút, hư nhiệt bế tắc."},{"h":"CHÂM CỨU","body":"Cứu, tùy theo tuổi.=\nD"}]},{"id":222,"ten":"Đệ Thập Ngũ Chùy Huyệt","sections":[{"h":"VỊ TRÍ","body":"Khe đốt sống thắt lưng 15 ra ngang 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị trẻ nhỏ bị cam, ghẻ lở."},{"h":"CHÂM CỨU","body":"Cứu 7 tráng."}]},{"id":223,"ten":"Đệ Thất Chùy Huyệt","sections":[{"h":"VỊ TRÍ","body":"Khe đốt sống ngực thứ 7 ra ngang 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị táo bón."},{"h":"CHÂM CỨU","body":"Cứu 7 tráng."}]},{"id":224,"ten":"Địa Cơ","sections":[{"h":"VỊ TRÍ","body":"Ở sát bờ sau trong xương chầy, dưới đường khớp ngang đầu gối 5 thốn, dưới huyệt Âm Lăng Tuyền 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị kinh nguyệt rối loạn, thống kinh, lưng đau, tiểu khó, đại trường viêm cấp, phù thũng."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ sau – trong xương chầy, chỗ bám của cơ sinh đôi trong, cơ dép là cơ gấp dài các ngón chân, cơ cẳng chân sau.\nThần kinh vận động cơ là các nhánh của dây chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L4."}]},{"id":225,"ten":"Địa Hợp","sections":[{"h":"VỊ TRÍ","body":"Điểm cao nổi lên ở phía trước chính giữa cằm (ngay dưới huyệt Thừa Tương)"},{"h":"CHỦ TRỊ","body":"Trị răng hàm dưới đau, liệt mặt."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,3 – 0,5 thốn.K\n!"}]},{"id":226,"ten":"Địa Ngũ Hội","sections":[{"h":"VỊ TRÍ","body":"Ở trong khoảng gian đốt xương bàn chân thứ 4 và 5, chỗ lõm trước gân cơ duỗi ngón út và cơ duỗi chung các ngón chân, cách huyệt Túc Lâm Khấp 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị tuyến vú viêm, vùng nách đau, tai ù."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Cứu 1 – 3 tráng. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa gân duỗi ngón 4 và 5 của cơ duỗi dài các ngón chân, cơ gian cốt mu chân, khe giữa các đầu trước của xương bàn chân 4 và 5.\nThần kinh vận động cơ là các nhánh của dây thần kinh chầy trước và nhánh của dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S1."}]},{"id":227,"ten":"Địa Thần","sections":[{"h":"VỊ TRÍ","body":"Tại chỗ lõm cuối nếp gấp ngón – bàn tay của ngón tay cái (bờ trên mô ngón cái)"},{"h":"CHỦ TRỊ","body":"Trị chết do thắt cổ."},{"h":"CHÂM CỨU","body":"Cứu 7 tráng."}]},{"id":228,"ten":"Địa Thương","sections":[{"h":"VỊ TRÍ","body":"Cách khóe miệng 0,4 thốn, hoặc trên đường ngang qua mép và rãnh mép mũi."},{"h":"CHỦ TRỊ","body":"Trị liệt mặt, dây thần kinh tam thoa đau, chảy nước miếng."},{"h":"CHÂM CỨU","body":"Châm xiên.\nChâm trị liệt mặt: luồn kim tới huyệt Giáp Xa.\nTrị thần kinh tam thoa đau: châm mũi kim hướng tới huyệt Nghênh Hương.\nÔn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là chỗ đan chéo thớ của cơ vòng môi, cơ gò má lớn, cơ cười, cơ tam giác môi, vào sâu có cơ mút và cơ nanh.\nThần kinh vận động cơ là các nhánh của dây thần kinh sọ não số VII.\nDa vùng huyệt chi phối bởi tiết đọan thần kinh sọ não"}]},{"id":229,"ten":"Điên Khốn","sections":[{"h":"VỊ TRÍ","body":"Tại giữa đường nối huyệt Đại Chùy (Đc 14) và Trường Cường (Đc 1). Tương đương gai đốt sống lưng thứ 11."},{"h":"CHỦ TRỊ","body":"Trị động kinh (Châm cứu Học Thượng Hải), Lưng đau, vàng da, tiểu đường (Châm cứu Học HongKong)"},{"h":"CHÂM CỨU","body":"Cứu.h\n B"}]},{"id":230,"ten":"Điều Khẩu","sections":[{"h":"VỊ TRÍ","body":"Ở giữa đoạn nối huyệt Độc Tỷ (Vi 35) và Giải Khê (Vi 41), cách dưới mắt gối ngoài 8 thốn, ngay dưới Thượng Cự Hư 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị chân đau và liệt, khớp gối viêm, dạ dầy viêm, ruột viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa cơ cẳng chân trước và cơ duỗi chung các ngón chân, vào sâu là bờ trong cơ duỗi dài riêng ngón chân cái, khe giữa xương chầy và xương mác, màng gian cốt.\nThần kinh vận động cơ là các nhánh của dây thần kinh chầy trước.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5."}]},{"id":231,"ten":"Đinh Căn","sections":[{"h":"VỊ TRÍ","body":"Khe gai đốt sống lưng 7 (D 7) đo ra hai bên mỗi bên 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị đinh nhọt."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 0,7 thốn."}]},{"id":232,"ten":"Đinh Du","sections":[{"h":"VỊ TRÍ","body":"Cuối lằn chỉ cổ tay trong (huyệt Thần Môn) lên 4 thốn."},{"h":"CHỦ TRỊ","body":"Trị đinh nhọt, buồn phiền."},{"h":"CHÂM CỨU","body":"Cứu.7\n]"}]},{"id":233,"ten":"Đính Thượng Hồi Mao","sections":[{"h":"VỊ TRÍ","body":"Tại chính giữa xoáy tóc ở đỉnh đầu."},{"h":"CHỦ TRỊ","body":"Trị trẻ nhỏ bị động kinh, sa trực trường, trĩ ra máu."},{"h":"CHÂM CỨU","body":"Cứu 3 – 5 tráng."}]},{"id":234,"ten":"Đình Đầu","sections":[{"h":"VỊ TRÍ","body":"Rốn đo xuống 4,5 thốn ra 0,5 thốn hoặc từ huyệt Đại Hách (Th 12) xuống 0,5 thốn rồi ra ngang 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị tử cung sa."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 1,5 thốn.g\n4"}]},{"id":235,"ten":"Đính Chùy","sections":[{"h":"VỊ TRÍ","body":"Giữa khe đốt sống cổ 7."},{"h":"CHỦ TRỊ","body":"Trị tiêu khát, tiểu đường."},{"h":"CHÂM CỨU","body":"Cứu 3 – 7 tráng."}]},{"id":236,"ten":"Định Suyễn","sections":[{"h":"VỊ TRÍ","body":"Gai đốt sống cổ thứ 7 (huyệt Đại Chùy) ra ngang 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị ho, suyễn, khí quản viêm, phong ngứa, mề đay, dị ứng, cổ vẹo cứng."},{"h":"CHÂM CỨU","body":"Châm mũi kim hướng về phía cột sống, sâu 1 – 1,5 thốn."}]},{"id":237,"ten":"Đoài Đoan","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ nhọn của môi trên, ngay dưới rãnh nhân trung, chỗ tiếp giáp giữa da và niêm mạc môi trên."},{"h":"CHỦ TRỊ","body":"Trị môi đau cứng, lợi răng đau, điên cuồng."},{"h":"CHÂM CỨU","body":"Châm thẳng hoặc xiên 0,2 – 0,5 thốn. Không cứu."},{"h":"GIẢI PHẪU","body":"Dưới da là niêm mạc môi và bờ dưới các cơ vòng môi trên.\nThần kinh vận động cơ là các nhánh của dây sọ não số VII.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V."}]},{"id":238,"ten":"Đoan Chính","sections":[{"h":"VỊ TRÍ","body":"Tại giữa lằn chỉ khớp ngón tay thứ 2 và 3 của ngón tay giữa."},{"h":"CHỦ TRỊ","body":"Trị cam tích."},{"h":"CHÂM CỨU","body":"Châm xiên 0,1 – 0,2 thốn."}]},{"id":239,"ten":"Đoan Đổng","sections":[{"h":"VỊ TRÍ","body":"Khe giữa đốt sống cùng 1 (S1) ra 1,5 thốn (huyệt Tiểu Trường Du) đo xuống 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị táo bón, tiểu bí, lưng đau, bụng dưới đau."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn."}]},{"id":240,"ten":"Đoàn Cương","sections":[{"h":"VỊ TRÍ","body":"Nằm sấp, huyệt ở lỗ xương cùng 1 (S1) đo xuống 2 thốn, rồi từ giữa cột sống đo ngang ra hai bên mỗi bên 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị lưng đau xuống đến thắt lưng, tiểu khó, tiêu khó."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 thốn.r\n6)"}]},{"id":241,"ten":"Đoàn Khu","sections":[{"h":"VỊ TRÍ","body":"Mỏm gai đốt sống cùng 1 (S1) ra ngang 1,5 thốn (huyệt Tiểu Trường Du), xuống 2 thốn rồi ra ngang 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị táo bón, lưng đau lan đến ngực."},{"h":"CHÂM CỨU","body":"Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút."}]},{"id":242,"ten":"Đoạn Hộ","sections":[{"h":"VỊ TRÍ","body":"Nằm ngửa, từ lỗ rốn đo xuống 2,3 thốn (ngay sát huyệt Tuyệt Dựng)"},{"h":"CHỦ TRỊ","body":"Trị không có con, kiết lỵ lâu ngày nơi trẻ nhỏ."},{"h":"CHÂM CỨU","body":"Cứu 3 – 49 tráng.C\n0-"}]},{"id":243,"ten":"Đoạn Hồng","sections":[{"h":"VỊ TRÍ","body":"Tại lưng bàn tay, chỗ khe giữa ngón 2 – 3, ngay trên huyệt Bát tà 2."},{"h":"CHỦ TRỊ","body":"Trị băng huyết, rong kinh, kinh nguyệt không đều, tử cung xuất huyết cơ năng."},{"h":"CHÂM CỨU","body":"Châm xiên 450 hướng về phía ngón 3, sâu 0,2 – 0,3 thốn."}]},{"id":244,"ten":"Đoạt Mệnh","sections":[{"h":"VỊ TRÍ","body":"Hơi nghiêng cánh tay, huyệt ở giữa đường nối mỏm vai và lằn chỉ khuỷu tay."},{"h":"CHỦ TRỊ","body":"Trị chóng mặt, hoa mắt, mắt có quầng thâm, phía trên cánh tay đau, bụng đau, phúc mạc viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 thốn. Cứu 5 – 7 tráng."}]},{"id":245,"ten":"Đốc Du","sections":[{"h":"VỊ TRÍ","body":"Dưới gai đốt sống lưng 6, đo ngang ra 1,5 thốn, ngang huyệt Linh Đài (Đc 10)"},{"h":"CHỦ TRỊ","body":"Trị trong và ngoài màng tim viêm, sôi ruột, bụng đau, nấc cụt, tóc rụng, ngoài da ngứa."},{"h":"CHÂM CỨU","body":"Châm xiên về cột sống 0,5 – 0,8 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ thang, cơ lưng to, cơ lưng dài, cơ bán gai của ngực, cơ ngang gai, cơ ngang sườn, vào trong là phổi.\nThần kinh vận động cơ là nhánh dây thần kinh sọ não số XI, nhánh đám rối cổ sâu, nhánh đám rối cánh tay, nhánh của dây thần kinh gian sườn 6 và nhánh của dây sống lưng 6.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D3."}]},{"id":246,"ten":"Đốc Mạch","sections":[{"h":"VỊ TRÍ","body":"Chính giữa bờ tóc trước, lui về phía sau 0,2 thốn, trước huyệt Thần đình 0,3 thốn."},{"h":"CHỦ TRỊ","body":"Trị trẻ nhỏ co giật, động kinh."},{"h":"CHÂM CỨU","body":"Cứu 30 tráng.S 6"}]},{"id":247,"ten":"Đốc Tích","sections":[{"h":"VỊ TRÍ","body":"Tại giữa đốt sống cổ thứ 7 (ngay trên huyệt Đại Chùy)"},{"h":"CHỦ TRỊ","body":"Trị trẻ nhỏ bị động kinh (bạo giản)"},{"h":"CHÂM CỨU","body":"Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."}]},{"id":248,"ten":"Độc Âm","sections":[{"h":"VỊ TRÍ","body":"Lòng bàn chân, ngay giữa nếp thứ nhất ngón chân thứ 2."},{"h":"CHỦ TRỊ","body":"Trị kinh nguyệt không đều, khó sinh, trục thai ra."},{"h":"CHÂM CỨU","body":"Cứu 10 – 15 phút."}]},{"id":249,"ten":"Độc Tỵ","sections":[{"h":"VỊ TRÍ","body":"Ngồi co đầu gối, huyệt ở chỗ lõm dưới góc dưới – ngoài xương bánh chè và ở ngoài gân cơ tứ đầu đùi."},{"h":"CHỦ TRỊ","body":"Trị khớp gối viêm, bệnh thuộc tổ chức phần mềm quanh khớp gối."},{"h":"CHÂM CỨU","body":"Châm hướng về giữa đầu gối, sâu 1 – 1,5 thốn. Cứu 5 – 7 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa cơ 4 đầu đùi và gân cơ căng cân đùi, góc ngoài bờ dưới xương bánh chè và khe khớp gối.\nThần kinh vận động cơ là các nhánh dây thần kinh đùi và nhánh của dây thần kinh mông trên.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L3."}]},{"id":250,"ten":"Đồn Trung","sections":[{"h":"VỊ TRÍ","body":"Lấy đoạn thẳng nối từ mấu chuyển lớn của xương đùi đến ụ ngồi làm đáy của hình tam giác đều, rồi đặt 2 cạnh lên trên làm đỉnh, huyệt ở tại đỉnh."},{"h":"CHỦ TRỊ","body":"Trị thần kinh tọa đau, chân lạnh, chi dưới liệt, mề đay."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 2 thốn."}]},{"id":251,"ten":"Đồng Minh","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm sát đường khớp của mỏm ngoài ổ mắt – xương gò má và xương trán (huyệt Đồng Tử Liêu – Đ.1) đo xuống 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị mắt lác, mắt lé."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,5 – 0,8 thốn."}]},{"id":252,"ten":"Đồng Tử Liêu","sections":[{"h":"VỊ TRÍ","body":"Cách góc ngoài mắt 0,5 thốn, chỗ lõm sát ngoài đường khớp của mỏm ngoài ổ mắt."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, liệt mặt, các bệnh về mắt."},{"h":"CHÂM CỨU","body":"Châm xiên dưới da 0,3 – 0,5 thốn, hướng mũi kim tới huyệt Thái Dương. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ ngoài và các bó phụ của cơ vòng miệng, cơ thái dương, chỗ tiếp khớp của xương gò má, xương trán và xương thái dương.\nThần kinh vận động cơ là nhánh của dây thần kinh mặt để nhánh dây thần kinh sọ não số V."}]},{"id":253,"ten":"Đởm Du","sections":[{"h":"VỊ TRÍ","body":"Dưới gai sống lưng 10, đo ngang ra 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị lưng đau, gan viêm, túi mật viêm, nôn mửa."},{"h":"CHÂM CỨU","body":"Châm xiên về cột sống 0,5 – 0,8 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ lưng to, cơ lưng dài, cơ bán gai của ngực, cơ ngang gai, cơ ngang sườn. Bên trái là Phổi, bên phải là Gan.\nThần kinh vận động cơ là nhánh của đám rối cánh tay, nhánh của dây thần kinh gian sườn 10 và nhánh của dây sống lưng 10.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D10.\nKxx3Bụng có nhiệt bế, táo bón, lưng đau lan đến ngực, cứu huyệt Đoàn Khu 100 tráng...” (Thiên Kim Phương)"}]},{"id":254,"ten":"Đởm Giáng","sections":[{"h":"VỊ TRÍ","body":"Từ chót dưới xương ức (xương mũi kiếm, dọc theo bờ cung sườn 1,5 thốn, sau đó thẳng xuống 2 thốn.\nHuyệt chỉ ở bên tay phải mà thôi."},{"h":"CHỦ TRỊ","body":"Trị ăn ít, bụng trướng, tiêu chảy, ợ hơi, sườn ngực đau chói."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1,5 – 2 thốn."}]},{"id":255,"ten":"Đởm Nang Huyệt","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm dưới bờ trước đầu xương mác, dưới huyệt Dương Lăng Tuyền 1 – 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị bệnh đường mật (mật có sạn, giun chui ống mật...), chi dưới liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 2 thốn."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là cơ mác dài ngắn, dây thần kinh hông khoeo ngoài và dây thần kinh hông khoeo trong.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L4 và S1."}]},{"id":256,"ten":"Đức Dữ","sections":[{"h":"VỊ TRÍ","body":"Từ đường chính giữa ngực ngang với bờ trên sườn thứ hai đo ngang ra hai bên 2,2 thốn."},{"h":"CHỦ TRỊ","body":"Trị hôn mê, bất tỉnh."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,3 thốn.V\nF"}]},{"id":257,"ten":"Đương Dương","sections":[{"h":"VỊ TRÍ","body":"Thẳng đồng tử mắt lên, sau chân tóc trán 1 thốn (sau huyệt Đầu Lâm Khấp 0,5 thốn)"},{"h":"CHỦ TRỊ","body":"Trị đầu đau, chóng mặt, cảm, mũi nghẹt, mắt sưng đỏ đau."},{"h":"CHÂM CỨU","body":"Châm luồn dưới da, sâu 0,3 – 0,5 thốn. Cứu 1 – 3 tráng. Ôn cứu 3 – 5 phút.S\n9K"}]},{"id":258,"ten":"Ế Minh","sections":[{"h":"VỊ TRÍ","body":"Phía sau huyệt Ế Phong 1 thốn (Châm Cứu Học Thượng Hải).\nGiữa đường nối huyệt Phong Trì (Đ.20) và Ế Phong [Ttu.17] (Châm Cứu Học HongKong)"},{"h":"CHỦ TRỊ","body":"Trị cận thị, viễn thị, quáng gà, thần kinh thị giác teo, mắt mờ, điếc, tai ù, chóng mặt, tuyến mang tai viêm, mất ngủ, đầu đau, bệnh tâm thần."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn.j:\n6"}]},{"id":259,"ten":"Ế Minh Hạ","sections":[{"h":"VỊ TRÍ","body":"Điểm giũa huyệt Phong Trì (Đ.20) và Ế Phong (Ttu17) [tức là huyệt Ế Minh] đo xuống 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị điếc."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn."}]},{"id":260,"ten":"Ế Phong","sections":[{"h":"VỊ TRÍ","body":"Phía sau trái tai, nơi chỗ lõm giữa góc hàm dưới và gai xương chũm, sau mỏm nhọn cao nhất của trái tai, sát bờ trước cơ ức đòn chũm."},{"h":"CHỦ TRỊ","body":"Trị điếc, tai ù, tai lãng, tuyến mang tai viêm, thần kinh mặt liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn, hoặc hướng mũi kim về phía mắt đối diện. Cứu 1 – 3 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là phía trước bờ trước cơ ức–đòn–chũm, cơ trâm hầu, trâm móng, trâm lưỡi và cơ 2 thân, trên các cơ bậc thang.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số XI và XII, nhánh của dây cổ số 3, 4, 5.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C2."}]},{"id":261,"ten":"Giác Tôn","sections":[{"h":"VỊ TRÍ","body":"Gấp vành tai về phía trước, huyệt ở bờ trên loa tai, trong chân tóc nơi có cơ cử động khi há miệng nhai, dưới huyệt là cơ tai trên, cơ thái dương."},{"h":"CHỦ TRỊ","body":"Trị tai nóng đỏ, vành tai viêm, mộng thịt mắt, răng đau, quai bị (đốt bằng bấc đèn)"},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn. Cứu 1 – 3 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ tai trên, cơ thái dương, xương thái dương.\nThần kinh vận động cơ là nhánh của dây thần kinh mặt và nhánh của dây thần kinh sọ não V.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C2."}]},{"id":262,"ten":"Giải Khê","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm trên nếp gấp trước khớp cổ chân, giữa 2 gân cơ cẳng chân trước và gân cơ duỗi dài ngón chân cái."},{"h":"CHỦ TRỊ","body":"Trị tổ chức phần mềm quanh khớp cổ chân bị viêm, cơ cẳng chân teo, thiếu máu não, thận viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 1 thốn, Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa gân cơ cẳng chân trước và gân cơ duỗi dài riêng ngón chân cái, khe khớp mác – chầy – sên.\nThần kinh vận động cơ là các nhánh của dây thần kinh chầy trước.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5 –"}]},{"id":263,"ten":"Giải Suyễn","sections":[{"h":"VỊ TRÍ","body":"Lỗ xương cùng 1 (S1 – Thượng Liêu) và lỗ xương cùng 2 (S2 – Thứ liêu) đo ngang ra hai bên mỗi bên 1 thốn."},{"h":"CHỦ TRỊ","body":"Bình suyễn, trị hen suyễn."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1,5 thốn, sau khi đắc khí, vê kim 10 – 15 phút rồi rút kim."}]},{"id":264,"ten":"Gian Sử","sections":[{"h":"VỊ TRÍ","body":"Bàn tay để ngửa, huyệt ở trên lằn chỉ cổ tay 3 thốn, giữa khe gân cơ gan tay lớn và bé."},{"h":"CHỦ TRỊ","body":"Trị hồi hộp, vùng trước tim đau, sốt rét, động kinh, tâm thần phân liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 1 thốn. Cứu 3–5 tráng. Ôn cứu 5–10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa gân cơ gan tay lớn và gân cơ gan tay bé, gân cơ gấp dài ngón tay cái, cơ gấp chung các ngón tay nông và sâu, bờ trên cơ sấp vuông, màng gian cốt.\nThần kinh vận động cơ là các nhánh của dây thần kinh giữa và dây thần kinh trụ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C6 hoặc"}]},{"id":265,"ten":"Giang Môn Tứ Huyệt","sections":[{"h":"VỊ TRÍ","body":"Quanh hậu môn, phía trên, dưới, bên phải, bên trái, mỗi bên đo ra 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị đại tiện không tự chủ do liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,2 thốn."}]},{"id":266,"ten":"Giáng Áp","sections":[{"h":"VỊ TRÍ","body":"Tại mu bàn chân, giữa khe bàn chân ngón thứ nhất, cách gốc móng chân cái một thốn."},{"h":"CHỦ TRỊ","body":"Trị huyết áp cao."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 thốn."}]},{"id":267,"ten":"Giao Tín","sections":[{"h":"VỊ TRÍ","body":"Huyệt Thái Khê (Th 3) đo lên 2 thốn, trước huyệt Phục Lưu 0,5 thốn, cạnh bờ sau trong xương chầy."},{"h":"CHỦ TRỊ","body":"Trị kinh nguyệt rối loạn, băng lậu, tiêu chảy, táo bón, cẳng chân sưng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 2 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa gân cơ gấp dài ngón chân cái và gân cơ gấp dài các ngón chân, mặt sau đầu dưới xương chầy.\nThần kinh vận động cơ là các nhánh của dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L4.\nChâm đắc khí có cảm giác căng tức hoặc như điện giật nửa đầu bên châm."}]},{"id":268,"ten":"Giảo Cơ","sections":[{"h":"VỊ TRÍ","body":"Khoé miệng đo thẳng xuống 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị niêm mạc miệng viêm loét, liệt mặt, thần kinh mặt co giật."},{"h":"CHÂM CỨU","body":"Châm xiên, luồn mũi kim hướng mũi kim về giữa rãnh môi – cằm."}]},{"id":269,"ten":"Giáp Căn","sections":[{"h":"VỊ TRÍ","body":"Tại đầu góc móng phía trong và ngoài ngón chân cái, có 4 huyệt."},{"h":"CHỦ TRỊ","body":"Trị sán khí."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,1 thốn."}]},{"id":270,"ten":"Giáp Lý","sections":[{"h":"VỊ TRÍ","body":"Trong xoang miệng, ở màng trong của má, gần vùng răng cấm 1."},{"h":"CHỦ TRỊ","body":"Trị hoàng đản, hàn thử ôn dịch."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,1 – 0,3 thốn."}]},{"id":271,"ten":"Giáp Nhân Trung","sections":[{"h":"VỊ TRÍ","body":"Ở ngang 2 bên huyệt Nhân Trung, chỗ nước mũi chảy qua."},{"h":"CHỦ TRỊ","body":"Cấp cứu, trị hôn mê, bất tỉnh."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,2 – 0,3 thốn."}]},{"id":272,"ten":"Giáp Phùng","sections":[{"h":"VỊ TRÍ","body":"Tại phía sau lưng, đỉnh nếp nách – tay ra ngang 2,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị vai lưng đau lan đến giáp nách."},{"h":"CHÂM CỨU","body":"Châm luồn dưới da, sâu 1 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."}]},{"id":273,"ten":"Giáp Thừa Tương","sections":[{"h":"VỊ TRÍ","body":"Tại giao điểm của đường ngang qua huyệt Thừa Tương (Nh 24) và đường thẳng từ Địa Thương (Vi 4) kéo xuống. Nơi chỗ lõm của xương hàm dưới."},{"h":"CHỦ TRỊ","body":"Trị thần kinh tam thoa đau, liệt mặt, thần kinh mặt co giật."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,2 – 0,5 thốn (liệt mặt) hoặc châm xiên vào phía dưới bên trong (trị thần kinh tam thoa đau)"}]},{"id":274,"ten":"Giáp Thượng Tinh","sections":[{"h":"VỊ TRÍ","body":"Giữa đường chân tóc trán lên 1 thốn (huyệt Thượng Tinh – Đc.23) rồi đo ra 2 bên, mỗi bên 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị mũi có thịt dư (polyp mũi)"},{"h":"CHÂM CỨU","body":"Cứu 100 tráng."}]},{"id":275,"ten":"Giáp Tỵ","sections":[{"h":"VỊ TRÍ","body":"Tại giao điểm của sụn mũi và xương mũi."},{"h":"CHỦ TRỊ","body":"Trị mũi có nhọt, mũi có mùi hôi, mũi viêm dạng teo, mũi viêm dị ứng."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,1 thốn. Lưu kim lâu, kích thích mạnh.-(\nEâ"}]},{"id":276,"ten":"Giáp Xa","sections":[{"h":"VỊ TRÍ","body":"Cắn chặt răng lại, huyệt ở trước góc hàm và ở trên bờ dưới xương hàm dưới một khoát ngón tay, đè vào chỗ lõm có cảm giác ê tức."},{"h":"CHỦ TRỊ","body":"Trị răng đau, mặt liệt, cơ nhai co rút, khớp hàm dưới viêm, tuyến mang tai viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn hoặc xiên tới huyệt Địa Thương (trị mặt liệt), hoặc hướng mũi kim lên trên (trị cơ nhai bị co rút) hoặc hướng mũi kim về phía răng đau (trị răng đau), ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ cắn, xương hàm dưới.\nThần kinh vận động cơ là nhánh thần kinh sọ não số V.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh sọ não số V."}]},{"id":277,"ten":"Hà Khẩu","sections":[{"h":"VỊ TRÍ","body":"Tại chỗ lõm bên trong mu bàn tay, từ huyệt Dương Trì (Ttu 4) đo ngang ra một thốn, thẳng huyệt Dương Khê (Đtr 5) lên."},{"h":"CHỦ TRỊ","body":"Trị cuồng, động kinh."},{"h":"CHÂM CỨU","body":"Cứu 3 – 5 tráng."}]},{"id":278,"ten":"Hạ Á Môn","sections":[{"h":"VỊ TRÍ","body":"Giữa đường chân tóc phía sau gáy (huyệt Á Môn – Đc 15) xuống 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị di chứng não."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn."}]},{"id":279,"ten":"Hạ Bá Lao","sections":[{"h":"VỊ TRÍ","body":"Khe đốt sống cổ 7 (Đại Chùy – Đc 14) đo ngang ra mỗi bên 1,3 thốn."},{"h":"CHỦ TRỊ","body":"Trị ho, lao hạch, vai đau lan đến gáy."},{"h":"CHÂM CỨU","body":"Châm Thẳng sâu 0,3 – 0,5 thốn, Cứu 3 – 7 tráng.5C\n'L"}]},{"id":280,"ten":"Hạ Chùy","sections":[{"h":"VỊ TRÍ","body":"Dưới gai sống cùng thứ 3."},{"h":"CHỦ TRỊ","body":"Trị kinh nguyệt không đều, hố chậu viêm."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,5 – 1 thốn."}]},{"id":281,"ten":"Hạ Côn Lôn","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm giữa đỉnh mắt cá chân ngoài và bờ ngoài gót chân (huyệt Côn Lôn – Bq 60) xuống 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị phong thấp, lưng đau, liệt nửa người."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn."}]},{"id":282,"ten":"Hạ Cự Hư","sections":[{"h":"VỊ TRÍ","body":"Dưới huyệt Thượng Cự Hư 3 thốn, phía ngoài xương mác 1 khoát ngón tay, bờ ngoài cơ cẳng chân trước."},{"h":"CHỦ TRỊ","body":"Trị thấp khớp, cước khí, chi dưới liệt, ăn kém, ruột viêm mạn, gan viêm cấp, bịnh về trường vị."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn, Cứu 5 – 7 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa cơ cẳng chân trước và cơ duỗi chung các ngón chân, ở sâu là bờ trong cơ duỗi dài riêng ngón chân cái, khe giữa xương chầy và xương mác.\nThần kinh vận động cơ là các nhánh của dây thần kinh chầy trước.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5."}]},{"id":283,"ten":"Hạ Cực Du","sections":[{"h":"VỊ TRÍ","body":"Dưới gai đốt sống lưng thứ 3."},{"h":"CHỦ TRỊ","body":"Trị thắt lưng đau, bàng quang viêm, chi dưới tê liệt."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 1 – 1,5 thốn."}]},{"id":284,"ten":"Hạ Địa Thương","sections":[{"h":"VỊ TRÍ","body":"Tại giao điểm của đường ngang qua huyệt Thừa Tương (Nh 24) và đường thẳng từ Địa Thương (Vi 4) kéo xuống. Nơi chỗ lõm của xương hàm dưới."},{"h":"CHỦ TRỊ","body":"Trị thần kinh tam thoa đau, liệt mặt, thần kinh mặt co giật."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,2 – 0,5 thốn (liệt mặt) hoặc châm xiên vào phía dưới bên trong (trị thần kinh tam thoa đau)"}]},{"id":285,"ten":"Hạ Đô","sections":[{"h":"VỊ TRÍ","body":"Giữa khe ngón tay 4 và 5, nơi giáp ranh của da thịt đỏ và trắng."},{"h":"CHỦ TRỊ","body":"Trị tay sưng, mắt sưng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,1 – 0,3 thốn."}]},{"id":286,"ten":"Hạ Hiệp Bạch","sections":[{"h":"VỊ TRÍ","body":"Huyệt Hiệp Bạch (P 4) đo xuống 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị thấp tim, hồi hộp."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn."}]},{"id":287,"ten":"Hạ Khế Mạch","sections":[{"h":"VỊ TRÍ","body":"Phía sau chân vành tai, ngang với bình tai, đo xuống 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị câm điếc."},{"h":"CHÂM CỨU","body":"Châm thẳng hướng mũi kim lên trên, sâu 0,7 – 1, 5 thốn."}]},{"id":288,"ten":"Hạ Liêm","sections":[{"h":"VỊ TRÍ","body":"Trên đường nối Khúc Trì và Dương Khê, cách Khúc Trì 4 thốn."},{"h":"CHỦ TRỊ","body":"Trị cánh tay và khuỷu tay đau, bụng đau, tuyến vú viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn, Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ sau cơ ngửa dài, bờ ngoài cơ quay 1, cơ ngửa ngắn và xương quay.\nThần kinh vận động cơ do các nhánh của dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C6."}]},{"id":289,"ten":"Hạ Liêu","sections":[{"h":"VỊ TRÍ","body":"Nơi lỗ xương cùng thứ 4, điểm giữa huyệt Bạch Hoàn Du (Bq 30) và Đốc Mạch."},{"h":"CHỦ TRỊ","body":"Trị bệnh thuộc về cơ quan sinh dục, vùng thắt lưng và xương cùng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 5 – 7 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân của cơ lưng to, khối cơ chung của các cơ ở rãnh cột sống, xương cùng.\nThần kinh vận động cơ là các nhánh của đám rối cánh tay, nhánh của dây thần kinh sống cùng 4.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S4."}]},{"id":290,"ten":"Hạ Quan","sections":[{"h":"VỊ TRÍ","body":"Khi ngậm miệng lại, huyệt ở chỗ lõm phía trước tai, dưới xương gò má, nơi góc phía trước của mỏm tiếp xương thái dương và lồi cầu xương hàm dưới."},{"h":"CHỦ TRỊ","body":"Trị răng đau, liệt mặt, thần kinh tam thoa đau, khớp hàm dưới viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn, Ôn cứu 5 – 10 phút.\nTrị dây thần kinh tam thoa đau: hướng mũi kim xuống dưới.\nTrị khớp hàm viêm: châm xiên, hướng mũi kim ra phía trước hoặc sau.\nTrị răng đau: châm dọc theo xương hàm hướng về phía răng đau.\nTrị tai giữa viêm: châm luồn kim hướng về bên phải cho có cảm giác lan đến tai.\nTrị cơ nhai co rút: châm xiên dưới da."},{"h":"GIẢI PHẪU","body":"Dưới da là tuyến mang tai, chỗ bám của bờ sau cơ nhai, ở sâu có cơ chân bướm ngoài.\nThần kinh vận động cơ là dây thần kinh sọ não số V.\nDa vùng huyệt chi phối bởi thần kinh sọ não số V."}]},{"id":291,"ten":"Hạ Quan Hạ","sections":[{"h":"VỊ TRÍ","body":"Dưới huyệt Hạ Quan 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị thiếu hơi, hụt hơi, răng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3–0,5 thốn."}]},{"id":292,"ten":"Hạ Quản","sections":[{"h":"VỊ TRÍ","body":"Lỗ rốn thẳng lên 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị bụng đau, trướng hơi, nôn mửa, dạ dầy đau, ăn không tiêu, ruột viêm mạn, người gầy dần, cổ trướng."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1,5 thốn. Cứu 10 – 30 phút."},{"h":"GIẢI PHẪU","body":"Huyệt ở trên đường trắng. Dưới đường trắng là mạc ngang, phúc mạc, vào sâu là Tụy và Tá tràng hoặc tử cung khi có thai gần sinh.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D9."}]},{"id":293,"ten":"Hạ Trì","sections":[{"h":"VỊ TRÍ","body":"Đầu nếp gấp khuỷu tay (huyệt Khúc Trì (Đtr 11) đo xuống 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị khuỷu tay đau, mũi viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn."}]},{"id":294,"ten":"Hạ Yêu","sections":[{"h":"VỊ TRÍ","body":"Chính giữa xương cùng, ở phía trên gần điểm giữa gai cột sống cùng thứ 3 và 4 (S3 – S4)"},{"h":"CHỦ TRỊ","body":"Trị tiêu chảy, phân có máu mủ lâu ngày, ruột viêm, sinh đẻ khó."},{"h":"CHÂM CỨU","body":"Cứu 3 – 7 tráng hoặc đến 50 tráng."}]},{"id":295,"ten":"Hạ Yêu II","sections":[{"h":"VỊ TRÍ","body":"Ở trên cột sống vùng xương cùng, giữa các cặp huyệt Bát liêu."},{"h":"CHỦ TRỊ","body":"Trị kiết lỵ ra mủ, máu, khó sinh đẻ."},{"h":"CHÂM CỨU","body":"Cứu 50 – 100 tráng."}]},{"id":296,"ten":"Hạc Đỉnh","sections":[{"h":"VỊ TRÍ","body":"Co đầu gối, huyệt ở giữa chỗ lõm bờ trên xương bánh chè."},{"h":"CHỦ TRỊ","body":"Trị đầu gối sưng đau, hạc tất phong, bệnh thuộc tổ chức phần mềm khớp gối."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 0,8 thốn."},{"h":"GIẢI PHẪU","body":"Dưới da là gân thẳng trước của cơ 4 đầu đùi, gân cơ rộng ngoài, gân cơ rộng trong, gân cơ rộng giữa, mặt trước đầu dưới xương đùi.\nThần kinh vận động cơ do các nhánh của dây thần kinh đùi.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L3.I(9\nK92"}]},{"id":297,"ten":"Hài Đái","sections":[{"h":"VỊ TRÍ","body":"Giữa lằn nếp gấp cổ chân."},{"h":"CHỦ TRỊ","body":"Trị khớp chân sưng đau, trẻ nhỏ co giật."}]},{"id":298,"ten":"Hài Liêu","sections":[{"h":"VỊ TRÍ","body":"Tại giao điểm của đường ngang qua huyệt Thừa Tương (Nh 24) và đường thẳng từ Địa Thương (Vi 4) kéo xuống. Nơi chỗ lõm của xương hàm dưới."},{"h":"CHỦ TRỊ","body":"Trị thần kinh tam thoa đau, liệt mặt, thần kinh mặt co giật."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,2 – 0,5 thốn (trị liệt mặt) hoặc châm xiên vào phía dưới bên trong (trị thần kinh tam thoa đau)"}]},{"id":299,"ten":"Hải Tuyền","sections":[{"h":"VỊ TRÍ","body":"Cong lưỡi lên, huyệt ở điểm giữa nếp hãm lưỡi, giữa huyệt Kim Tân và Ngọc Dịch."},{"h":"CHỦ TRỊ","body":"Trị tiểu đường, lưỡi viêm, lưỡi cứng, nấc (cơ hoành co thắt)"},{"h":"CHÂM CỨU","body":"Châm ra máu."},{"h":"GIẢI PHẪU","body":"Dưới niêm mạc lưỡi là vách lưỡi, cơ cằm – lưỡi, cơ móng – lưỡi.\nThần kinh vận động cơ là các nhánh của dây thần kinh sọ não số XII.\nNiêm mạc chi phối bởi dây thần kinh sọ não số V."}]},{"id":300,"ten":"Hàm Yến","sections":[{"h":"VỊ TRÍ","body":"Trong chân tóc vùng thái dương, nơi có di động khi há miệng nhai, huyệt Đầu Duy (Vi 8) đo xuống một thốn, tại 1/4 trên và 3/4 dưới của đoạn nối huyệt Đầu Duy và Khúc Tân (Đ 7)"},{"h":"CHỦ TRỊ","body":"Trị nửa đầu đau, chóng mặt, tai ù, liệt mặt."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ tai trên, cơ thái dương, xương thái dương.\nThần kinh vận động cơ là các nhánh của dây thần kinh mặt, nhánh của dây thần kinh sọ não số V.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số"}]},{"id":301,"ten":"Hãm Cốc","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm nối thân và đầu trước xương bàn chân 2, giữa kẽ ngón chân 2 – 3, huyệt Nội Đình (Vi 45) lên 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị mặt phù, toàn thân phù thũng, sôi ruột, bụng đau, họng viêm, mu bàn chân sưng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Cứu 3 – 7 tráng, Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa các gân duỗi các ngón chân 2 và 3 của cơ duỗi dài và cơ duỗi ngắn các ngón chân, các gian cốt mu chân 2, khe giữa xương bàn chân 2 và 3.\nThần kinh vận động cơ là các nhánh của dây thần kinh chày trước và nhánh của dây thần kinh chày sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5."}]},{"id":302,"ten":"Hạng Trung","sections":[{"h":"VỊ TRÍ","body":"Giữa đường nối huyệt Phong Trì và Ế Minh (tức là huyệt An Miên 2) đo xuống 2 thốn, ở bờ sau cơ ức – đòn – chũm."},{"h":"CHỦ TRỊ","body":"Trị cổ vẹo cứng, nửa người liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng hoặc xiên lên trên sâu 0,5 – 1 thốn."}]},{"id":303,"ten":"Hành Gian","sections":[{"h":"VỊ TRÍ","body":"Ép ngón chân cái sát vào ngón thứ 2, huyệt nằm ngay trên đầu kẽ của 2 ngón chân, về phía mu chân."},{"h":"CHỦ TRỊ","body":"Trị vùng gian sườn đau, mắt sưng đỏ, đái dầm, tử cung viêm, kinh nguyệt rối loạn, động kinh, huyết áp cao, mất ngủ."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút.\nTrị mất ngủ, châm trước khi đi ngủ 1 – 2 giờ."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa các gân duỗi ngón 2 của cơ duỗi dài và cơ duỗi ngắn các ngón chân ở phía ngoài với các gân duỗi dài riêng ngón 1 và gân duỗi ngón chân 1 của cơ duỗi ngắn các ngón chân ở phía trong, cơ gian cốt mu chân, khe giữa các đốt 1 xương ngón chân 1 và 2.\nThần kinh vận động cơ là các nhánh của dây thần kinh chầy trước và nhánh của dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5."}]},{"id":304,"ten":"Hậu Dịch Hạ","sections":[{"h":"VỊ TRÍ","body":"Tận cuối phía ngoài nếp gấp trục phía sau."},{"h":"CHỦ TRỊ","body":"Trị tay không giơ lên được."},{"h":"CHÂM CỨU","body":"Châm hơi hướng về phía bên cạnh, sâu 0,5 – 0,8 thốn. Cứu 5 – 10 phút.+\nu"}]},{"id":305,"ten":"Hậu Dương Quan","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm phía ngoài lồi cầu xương đùi (huyệt Dương Quan – Đ.33) đo ra phía sau 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị khớp gối đau, chi dưới liệt, bệnh tâm thần."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn."}]},{"id":306,"ten":"Hậu Đỉnh","sections":[{"h":"VỊ TRÍ","body":"Tại giữa huyệt Cường Gian (Đc 18) và huyệt Bá Hội (Đc 20), sau huyệt Bá Hội 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, điên cuồng, kinh giật, choáng váng."},{"h":"CHÂM CỨU","body":"Châm luồn kim dưới da, sâu 0,2 – 1 thốn. Cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân sọ, dưới cân sọ là xương sọ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C3."}]},{"id":307,"ten":"Hậu Ế Minh","sections":[{"h":"VỊ TRÍ","body":"Tại chỗ lõm dưới xương chũm đo thẳng xuống 0,5 thốn, nơi dừng lại của cơ ức – đòn – chũm."},{"h":"CHỦ TRỊ","body":"Trị câm điếc."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn.Z\n6"}]},{"id":308,"ten":"Hậu Khê","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm phía sau khớp xương ngón và bàn của ngón thứ 5, ngang với đầu trong đường vân tim ở bàn tay, nơi tiếp giáp da gan tay – mu tay."},{"h":"CHỦ TRỊ","body":"Trị cổ gáy đau cứng, đầu đau, lưng đau, tai ù, điếc, chi trên liệt, động kinh, sốt rét, ra mồ hôi trộm."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ dạng ngón tay út, bờ trong cơ gấp ngắn ngón tay, cơ đối ngón út, bờ trong đầu dưới xương bàn tay thứ 5.\nThần kinh vận động cơ là các nhánh của dây thần kinh trụ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D1."}]},{"id":309,"ten":"Hậu Kỳ Môn","sections":[{"h":"VỊ TRÍ","body":"Xác định huyệt Hoàn khiêu, từ đó đo thẳng ra đến chỗ lõm ở đầu xương đùi là huyệt."},{"h":"CHỦ TRỊ","body":"Trị vùng mông đùi đau, khó sinh đẻ."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1,5 – 3 thốn."}]},{"id":310,"ten":"Hậu Ngũ Hội","sections":[{"h":"VỊ TRÍ","body":"Khe ngón chân 4–5 lên 1 thốn, giữa huyệt Địa Ngũ Hội (Đ 42) và Túc Lâm Khấp (Đ 44)"},{"h":"CHỦ TRỊ","body":"Trị thần kinh tọa đau, biên đào thể viêm (amidal viêm)"},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn.3T\n8"}]},{"id":311,"ten":"Hậu Phát Tế","sections":[{"h":"VỊ TRÍ","body":"Dưới đường chân tóc sau gáy, ngay dưới huyệt Á Môn (Đc 15)"},{"h":"CHỦ TRỊ","body":"Trị chảy máu cam."},{"h":"CHÂM CỨU","body":"Cứu 3 tráng.9\nT"}]},{"id":312,"ten":"Hậu Thái Xung","sections":[{"h":"VỊ TRÍ","body":"Cuối kẽ ngón chân 1 và 2 (huyệt Thái Xung – C.3) đo lùi ra phía sau 1,5 thốn. Vểnh bàn chân lên cho rõ khe, huyệt ở chỗ lõm ngay dưới lõm huyệt Giải Khê (Vi 41)"},{"h":"CHỦ TRỊ","body":"Trị thấp tim."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn."}]},{"id":313,"ten":"Hậu Thính Cung","sections":[{"h":"VỊ TRÍ","body":"Gấp vành tai ra phía trước, huyệt ở vùng chân tai, ngang với đường đỉnh nhọn của bình tai và huyệt Thính Cung (trước tai), đối diện với huyệt Thính Cung."},{"h":"CHỦ TRỊ","body":"Trị điếc."},{"h":"CHÂM CỨU","body":"Châm xiên hướng lên trên, sâu 0,5 – 1 thốn.A\n2"}]},{"id":314,"ten":"Hậu Thính Hội","sections":[{"h":"VỊ TRÍ","body":"Tại chỗ lõm trên huyệt Ế Phong 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị câm điếc, tai ù."},{"h":"CHÂM CỨU","body":"Châm xiên hơi hướng xuống dưới, sâu 1 – 1,5 thốn."}]},{"id":315,"ten":"Hậu Thính Huyệt","sections":[{"h":"VỊ TRÍ","body":"Sau vành tai, tại giữa huyệt Hậu Thính Cung và Hậu Thính Hội. Đối diện với huyệt Thính Huyệt (ở trước tai)"},{"h":"CHỦ TRỊ","body":"Trị điếc."},{"h":"CHÂM CỨU","body":"Châm xiên hướng lên trên, sâu 0,5 – 0,8 thốn.l\n."}]},{"id":316,"ten":"Hậu Thông","sections":[{"h":"VỊ TRÍ","body":"Giữa đường nếp gấp gốc chân sau tai và đường chân tóc."},{"h":"CHỦ TRỊ","body":"Trị điếc."},{"h":"CHÂM CỨU","body":"Châm xiên hướng vào phía trong, sâu 0,3 – 0,5 thốn."}]},{"id":317,"ten":"Hiếp Đường","sections":[{"h":"VỊ TRÍ","body":"Trên đường giữa nách, dưới hố nách 2 thốn. Giơ tay lên cho dễ lấy huyệt."},{"h":"CHỦ TRỊ","body":"Trị ngực đầy tức, ợ hơi, khó thở."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,4 thốn. Cứu 3 tráng."}]},{"id":318,"ten":"Hiệp Bạch","sections":[{"h":"VỊ TRÍ","body":"Ở mặt trong cánh tay, nơi gặp nhau của bờ ngoài cơ 2 đầu cánh tay với đường ngang dưới đầu nếp nách trước 4 thốn, trên khớp khuỷu (Xích Trạch) 5 thốn, dưới huyệt Thiên Phủ 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị mặt trong cánh tay đau, ho, ngực đau tức, hơi thở ngắn."},{"h":"CHÂM CỨU","body":"Châm thẳng 05 – 1 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ ngoài cơ 2 đầu cánh tay, cơ cánh tay trước và bờ ngoài xương cánh tay.\nThần kinh vận động cơ là các nhánh của dây thần kinh cơ da.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C3."}]},{"id":319,"ten":"Hiệp Khê","sections":[{"h":"VỊ TRÍ","body":"Khe giữa xương bàn chân ngón thứ 4 và 5, huyệt nằm ở đầu kẽ giữa 2 ngón chân, phía trên mu chân."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, tai điếc, chóng mặt, tay chân lạnh do rối loạn khí, thần kinh gian sườn đau, ngực tức."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Cứu 1 – 3 tráng. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa các gân duỗi các ngón 4 và 5 của cơ duỗi dài các ngón chân, gân duỗi ngón 4 của cơ duỗi ngắn các ngón chân, cơ gian cốt mu chân, khe giữa các đốt 1 của các xương ngón chân 4 và 5.\nThần kinh vận động cơ và các nhánh của dây thần kinh chày trước và nhánh của dây thần kinh chày sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S1."}]},{"id":320,"ten":"Hoa Cái","sections":[{"h":"VỊ TRÍ","body":"Ở điểm gặp nhau của đường dọc giữa xương ức và đường ngang qua giữa 2 khớp xương ức."},{"h":"CHỦ TRỊ","body":"Trị ngực đau, ho suyễn."},{"h":"CHÂM CỨU","body":"Châm xiên, sâu 0,3 – 1 thốn. Cứu 5 – 20 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là xương ức, chỗ tiếp nối đầu xương ức với thân xương ức.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D2."}]},{"id":321,"ten":"Hoa Đà Huyệt","sections":[{"h":"VỊ TRÍ","body":"Tại đầu ngón chân cái, cách móng 5 phân."},{"h":"CHỦ TRỊ","body":"Trị thoát vị bẹn."},{"h":"CHÂM CỨU","body":"Cứu 5 – 10 phút."}]},{"id":322,"ten":"Hòa Liêu","sections":[{"h":"VỊ TRÍ","body":"Huyệt nằm trên đường ngang qua 1/3 trên hoặc 2/3 dưới của rãnh nhân trung, cách đường giữa rãnh 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị mũi viêm, dây thần kinh mặt liệt, thần kinh mặt co giật."},{"h":"CHÂM CỨU","body":"Châm thẳng hoặc xiên 0,3 – 0,5 thốn."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ vòng môi trên, xương hàm trên.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số VII.\nDa vùng huyệt chi phối nhánh dưới hố mắt của dây thần kinh sọ não số V."}]},{"id":323,"ten":"Hòa Liêu","sections":[{"h":"VỊ TRÍ","body":"Phía trước lỗ tai, trong chân tóc, trước và trên huyệt Nhĩ Môn (Ttu 21). Huyệt ở bờ trên của mỏm tiếp xương thái dương phía trên và sau bờ sau chân tóc mai, sờ thấy động mạch thái dương nông, trước bình tai một đốt ngón tay."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, tai ù, thần kinh mặt liệt, cấm khẩu."},{"h":"CHÂM CỨU","body":"Châm xiên dưới da 0,3 – 0,5 thốn. Cứu 1 – 3 tráng."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ tai trên, cơ thái dương, xương thái dương.\nThần kinh vận động cơ là nhánh của dây thần kinh mặt, nhánh của dây thần kinh sọ não số 5.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V."}]},{"id":324,"ten":"Hoàn Cốt","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm phía sau và dưới mỏm xương chũm, sát bờ sau cơ ức đòn chũm."},{"h":"CHỦ TRỊ","body":"Trị răng đau, mặt sưng đau, mặt liệt, tai ù."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 1 thốn. Cứu 1 – 3 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ ức – đòn – chũm, cơ gối đầu, cơ đầu dài, cơ trâm móng, cơ trâm lưỡi, cơ trâm hầu và cơ 2 thân.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số XI, nhánh cổ 2, nhánh dây thần kinh chẩm lớn, nhánh dây thần kinh dưới chẩm, các nhánh của dây thần kinh sọ não số XII, IX và số VII.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C2."}]},{"id":325,"ten":"Hoàn Khiêu","sections":[{"h":"VỊ TRÍ","body":"Nằm nghiêng co chân đau ở trên, chân dưới duỗi thẳng, huyệt ở vị trí 1/3 ngoài và 2/3 trong của đoạn nối điểm cao nhất của mấu chuyển lớn xương đùi và khe xương cùng. Hoặc nằm sấp, gấp chân vào mông, gót chân chạm mông ở đâu, đó là huyệt."},{"h":"CHỦ TRỊ","body":"Trị chi dưới liệt, khớp háng viêm, thần kinh tọa đau, cước khí."},{"h":"CHÂM CỨU","body":"Châm thẳng 2–3 thốn hoặc hướng mũi kim qua 2 bên. Cứu 5 – 10 tráng. Ôn cứu 10 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ mông to, bờ dưới cơ tháp, bờ trên cơ sinh đôi trên.\nThần kinh vận động cơ là nhánh của dây thần kinh mông trên, dây thần kinh mông dưới và các nhánh của đám rối thần kinh cùng.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh"}]},{"id":326,"ten":"Hoàn Trung","sections":[{"h":"VỊ TRÍ","body":"Tại giữa đường nối huyệt Hoàn Khiêu (Đ 30) và huyệt Yêu Du (Đc 2)"},{"h":"CHỦ TRỊ","body":"Trị thần kinh tọa đau, thắt lưng đau, lưng đùi đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 2 thốn."}]},{"id":327,"ten":"Hoạn Môn","sections":[{"h":"VỊ TRÍ","body":"Khe đốt sống lưng 5 ra ngang 1,5 thốn (Tâm Du – Bq 15), hơi nhích lên trên một ít."},{"h":"CHỦ TRỊ","body":"Trị khí quản viêm, hen suyễn, lao phổi, cơ thể suy nhược."},{"h":"CHÂM CỨU","body":"Cứu."}]},{"id":328,"ten":"Hoang Du","sections":[{"h":"VỊ TRÍ","body":"Rốn (huyệt Thần Khuyết – Nh.8) đo ngang ra 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị dạ dày bị co thắt, đau do thoái vị, kinh rong, táo bón, hoàng đản."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 5 – 7 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ chéo to của bụng, bờ trong cơ thẳng to, mạc ngang, phúc mạc, ruột non hoặc bàng quang khi bí tiểu tiện nhiều, tử cung khi có thai 7 – 8 tháng.\nThần kinh vận động cơ là 6 nhánh dây thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh"}]},{"id":329,"ten":"Hoang Mộ","sections":[{"h":"VỊ TRÍ","body":"Nằm ngửa, lấy 1 sợi dây, đo từ đầu vú đến giữa rốn, cắt đôi sợi dây đó. Đặt một đầu dây trên đầu vú, một đầu thõng xuống, đầu cuối dây là huyệt. Hai bên có hai huyệt."},{"h":"CHỦ TRỊ","body":"Trong bụng có khối u đau, suy nhược sau khi bệnh."},{"h":"CHÂM CỨU","body":"Cứu 3 – 7 tráng hoặc tuỳ theo số tuổi."}]},{"id":330,"ten":"Hoang Môn","sections":[{"h":"VỊ TRÍ","body":"Dưới gai sống thắt lưng 1, đo ngang ra 3 thốn, cách huyệt Tam Tiêu Du 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị bụng trên đau, táo bón, tuyến vú viêm, chi dưới liệt."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 0,8 thốn. Cứu 5 – 7 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ lưng to, cơ răng cưa bé sau – dưới, cơ chậu – sườn – thắt lưng, cân thắt lưng, cơ vuông thắt lưng, niệu quản.\nThần kinh vận động cơ là nhánh của đám rối cánh tay, nhánh của dây sống thắt lưng 1.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D11."}]},{"id":331,"ten":"Hoàng Huyền","sections":[{"h":"VỊ TRÍ","body":"Bảo người bệnh áp bàn tay vào lưng cùng, ngón thứ nhất đặt tại huyệt Hoàn Khiêu (Đ 30), ngón thứ 3 ở giữa đầu xương cụt, đầu ngón thứ 2 là huyệt."},{"h":"CHỦ TRỊ","body":"Trị trĩ, giang mai, bệnh lậu."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn. Cứu 5 – 10 phút."}]},{"id":332,"ten":"Hoành Cốt","sections":[{"h":"VỊ TRÍ","body":"Ở bụng dưới, sát bờ trên xương mu, đo cách đường giữa bụng 0,5 thốn, ngang huyệt Khúc Cốt (Nh 2)"},{"h":"CHỦ TRỊ","body":"Trị thoát vị bẹn, đường tiểu viêm, liệt dương, di tinh, tiểu khó."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ chéo to của bụng, cơ tháp, bờ trong cơ thẳng to, mạc ngang, phúc mạc, ruột non hoặc bàng quang khi đầy, tử cung khi có thai.\nThần kinh vận động cơ là 6 nhánh dây thần kinh gian sườn dưới và dây thần kinh sinh dục–bụng.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L1."}]},{"id":333,"ten":"Hoành Cốt 2","sections":[{"h":"VỊ TRÍ","body":"Giữa vùng tiếp hợp của xương thẹn."},{"h":"CHỦ TRỊ","body":"Trị đái dầm, tiểu bí, tiểu không tự chủ, thoát vị bẹn."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,4 thốn. Cứu 3 – 5 tráng."}]},{"id":334,"ten":"Hoành Môn","sections":[{"h":"VỊ TRÍ","body":"Giữa lằn chỉ nếp gấp cổ tay trong (huyệt Đại lăng) đo lên 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị bụng đau, tiêu chảy, nôn mửa."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 thốn. Cứu 3 – 7 tráng.D\n\""}]},{"id":335,"ten":"Hoành Văn","sections":[{"h":"VỊ TRÍ","body":"Rốn đo ngang ra 3,5 thốn (huyệt Đại Hoành – Ty.15, đo vào 0,5 thốn)"},{"h":"CHỦ TRỊ","body":"Trị mồ hôi ra nhiều, cơ thể mỏi mệt."},{"h":"CHÂM CỨU","body":"Cứu 10 – 15 phút."}]},{"id":336,"ten":"Hoạt Nhục Môn","sections":[{"h":"VỊ TRÍ","body":"Trên rốn 1 thốn, cách đường giữa bụng 2 thốn, ngang huyệt Thủy Phân (Nh 9)"},{"h":"CHỦ TRỊ","body":"Trị dạ dầy đau, tâm thần rối loạn, chóng mặt, nôn mửa."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn, Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ chéo to, cơ thẳng to, mạc ngang, phúc mạc, trong ổ bụng là ruột non và tử cung khi có thai đến ngày sinh.\nThần kinh vận động cơ là 6 dây thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D9."}]},{"id":337,"ten":"Hoặc Trung","sections":[{"h":"VỊ TRÍ","body":"Ở khoảng gian sườn 1, cách đường giữa ngực 2 thốn, ngang huyệt Hoa Cái (Nh."},{"h":"CHỦ TRỊ","body":"Trị ho, ngực đau, nôn mửa."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ ngực to, các cơ gian sườn 1, sâu hơn có động mạch chủ (bên trái), tĩnh mạch thần kinh nách và dây thần kinh gian sườn 1.\nThần kinh vận động cơ là dây thần kinh ngực to của đám rối thần kinh nách và dây thần kinh gian sườn 1.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D2."}]},{"id":338,"ten":"Hô Hấp Huyệt","sections":[{"h":"VỊ TRÍ","body":"Tại giao điểm của bờ ngoài cơ ức – đòn – chũm và tĩnh mạch cổ đo xuống 0,3 thốn."},{"h":"CHỦ TRỊ","body":"Trị nấc, ngưng thở, cơ hô hấp bị liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn."}]},{"id":339,"ten":"Hổ Biên","sections":[{"h":"VỊ TRÍ","body":"Giữa huyệt Tam Gian (Đtr 3) và Hợp Cốc (Đtr 4)"},{"h":"CHỦ TRỊ","body":"Trị động kinh, tâm thần phân liệt, Hysteria."},{"h":"CHÂM CỨU","body":"Châm thẳng, mũi kim hướng đến phía sau huyệt Hậu Khê (Ttr 3), sâu 1 – 1,5 thốn."}]},{"id":340,"ten":"Hổ Khẩu","sections":[{"h":"VỊ TRÍ","body":"Tại kẽ ngón tay 1 và 2 (phía trước huyệt Hợp Cốc)"},{"h":"CHỦ TRỊ","body":"Trị đầu đau, ngực đau, khát, môi sưng đau, răng sưng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 0,8 thốn. Cứu 5 – 10 phút."}]},{"id":341,"ten":"Hộ Cung","sections":[{"h":"VỊ TRÍ","body":"Rốn đo thẳng xuống 1,5 thốn (tức huyệt Khí Hải), từ đó đo ngang ra hai bên, mỗi bên 2,6 thốn."},{"h":"CHỦ TRỊ","body":"Phối hợp với huyệt Quan Nguyên (Nh 4) trị vô sinh, u nang buồng trứng, phần phụ viêm, dịch hoàn viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 2 thốn."}]},{"id":342,"ten":"Hối Dương","sections":[{"h":"VỊ TRÍ","body":"Khe đốt sống lưng thứ 12 ra ngang 5 thốn (huyệt Vị Thương [Bq 50] ra 2 thốn)"},{"h":"CHỦ TRỊ","body":"Trị dạ dầy loét, tá tràng loét."},{"h":"CHÂM CỨU","body":"Châm xiên, sâu 0,5 – 0,8 thốn.N ="}]},{"id":343,"ten":"Hồi Dương Cửu Châm Huyệt","sections":[{"h":"VỊ TRÍ","body":"Gồm 9 huyệt: Á Môn (Đc 15) + Dũng Tuyền (Th 1) + Hoàn Khiêu (Đ 30) + Hợp Cốc (Đtr 4) + Tam Âm Giao (Ty 6) + Thái Khê (Th.3) + Trung Quản (Nh 12) + Túc Tam Lý (Vi 36)"},{"h":"CHỦ TRỊ","body":"Cấp cứu chứng thoát dương, cứu tỉnh."},{"h":"CHÂM CỨU","body":"Tùy theo vị trí của từng huyệt."}]},{"id":344,"ten":"Hồi Khí","sections":[{"h":"VỊ TRÍ","body":"Ngay chót xương cụt, trên huyệt Trường Cường (Đc 1) một ít."},{"h":"CHỦ TRỊ","body":"Trị tiểu ra máu, tiêu chảy, thượng mã phong."},{"h":"CHÂM CỨU","body":"Cứu 10 – 15 phút trở lên. có thể châm nặn máu trong điều trị thượng mã phong."}]},{"id":345,"ten":"Hội Âm","sections":[{"h":"VỊ TRÍ","body":"Giữa tiền âm và hậu âm (Giáp Ất) hoặc ở giữa bìu dái và hậu môn (đàn ông) hoặc ở đường sau của âm thần và hậu môn (phụ nữ), huyệt ở giữa nút đáy chậu (chỗ tụ hội của các nếp da chạy từ hậu môn, phần sinh dục ngoài và 2 bên háng tới)"},{"h":"CHỦ TRỊ","body":"Trị các bệnh của hệ sinh dục ngoài, bệnh của hậu môn, niệu đạo (niệu đạo viêm, tiền liệt tuyến viêm), kinh nguyệt không đều, di tinh, điên cuồng, chết đuối, thượng mã phong."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 1,5 thốn. Cứu 10 phút."},{"h":"GIẢI PHẪU","body":"Huyệt ở giữa nút xơ đáy chậu, nút được tạo nên bởi sự đan chéo nhau của các thớ cơ: ngang nông đáy chậu, thắt vân hậu môn, thắt vân niệu đạo, cơ âm đạo – trực tràng, cơ trực tràng – niệu đạo, cơ ngang sâu đáy chậu và bó trước hậu môn của cơ nâng hậu môn.\nThần kinh vận động cơ do 2 nhánh đáy chậu của thần kinh thẹn trong.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S5."}]},{"id":346,"ten":"Hội Dương","sections":[{"h":"VỊ TRÍ","body":"Ngang đầu dưới xương cụt, cách đường giữa lưng 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị lưng đau trong kỳ kinh nguyệt, bạch đới, liệt dương, tiêu chảy, trĩ."},{"h":"CHÂM CỨU","body":"Châm thẳng 1–1,5 thốn. Cứu 3–7 tráng. Ôn cứu 5–15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khối mỡ nhão của hố ngồi – trực tràng, cơ nâng mông, cơ ngồi cụt.\nThần kinh vận động cơ là các nhánh của dây thần kinh thẹn.\nDa vùng huyệt chi phối bởi tiết đọan thần kinh S5."}]},{"id":347,"ten":"Hội Tông","sections":[{"h":"VỊ TRÍ","body":"Mặt sau cẳng tay, trên lằn cổ tay 3 thốn, ngang huyệt Chi Câu (Ttu 6), cách 1 thốn, về phía sát bờ ngoài xương trụ."},{"h":"CHỦ TRỊ","body":"Trị cánh tay đau, điếc, động kinh, van tim hẹp."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa cơ trụ sau và cơ duỗi riêng ngón tay trỏ, bờ ngoài xương trụ.\nThần kinh vận động cơ là các nhánh của dây thần kinh tay quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh thai, không châm.\nBí tiểu, không châm sâu.\nLỡ bị ngộ châm sinh ra bí tiểu, nên châm huyệt Dũng Tuyền (Th 1) để giải. Nằm ngửa, châm sâu 0,5 thốn, vê kim chừng một phút, đợi đến khi người bệnh thấy dễ chịu hoặc muốn tiểu thì rút kim ra (Danh Từ Huyệt Vị Châm Cứu)"}]},{"id":348,"ten":"Hồn Môn","sections":[{"h":"VỊ TRÍ","body":"Dưới gai sống lưng 9, đo ngang ra 3 thốn, cách Can Du 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị các bệnh về gan mật, dạ dày đau, tiêu hóa kém, cơ tim và màng ngực viêm."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 0,8 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ lưng to, cơ chậu – sườn – ngực, cơ gian sườn 9 rồi vào phổi.\nThần kinh vận động cơ là nhánh của đám rối cánh tay và nhánh của dây thần kinh gian sườn 9.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D9 hoặc D8 ."}]},{"id":349,"ten":"Hồn Xá","sections":[{"h":"VỊ TRÍ","body":"Giữa lỗ rốn ra ngang 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị lỵ, ruột viêm, táo bón."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 0,8 thốn. Cứu 5 – 10 phút."}]},{"id":350,"ten":"Hồng Âm","sections":[{"h":"VỊ TRÍ","body":"Đỉnh cao cuống hầu đo ngang ra 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị họng viêm cấp và mạn tính, câm."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn."}]},{"id":351,"ten":"Hồng Tuyến","sections":[{"h":"VỊ TRÍ","body":"Mặt trong đùi, đầu lằn chỉ nếp gấp nhượng chân (huyệt Khúc tuyền) đo lên phía đùi 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị tĩnh mạch viêm tắc."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 2 thốn."}]},{"id":352,"ten":"Hợp Cốc","sections":[{"h":"VỊ TRÍ","body":"a.\tỞ bờ ngoài, giữa xương bàn ngón 2.\nb. Khép ngón trỏ và ngón cái sát nhau, huyệt ở điểm cao nhất của cơ bắp ngón trỏ – ngón cái.\nc. Ngón tay cái và ngón tay trỏ xòe rộng, lấy nếp gấp giữa đốt 1 và đốt 2 của ngón tay cái bên kia để vào chỗ da nối ngón trỏ và ngón cái (hổ khẩu tay này, đặt áp đầu ngón cái lên mu bàn tay giữa 2 xương bàn 1 và 2), đầu ngón tay ở đâu, nơi đó là huyệt, ấn vào có cảm giác ê tức."},{"h":"CHỦ TRỊ","body":"Trị ngón tay đau, tê, bàn tay liệt, đầu đau, răng đau, cánh tay liệt, liệt mặt, amidal viêm, khớp hàm dưới viêm, mắt đau, cảm cúm, sốt, bướu giáp đơn thuần [bướu cổ], làm co bóp tử cung."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ gian cốt mu tay, bờ trên cơ khép ngón tay cái, bờ trong gân cơ duỗi dài ngón tay cái.\nThần kinh vận động cơ là các nhánh của dây thần kinh trụ và dây thần kinh tay quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C6–C7.V\nKhông châm sâu vì có thể đụng phổi."}]},{"id":353,"ten":"Hợp Dương","sections":[{"h":"VỊ TRÍ","body":"Ở đỉnh của góc dưới tứ giác kheo chân tạo nên bởi phần trên cơ sinh đôi ngoài, giữa mặt sau đầu trên xương chày. Từ huyệt ủy Trung (Bq 40) đo thẳng xuống 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị lưng và chân đau mỏi, chi dưới liệt, băng lậu."},{"h":"CHÂM CỨU","body":"Châm thẳng 1–1,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là góc của 2 cơ sinh đôi, bờ trên cơ kheo, giữa mặt sau đầu trên xương chày.\nThần kinh vận động cơ là các nhánh của dây thần kinh chày sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh"}]},{"id":354,"ten":"Hung Hương","sections":[{"h":"VỊ TRÍ","body":"Ở khoảng gian sườn 3, cách đường giữa 6 thốn (ngang huyệt Ngọc Đường – Nh."},{"h":"CHỦ TRỊ","body":"Trị vùng ngực đau, thần kinh gian sườn đau."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3–0,5 thốn. Cứu 3–5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ ngực to, cơ ngực bé, cơ răng cưa to, các cơ gian sườn 4 rồi vào phổi.\nThần kinh vận động cơ là dây ngực to, dây thần kinh ngực bé và dây thần kinh gian sườn 4.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D3."}]},{"id":355,"ten":"Hung Thông Cốc","sections":[{"h":"VỊ TRÍ","body":"Đầu vú đo xuống 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị tim đau, màng ngực viêm, tuyến vú viêm."},{"h":"CHÂM CỨU","body":"Cứu 50 tráng."}]},{"id":356,"ten":"Huyền Chung","sections":[{"h":"VỊ TRÍ","body":"Trên đỉnh mắt cá ngoài 3 thốn, giữa bờ sau xương mác và gân cơ mác bên dài, cơ mác bên ngắn."},{"h":"CHỦ TRỊ","body":"Trị khớp gối và tổ chức mềm chung quanh bị viêm, cổ gáy đau cứng, chi dưới liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3–5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa cơ mác bên ngắn với bờ trước xương mác.\nThần kinh vận động cơ là nhánh của dây thần kinh cơ – da.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5."}]},{"id":357,"ten":"Huyền Khu","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm dưới đầu mỏm gai đốt sống thắt lưng 1."},{"h":"CHỦ TRỊ","body":"Trị vùng thắt lưng đau cứng, lưng đau, ăn không tiêu, tiêu chảy."},{"h":"CHÂM CỨU","body":"Châm kim chếch lên trên, luồn kim dưới mỏm gai, hướng vào khoảng gian đốt sống thắt lưng 1 – 2, sâu 0,3 – 1 thốn. Cứu 10 – 40 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân ngực – thắt lưng của cơ lưng to, chỗ bám của cơ răng bé sau – dưới, cơ gian gai, cơ ngang gai, dây chằng trên gai, dây chằng gian gai, dây chằng vàng, ống sống.\nThần kinh vận động cơ là các nhánh của dây thần kinh sống.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D10.s1:A:3Vùng huyệt rất dễ bị nhiễm trùng, cần thận trọng khi châm."}]},{"id":358,"ten":"Huyền Lư","sections":[{"h":"VỊ TRÍ","body":"Ở sát động mạch Thái Dương nông, trên đường nối huyệt Hàm Yến (Đ 4) và Khúc Tân (Đ 7), cách Hàm Yến 0,6 thốn."},{"h":"CHỦ TRỊ","body":"Trị nửa đầu đau, răng đau, thần kinh suy nhược."},{"h":"CHÂM CỨU","body":"Châm luồn dưới da 0,3 – 0,5 thốn. Cứu 1 – 3 tráng. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ tai trên, cơ thái dương, xương thái dương.\nThần kinh vận động cơ là nhánh của dây thần kinh mặt, nhánh của dây thần kinh sọ não số V.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số"}]},{"id":359,"ten":"Huyền Ly","sections":[{"h":"VỊ TRÍ","body":"Ở điểm nối 3/4 trên và 1/3 dưới của đoạn nối huyệt Đầu Duy (Vi 8) và Khúc Tân (Đ 7), sát động mạch Thái Dương nông, dưới Huyền Lư 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, răng đau, mặt phù, thần kinh suy nhược."},{"h":"CHÂM CỨU","body":"Châm luồn dưới da 0,3 – 0,5 thốn. Cứu 1 – 3 tráng. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ tai trên, cơ thái dương, xương thái dương.\nThần kinh vận động cơ là nhánh của dây thần kinh mặt, nhánh của dây thần kinh sọ não số V.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V."}]},{"id":360,"ten":"Huyền Mạng","sections":[{"h":"VỊ TRÍ","body":"Tại đường gân xanh ngay giữa dưới môi trên."},{"h":"CHỦ TRỊ","body":"Trị mất tiếng, không nói được do di chứng não."},{"h":"CHÂM CỨU","body":"Lật môi trên lên, châm nặn máu.,\n/y"}]},{"id":361,"ten":"Huyết Áp Điểm","sections":[{"h":"VỊ TRÍ","body":"Gai đốt sống cổ thứ 6 đo ra ngang 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị huyết áp cao, huyết áp thấp."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn."}]},{"id":362,"ten":"Huyết Hải","sections":[{"h":"VỊ TRÍ","body":"Mặt trước trong đùi, từ xương bánh chè đầu gối đo lên 2 thốn, huyệt nằm trong khe lõm giữa cơ may và cơ rộng trong, ấn vào có cảm giác ê tức. Hoặc ngồi đối diện với bệnh nhân, bàn tay phải của thầy thuốc, đặt trên xương bánh chè bên trái của bệnh nhân, 4 ngón tay áp tại đầu gối, ngón cái ở phía trên đùi, chỗ đầu ngón cái là huyệt."},{"h":"CHỦ TRỊ","body":"Trị kinh nguyệt không đều, tử cung xuất huyết, phong ngứa, da viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1–2 thốn. Cứu 3–5 tráng, Ôn cứu 5–10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa cơ may và cơ rộng trong, cơ rộng giữa xương đùi.\nThần kinh vận động cơ là các nhánh của dây thần kinh đùi.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L3."}]},{"id":363,"ten":"Huyết Môn","sections":[{"h":"VỊ TRÍ","body":"Rốn đo lên 4 thốn (Trung Quản), đo ngang ra 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị phụ nữ trong bụng có huyết khối, dạ dầy đau, si ngốc, tiêu hóa rối loạn."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 15 phút."}]},{"id":364,"ten":"Huyết Phủ","sections":[{"h":"VỊ TRÍ","body":"Gai xương thắt lưng thứ 2 (L2) đo ngang ra 4 thốn."},{"h":"CHỦ TRỊ","body":"Trị bế kinh, buồng trứng sưng, gan lách sưng, di tinh."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1–1,5 thốn.3\n7ò"}]},{"id":365,"ten":"Huyết Sầu","sections":[{"h":"VỊ TRÍ","body":"Tại trên mỏm gai đốt sống thắt lưng thứ 2."},{"h":"CHỦ TRỊ","body":"Trị các chứng xuất huyết."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn. Cứu 5 – 10 phút."}]},{"id":366,"ten":"Hưng Phấn","sections":[{"h":"VỊ TRÍ","body":"Từ huyệt An Miên 2 đo xiên lên trên 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị tim đập chậm, mệt mỏi, thích ngủ, si ngốc do di chứng não."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn."}]},{"id":367,"ten":"Hữu Du","sections":[{"h":"VỊ TRÍ","body":"Thẳng giữa vú xuống đến xương sườn chót bên phải."},{"h":"CHỦ TRỊ","body":"Trị bụng đau, bụng dưới đau dồn lên trên."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3–0,5 thốn. Cứu 5–10 phút."}]},{"id":368,"ten":"Hữu Nghi","sections":[{"h":"VỊ TRÍ","body":"Huyệt Nhũ Căn (Vi.18) đo ngang ra bên phải 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị tuyến vú viêm, màng ngực viêm, màng trong tim viêm, thần kinh liên sườn đau."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn."}]},{"id":369,"ten":"Hữu Quan","sections":[{"h":"VỊ TRÍ","body":"Tại bụng trên, rốn lên 3 thốn (tức huyệt Kiến lý), đo ngang ra bên phải 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị dạ dày đau."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 1 thốn. Cứu 3 – 7 tráng."}]},{"id":370,"ten":"Kết Hạch Huyệt","sections":[{"h":"VỊ TRÍ","body":"Khe giữa đốt sống cổ 6 – 7 (huyệt Đại Chùy (Đc 14) đo ngang ra 3,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị lao phổi, các bệnh thuộc dạng lao khác."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 0,8 thốn."}]},{"id":371,"ten":"Khái Thấu Huyệt","sections":[{"h":"VỊ TRÍ","body":"Thẳng đầu vú vòng ra sau lưng chạm cột sống chỗ nào, đó là huyệt."},{"h":"CHỦ TRỊ","body":"Trị ho ra máu, suy nhược, sốt cơn."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn. Cứu 5 – 10 phút."}]},{"id":372,"ten":"Kháo Sơn","sections":[{"h":"VỊ TRÍ","body":"Ngửa bàn tay, huyệt ở ngay ngoài khớp cổ tay, thẳng phía ngón tay cái, bên cạnh ngoài huyệt Thái Uyên (P 9)"},{"h":"CHỦ TRỊ","body":"Trị sốt rét, đờm."},{"h":"CHÂM CỨU","body":"Cứu 5 – 10 phút.0m\nj"}]},{"id":373,"ten":"Khâu Khư","sections":[{"h":"VỊ TRÍ","body":"Ở phía trước và dưới mắt cá ngoài chân, nơi chỗ lõm của khe xương cạnh nhóm cơ duỗi dài các ngón chân, hoặc từ ngón chân thứ 4 kéo thẳng lên mắt cá gặp chỗ lõm hoặc lấy ở chỗ lõm giữa huyệt Thân Mạch (Bq 62) và huyệt Giải Khê (Vi 41), ấn vào thấy tức."},{"h":"CHỦ TRỊ","body":"Trị cẳng chân đau, khớp mắt cá chân đau, ngực đầy tức."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn, đối diện với khớp trong mắt cá, lách mũi kim vào khe khớp. Cứu 1 – 3 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ duỗi ngắn các ngón chân, bờ sau – ngoài cơ mác trước, khe khớp xương hộp – thuyền – chêm 3.\nThần kinh vận động cơ là các nhánh của dây thần kinh chầy trước.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S1."}]},{"id":374,"ten":"Khê Thượng","sections":[{"h":"VỊ TRÍ","body":"Dưới gai đốt sống thắt lưng 4 (L4) đo ra mỗi bên 0,3 – 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị lưng đau, đùi đau mạn tính."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1,5 – 2 thốn."}]},{"id":375,"ten":"Khế Mạch","sections":[{"h":"VỊ TRÍ","body":"Phía sau tai, giữa gai xương chũm, hoặc khi ép vành tai vào đầu, huyệt ở chỗ nối 1/3 dưới và 2/3 trên của đường cong theo bờ vành tai từ huyệt Ế Phong (Ttu 17) đến Giác Tôn (Ttu 20), nơi cơ ức – đòn – chũm."},{"h":"CHỦ TRỊ","body":"Trị tai ù, điếc, liệt mặt."},{"h":"CHÂM CỨU","body":"Châm luồn dưới da 0,3 – 0,5 thốn. Cứu 1 – 3 tráng. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là chỗ cơ ức – đòn – chũm, cơ gối đầu, cơ đầu dài và cơ 2 thân bám vào mỏm xương chũm.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số XI, nhánh của đám rối cổ sâu, nhánh dây thần kinh chẩm lớn, dây thần kinh chẩm dưới và dây thần kinh sọ não số XII.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C2."}]},{"id":376,"ten":"Khí Đoan","sections":[{"h":"VỊ TRÍ","body":"Huyệt ở đầu mút của 10 ngón chân, cách móng chân chừng 0,1 thốn."},{"h":"CHỦ TRỊ","body":"Trị ngón chân tê, mu bàn chân sưng, cước khí, trúng phong hôn mê."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,1 – 0,2 thốn nặn máu. Cứu 3 tráng.A\nBÚ"}]},{"id":377,"ten":"Khí Đường","sections":[{"h":"VỊ TRÍ","body":"Ngay dưới đầu xương đòn, chỗ lõm đầu cơ ức – nhũ, gần huyệt Khí Xá (Vi 11) và Thiên Đột (Nh 22)"},{"h":"CHỦ TRỊ","body":"Trị ho, suyễn."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Cứu 5 – 10 phút."}]},{"id":378,"ten":"Khí Hải","sections":[{"h":"VỊ TRÍ","body":"Lỗ rốn thẳng xuống 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị bụng và quanh rốn đau, bệnh về sinh dục, đường tiểu, kinh nguyệt, tiểu dầm, tiểu nhiều, chân khí hư, ngũ tạng hư, tay chân quyết lạnh, hư thoát, thần kinh suy nhược."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1,5 thốn. Cứu 15 – 30 phút hoặc nhiều hơn."},{"h":"GIẢI PHẪU","body":"Huyệt ở trên đường trắng, sau đường trắng là mạc ngang, phúc mạc, vào sâu có ruột non khi không bí tiểu nhiều hoặc có thai còn nhỏ, có bàng quang khi bí tiểu nhiều, có tử cung khi thai 4 – 5 tháng.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D11."}]},{"id":379,"ten":"Khí Hải Du","sections":[{"h":"VỊ TRÍ","body":"Dưới gai sống thắt lưng 3, đo ngang ra 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị các bệnh xuất huyết, vùng thắt lưng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân ngực – thắt lưng của cơ lưng to, cơ lưng dài, cơ ngang – gai, cơ gian mỏm ngang, cơ vuông thắt lưng, cơ đái – chậu.\nThần kinh vận động cơ là nhánh của đám rối cánh tay, nhánh của dây sống thắt lưng 3, nhánh của đám rối thắt lưng.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L2 hoặc L3."}]},{"id":380,"ten":"Khí Hộ","sections":[{"h":"VỊ TRÍ","body":"Ở sát dưới xương đòn, dưới huyệt Khuyết Bồn 1 thốn, cách đường giữa ngực 4 thốn."},{"h":"CHỦ TRỊ","body":"Trị lưng và ngực đau, khó thở, nấc, suyễn, khí quản viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn hoặc xiên 0,5 – 0,8 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ bám da cổ, cơ ngực to, cơ dưới đòn, bờ trên xương sườn 1, đỉnh phổi.\nThần kinh vận động cơ là nhánh cơ bám da của thần kinh mặt, nhánh cơ ngực to và cơ dưới đòn của đám rối thần kinh nách.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C4."}]},{"id":381,"ten":"Khí Huyệt","sections":[{"h":"VỊ TRÍ","body":"Từ huyệt Hoành Cốt (Th 11) đo xuống 3 thốn, cách tuyến giữa bụng 0,5 thốn, ngang huyệt Quan Nguyên (Nh 4) hoặc từ rốn xuống 3 thốn (huyệt Quan Nguyên), đo ra ngang 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị kinh nguyệt bị rối loạn, tiêu chảy."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ chéo to của bụng, bờ trong cơ thẳng to, mạc ngang, ruột non hoặc bàng quang khi bí tiểu ít, tử cung khi có thai 4 – 5 tháng.\nThần kinh vận động cơ là 6 dây thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D11 hoặc D12."}]},{"id":382,"ten":"Khí Môn","sections":[{"h":"VỊ TRÍ","body":"Rốn xuống 3 thốn (huyệt Quan Nguyên (Nh 4) đo ra 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị thoát vị ruột, rong kinh cơ năng, băng lậu, có thai ra huyết."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 1 thốn.9\nB"}]},{"id":383,"ten":"Khí Suyễn","sections":[{"h":"VỊ TRÍ","body":"Dưới mỏm gai đốt sống lưng thứ 7 đo ra 2 thốn hoặc nối 2 đầu vai xương dưới bả vai, lấy huyệt ở điểm cách Đốc mạch ra 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị khí quản viêm, suyễn, màng ngực viêm."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 1 thốn. Cứu 3 – 7 tráng. Ôn cứu 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ thang, cơ lưng to, cơ lưng dài, cơ bán gai ngực, cơ ngang – gai, cơ ngang – sườn, cơ gian sườn 6. Dưới nữa là phổi.\nThần kinh vận động cơ là nhánh của thần kinh sọ não số XI, nhánh của đám rối cổ sâu, nhánh của đám rối cánh tay, các nhánh của thần kinh sống lưng 7, các nhánh của thần kinh gian sườn 7."}]},{"id":384,"ten":"Khí Trung","sections":[{"h":"VỊ TRÍ","body":"Rốn đo xuống 1,5 thốn (huyệt Khí Hải – Nh.6) đo ngang ra 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị ruột co thắt, bụng căng, ruột sôi, thiếu máu."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 1,5 thốn.C\n2Y"}]},{"id":385,"ten":"Khí Vệ","sections":[]},{"id":386,"ten":"Khí Xá","sections":[{"h":"VỊ TRÍ","body":"Ở đáy cổ, ngay chỗ lõm sát bờ trên xương đòn, khe giữa bó ức và bó đòn cơ ức – đòn – chũm. Hoặc giao điểm từ huyệt Nhân Nghênh (Vi 9) kéo thẳng xuống và huyệt Thiên Đột (Nh 22) ngang ra 01 thốn."},{"h":"CHỦ TRỊ","body":"Trị họng đau, cổ gáy cứng, lao hạch cổ."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,3 – 0,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa bó ức và cơ bó đòn, cơ ức – đòn – chũm, vào sâu là cơ ức – đòn – móng và ức – giáp.\nThần kinh vận động cơ là các nhánh của dây thần kinh sọ não XI và XII, nhánh của dây thần kinh cổ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C3."}]},{"id":387,"ten":"Khí Xung","sections":[{"h":"VỊ TRÍ","body":"Rốn xuống 5 thốn (huyệt Khúc Cốt – Nh.2) đo ra ngang 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị vùng thận đau dữ dội, các bệnh về bộ phận sinh dục, đau do thoát vị."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn hoặc hướng mũi kim về phía bộ phận sinh dục, Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ chéo to, bờ ngoài cơ thẳng to, cân cơ chéo bé của bụng và cơ ngang bụng, mạc ngang, phúc mạc; Trong ổ bụng là ruột non và tử cung khi có thai 2 – 3 tháng, bàng quang khi đầy.\nThần kinh vận động cơ là 6 dây thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L1.\nHuyệt Khâu Khư, Dương Lăng Tuyền (Đ 34) và Đởm Du (Bq 19) có công hiệu khác nhau: cả 3 huyệt đều chữa bệnh về Đởm nhưng Dương Lăng Tuyền + Đởm Du thiên về chữa bệnh ở Đởm phủ còn Khâu Khư thiên về chữa bệnh ở kinh Đởm” (Du Huyệt Công Năng Giám Biệt).\n“Tả Khâu Khư + Âm Lăng Tuyền (Ty 9) + Hành Gian (C 3) có tác dụng tả thực nhiệt ở Can Đởm, giống bài Long Đởm Tả Can Thang của sách Hòa Tễ Cục Phương (Thường Dụng Du Huyệt Lâm Sàng Phát Huy)"}]},{"id":388,"ten":"Khích Môn","sections":[{"h":"VỊ TRÍ","body":"Trên khớp cổ tay 5 thốn, giữa 2 khe cơ gan tay lớn và bé."},{"h":"CHỦ TRỊ","body":"Trị cơ tim viêm, vùng trước tim đau, màng ngực viêm, tuyến vú viêm, thần kinh suy nhược."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,8 – 1,2 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa cơ gan tay lớn và cơ gan tay bé, cơ gấp dài ngón tay cái,cơ gấp chung nông và sâu, khe giữa xương quay và xương trụ.\nThần kinh vận động cơ là các nhánh của dây thần kinh giữa và dây thần kinh trụ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D1 hoặc YDO:"}]},{"id":389,"ten":"Khiên Chính Huyệt","sections":[{"h":"VỊ TRÍ","body":"Trước bình tai 0,5 – 1 thốn, ngay chỗ động mạch khi nhai."},{"h":"CHỦ TRỊ","body":"Trị liệt mặt, tuyến mang tai viêm, lợi răng viêm, miệng lở loét."},{"h":"CHÂM CỨU","body":"Châm xiên lên trên, sâu 0,5 – 1 thốn."}]},{"id":390,"ten":"Khoả Hạ","sections":[{"h":"VỊ TRÍ","body":"Dưới mắt cá chân trong, chỗ giáp giữa thịt trắng và đỏ."},{"h":"CHỦ TRỊ","body":"Trị phù thũng, mặt phù, bàn chân đau."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 thốn. Cứu 3 tráng."}]},{"id":391,"ten":"Khỏa Tam Châm","sections":[{"h":"VỊ TRÍ","body":"3 huyệt ở mắt cá chân gồm: Côn Lôn (Bq 67) + Giải Khê (Vi 41) + Thái Khê (Th 3)"},{"h":"CHỦ TRỊ","body":"Trị bại liệt."},{"h":"CHÂM CỨU","body":"Tùy theo vị trí từng huyệt."}]},{"id":392,"ten":"Khoan Cốt","sections":[{"h":"VỊ TRÍ","body":"Huyệt Lương Khâu (Vi 34) ra ngang 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị khớp gối viêm, chi dưới liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút.\t,\n\""}]},{"id":393,"ten":"Khố Phòng","sections":[{"h":"VỊ TRÍ","body":"Ở khoảng gian sườn 1, ngay dưới huyệt Khí Hộ (Vi 13), cách đường giữa ngực 4 thốn."},{"h":"CHỦ TRỊ","body":"Trị thần kinh liên sườn đau, khí quản viêm, Hysteria."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,8 thốn, cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ ngực to, các cơ gian sườn 1, bờ trên xương sườn 2, đỉnh phổi.\nThần kinh vận động cơ là nhánh ngực to của đám rối thần kinh nách, dây thần kinh gian sườn 1.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C4."}]},{"id":394,"ten":"Khổng Cấp","sections":[{"h":"VỊ TRÍ","body":"Ở mu bàn tay, giữa đầu xương bàn tay 3 – 4, lùi về phía sau 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị thần kinh sườn đau, dạ dầy đau, túi mật viêm, giun chui ống mật, sỏi mật."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn.F\nN/"}]},{"id":395,"ten":"Khổng Tối","sections":[{"h":"VỊ TRÍ","body":"Ở bờ ngoài cẳng tay, trên cổ tay 7 thốn, nơi gặp nhau của bờ trong cơ ngửa dài hay bờ ngoài của cơ gan tay to với đường ngang trên khớp cổ tay 7 thốn, trên đường thẳng nối huyệt Xích Trạch (P 5) và Thái Uyên (P 9)"},{"h":"CHỦ TRỊ","body":"Trị tay và khuỷu tay đau, ho, suyễn, amidal viêm, phổi viêm, ho ra máu."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Cứu 3 – 7 tráng, Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ trong cơ ngửa dài, bờ ngoài cơ gan tay to, cơ sấp tròn, cơ gấp chung nông các ngón tay.\nThần kinh vận động cơ là các nhánh của dây thần kinh giữa và thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C6."}]},{"id":396,"ten":"Khuất Cốt Đoan","sections":[{"h":"VỊ TRÍ","body":"Tại ngay giữa nếp háng."},{"h":"CHỦ TRỊ","body":"Trị tiểu gắt, tiểu bí, sán khí."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút."}]},{"id":397,"ten":"Khuất Dương Ủy","sections":[{"h":"VỊ TRÍ","body":"Gấp cánh tay lại, huyệt tại chỗ lõm bên ngoài nếp gấp khuỷu tay 1 ít."},{"h":"CHỦ TRỊ","body":"Trị thần kinh rối loạn."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 2 thốn. Cứu 5 – 10 phút.WF\n3"}]},{"id":398,"ten":"Khúc Cốt","sections":[{"h":"VỊ TRÍ","body":"Ở trên xương mu, dưới huyệt Trung Cực 1 thốn hoặc chỗ lõm ngay chính giữa bờ trên xương mu."},{"h":"CHỦ TRỊ","body":"Trị bàng quang viêm, dịch hoàn viêm, tử cung sa, kinh nguyệt không đều, tiểu khó, tiểu bí."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 1,5 thốn. Cứu 10 – 45 phút."},{"h":"GIẢI PHẪU","body":"Huyệt ở trên đường trắng giữa bụng, giữa nền và trụ của đường trắng. Sau đường trắng là mạc ngang và phúc mạc. Vào sâu là ổ bụng dưới, có đáy bàng quang khi rỗng, đáy của tử cung khi không có thai.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L1.\nHuyệt bên trái gọi là Bào Môn, bên phải là Tử Hộ."}]},{"id":399,"ten":"Khúc Sai","sections":[{"h":"VỊ TRÍ","body":"Trên trán, cách đường giữa đầu 1,5 thốn, trong chân tóc 0,5 thốn, cách ngang Mi Xung 01 thốn."},{"h":"CHỦ TRỊ","body":"Trị đầu và vùng trán đau, mũi nghẹt, mũi chảy máu."},{"h":"CHÂM CỨU","body":"Châm luồn dưới da 0,3 – 0,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là chỗ bám của cơ trán vào cân sọ, dưới cân sọ là xương sọ.\nThần kinh vận động cơ là nhánh của dây thần kinh mặt.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V."}]},{"id":400,"ten":"Khúc Tân","sections":[{"h":"VỊ TRÍ","body":"Tại giao điểm của đường nằm ngang bờ trên tai ngoài và đường thẳng trước tai ngoài, trên chân tóc, sát động mạch thái dương nông."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, cổ gáy cứng, co cứng hàm nhai, đau sưng vùng má và hàm trên."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn. Cứu 1 – 3 tráng. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ tai trên, cơ thái dương, xương thái dương.\nThần kinh vận động cơ là nhánh của dây thần kinh mặt, nhánh của dây thần kinh sọ não số V.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V."}]},{"id":401,"ten":"Khúc Trạch","sections":[{"h":"VỊ TRÍ","body":"Trên nếp gấp khớp khuỷu tay, chỗ lõm phía trong khuỷu tay, bờ trong gân cơ 2 đầu cánh tay."},{"h":"CHỦ TRỊ","body":"Trị sốt, hồi hộp, dạ dày đau, thấp tim."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 0,8 thốn.\nTrường hợp trị sốt cao do trường vị viêm cấp, do trúng nắng, có thể dùng kim Tam Lăng châm nặn ra ít máu ở huyệt này.\nCứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ trong gân cơ 2 đầu cánh tay, co cánh tay trước, bờ trên cơ sấp tròn, khe khớp khủy.\nThần kinh vận động cơ là các nhánh của dây thần kinh cơ – da và dây thần kinh giữa.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D1 hoặc"}]},{"id":402,"ten":"Khúc Trì","sections":[{"h":"VỊ TRÍ","body":"Co khuỷu tay vào ngực, huyệt ở đầu lằn chỉ nếp gấp khuỷu, nơi bám của cơ ngửa dài, cơ quay 1, cơ ngửa ngắn khớp khủy."},{"h":"CHỦ TRỊ","body":"Trị khuỷu tay đau, cánh tay đau, chi trên liệt, vai đau, sốt, cảm cúm, dị ứng, ngứa, da viêm, huyết áp cao."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn hoặc xuyên tới huyệt Thiếu Hải, sâu 2 – 2,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là chỗ bám của cơ ngửa dài, cơ quay 1, cơ ngửa ngắn khớp khủy.\nThần kinh vận động cơ là các nhánh của dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C6.Lv\"W8[lo"}]},{"id":403,"ten":"Khúc Trì Đinh Tự Thích","sections":[{"h":"VỊ TRÍ","body":"Từ huyệt Khúc trì đến huyệt Thiếu Hải là một huyệt châm.\nTừ huyệt Khúc Trạch là một huyệt châm.\nHai huyệt châm tạo thành hai nhóm huyệt."},{"h":"CHỦ TRỊ","body":"Trị liệt chi trên, khớp khuỷu tay đau, họng đau, thanh quản sưng đau, huyết áp cao, sốt cao, tuyến giáp viêm, phong ngứa, mề đay."},{"h":"CHÂM CỨU","body":"Châm từ huyệt Khúc Trì xuyên đến huyệt Thiếu Hải rồi châm Khúc Trạch sâu thẳng 1 thốn."}]},{"id":404,"ten":"Khúc Tuyền","sections":[{"h":"VỊ TRÍ","body":"Ở đầu trong nếp gấp nhượng chân, nơi khe giữa của bờ trước gân cơ bán mạc và cơ thẳng trong."},{"h":"CHỦ TRỊ","body":"Trị khớp gối và tổ chức phần mềm quanh khớp gối viêm, đau do thoát vị (sán khí), liệt dương, di tinh, viêm nhiễm ở hệ tiết niệu và sinh dục."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa gân cơ bán mạc và gân cơ thẳng trong, đầu trên cơ sinh đôi trong, khe khớp kheo.\nThần kinh vận động cơ là các nhánh của dây thần kinh hông kheo to và dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L3."}]},{"id":405,"ten":"Khúc Viên","sections":[{"h":"VỊ TRÍ","body":"Huyệt ở 1/3 trong bờ trên gai xương bả vai, cách huyệt Bỉnh Phong 1,5 thốn, giữa huyệt Nhu Du (Ttr 10) và gai đốt sống lưng 2."},{"h":"CHỦ TRỊ","body":"Trị khớp vai đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Cứu 3 – 5 phút, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ thang, cơ trên gai, chỗ bám của cơ góc, góc trên – trong của xương bả vai.\nThần kinh vận động cơ là các nhánh của dây thần kinh sọ não số XI, nhánh đám rối cổ sâu, nhánh dây thần kinh trên vai, nhánh của dây thần kinh chẩm lớn.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C5."}]},{"id":406,"ten":"Khúc Xích","sections":[{"h":"VỊ TRÍ","body":"Ở phía trong – trước mu bàn chân, phía dưới trước mắt cá chân, tại chỗ lõm bờ trong cơ cẳng trước."},{"h":"CHỦ TRỊ","body":"Trị cổ trướng, quanh rốn đau, bụng dưới đau, thắt lưng đau, di tinh."},{"h":"CHÂM CỨU","body":"châm xiên sâu 0,3 – 0,5 thốn. Cứu 3 – 5 tráng.c\nEm"}]},{"id":407,"ten":"Khuyết Bồn","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm sát bờ trên xương đòn, ngay đầu ngực thẳng lên, dưới huyệt là hố trên đòn."},{"h":"CHỦ TRỊ","body":"Trị thần kinh liên sườn đau, họng đau, suyễn."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là hố trên đòn, có các cơ bậc thang và cơ vai – móng.\nThần kinh vận động cơ là các nhánh trước của dây thần kinh cổ số 3, 4, 5 và nhánh của dây thần kinh sọ não số XII."}]},{"id":408,"ten":"Khử Đờm Thuật","sections":[{"h":"VỊ TRÍ","body":"Gồm 7 huyệt nằm trên mạch Nhâm là Cưu Vĩ, Trung Đình, Chiên Trung, Ngọc Đường, Tử Cung, Hoa Cái, Triền Cơ, 7 huyệt này làm thành một nhóm huyệt."},{"h":"CHỦ TRỊ","body":"Trị khí quản viêm, suyễn, lao phổi, ngực đau, hysteria, động kinh, suy tim, huyết áp thấp, nhịp tim nhanh."},{"h":"CHÂM CỨU","body":"Châm kim xiên từ huyệt Cưu vĩ dọc theo da lên đến huyệt Triền cơ."}]},{"id":409,"ten":"Kiếm Cự","sections":[{"h":"VỊ TRÍ","body":"Tại mặt trong cẳng tay, từ nếp gấp cổ tay lên 3,2 thốn, gần huyệt Gian Sử (Tb 5), hướng ngón tay áp út thẳng lên."},{"h":"CHỦ TRỊ","body":"Trị chứng mã đao (mụn nhọt ở cổ)"},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút.r\n\""}]},{"id":410,"ten":"Kiên Bối","sections":[{"h":"VỊ TRÍ","body":"Huyệt Khuyết bồn đo xéo lên cơ thang 2 thốn, về phía huyệt Kiên tỉnh."},{"h":"CHỦ TRỊ","body":"Trị vai lưng đau, lưng gáy đau, sốt rét."},{"h":"CHÂM CỨU","body":"Châm xiên qua cơ thang, xuống huyệt Đào đạo hoặc Thân trụ.F\n)"}]},{"id":411,"ten":"Kiên Du","sections":[{"h":"VỊ TRÍ","body":"Tại giữa huyệt Kiên Ngung (Đtr 15) và huyệt Vân Môn (P 2)"},{"h":"CHỦ TRỊ","body":"Trị vai và tay đau không giơ lên được."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 10 phút.;\n't"}]},{"id":412,"ten":"Kiên Đầu","sections":[{"h":"VỊ TRÍ","body":"Nâng tay lên, huyệt ở chỗ lõm khớp vai, sát phía trên huyệt Kiên Ngung (Đtr 15)"},{"h":"CHỦ TRỊ","body":"Trị ngứa, răng đau, vai lưng đau, chung quanh khớp vai sưng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút.Q\nA"}]},{"id":413,"ten":"Kiên Liêu","sections":[{"h":"VỊ TRÍ","body":"Đưa cánh tay ngang vai, hiện ra 2 chỗ hõm ở mỏm vai, huyệt ở chỗ hõm phía dưới và sau mỏm cùng vai, sau huyệt Kiên Ngung (Đtr 15) 1 thốn, dưới huyệt là khe giữa bó cùng và bó gai sống của cơ delta."},{"h":"CHỦ TRỊ","body":"Trị quanh khớp vai đau, chi trên liệt và đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn khi trị bệnh ở khớp vai.\nChâm xiên, hướng xuống trong điều trị bệnh ở quanh khớp vai.\nChâm mũi kim giữa 2 khớp xương mỏm cao của xương đòn gánh và khớp xương lớn của cánh tay, mũi kim hướng xuống hoặc xuyên thấu huyệt Cực Tuyền khi trị cánh tay bị lệch ra ngoài."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa bó cùng và bó gai sống của cơ Delta, cơ trên sống, cơ dưới sống, khe của mỏm cùng vai và đầu trên xương cánh tay.\nThần kinh vận động cơ là dây thần kinh mũ, dây thần kinh trên vai.\nDa vùng huyệt chi phối bởi tiết doạn thần kinh C4."}]},{"id":414,"ten":"Kiên Ngoại Du","sections":[{"h":"VỊ TRÍ","body":"Dưới gai bên đốt sống 1, cách giữa lưng 3 thốn, trên đường mép bờ trong xương bả vai."},{"h":"CHỦ TRỊ","body":"Trị khớp vai đau; bả vai, cổ tay đau cứng."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 1 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ thang, cơ góc, cơ răng bé sau – trên.\nThần kinh vận động cơ là các nhánh của dây chẩm lớn, nhánh của dây sọ não số XI, nhánh của đám rối cổ sâu, nhánh dây trên vai và dây gian sườn 1.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C7."}]},{"id":415,"ten":"Kiên Ngung","sections":[{"h":"VỊ TRÍ","body":"Dang cánh tay thẳng, huyệt ở chỗ lõm, phía trước và ngoài khớp, mỏm cùng – xương đòn."},{"h":"CHỦ TRỊ","body":"Trị cánh tay và vai đau, khớp vai đau, cơ đau do phong thấp, bán thân bất toại, bệnh ngoài da."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1,5 thốn hoặc giơ tay lên cho ngang với vai, châm thẳng tới huyệt Cực Tuyền (hố nách).\nTrị bệnh ở cơ bó đòn và bó cùng: xuôi tay xuống, châm mũi kim giữa khớp xương cánh tay và khớp vai, sâu 0,5 – 1 thốn, khi đắc khí rồi thì hướng mũi kim ra 2 bên (mỗi bên sâu 2 – 3 thốn) cho đến khi có cảm giác như điện giật xuống vùng cánh tay.\nTrị tay lệch ra ngoài thì châm luồn kim dưới da, hướng kim về phía cơ tam giác.\nCứu 3 – 5 tráng, Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa bó đòn và bó cùng vai của cơ Delta, khe khớp – giữa xương bả vai và xương cánh tay.\nThần kinh vận động cơ là dây thần kinh mũ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C4."}]},{"id":416,"ten":"Kiên Nội Du","sections":[{"h":"VỊ TRÍ","body":"Từ giữa huyệt Kiên Ngung (Đtr 15) và Vân Môn (P 2) đo xuống 1 thốn tức dưới huyệt Kiên Du 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị vai tay đau không giơ lên được."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."}]},{"id":417,"ten":"Kiên Nội Lăng","sections":[{"h":"VỊ TRÍ","body":"Buông thả tay, huyệt nằm ở giữa huyệt Kiên Ngung (Đtr 15) và cuối nếp nhăn ở nách trước."},{"h":"CHỦ TRỊ","body":"Trị trúng phong, liệt nửa người, đau thần kinh hoặc cơ do phong thấp, khớp vai viêm, huyết áp cao, mồ hôi ra nhiều."},{"h":"CHÂM CỨU","body":"Châm: Thẳng, hướng ra sau vai, sâu 1 – 1,5 thốn.\nKhi điều trị viêm gân cơ 2 đầu có thể hướng mũi kim xuống dưới 2 – 3 thốn.\nCứu: 3 – 7 tráng, Ôn cứu 5 – 20 phút."}]},{"id":418,"ten":"Kiên Tam Châm","sections":[{"h":"VỊ TRÍ","body":"Gồm 3 huyệt: Kiên Ngung (Đtr 15) + Kiên Tiền (trên nếp gấp nách trước 1 thốn) + Kiên Hậu (trên nếp gấp nách sau 1 thốn)"},{"h":"CHỦ TRỊ","body":"Trị khớp vai viêm, bệnh thuộc tổ chức mềm ở khớp vai, bại liệt, chi trên liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1,5 – 2 thốn."}]},{"id":419,"ten":"Kiên Thống Điểm","sections":[{"h":"VỊ TRÍ","body":"Điểm giữa bờ ngoài xương bả vai."},{"h":"CHỦ TRỊ","body":"Trị chi trên liệt, khớp vai viêm, quanh tổ chức mềm khớp vai viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 0,8 thốn."}]},{"id":420,"ten":"Kiên Thượng","sections":[{"h":"VỊ TRÍ","body":"Giữa điểm nối huyệt Đại chùy và bả vai."},{"h":"CHỦ TRỊ","body":"Trị khớp vai đau nơi người lớn tuổi, họng đau, răng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,4 – 0,6 thốn. Cứu 3 – 7 tráng."}]},{"id":421,"ten":"Kiên Tỉnh","sections":[{"h":"VỊ TRÍ","body":"Tại giao điểm của đường thẳng ngang qua đầu ngực với đường ngang nối huyệt Đại Chùy (Đc 14) và điểm cao nhất của đầu ngoài xương đòn, ấn vào có cảm giác ê tức.\nHoặc đứng thẳng, dùng tay áp vào ngực, với sang bả vai phía đối diện, làm sao cho bàn tay úp vào vùng vai – cơ thang, đầu ngón tay giữa chạm vào vùng vai chỗ nào, đó là huyệt."},{"h":"CHỦ TRỊ","body":"Trị vai lưng đau, cổ gáy cứng, tuyến vú viêm, rong kinh cơ năng, lao hạch cổ, bại liệt do trúng phong."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 0,8 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ thang, cơ trên sống và cơ góc.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số XI, nhánh dây thần kinh cổ 2, nhánh của dây thần kinh trên vai.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C4."}]},{"id":422,"ten":"Kiên Trinh","sections":[{"h":"VỊ TRÍ","body":"Đặt cánh tay lên hông sườn, huyệt ở mặt sau vai, từ đầu chỉ nếp nách thẳng lên 1 thốn hoặc chỗ lõm ở giao điểm đường dọc từ Kiên Ngung (Đtr 15) xuống và đường ngang qua lằn sau nách, cách tuyến giữa lưng 6 thốn."},{"h":"CHỦ TRỊ","body":"Trị quanh khớp vai và tổ chức phần mềm quanh khớp vai đau, cánh tay đau, chi trên liệt, mồ hôi nách ra nhiều."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là cơ Delta khe giữa cơ tròn to, cơ tròn bé, phần dài cơ 3 đầu cánh tay.\nThần kinh vận động cơ là dây thần kinh mũ, các nhánh dây thần kinh trên vai, nhánh của dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D2."}]},{"id":423,"ten":"Kiên Trụ Cốt","sections":[{"h":"VỊ TRÍ","body":"Sau lưng, ngay cuối đỉnh xương giáp vai."},{"h":"CHỦ TRỊ","body":"Trị loa lịch [lao hạch], vai và tay đau."},{"h":"CHÂM CỨU","body":"Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút."}]},{"id":424,"ten":"Kiên Trung Du","sections":[{"h":"VỊ TRÍ","body":"Cách tuyến giữa lưng 2 thốn, ngang đốt sống cổ 7, trên đường nối huyệt Đại Chùy (Đc 14) và Kiên Tỉnh (Đ 21)"},{"h":"CHỦ TRỊ","body":"Trị vai đau, lưng và cổ gáy cứng, suyễn, khí quản viêm."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 0,8 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ thang, cơ góc, cơ răng bé sau – trên, cơ chậu sườn đoạn lưng cổ, cơ ngang sườn, cơ gian mỏng ngang.\nThần kinh vận động cơ là các nhánh của dây thần kinh sọ não số XI, nhánh đám rối cổ sâu, nhánh dây chẩm lớn, nhánh dây sống cổ và nhánh dây gian sườn số 1.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C6."}]},{"id":425,"ten":"Kiến Lý","sections":[{"h":"VỊ TRÍ","body":"Lỗ rốn thẳng lên 3 thốn, hoặc lấy đường nối 2/8 dưới và 6/8 trên của đoạn nối rốn và điểm gặp nhau của 2 bờ sườn."},{"h":"CHỦ TRỊ","body":"Trị dạ dầy đau, nôn mửa, bụng đầy, khó tiêu, phù thũng."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1,5 thốn. Cứu 10 – 30 phút."},{"h":"GIẢI PHẪU","body":"Huyệt ở trên đường trắng. Sau đường trắng là mạc ngang, phúc mạc, vào sâu là tụy tạng và tá tràng hoặc tử cung khi có thai gần đẻ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D2."}]},{"id":426,"ten":"Kiến Minh","sections":[{"h":"VỊ TRÍ","body":"Tại phía ngoài cánh tay, bờ sau cơ tam giác. Điểm cuối của cơ tam giác phía sau đo lên 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị bệnh mắt, bại xụi, tay liệt."},{"h":"CHÂM CỨU","body":"Châm hướng lên trên, xiên 2 – 3 thốn."}]},{"id":427,"ten":"Kiện Khố","sections":[{"h":"VỊ TRÍ","body":"Xác định điểm cao nhất của xương mào chậu và mấu chuyển lớn xương đùi, Huyệt là điểm giữa của đường thẳng nối 2 điểm này."},{"h":"CHỦ TRỊ","body":"Trị liệt nửa người."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 2 – 3 thốn."}]},{"id":428,"ten":"Kiện Lý Tam Huyệt","sections":[{"h":"VỊ TRÍ","body":"Giữa lòng bàn tay, chính giữa khe xương bàn tay thứ 3 – 4 đo thẳng ra sau 1 thốn là 1 huyệt, từ đó lại đo ra 2 bên mỗi bên một huyệt nữa. Tất cả là 3 huyệt."},{"h":"CHỦ TRỊ","body":"Trị bệnh thuộc Can, Tỳ, Vị, đầu đau, bệnh về mắt, khí quản viêm, hen suyễn, hồi hộp, tim suy, thận viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng hoặc xiên, sâu 1 thốn."}]},{"id":429,"ten":"Kiện Tất","sections":[{"h":"VỊ TRÍ","body":"Co chân, huyệt ở bờ trên xương bánh chè 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị chi dưới liệt, bại xuội, khớp gối viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng hoặc xiên 1 – 2 thốn."}]},{"id":430,"ten":"Kim Môn","sections":[{"h":"VỊ TRÍ","body":"Dưới và trước huyệt Thân Mạch (Bq 62), cách Thân Mạch 0,5 thốn, nơi chỗ lõm chếch về phía trước sát bờ xương hộp, đầu sau xương bàn chân 5."},{"h":"CHỦ TRỊ","body":"Trị quanh khớp mắt cá chân đau, gót chân và lưng đùi đau, trẻ nhỏ kinh phong, động kinh."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ dạng ngón út, gân cơ mác bên dài, gân cơ mác bên ngắn, đầu xương bàn chân 5, xương hộp.\nThần kinh vận động cơ là các nhánh của dây thần kinh cơ – da và dây thần kinh chày sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S1."}]},{"id":431,"ten":"Kim Tân Ngọc Dịch","sections":[{"h":"VỊ TRÍ","body":"Uốn cong lưỡi, huyệt tại 2 tĩnh mạch xanh 2 bên dưới lưỡi."},{"h":"CHỦ TRỊ","body":"Trị miệng lở, lưỡi viêm, họng viêm, trường vị viêm cấp tính, tiểu đường."},{"h":"CHÂM CỨU","body":"Chích nặn ra tí máu, không cứu."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là cơ cằm – lưỡi và cơ móng – lưỡi. Thần kinh vận động cơ là các nhánh của dây thần kinh sọ não số XII."}]},{"id":432,"ten":"Kinh Cốt","sections":[{"h":"VỊ TRÍ","body":"Bờ ngoài bàn chân, thẳng với ngón út, trước huyệt Kim Môn (Bq 63), đầu sau xương bàn chân 5, nơi tiếp giáp làn da đổi màu."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, chóng mặt, hồi hộp, động kinh, cơ tim viêm, lưng, đùi đau."},{"h":"CHÂM CỨU","body":"Châm xiên, mũi kim hướng vào trong phía dưới, sâu 0,3 – 0,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ dạng ngón chân út, cùng xương bàn chân 5.\nThần kinh vận động cơ là nhánh của dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh"}]},{"id":433,"ten":"Kinh Cừ","sections":[{"h":"VỊ TRÍ","body":"Trên lằn chỉ cổ tay 1 thốn, ở mặt trong đầu dưới xương quay."},{"h":"CHỦ TRỊ","body":"Trị bàn tay và cổ tay đau, ngực đau, họng đau, ho, suyễn."},{"h":"CHÂM CỨU","body":"Châm thẳng hoặc xiên 0,3 – 0,5 thốn. Ôn cứu 3 – 5 thốn."},{"h":"GIẢI PHẪU","body":"Dưới da là rãnh mạch quay. Rãnh tạo nên bởi gân cơ ngửa dài và mặt trong đầu dưới xương quay (ở ngoài), gân cơ gan tay to và gân cơ gấp chung nông (ở trong), gân cơ gấp riêng ngón tay cái và cơ sấp vuông (ở đáy rãnh).\nThần kinh vận động cơ là các nhánh của dây thần kinh giữa và dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C6.e\t=+:8ÙP2Châm đắc khí tại chỗ có cảm giác căng tức."}]},{"id":434,"ten":"Kinh Môn","sections":[{"h":"VỊ TRÍ","body":"Ngang vùng bụng, huyệt ở bờ dưới đầu xương sườn tự do thứ 12."},{"h":"CHỦ TRỊ","body":"Trị thần kinh liên sườn đau, bụng đầy, vùng bụng đau, Thận viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ chéo to của bụng, cơ chéo bé của bụng, cơ ngang bụng, đầu cụt xương sườn 12, mạc ngang, phúc mạc, thận.\nThần kinh vận động cơ là 6 dây thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D9."}]},{"id":435,"ten":"Kinh Môn Trạch Điền","sections":[{"h":"VỊ TRÍ","body":"Giữa gai xương thắt lưng 2 – 3 đo ngang ra hai bên, mỗi bên 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị viêm thận, hói tóc hai bên trán, lông mi thưa."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,9 thốn. Cứu 3 – 10 tráng.D\n32"}]},{"id":436,"ten":"Kinh Môn Tứ Hoa","sections":[{"h":"VỊ TRÍ","body":"Lấy huyệt Tứ Hoa (Cách Du + Đởm Du), bỏ 2 huyệt trên (Cách Du) đi, tức chỉ lấy huyệt Đởm Du, từ đó đo lên và xuống 2 bên mỗi bên 1 thốn, được tất cả 6 huyệt, bỏ 2 huyệt ở trên đi còn 4 huyệt, gọi là Kinh Môn Tứ Hoa."},{"h":"CHỦ TRỊ","body":"Trị khí quản viêm, suyễn, lao phổi, phế khí thũng."},{"h":"CHÂM CỨU","body":"Cứu."}]},{"id":437,"ten":"Kinh Trung","sections":[{"h":"VỊ TRÍ","body":"Rốn đo xuống 1,5 thốn (huyệt Khí Hải (Nh 6) rồi đo ra ngang 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị tiêu tiểu không thông, ngũ lâm, đới hạ, kinh nguyệt không đều, ruột co thắt, bụng căng, sôi ruột, ruột viêm, thiếu máu."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 1,5 thốn."}]},{"id":438,"ten":"Kỳ Môn","sections":[{"h":"VỊ TRÍ","body":"Huyệt nằm trên đường thẳng ngang qua đầu ngực, trong khoảng gian sườn (của sườn) thứ 6 – 7."},{"h":"CHỦ TRỊ","body":"Trị màng ngực viêm, gan viêm, ngực đau, thần kinh liên sườn đau."},{"h":"CHÂM CỨU","body":"Châm xiên hoặc luồn kim dưới da, sâu 0,5 – 0,8 thốn. Cứu 3 – 7 tráng, Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ chéo to của bụng, các cơ gian sườn 6, bên phải là gan, bên trái là lách.\nThần kinh vận động cơ là dây thần kinh gian sườn 6.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C5."}]},{"id":439,"ten":"Kỷ Môn","sections":[{"h":"VỊ TRÍ","body":"Đầu vú đo thẳng xuống 2 xương sườn, huyệt ở giữa khe sườn."},{"h":"CHỦ TRỊ","body":"Trị vú đau, sườn đầy tức."},{"h":"CHÂM CỨU","body":"Châm 0,3 thốn, Cứu 3 – 7 tráng."}]},{"id":440,"ten":"Ký Hải Du","sections":[]},{"id":441,"ten":"Kỵ Trúc Mã","sections":[{"h":"VỊ TRÍ","body":"Dưới mỏm gai đốt sống lưng thứ 10, đo ra 0,5 thốn.\nHoặc xác định đốt sống lưng 7 để tìm đốt sống lưng 10 bằng cách dựa vào xương sườn cụt. Dưới mỏm gai đốt sống lưng 10 đo ra 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị các loại mụn nhọt, ghẻ lở, đinh nhọt, sưng lở, bướu cổ, tràng nhạc."},{"h":"CHÂM CỨU","body":"Châm: 0,5 – 1 thốn. Cứu 20 – 30 tráng. Ôn cứu 10 – 20 phút."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là cơ thang, cơ lưng to, cơ gian gai, cơ bán gai, cơ ngang gai, khoảng đốt sống lưng 10.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số XI, nhánh đám rối cổ sâu, nhánh đám rối cánh tay, các nhánh của dây sống lưng"}]},{"id":442,"ten":"Lạc Cảnh","sections":[{"h":"VỊ TRÍ","body":"Chỗ trũng sau tai (huyệt Ế Phong – Ttu 17) đo xuống 2 thốn, ngay mỏm nhọn của góc xương hàm dưới.\nTại giao điểm của 1/3 phía dưới – trong – trên cơ ức đòn chũm."},{"h":"CHỦ TRỊ","body":"Trị gáy cứng, cổ vẹo."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 0,8 thốn. Cứu 5–10 phút."}]},{"id":443,"ten":"Lạc Chẩm","sections":[{"h":"VỊ TRÍ","body":"Ở mu bàn tay, giữa đốt xương bàn tay ngón 2 và 3, sau khớp nối bàn và ngón tay khoảng 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị gáy đau, gáy cứng, nửa đầu đau, vai và tay đau, họng đau, dạ dầy đau."},{"h":"CHÂM CỨU","body":"Châm thẳng hoặc xiên 0,5–1 thốn."}]},{"id":444,"ten":"Lạc Chẩm","sections":[]},{"id":445,"ten":"Lạc Địa","sections":[{"h":"VỊ TRÍ","body":"Giữa nếp sau chân (huyệt Ủy Trung – Bq.40) đo xuống 9,5 thốn (dưới huyệt Thừa Sơn 1,5 thốn)"},{"h":"CHỦ TRỊ","body":"Trị di chứng bại liệt trẻ nhỏ."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1–2 thốn. Cứu 5–10 phút."}]},{"id":446,"ten":"Lạc Khích","sections":[]},{"id":447,"ten":"Lạc Khước","sections":[{"h":"VỊ TRÍ","body":"Ngay sau huyệt Thông Thiên 1,5 thốn, cách tuyến giữa đầu 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị vùng đỉnh đầu đau, phế quản viêm mạn, mũi viêm."},{"h":"CHÂM CỨU","body":"Châm luồn dưới da 0,3 – 0,5 thốn. Cứu 1 – 3 tráng. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân sọ, xương sọ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C2."}]},{"id":448,"ten":"Lãi Câu","sections":[{"h":"VỊ TRÍ","body":"Ở bờ sau xương chày, cách trên đỉnh mắt cá trong 5 thốn."},{"h":"CHỦ TRỊ","body":"Trị khớp xương chậu viêm, tiểu bí, di tinh, liệt dương."},{"h":"CHÂM CỨU","body":"Châm thẳng vào bờ sau xương chày, sâu 0,5– 0,8 thốn.\nTrị cơ thể đau: hướng mũi kim lên bờ sau xương chày 1,5 – 2 thốn, sau khi đắc khí, vê mạnh có cảm giác căng tức lan lên đầu gối hoặc lan tới vùng bộ phận sinh dục.\nCứu 1 – 3 tráng, Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là mặt trước – trong của xương chầy.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L4."}]},{"id":449,"ten":"Lan Môn","sections":[{"h":"VỊ TRÍ","body":"Giữa bờ trên xương mu (huyệt Khúc Cốt – Nh.2) đo ngang ra 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị bôn đồn, sán khí âm hộ sưng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."}]},{"id":450,"ten":"Lan Môn 2","sections":[{"h":"VỊ TRÍ","body":"Đầu trong nếp gấp kheo chân (huyệt Khúc Tuyền – C.8) đo lùi ra phía sau 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị bàng quang thất sán (sán khí), bôn đồn."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1–1,5 thốn.P\n,8"}]},{"id":451,"ten":"Lan Vĩ","sections":[{"h":"VỊ TRÍ","body":"Thẳng dưới huyệt Túc Tam Lý (Vi.36) khoảng 1 – 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị ruột dư viêm cấp và mạn tính, tiêu hóa kém, ruột viêm cấp và mạn, chân bị liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng, hơi hướng về phía xương chầy, sâu 1 – 1,5 thốn hoặc xiên hướng mũi kim xuống dưới sâu 2 – 3 thốn."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ cẳng chân trước và cơ duỗi chung cẳng chân, khe giữa xương chầy và xương mác. Lớp nông có nhánh da dầy thần kinh hiển và dây thần kinh da bắp chân ngoài của tiết đoạn thần kinh thắt lưng 3 – xương cùng 2. Lớp sâu có dây thần kinh hông kheo trong của tiết đoạn thần kinh thắt lưng 4–5.\nThần kinh vận động cơ là nhánh của dây thần kinh hông to, nhánh của dây thần kinh chầy trước.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5.F47\nHuyệt bên trái gọi là Kim Tân, huyệt bên phải gọi là Ngọc Dịch."}]},{"id":452,"ten":"Lan Vĩ Điểm","sections":[{"h":"VỊ TRÍ","body":"Tại chỗ trũng nhất của cánh mũi."},{"h":"CHỦ TRỊ","body":"Trị ruột dư viêm cấp và mạn tính."},{"h":"CHÂM CỨU","body":"Châm xiên Dùng phép tả cho đến khi có cảm giác đau và tê là được.F\t)"}]},{"id":453,"ten":"Lao Cung","sections":[{"h":"VỊ TRÍ","body":"Huyệt ở trên đường văn tim của gan bàn tay, nơi khe của ngón giữa và ngón vô danh (ngón 4) chạm vào đường văn này hoặc gấp các ngón tay vào lòng bàn tay, đầu ngón tay giữa chạm vào đường nếp gấp giữa lòng bàn tay (đường tâm đạo) ở đâu thì đó là huyệt."},{"h":"CHỦ TRỊ","body":"Trị mồ hôi tay, eczema ở vùng bàn tay, vùng tim đau, động kinh, nấc, xoang miệng viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng từ lòng bàn tay hướng về phía lưng bàn tay đối diện 0,3 – 0,5 thốn. Cứu 1 – 3 tráng, ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân tay giữa, cơ giun, phía trong gân gấp ngón giữa của cơ gấp chung ngón tay nông và sâu, cơ gian cốt gan tay và cơ gian cốt mu tay, bờ trong đầu dưới xương bàn tay 3.\nThần kinh vận động cơ là nhánh của dây thần kinh giữa và dây thần kinh trụ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C7 hoặc C8.l!\nTránh châm sâu vào xương và động mạch.\nSách Giáp Ất ghi không cứu vì có thể ảnh hưởng đến thần minh."}]},{"id":454,"ten":"Lão Thương","sections":[{"h":"VỊ TRÍ","body":"Tại mé ngoài gốc móng ngón tay cái, cách gốc móng 0,1 thốn."},{"h":"CHỦ TRỊ","body":"Trị amidal viêm, cúm, quai bị."},{"h":"CHÂM CỨU","body":"Châm nặn máu."}]},{"id":455,"ten":"Lạt Ma","sections":[{"h":"VỊ TRÍ","body":"Phía sau lưng vai, lấy giao điểm của đường thẳng ngang qua mỏm gai đốt sống lưng 4 và đường thẳng ngang qua chỗ dày nhất của gai sống vai (tức huyệt Thiên Tông – Ttr.11), từ đó xiên tới đầu nếp nách chừng 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị họng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,8 – 1 thốn."}]},{"id":456,"ten":"Lặc Đầu","sections":[{"h":"VỊ TRÍ","body":"Tại khe xương sườn thứ 1 – 2 và 2 – 3, hai bên có 4 huyệt."},{"h":"CHỦ TRỊ","body":"Trị ho suyễn, nấc cụt."},{"h":"CHÂM CỨU","body":"Cứu 3 – 7 tráng."}]},{"id":457,"ten":"Lặc Đường","sections":[{"h":"VỊ TRÍ","body":"Dưới hố nách 2 thốn hoặc xác định huyệt Uyên Dịch (Đ.22) hơi hướng lên phía trước – ngoài 1 thốn."},{"h":"CHỦ TRỊ","body":"(Phối hợp với huyệt Cử Tý) trị ngực sườn đầy trướng, bụng đầy, ho suyễn, mắt vàng, thần kinh hông sườn đau."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3–0,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."}]},{"id":458,"ten":"Lặc Há","sections":[{"h":"VỊ TRÍ","body":"Đầu vú thẳng ra đến kẽ sườn thẳng hố nách xuống."},{"h":"CHỦ TRỊ","body":"Trị ngực đau, hông sườn đau, ho."},{"h":"CHÂM CỨU","body":"Cứu 5 – 10 phút.1\n!"}]},{"id":459,"ten":"Lăng Hạ","sections":[{"h":"VỊ TRÍ","body":"Dưới huyệt Dương Lăng Tuyền (Đ.34) khoảng 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị mật có sạn, giun chui ống mật, điếc."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1–2 thốn. Cứu 5 – 10 phút."}]},{"id":460,"ten":"Lăng Hậu","sections":[{"h":"VỊ TRÍ","body":"Tại chỗ trũng bờ sau đầu nhỏ xương mác, ấn vào có đường gân, đối diện ngang với huyệt Dương Lăng Tuyền (Đ."},{"h":"CHỦ TRỊ","body":"Trị ngực và sườn đau, thần kinh đùi đau, thần kinh tọa đau, khớp gối viêm, khớp gối biến dạng, chi dưới liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 2 thốn. Cứu 5 – 20 phút."}]},{"id":461,"ten":"Lăng Hậu Hạ","sections":[{"h":"VỊ TRÍ","body":"Dưới huyệt Lăng Hậu 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị khớp gối viêm, thần kinh tọa đau, chi dưới liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 2 thốn. Cứu 5 – 10 phút.7\n5"}]},{"id":462,"ten":"Lâm Tuyền","sections":[{"h":"VỊ TRÍ","body":"Đo 2 bên khóe miệng thành 1 đơn vị khẩu thốn, đặt trên huyệt Trường Cường (Đc.1), đo lên 1 khẩu thốn, ra ngang 2 bên mỗi bên 0,5 thốn (Châm Cứu Tập Thành)"},{"h":"CHỦ TRỊ","body":"Trị các bệnh lâm lậu, bệnh đường tiểu."},{"h":"CHÂM CỨU","body":"Cứu 5–10 phút.0\n'b"}]},{"id":463,"ten":"Lập Mạng","sections":[{"h":"VỊ TRÍ","body":"Tại giao điểm của đường thẳng ngang lỗ mũi kéo ra chạm vào chân viền cánh mũi."},{"h":"CHỦ TRỊ","body":"Trị mũi nghẹt, cuồng ngôn, loạn ngữ, tim hồi hộp."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,2 – 0,3 thốn.\tO\n2j"}]},{"id":464,"ten":"Lậu Âm","sections":[{"h":"VỊ TRÍ","body":"Dưới mắt cá chân trong khoảng 0,5 thốn, phía sau huyệt Chiếu Hải (Th."},{"h":"CHỦ TRỊ","body":"Trị các bệnh lâm lậu mạn tính, bệnh đường tiểu, băng lậu, xích bạch đới."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 10 phút.I\nID"}]},{"id":465,"ten":"Lậu Cốc","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm sát bờ sau trong xương chày, từ đỉnh cao của mắt cá trong đo thẳng lên 6 thốn."},{"h":"CHỦ TRỊ","body":"Trị cẳng chân đau, chi dưới liệt, bụng trướng, ruột sôi."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ sau – trong xương chầy, bờ trong cơ dép, cơ gấp dài các ngón chân, cơ cẳng sau chân.\nThần kinh vận động cơ là các nhánh của dây chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L4."}]},{"id":466,"ten":"Lệ Đoài","sections":[{"h":"VỊ TRÍ","body":"Ở phía ngoài góc ngoài móng chân ngón thứ 2, cách chân móng 0,1 thốn, trên đường tiếp giáp da gan chân – mu chân."},{"h":"CHỦ TRỊ","body":"Trị mất ngủ, răng đau, chảy máu cam, sốt cao, bàn chân lạnh."},{"h":"CHÂM CỨU","body":"Thẳng hoặc xiên 0,1 – 0,2 thốn. Cứu 1 – 3 tráng, Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là xương đốt 3 ngón chân thứ 2.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh KHÁC\nTên gọi khác của huyệt Ngoại Lao Cung (Châm Cứu Học Từ Điển)"}]},{"id":467,"ten":"Liêm Tuyền","sections":[{"h":"VỊ TRÍ","body":"Chính giữa bờ trên sụn giáp trạng, trên lằn chỉ ngang chỗ cuống hầu 0,2 thốn (Ngước đầu lên để tìm huyệt)"},{"h":"CHỦ TRỊ","body":"Trị lưỡi rụt, lưỡi cứng, lưỡi mềm nhão, thở khó, nuốt khó, chảy nước miếng, họng viêm, amidal viêm, câm, mất tiếng."},{"h":"CHÂM CỨU","body":"Châm luồn kim dưới da, mũi kim hướng ngược lên cuống lưỡi, sâu 0,2 – 1 thốn. Cứu 5 – 10 phút.\nChâm thẳng trị bệnh ở họng.\nChâm hướng về phía dưới cuống lưỡi, châm vào cơ lưỡi, trị lưỡi sưng, lưỡi cứng như gỗ, lưỡi lở loét.\nChâm xiên hướng về 2 bên phải và trái hoặc châm hướng về phía hạch hàm, dưới tai, trong tai, tuyến mang tai, trị chứng amydale (hầu nga), tai ù, điếc, tuyến mang tai viêm (Thường Dụng Du Huyệt Lâm Sàng Phát Huy)"},{"h":"GIẢI PHẪU","body":"Huyệt ở trên khe của xương móng và sụn giáp trạng. Từ nông vào sâu có cơ ức – đòn – móng, cơ giáp móng, sau cơ là thanh quản, thực quản.\nThần kinh vận động cơ do các nhánh của đám rối cổ sâu và dây thần kinh sọ não số XII.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C3.y3k.t]dV2Nếu lỡ châm làm cho người bệnh đột ngột bị câm, không nói được, châm ngay huyệt Chí Âm (Bq.67) để giải. Châm sâu 0,1 thốn, vê kim chừng nửa giờ thì có thể nói lại được (Danh Từ Huyệt Vị Châm Cứu)"}]},{"id":468,"ten":"Liệt Khuyết","sections":[{"h":"VỊ TRÍ","body":"Dưới đầu xương quay nối với thân xương, cách lằn chỉ ngang cổ tay 1,5 thốn. Hoặc chéo 2 ngón tay trỏ và ngón tay cái của 2 bàn tay với nhau, huyệt ở chỗ lõm ngay dưới đầu ngón tay trỏ."},{"h":"CHỦ TRỊ","body":"Trị cổ tay đau sưng, đầu đau, cổ gáy cứng, ho, suyễn, liệt mặt."},{"h":"CHÂM CỨU","body":"Châm xiên, hướng mũi kim vào khớp cùi chỏ, sâu 0,5 – 1 thốn, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ trong – trước của gân cơ ngửa dài, cơ gấp dài ngón cái, chỗ bám của cơ sấp vuông vào xương quay.\nThần kinh vận động cơ là nhánh của dây thần kinh giữa.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C6.\nPhối Đại Đôn (C.1) + Hành Gian (C.2) + Quan Nguyên (Nh.4) + Thái Xung (C.3) + Thủy Đạo (Vi.28) + Trung Phong (C.4) trị các loại sán khí (Y Học Cương Mục)"}]},{"id":469,"ten":"Liêu Liêu","sections":[{"h":"VỊ TRÍ","body":"Bên trong đầu gối, điểm cao nhất bên trong mắt cá xương đùi, phía dưới – ngoài huyệt Âm Lăng Tuyền 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị kinh nguyệt không đều, băng lậu, mặt trong cẳng chân bị lở ngứa."},{"h":"CHÂM CỨU","body":"Châm xiên 1 – 1,5 thốn.k\nEL"}]},{"id":470,"ten":"Linh Bảo","sections":[{"h":"VỊ TRÍ","body":"Trên lằn chỉ xếp ở nhượng chân 6 thốn, về phía mặt bên ngoài."},{"h":"CHỦ TRỊ","body":"Trị bệnh tâm thần, liệt do Hysteria."},{"h":"CHÂM CỨU","body":"Châm thẳng 2–3 thốn."}]},{"id":471,"ten":"Linh Đài","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm dưới đầu mỏm gai đốt sống lưng 6."},{"h":"CHỦ TRỊ","body":"Trị lưng đau, gáy cứng, ho suyễn."},{"h":"CHÂM CỨU","body":"Châm chếch lên, luồn dưới mỏm gai, hướng vào khoảng gian đốt sống lưng 6 – 7, sâu 0,3 – 0,8 thốn. Cứu 10 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là gân cơ thang, cân ngực – thắt lưng của cơ lưng to, cơ gai dài của lưng, cơ ngang gai, dây chằng trên gai, dây chằng gian gai, dây chằng vàng, ống sống.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số XI, nhánh đám rối cổ sâu và các nhánh của dây thần kinh sống.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh"}]},{"id":472,"ten":"Linh Đạo","sections":[{"h":"VỊ TRÍ","body":"Ở mặt trước trong cẳng tay, trên nếp gấp cổ tay 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Khớp cổ tay đau, thần kinh trụ đau, vùng tim đau, hysteria."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 0,8 thốn. Cứu 1 – 3 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa cơ trụ trước – trong và các gân cơ gấp chung\nnông các ngón tay ở ngoài, bờ trong gân cơ gấp chung sâu các ngón tay, cơ sấp vuông, xương trụ.\nThần kinh vận động cơ là các nhánh của dây thần kinh giữa và dây trụ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D1."}]},{"id":473,"ten":"Linh Khư","sections":[{"h":"VỊ TRÍ","body":"Ở khoảng gian sườn 3, cách đường giữa ngực 2 thốn, ngang huyệt Ngọc Đường (Nh."},{"h":"CHỦ TRỊ","body":"Trị ho, nôn mửa, ngực đau, tuyến vú viêm, thần kinh liên sườn đau."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ ngực to, các cơ gian sườn 3, cơ ngang ngực. Bên phải là phổi, bên trái là tim.\nThần kinh vận động cơ là dây ngực to của đám rối thần kinh nách và dây thần kinh liên sườn 3.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D3."}]},{"id":474,"ten":"Long Cốt","sections":[{"h":"VỊ TRÍ","body":"Giữa bờ trên xương mu đo thẳng xuống 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị bàng quang viêm, tiểu bí, tiểu gắt, bế kinh, da vàng, không thụ thai."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,2 – 0,3 thốn."}]},{"id":475,"ten":"Long Hàm","sections":[{"h":"VỊ TRÍ","body":"Rốn đo thẳng lên 8,5 thốn (trên huyệt Cưu Vĩ 1,5 thốn)"},{"h":"CHỦ TRỊ","body":"Trị ngực đau, dạ dày đau, suyễn."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 1 thốn.8\n!"}]},{"id":476,"ten":"Long Huyền","sections":[{"h":"VỊ TRÍ","body":"Bờ ngoài cổ tay đo lên 2 thốn (huyệt Liệt Khuyết, đo lên 0,5 thốn)"},{"h":"CHỦ TRỊ","body":"Trị tay đau, răng đau, trúng phong méo miệng."},{"h":"CHÂM CỨU","body":"Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút. Không châm.D\n."}]},{"id":477,"ten":"Long Môn","sections":[{"h":"VỊ TRÍ","body":"Bờ dưới điểm giữa của xương mu."},{"h":"CHỦ TRỊ","body":"Trị băng lậu, tiểu dầm, chứng không sinh đẻ."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 1 thốn.8\n-?"}]},{"id":478,"ten":"Lỗ Căn","sections":[{"h":"VỊ TRÍ","body":"Giữa nhượng chân (huyệt Uỷ trung) lên 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị nhượng chân đau nhức."},{"h":"CHÂM CỨU","body":"Châm 1 – 3 thốn."}]},{"id":479,"ten":"Lỗi Lịch","sections":[{"h":"VỊ TRÍ","body":"Giữa lằn chỉ cổ tay trong (huyệt Đại Lăng) đo lên 3,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị lao hạch, loa lịch."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Cứu 5 – 10 phút."}]},{"id":480,"ten":"Lục Cảnh Chùy Bàng","sections":[{"h":"VỊ TRÍ","body":"Trên gai cổ xương thứ 6, đo ra 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị mũi viêm, rối loạn cảm giác hôi thối."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn."}]},{"id":481,"ten":"Lục Hoa","sections":[{"h":"VỊ TRÍ","body":"Chia đường giữa của 2 xương đòn gánh thành 8 phần. Lấy 2 phần làm cạnh của hình tam giác đều. Đem đỉnh hình tam giác đó đặt trên huyệt Đại Chùy, 2 góc cạnh kia là 2 huyệt. Đặt tiếp đỉnh tam giác trên điểm giữa của cạnh đáy trên sẽ được 2 huyệt khác. làm 3 lần sẽ được 6 huyệt, gọi là Lục Hoa (Châm Cứu Học Thượng Hải).\nHoặc: Dùng một sợi dây, đo bề ngang 2 đầu vú, cắt bỏ đi 1/4, chỉ lấy 3/4 khúc dây việc lại, làm thành một tam giác đều. Đặt đỉnh của tam giác này tại huyệt Đại Chùy, 2 đầu của cạnh dưới tam giác là 2 huyệt Lục Hoa đầu tiên. Đặt đỉnh của tam giác đó tại giữa đường nối 2 huyệt Lục Hoa đầu sẽ được 2 huyệt Lục Hoa tiếp. Đến lần thứ ba sẽ được 6 huyệt là Lục Hoa (Châm Cứu Học HongKong)"},{"h":"CHỦ TRỊ","body":"Trị khí quản viêm, hen suyễn, lao phổi, thiếu máu, suy nhược cơ thể do bệnh mạn tính."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,5–1 thốn. Bệnh mạn tính thường dùng cứu 5–10 phút."}]},{"id":482,"ten":"Lục Phùng","sections":[{"h":"VỊ TRÍ","body":"Ở giữa đốt giữa của 4 ngón tay (2, 3, 4, 5) và 2 lằn chỉ của ngón thứ 1, tất cả là 6 huyệt."},{"h":"CHỦ TRỊ","body":"Trị nhọt, ghẻ ngứa, cam tích, giun."},{"h":"CHÂM CỨU","body":"Châm nặn máu."}]},{"id":483,"ten":"Lung Huyệt","sections":[{"h":"VỊ TRÍ","body":"Giữa đường nối huyệt Thính Cung (Ttr 16) và huyệt Nhĩ Môn (Ttu 21)"},{"h":"CHỦ TRỊ","body":"Trị câm điếc."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5–0,8 thốn.0\tD"}]},{"id":484,"ten":"Lung Thông","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm dưới xương chũm đo xuống 1 ngang ngón tay, rồi lùi ra phía sau 1 ngang ngón tay."},{"h":"CHỦ TRỊ","body":"Trị câm điếc."},{"h":"CHÂM CỨU","body":"Châm xiên về phía tai, sâu 1 – 2 thốn."}]},{"id":485,"ten":"Lư Môn Bất Hợp","sections":[{"h":"VỊ TRÍ","body":"2 huyệt ở trên và dưới rốn 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị kiết lỵ, ruột sôi, kinh nguyệt không đều, tiêu chảy, bụng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 0,8 thốn. Cứu 5 – 10 phút."}]},{"id":486,"ten":"Lư Thượng","sections":[{"h":"VỊ TRÍ","body":"Xương cụt đo lên 1 thốn là một huyệt, từ huyệt này đo ngang ra 2 bên mỗi bên 1 thốn nữa thành 3 huyệt."},{"h":"CHỦ TRỊ","body":"Trị trĩ lở loét, tiêu ra máu."},{"h":"CHÂM CỨU","body":"Cứu 3 – 7 tráng, Ôn cứu 5 – 10 phút."}]},{"id":487,"ten":"Lư Tức","sections":[{"h":"VỊ TRÍ","body":"Sau loa tai, trên huyệt Khế Mạch 1 thốn hoặc ép sát vành tai vào đầu, huyệt ở chỗ nối 2/3 dưới và 1/3 trên của đường cong theo bờ vành tai từ h. Ế Phong đến Giác Tôn."},{"h":"CHỦ TRỊ","body":"Trị tai giữa viêm, tai ù, nôn mửa, co giật."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn. Cứu 1 – 3 tráng. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ tai sau, cơ chẩm, xương chẩm.\nThần kinh vận động cơ là nhánh của dây thần kinh mặt và nhánh của dây thần kinh chẩm lớn.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C2."}]},{"id":488,"ten":"Lữ Thượng","sections":[{"h":"VỊ TRÍ","body":"Lấy dây đo từ đầu ngón tay giữa đến lằn chỉ ngang thứ 3 (sát với bàn tay), cắt khúc đó. Lấy dây đo từ chót xương cụt lên dọc đến giữa cột sống, đánh dấu chỗ đó, rồi đem khúc dây đã cắt ở trên, đặt vào giữa chỗ đánh dấu, 2 bên sợi dây đụng vào hai bên thăn thịt, sẽ có tất cả 3 huyệt: một ở giữa cột sống và hai huyệt hai bên."},{"h":"CHỦ TRỊ","body":"Trị tiểu buốt, tiểu khó (lâm chứng)"},{"h":"CHÂM CỨU","body":"Cứu 7 tráng."}]},{"id":489,"ten":"Lương Khâu","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm trên bờ trên ngoài xương đầu gối 2 thốn, thẳng trên huyệt Độc Tỵ (Vi."},{"h":"CHỦ TRỊ","body":"Khớp gối viêm, tuyến vú viêm. dạ dày đau, dạ dầy co cứng."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn, Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa cơ thẳng trước và cơ rộng ngoài, cơ rộng giữa, xương đùi.\nThần kinh vận động cơ là các nhánh của dây thần kinh đùi.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L3.Q7T6(:BN92Không châm thẳng vì kim có thể xuyên qua thanh quản gây ho."}]},{"id":490,"ten":"Lương Môn","sections":[{"h":"VỊ TRÍ","body":"Trên rốn 4 thốn, cách đường giữa bụng 2 thốn, ngang huyệt Trung Quản (Nh."},{"h":"CHỦ TRỊ","body":"Trị dạ dầy viêm cấp và mạn tính, thần kinh Vị (dạ dầy) đau, nôn mửa, bụng sôi."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn, Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ chéo to, mạc ngang, phúc mạc, bên phải là gan, bên trái là dạ dày.\nThần kinh vận động cơ là 6 dây thần kinh gian sườn và dây thần kinh bụng–sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D7.K\nÌNBOBTR2"}]},{"id":491,"ten":"Lượng Nhãn","sections":[{"h":"VỊ TRÍ","body":"Dưới đốt sống lưng thứ 6 (D6) đo ngang ra 1,5 thốn, giữa đường nối huyệt Tâm Du (Bq.15) và Đốc Du (Bq."},{"h":"CHỦ TRỊ","body":"Trị kết mạc viêm cấp, khóe mắt loét, bướu hạch mi mắt."},{"h":"CHÂM CỨU","body":"Cứu bên bệnh – Nếu 2 bên bệnh thì cứu cả 2 bên."}]},{"id":492,"ten":"Lý Kỳ Môn","sections":[{"h":"VỊ TRÍ","body":"Ở ngực, dưới bờ cong cung sườn 2 thốn, rồi đo ngang ra 2 bên, mỗi bên 3,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị ngực sườn đau."},{"h":"CHÂM CỨU","body":"Cứu 3 – 5 tráng.P\nE"}]},{"id":493,"ten":"Lý Ngoại","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm phía ngoài xương bánh chè đo xuống 3 thốn (huyệt Túc Tam Lý – Vi.36) rồi đo ngang ra 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị di chứng bại liệt trẻ em."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 2 thốn."}]},{"id":494,"ten":"Lý Nội Đình","sections":[{"h":"VỊ TRÍ","body":"Dưới bàn chân, phía trước khớp ngón chân 2 và 3, nơi có chỗ lõm."},{"h":"CHỦ TRỊ","body":"Trị ngón chân đau nhức, động kinh."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn."}]},{"id":495,"ten":"Lý Thượng","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm bên ngoài xương bánh chè đo xuống 2 thốn (trên huyệt Túc Tam Lý (Vi.36) một thốn."},{"h":"CHỦ TRỊ","body":"Trị di chứng liệt trẻ nhỏ."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1,5 – 2 thốn."}]},{"id":496,"ten":"Lỵ Tật Mẫn Cảm Điểm","sections":[{"h":"VỊ TRÍ","body":"Tại giáp giới 2/5 trên và 3/5 dưới của đường nối từ huyệt Âm Lăng Tuyền (Ty.9) và đỉnh cao của mắt cá chân trong."},{"h":"CHỦ TRỊ","body":"Trị lỵ, di chứng bại liệt trẻ nhỏ."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 2 thốn."}]},{"id":497,"ten":"Mạch Lạp Thũng","sections":[{"h":"VỊ TRÍ","body":"Khe đốt sống lưng 4 – 5 đo ngang ra 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị chắp lẹo."},{"h":"CHÂM CỨU","body":"Tìm những vết ban đỏ nhỏ, dùng kim Tam lăng châm ra máu các vết ban đó.F0,\nÔ"}]},{"id":498,"ten":"Mai Hoa Huyệt","sections":[{"h":"VỊ TRÍ","body":"Rốn đo lên 4 thốn, rồi đo ra ngang 0,5 thốn (huyệt Âm Đô (Th 19), xong đo lên, đo xuống mỗi bên 0,5 thốn Gồm 4 huyệt. Thêm huyệt Trung Quản (Nh 12) nữa là 5 huyệt."},{"h":"CHỦ TRỊ","body":"Trị tiêu hóa kém, dạ dày viêm, dạ dày loét."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3–7 tráng."}]},{"id":499,"ten":"Mai Hoa Tam Châm","sections":[{"h":"VỊ TRÍ","body":"Gồm 3 huyệt, do huyệt Quan Nguyên (Nh 4) và huyệt Hộ Cung tạo thành (Đỉnh là huyệt Quan nguyên, hai đỉnh kia là huyệt Hộ cung – tạo thành hình tam giác)"},{"h":"CHỦ TRỊ","body":"Trị vô sinh, u nang buồng trứng, phần phụ viêm, dịch hoàn viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 2 thốn."}]},{"id":500,"ten":"Mạng Quan","sections":[{"h":"VỊ TRÍ","body":"Từ đầu vú đo chếch ra huyệt Trung Quản (Nh 12) và một đường chéo ra cạnh sườn (cũng bằng đường chéo ra huyệt Trung Quản), thành một hình tam giác đều, 3 góc là 3 huyệt."},{"h":"CHỦ TRỊ","body":"Trị lách sưng to, bụng trướng, thù thũng, tiểu không thông, khí suyễn không nằm được, nôn mửa, hưu tức lỵ, đại tiện không cầm, Tỳ ngược, sườn đau, hoàng hắc đản."},{"h":"CHÂM CỨU","body":"Không châm và cứu vào đầu vú – Không châm sâu."}]},{"id":501,"ten":"Manh Môn","sections":[{"h":"VỊ TRÍ","body":"Rốn thẳng xuống 7 thốn, đo ngang ra 3,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị tử cung lạnh, không thụ thai."},{"h":"CHÂM CỨU","body":"Cứu 5–10 phút. Không châm."}]},{"id":502,"ten":"Manh Trường","sections":[{"h":"VỊ TRÍ","body":"Ở giữa đường nối gai trên mào chậu trước bên phải và giữa rốn."},{"h":"CHỦ TRỊ","body":"Trị bụng đau, tiêu chảy, ruột đau."},{"h":"CHÂM CỨU","body":"Châm thẳng hoặc xiên sâu 1 thốn. Cứu 3 – 7 tráng."}]},{"id":503,"ten":"Mẫu Chỉ Gian","sections":[{"h":"VỊ TRÍ","body":"Tại đầu móng ngón tay cái, cách đầu móng 1cm."},{"h":"CHỦ TRỊ","body":"Trị thận có nước, thận hư nhiễm mỡ."},{"h":"CHÂM CỨU","body":"Châm nông 0,1 – 0,2 thốn. Châm ra máu."}]},{"id":504,"ten":"Mẫu Chỉ Hoành Lý Tam Mao","sections":[{"h":"VỊ TRÍ","body":"Tại mu ngón chân cái, ngay chính giữa lằn chỉ của khớp gốc ngón."},{"h":"CHỦ TRỊ","body":"Trị dạ dầy đau, dịch hoàn viêm, chảy máu cam."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,2 – 0,3 thốn./A\n."}]},{"id":505,"ten":"Mẫu Chỉ Lý Hoành Văn","sections":[{"h":"VỊ TRÍ","body":"Dưới bàn chân, giữa lằn chỉ của khớp ngón chân cái."},{"h":"CHỦ TRỊ","body":"Trị dịch hoàn viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn."}]},{"id":506,"ten":"Mẫu Chỉ Tiết Hoành Văn","sections":[{"h":"VỊ TRÍ","body":"Tại mặt trong ngón tay cái, giữa lằn chỉ của khớp ngón tay cái."},{"h":"CHỦ TRỊ","body":"Trị giác mạc bong."},{"h":"CHÂM CỨU","body":"Cứu."}]},{"id":507,"ten":"Mẫu Chỉ Tụ Mao","sections":[{"h":"VỊ TRÍ","body":"Ngay giữa chỗ mọc lông ngón chân cái."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, chóng mặt, trúng phong."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,1 – 0,2 thốn. Cứu 5 – 10 phút."}]},{"id":508,"ten":"Mệnh Môn","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm dưới đầu mỏm gai đốt sống thắt lưng 2."},{"h":"CHỦ TRỊ","body":"Trị vùng thắt lưng đau, yếu, cứng, đầu đau, lưng đau, lạnh từ ống chân trở xuống (chân dương (hỏa) hư), di mộng tinh, liệt dương, đái hạ, sốt không ra mồ hôi, tiểu đục, trẻ nhỏ lên cơn co giật, phong đòn gánh."},{"h":"CHÂM CỨU","body":"Châm kim chếch lên, luồn dưới mỏm gai, hướng vào khoảng gian đốt sống thắt lưng 2 – 3, sâu 0,3 – 1,5 thốn. Cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân ngực – thắt lưng của cơ lưng to, chỗ bám của cơ răng bé sau – dưới, cơ gian gai, cơ ngang gai, dây chằng gian gai, dây chằng trên gai, dây chằng vàng, ống sống.\nThần kinh vận động cơ là các nhánh của dây thần kinh sống.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh"}]},{"id":509,"ten":"Mi Xung","sections":[{"h":"VỊ TRÍ","body":"Thẳng trên huyệt Toàn Trúc, vào trong chân tóc 0,5 thốn, ngang huyệt Thần Đình (Đc."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, mắt sưng đỏ, chóng mặt."},{"h":"CHÂM CỨU","body":"Châm xiên, luồn kim dưới da 0,3 – 0,5 thốn. Cẩn thận khi cứu."},{"h":"GIẢI PHẪU","body":"Dưới da là chỗ cơ trán bám vào cân sọ, dưới gân là xương sọ.\nThần kinh vận động cơ là nhánh của dây thần kinh mặt.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh sọ não số V."}]},{"id":510,"ten":"Minh Nhãn","sections":[{"h":"VỊ TRÍ","body":"Ngón tay cái hơi co lại, huyệt nằm ở trên cuối lằn chỉ của ngón cái (phía ngón cái và trỏ)"},{"h":"CHỦ TRỊ","body":"Trị quáng gà, kết mạc viêm, amidal viêm, bệnh trường vị của trẻ nhỏ."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,1 – 0,2 thốn."}]},{"id":511,"ten":"Mỗ Tử","sections":[{"h":"VỊ TRÍ","body":"Dùng một sợi dây, đo chiều dài 2 bên mép, cắt làm 3 phần bằng nhau, làm thành hình tam giác đều, đặt đỉnh vào giữa lỗ rốn, còn hai đáy để ở dưới rốn."},{"h":"CHỦ TRỊ","body":"Trị chứng thiên trụy, sán khí, thoái vị bẹn."},{"h":"CHÂM CỨU","body":"Cứu 14 – 40 tráng."}]},{"id":512,"ten":"Mục Minh","sections":[{"h":"VỊ TRÍ","body":"Mắt nhìn thẳng, từ con ngươi kéo thẳng lên, chạm vào chân tóc đầu là huyệt, dưới huyệt Đầu Lâm Khấp 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, kết mạc viêm, thị lực giảm."},{"h":"CHÂM CỨU","body":"Châm xiên, sâu 0,5 – 1 thốn.n\n)"}]},{"id":513,"ten":"Mục Phi","sections":[{"h":"VỊ TRÍ","body":"Ngay con ngươi mắt thẳng lên đầu mi tóc 0,1 thốn."},{"h":"CHỦ TRỊ","body":"Trị chảy máu cam, trước trán đau, chảy nước mũi, hồi hộp."},{"h":"CHÂM CỨU","body":"Châm xiên 0,2 – 0,3 thốn. Cứu 5 – 10 phút.2\n:w"}]},{"id":514,"ten":"Mục Song","sections":[{"h":"VỊ TRÍ","body":"Trên huyệt Đầu Lâm Khấp 0,1 thốn."},{"h":"CHỦ TRỊ","body":"Trị bệnh về mặt, mặt phù, mắt mờ, mắt sưng đau, răng đau."},{"h":"CHÂM CỨU","body":"Châm dưới da 0,3 – 0,5 thốn. Cứu 1 – 3 tráng. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân sọ, đường khớp trán – đỉnh.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V.\n giật mà không dùng đến huyệt Lư Tức thì không khỏi (Bách Chứng Phú)"}]},{"id":515,"ten":"Nam Âm Phùng","sections":[{"h":"VỊ TRÍ","body":"Tại ngay giữa đường nếp ngang của âm nang."},{"h":"CHỦ TRỊ","body":"Trị hoàng đản, âm nang lệch sang một bên (Thiên trụy)"},{"h":"CHÂM CỨU","body":"Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút.+\n7"}]},{"id":516,"ten":"Nan Lập","sections":[{"h":"VỊ TRÍ","body":"Bờ trên – ngoài xương bánh chè đo lên 5 thốn."},{"h":"CHỦ TRỊ","body":"Trị chi dưới liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1,5 – 2 thốn."}]},{"id":517,"ten":"Nan Phục","sections":[{"h":"VỊ TRÍ","body":"Bờ trên – ngoài xương bánh chè đo lên 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị chi dưới liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 2 thốn."}]},{"id":518,"ten":"Nang Để","sections":[{"h":"VỊ TRÍ","body":"Ở ngay nếp da nối liền hậu môn với bộ phận sinh dục ngoài ở phía dưới và phía sau bộ phận sinh dục ngoài."},{"h":"CHỦ TRỊ","body":"Trị các bệnh của Thận."},{"h":"CHÂM CỨU","body":"Cứu 5 – 20 phút."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là cơ hành lang, cơ ngang nông và sâu của đái – chậu trước.\nThần kinh vận động cơ là các nhánh của dây thần kinh thẹn trong."}]},{"id":519,"ten":"Não Cái","sections":[]},{"id":520,"ten":"Não Căn","sections":[{"h":"VỊ TRÍ","body":"Tại chỗ lõm giữa gân gót chân và mắt cá chân ngoài (gần huyệt Côn Lôn – Bq 60)"},{"h":"CHỦ TRỊ","body":"Trị điên cuồng."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 2 thốn."}]},{"id":521,"ten":"Não Hộ","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm ngay trên ụ chẩm ngoài, trên huyệt Phong Phủ 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị cổ gáy đau cứng, chóng mặt, điên cuồng, cận thị."},{"h":"CHÂM CỨU","body":"Châm luồn kim dưới da sâu 0,2 – 0,8 thốn. Cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân hộp sọ, chỗ bám của gân cơ thang và gân cơ rối to hoặc cơ bán gai, mào chẩm ngoài của xương chẩm.\nThần kinh vận động cơ do nhánh của dây thần kinh sọ não số XI và nhánh của dây cổ 2.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C3."}]},{"id":522,"ten":"Não Không","sections":[{"h":"VỊ TRÍ","body":"Sau huyệt Thừa Linh 1,5 thốn, trên Phong Trì 1,5 thốn, ngang với ụ chẩm và Não Hộ (Đốc Mạch)"},{"h":"CHỦ TRỊ","body":"Trị đầu đau, cổ gáy cứng, suyễn."},{"h":"CHÂM CỨU","body":"Châm dưới da 0,3 – 0,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là chỗ cơ chẩm, cơ gối đầu và cơ thang bám vào đường cong chẩm trên của xương chẩm. Thần kinh vận động cơ là nhánh của dây thần kinh sọ não số XI, nhánh của dây thần kinh số 2, nhánh của dây thần kinh chẩm lớn, nhánh của thần kinh dưới chẩm.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C2."}]},{"id":523,"ten":"Não Thanh","sections":[{"h":"VỊ TRÍ","body":"Trên huyệt Giải Khê (Vi 41) 2 khoát ngón tay, bờ ngoài xương chầy."},{"h":"CHỦ TRỊ","body":"Trị thích ngủ, si ngốc do di chứng của viêm não, hoa mắt, hay quên, chân liệt do di chứng."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn, tại chỗ có cảm giác căng tức, có khi tê xuống lưng bàn chân."}]},{"id":524,"ten":"Nga Căn","sections":[{"h":"VỊ TRÍ","body":"Bên dưới hàm, phía trước góc hàm dưới của xương hàm dưới 1 thốn, bờ trong của xương hàm dưới."},{"h":"CHỦ TRỊ","body":"Trị amidal viêm cấp."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0, 8 thốn."}]},{"id":525,"ten":"Ngạch Trung","sections":[{"h":"VỊ TRÍ","body":"Điểm giữa 2 đầu lông mày (huyệt Ấn Đường) lên chạm đường ngang giữa trán."},{"h":"CHỦ TRỊ","body":"Trị mũi viêm, mất ngủ, hồi hộp, chóng mặt."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,5 – 1 thốn.1J\n+g"}]},{"id":526,"ten":"Ngân Bình","sections":[{"h":"VỊ TRÍ","body":"Nơi gặp nhau của đường nối mắt cá chân trong, mắt cá chân ngoài và gân gót chân."},{"h":"CHỦ TRỊ","body":"Trị di chứng liệt trẻ con."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 0,8 thốn. Ôn cứu 10 – 15 phút."}]},{"id":527,"ten":"Ngân Giao","sections":[{"h":"VỊ TRÍ","body":"Ở giữa kẽ môi trên và chân lợi, thẳng huyệt Đoài Đoan (Đc 27) vào, ở đầu trên nếp gần môi trên."},{"h":"CHỦ TRỊ","body":"Trị lợi răng sưng đau, chảy nước mũi, điên cuồng."},{"h":"CHÂM CỨU","body":"Châm kim xiên lên sâu 0,1 – 0,2 thốn, hoặc dùng kim tam lăng châm nặn ra ít máu. Không cứu."},{"h":"GIẢI PHẪU","body":"Ở phía sau cơ vòng môi trên, trên nếp hãm môi trên, trước khe của các chân răng cửa.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số VII.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số"}]},{"id":528,"ten":"Ngân Khẩu","sections":[{"h":"VỊ TRÍ","body":"Dưới góc xương bả vai."},{"h":"CHỦ TRỊ","body":"Trị thần kinh liên sườn đau, tổn thương tổ chức phần mềm cơ lưng."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 1 thốn."}]},{"id":529,"ten":"Nghênh Hương","sections":[{"h":"VỊ TRÍ","body":"Điểm gặp nhau của đường ngang qua chân cách mũi và rãnh mũi - miệng."},{"h":"CHỦ TRỊ","body":"Trị các bệnh về mũi, mặt ngứa, mặt phù, liệt mặt (liệt dây thần kinh VII), giun chui ống mật."},{"h":"CHÂM CỨU","body":"Châm xiên hoặc luồn dưới da.\nTrị giun chui ống mật: mũi kim hướng đến huyệt Tứ Bạch.\nBệnh ở mũi: mũi kim hướng đến huyệt Tỵ Thông."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là bờ ngoài cơ nâng cánh mũi và môi trên, bờ ngoài cơ nở cánh mũi, và cơ ngang mũi, bờ trong cơ gò má nhỏ và cơ nanh, bờ trên cơ vòng môi.\nThần kinh vận động cơ là các nhánh của dây thần kinh sọ não số VII.\nDa vùng huyệt chi phối bởi nhánh dưới hố mắt của dây thần kinh sọ não số !"}]},{"id":530,"ten":"Nghiên Tử Cốt","sections":[{"h":"VỊ TRÍ","body":"Tại chỗ lõm sát đỉnh cao của lồi xương trụ. Hơi nghiêng bàn tay để dễ lấy huyệt."},{"h":"CHỦ TRỊ","body":"Trị khớp đầu xương trụ đau, lở loét vùng xương đậu, xương đậu đau."},{"h":"CHÂM CỨU","body":"Cứu 3 tráng (Nam bên trái, nữ bên phải)"}]},{"id":531,"ten":"Ngoại Âm Liêm","sections":[{"h":"VỊ TRÍ","body":"Nằm ngửa, từ rãnh bụng – đùi đo xuống một khoát ngón tay, ở phía mặt ngoài của động mạch nhảy, phía trên ở ngoài huyệt Âm Liêm (C 11)"},{"h":"CHỦ TRỊ","body":"Trị chi dưới liệt, lưng đùi đau, thần kinh đùi đau."},{"h":"CHÂM CỨU","body":"Châm thẳng hơi hướng mũi kim ra bên ngoài sâu 1 – 1,5 thốn. Cứu 1 – 3 tráng. Ôn cứu 5 – 10 phút."}]},{"id":532,"ten":"Ngoại Định Suyễn","sections":[{"h":"VỊ TRÍ","body":"Từ huyệt Đại Chùy (Đc 14) đo ra 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị suyễn, khí quản viêm."},{"h":"CHÂM CỨU","body":"Châm xiên, sâu 0,5 – 0,8 thốn."}]},{"id":533,"ten":"Ngoại Khâu","sections":[{"h":"VỊ TRÍ","body":"Trên mắt cá chân 7 thốn, phía sau huyệt Dương Giao (Đ 33), đo ngang ra 1 thốn, ở bờ sau xương mác, khe giữa cơ mác bên đùi và cơ dép."},{"h":"CHỦ TRỊ","body":"Trị cẳng chân đau, cơ bắp chân bị co rút, động kinh, bị chó cắn."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa các cơ mác bên dài và cơ dép, xương mác.\nThần kinh vận động cơ là các nhánh của dây thần kinh cơ – da và dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5."}]},{"id":534,"ten":"Ngoại Khoả Thượng","sections":[{"h":"VỊ TRÍ","body":"Đỉnh nhọn mắt cá chân ngoài đo lên phía ống chân 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị cẳng chân đau."},{"h":"CHÂM CỨU","body":"Cứu 3 – 5 tráng."}]},{"id":535,"ten":"Ngoại Khỏa Tiêm","sections":[{"h":"VỊ TRÍ","body":"Tại điểm cao nhất của mắt cá chân ngoài."},{"h":"CHỦ TRỊ","body":"Trị răng đau, cước khí, liệt nửa người, trúng phong."},{"h":"CHÂM CỨU","body":"Châm ra máu."}]},{"id":536,"ten":"Ngoại Khoả Tiền Giao Mạch","sections":[{"h":"VỊ TRÍ","body":"Phía trên – trước lồi cầu xương mắt cá chân ngoài, nơi có động mạch đi qua."},{"h":"CHỦ TRỊ","body":"Trị răng sưng đau (phong xỉ thống), chân sưng đau."},{"h":"CHÂM CỨU","body":"Cứu 3 tráng.L\n38"}]},{"id":537,"ten":"Ngoại Kim Tân Ngọc Dịch","sections":[{"h":"VỊ TRÍ","body":"Ngẩng đầu lên, huyệt ở trên cuống hầu 1 thốn, ở đường giữa đo ra 0,3 thốn. Bên trái gọi là Ngoại Kim Tân, bên phải gọi là Ngoại Ngọc Dịch."},{"h":"CHỦ TRỊ","body":"Trị trúng phong không nói được, cơ lưỡi liệt, xoang miệng viêm."},{"h":"CHÂM CỨU","body":"Châm xiên, mũi kim hướng vào phía gốc lưỡi, sâu 1 – 1,5 thốn."}]},{"id":538,"ten":"Ngoại Lao Cung","sections":[{"h":"VỊ TRÍ","body":"Giữa khe xương ngón tay 2 và 3, đối diện với huyệt Lao Cung (qua lòng bàn tay)"},{"h":"CHỦ TRỊ","body":"Trị tiêu hóa kém, trẻ nhỏ bị cấp và mạn kinh phong, cổ vẹo, lòng bàn tay tê, ngứa."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn. Cứu 1 – 3 tráng. Ôn cứu 3 – 5 phút.7P\nS"}]},{"id":539,"ten":"Ngoại Lao Cung II","sections":[{"h":"VỊ TRÍ","body":"Ở mu bàn tay, giữa khe khớp xương bàn tay 3 – 4."},{"h":"CHỦ TRỊ","body":"Trị khớp bàn tay đau, ngón tay tê."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn."}]},{"id":540,"ten":"Ngoại Lao Cung III","sections":[{"h":"VỊ TRÍ","body":"Ở mu bàn tay, giữa khe khớp xương bàn tay 4–5."},{"h":"CHỦ TRỊ","body":"Trị khớp bàn tay đau, ngón tay tê."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn."}]},{"id":541,"ten":"Ngoại Lăng","sections":[{"h":"VỊ TRÍ","body":"Dưới rốn 1 thốn (huyệt Âm Giao – Nh.7) ra ngang 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị bụng đau, kinh nguyệt rối loạn."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn, Cứu 5 – 7 tráng, Ôn cứu 10 – 20 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ chéo to, cơ thẳng to, mạc ngang, phúc mạc, trong ổ bụng là ruột non và tử cung khi có thai 6–7 tháng, bàng quang khi bí tiểu.\nThần kinh vận động cơ là 6 dây thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D11."}]},{"id":542,"ten":"Ngoại Minh","sections":[{"h":"VỊ TRÍ","body":"Tại góc trên ngoài mắt chừng 0,3 thốn."},{"h":"CHỦ TRỊ","body":"Trị nhìn xiên, giác mạc bong, thần kinh thị giác teo."},{"h":"CHÂM CỨU","body":"Châm thẳng, theo bờ trên hố mắt, sâu 1–1,5 thốn."}]},{"id":543,"ten":"Ngoại Nhĩ Đạo Khẩu","sections":[{"h":"VỊ TRÍ","body":"Tại ống tai ngoài."},{"h":"CHỦ TRỊ","body":"Trị tai ù, điếc."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn."}]},{"id":544,"ten":"Ngoại Quan","sections":[{"h":"VỊ TRÍ","body":"Trên lằn chỉ cổ tay 2 thốn, giữa xương quay và xương trụ, ở mặt giữa sau cánh tay."},{"h":"CHỦ TRỊ","body":"Trị chi trên liệt, thần kinh gian sườn đau, đầu đau, tai ù, điếc, cổ gáy cứng, sốt, cảm mạo."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn, hoặc xiên qua Nội Quan. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa các cơ duỗi chung ngón tay và cơ duỗi dài riêng ngón tay cái ở ngoài, với các cơ duỗi riêng ngón tay út và cơ duỗi riêng ngón tay trỏ ở trong, giữa màng gian cốt.\nThần kinh vận động cơ là các nhánh của dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C7."}]},{"id":545,"ten":"Ngoại Tứ Mãn","sections":[{"h":"VỊ TRÍ","body":"Rốn xuống 2 thốn (huyệt Thạch Môn – Nh.5), ra ngang 1,5 thốn (tức từ huyệt Tứ Mãn (Th 14) đo ra 1 thốn)"},{"h":"CHỦ TRỊ","body":"Trị kinh nguyệt không đều."},{"h":"CHÂM CỨU","body":"Cứu."}]},{"id":546,"ten":"Ngọc Chẩm","sections":[{"h":"VỊ TRÍ","body":"Ngay sau huyệt Lạc Khước 1,5 thốn, ngang huyệt Não Hộ (Đc 17) cách 1,3 thốn, ngang với ụ chẩm 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, chóng mặt, mắt đau."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn. Cứu 1–3 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là cơ chẩm, nơi bám của cơ thang vào đường cong chẩm trên của xương chẩm.\nThần kinh vận động cơ là nhánh của dây thần kinh chẩm lớn, nhánh của dây thần kinh sọ não số XI, nhánh của đám rối cổ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C3.Kh !"}]},{"id":547,"ten":"Ngọc Dịch","sections":[{"h":"VỊ TRÍ","body":"Uốn cong lưỡi, huyệt tại 2 tĩnh mạch xanh 2 bên dưới lưỡi."},{"h":"CHỦ TRỊ","body":"Trị miệng lở, lưỡi viêm, họng viêm, trường vị viêm cấp tính, tiểu đường."},{"h":"CHÂM CỨU","body":"Chích nặn ra tí máu, không cứu."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là cơ cằm – lưỡi và cơ móng – lưỡi. Thần kinh vận động cơ là các nhánh của dây thần kinh sọ não số XII.;\nI s"}]},{"id":548,"ten":"Ngọc Điền","sections":[{"h":"VỊ TRÍ","body":"Tại dưới gai đốt sống cùng 4 (S4)"},{"h":"CHỦ TRỊ","body":"Trị vùng lưng cùng đau, sinh khó."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 1 thốn. Cứu 3–7 tráng. Ôn cứu 5 –10 phút."}]},{"id":549,"ten":"Ngọc Đường","sections":[{"h":"VỊ TRÍ","body":"Ở điểm gặp nhau của đường dọc giữa xương ức với đường ngang qua bờ trên khớp ức – sườn 4."},{"h":"CHỦ TRỊ","body":"Trị ngực đau, ho suyễn."},{"h":"CHÂM CỨU","body":"Châm luồn kim dưới da, mũi kim hướng xuống bụng, sâu 0,5 – 1 thốn. Cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là xương ức.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D3.m\nZ?"}]},{"id":550,"ten":"Ngọc Tuyền","sections":[{"h":"VỊ TRÍ","body":"Rốn đo xuống 6,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị đồi sán, thiên trụy, dịch hoàn viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3–0,5 thốn. Cứu 3–7 tráng. Ôn cứu 5–15 phút."}]},{"id":551,"ten":"Ngọc Tuyền II","sections":[{"h":"VỊ TRÍ","body":"Huyệt Ngọc Chẩm đo xuống 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị nói không rõ."},{"h":"CHÂM CỨU","body":"Cứu 1 – 3 tráng. Ôn cứu 3 – 5 phút."}]},{"id":552,"ten":"Ngũ Chỉ Huyệt","sections":[{"h":"VỊ TRÍ","body":"Dưới mỗi một ngón chân đo xuống 0,1 thốn, 2 chân tất cả 10 huyệt."},{"h":"CHỦ TRỊ","body":"Trị liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng, có phản ứng là được.B\nU"}]},{"id":553,"ten":"Ngũ Chỉ Huyệt II","sections":[{"h":"VỊ TRÍ","body":"Mu bàn tay, tại giữa lằn chỉ khớp thứ nhất của các ngón tay."},{"h":"CHỦ TRỊ","body":"Trị bụng đau, khó thở, khí huyết không thông."},{"h":"CHÂM CỨU","body":"Day ấn, bấm.=\n."}]},{"id":554,"ten":"Ngũ Chuỳ Thượng","sections":[{"h":"VỊ TRÍ","body":"Giữa khe gai đốt sống thắt lưng 5."},{"h":"CHỦ TRỊ","body":"Trị trúng phong không nói được."},{"h":"CHÂM CỨU","body":"Cứu 7 tráng."}]},{"id":555,"ten":"Ngũ Hổ","sections":[{"h":"VỊ TRÍ","body":"Nắm tay lại huyệt ở đốt 2 ngón tay trỏ và đeo nhẫn hoặc lấy chính giữa mặt sau khớp đốt 1 và 2 của ngón tay trỏ và ngón đeo nhẫn. Huyệt ở trên chóp xương của khớp ngón vô danh và ngón trỏ, 2 tay có 4 huyệt."},{"h":"CHỦ TRỊ","body":"Trị cổ gáy đau, dây thần kinh hông đau, năm ngón tay co quắp, co rút."},{"h":"CHÂM CỨU","body":"Châm xiên 0,2 – 0,3 thốn. Ôn cứu 5 – 15 phút."}]},{"id":556,"ten":"Ngũ Khu","sections":[{"h":"VỊ TRÍ","body":"Ở phía trước gai chậu trước trên, ngang huyệt Quan Nguyên (Nh 4), phía trước và dưới Mạch Đới 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị bụng dưới đau, lưng đau, màng trong tử cung viêm, dịch hoàn viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ chéo to của bụng, cơ chéo bé của bụng, cơ ngang bụng, mạch ngang, phúc mạc, đại trường.\nThần kinh vận động cơ là 6 dây thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D12.\nKhi châm kim, nên dựa theo mặt xương hàm trên để tránh châm vào xương."}]},{"id":557,"ten":"Ngũ Linh","sections":[{"h":"VỊ TRÍ","body":"Cuối nếp gấp mặt ngoài kheo chân đo lên 5 thốn."},{"h":"CHỦ TRỊ","body":"Trị bệnh tâm thần, liệt do Hysteria."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 2–3 thốn."}]},{"id":558,"ten":"Ngũ Lý Trạch Điền","sections":[{"h":"VỊ TRÍ","body":"Tại chính giữa mặt trong mông lớn, ngang đường giữa xương bánh chè đo thẳng lên 8,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị cận thị, mắt có màng."},{"h":"CHÂM CỨU","body":"Châm 0,5 – 0,8 thốn. Cứu 3 – 5 tráng.4Z\nG"}]},{"id":559,"ten":"Ngũ Tạng Du","sections":[{"h":"VỊ TRÍ","body":"Gồm 5 huyệt: Phế Du (Bq 13) + Tâm Du (Bq 15) + Can Du (Bq 18) + Tỳ Du (Bq 20) + Thận Du (Bq 23).\nXem từng huyệt."},{"h":"CHỦ TRỊ","body":"Trị bệnh ở ngũ tạng."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 0,8 thốn. Cứu 5 – 10 phút.CU\ng"}]},{"id":560,"ten":"Ngũ Trụ Cứu","sections":[{"h":"VỊ TRÍ","body":"Gồm các huyệt: Cự Khuyết (Nh 14) + Thượng Quản (Nh 13) + Trung Quản (Nh 12) + 2 huyệt Lương Môn (Vi 21).\nXem từng huyệt."},{"h":"CHỦ TRỊ","body":"Trị quan cách, khí suyễn."},{"h":"CHÂM CỨU","body":"Cứu 10 – 15 phút."}]},{"id":561,"ten":"Ngũ Xứ","sections":[{"h":"VỊ TRÍ","body":"Giữa đường chân tóc trán lên 1 thốn (huyệt Thượng Tinh – Đc.23) đo ngang ra 1,5 thốn hoặc sau huyệt Khúc Sai 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, chóng mặt, mũi viêm."},{"h":"CHÂM CỨU","body":"Châm xiên 0,2–0,3 thốn. Cứu 2–3 phút. Ôn cứu 5–10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân sọ, xương sọ.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V.Iìw (?\"85Không châm sâu quá vì có thể gây tổn thương động mạch đùi.\nChâm đắc khí: tại chỗ có cảm giác căng hoặc như điện giật xuống đầu gối."}]},{"id":562,"ten":"Ngũ Xứ II","sections":[{"h":"VỊ TRÍ","body":"Tại chỗ cao nhất của gai cột sống thắt lưng 5 (L 5) là một huyệt, lại đo ra hai bên, mỗi bên 2 thốn, rồi đo tiếp ra hai bên, mỗi bên 4 thốn. Có tất cả 5 huyệt."},{"h":"CHỦ TRỊ","body":"Trị đau giữa vùng thắt lưng."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 thốn. Cứu 9 – 11 tráng."}]},{"id":563,"ten":"Ngung Tiền","sections":[{"h":"VỊ TRÍ","body":"Trước đỉnh của huyệt Kiên Ngung (Đtr 15) đo lên 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị vai đau, tay đau, tay không dơ lên được."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 –1,5 thốn. Cứu 5 – 10 phút."}]},{"id":564,"ten":"Ngư Tế","sections":[{"h":"VỊ TRÍ","body":"Ở mặt trong lòng bàn tay, trung điểm giữa xương bàn ngón tay cái, nơi phần tiếp giáp lằn da đổi màu. Gấp ngón tay trỏ vào lòng bàn tay, đầu ngón tay trỏ chạm vào chỗ nào ở mô ngón tay cái, đó là huyệt."},{"h":"CHỦ TRỊ","body":"Trị sốt, ho suyễn, bụng đau, lao phổi."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 1 thốn. Cứu 3 – 5 tráng, Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ ngoài cơ dạng ngắn ngón tay cái, cơ đốt ngón tay cái, bờ ngoài cơ gấp ngón tay cái, xương bàn tay 1.\nThần kinh vận động cơ là các nhánh của dây thần kinh giữa.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C6.Ê0'Br:2Chứng Phong xỉ thống, ở giao mạch phía trước xương cao mắt cá chân ngoài, cứu 3 tráng” (Thiên Kim Yếu Phương).\n“Có kỳ huyệt tên là Ngoại Khoả Tiền Giao Mạch, tại mặt ngoài của khớp mắt cá chân. Tại phía ngoài ¼ giao điểm của mắt cá ngoài với đường giữa cổ chân” (Châm Cứu Khổng Huyệt Cập Kỳ Liệu Pháp Tiện Lãm)"}]},{"id":565,"ten":"Ngư Vĩ","sections":[{"h":"VỊ TRÍ","body":"Ngoài khoé mắt ngoài 0,1 thốn."},{"h":"CHỦ TRỊ","body":"Trị liệt mặt, thiên đầu thống, co rút, các chứng bệnh ở mắt."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn."}]},{"id":566,"ten":"Ngư Yêu","sections":[{"h":"VỊ TRÍ","body":"Giữa lông mày. Hoặc đồng tử nhìn thẳng, huyệt là điểm gặp nhau của đường ngang chia đôi lông mày và đường dọc qua chính giữa ổ mắt (nơi đồng tử kéo lên)"},{"h":"CHỦ TRỊ","body":"Trị cận thị, kết mạc viêm cấp tính, liệt cơ mắt, liệt thần kinh mặt, đau thần kinh hố trên mắt, mộng thịt, mắt có màng."},{"h":"CHÂM CỨU","body":"Châm ngang.\nKhi điều trị đau thần kinh hố trên mắt có thể luồn theo da và hướng mũi kim sang 2 bên thấu đến Toàn Trúc hoặc Ty Trúc Không, sâu 0,5–1 thốn."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là cơ mày, cơ tháp, cơ trán và cơ vòng mi, xương trán.\nThần kinh vận động cơ do các nhánh của dây thần kinh mặt.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V."}]},{"id":567,"ten":"Ngược Môn","sections":[{"h":"VỊ TRÍ","body":"Ở mặt lưng bàn tay, giữa ngón thứ 3 và 4, nơi chỗ da giới hạn giữa đỏ và trắng, tương đương với huyệt Trung Đô."},{"h":"CHỦ TRỊ","body":"Trị sốt rét, bệnh mắt, lở loét, suyễn."},{"h":"CHÂM CỨU","body":"Châm xiên, sâu 1 – 1,5 thốn."}]},{"id":568,"ten":"Nha Thống","sections":[{"h":"VỊ TRÍ","body":"Ở lòng bàn tay, giữa xương thứ 3 và 4, sau khe ngón tay chừng 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị răng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 thốn."}]},{"id":569,"ten":"Nham Trì","sections":[{"h":"VỊ TRÍ","body":"Tại giao điểm của đường chân tóc sau tai và điểm cao nhất của ụ lồi sau tai."},{"h":"CHỦ TRỊ","body":"Trị quáng gà, chóng mặt, huyết áp cao."},{"h":"CHÂM CỨU","body":"Châm thẳng, mũi kim hơi hướng về bên phải sâu 1–1,5 thốn.M'iTheo De La Fuye: tả huyệt này, nên thêm huyệt Thân Mạch (Bq 62)"}]},{"id":570,"ten":"Nhân Nghênh","sections":[{"h":"VỊ TRÍ","body":"Nơi gặp nhau của bờ trước cơ ức – đòn chũm và đường ngang qua chỗ lồi nhất của yết hầu, sờ ở cổ có động mạch cảnh đập."},{"h":"CHỦ TRỊ","body":"Trị họng đau, mất tiếng nói, suyễn, huyết áp cao."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn, tránh động mạnh – Cấm cứu (Giáp Ất Kinh)"},{"h":"GIẢI PHẪU","body":"Dưới da là bờ trước cơ ức đòn chũm, bó mạch thần kinh cảnh, lớp sâu là cơ bậc thang, cơ cổ dài và cơ góc.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số XI và XII, các nhánh của đám rối thần kinh cổ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C3.\nKhi châm, vùng nhãn cầu có cảm giác căng."}]},{"id":571,"ten":"Nhân Trung","sections":[{"h":"VỊ TRÍ","body":"Tại điểm nối 1/3 trên và 2/3 dưới của rãnh Nhân trung, giữa đáy rãnh."},{"h":"CHỦ TRỊ","body":"Trị miệng méo, môi trên co giật, cảm giác như kiến bò ở môi trên, lưng và thắt lưng đau cứng, cấp cứu ngất, hôn mê, động kinh, điên cuồng, trụy tim mạch."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,2 – 0,3 thốn hoặc châm xiên mũi kim hướng lên trên sâu 0,5 – 1 thốn.\nKhi điều trị chứng chảy nước miếng thì trước hết châm mũi kim hướng lên trên xong rút kim ra đến dưới da, rồi châm qua bên trái bên phải, gọi là Tam Thấu Pháp.\nCứu 5 – 10 phút nhưng cứu ít hiệu quả hơn châm."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ vòng môi trên.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số VII.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V."}]},{"id":572,"ten":"Nhân Trung Tâm Điểm","sections":[{"h":"VỊ TRÍ","body":"Tại ngay giữa lóng 2 ngón tay thứ 3."},{"h":"CHỦ TRỊ","body":"Ngừa và trị cảm."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,2 – 0,3 thốn."}]},{"id":573,"ten":"Nhất Oa Phong","sections":[{"h":"VỊ TRÍ","body":"Mu bàn tay, tại gốc ngón tay giữa, gần cổ tay (huyệt Dương Khê hơi chếch về bên trong một ít)"},{"h":"CHỦ TRỊ","body":"Trị bệnh thuộc về hậu môn, kinh phong cấp, kinh phong mạn."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,1 – 0,3 thốn. Cứu 1 – 3 tráng."}]},{"id":574,"ten":"Nhất Phiến Môn","sections":[{"h":"VỊ TRÍ","body":"Ở mu bàn tay, chỗ lõm nối giữa ngón tay thứ 2 và 3."},{"h":"CHỦ TRỊ","body":"Trị bệnh về mắt, sốt không ra mồ hôi, ngứa."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,2 – 0,3 thốn."}]},{"id":575,"ten":"Nhất Y","sections":[{"h":"VỊ TRÍ","body":"Tại đỉnh cao bờ trên cơ tam giác vai. Giữa hai đường nối của ụ chẩm ngoài và lồi cầu vai."},{"h":"CHỦ TRỊ","body":"Trị vai đau, cánh tay đau, sốt không ra mồ hôi."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 0,7 thốn. Cứu 3 – 5 tráng."}]},{"id":576,"ten":"Nhật Nguyệt","sections":[{"h":"VỊ TRÍ","body":"Tại giao điểm của đường thẳng ngang qua đầu ngực và khoảng gian sườn 7."},{"h":"CHỦ TRỊ","body":"Trị dạ dày viêm, gan viêm, túi mật viêm, nấc cụt."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 0,8 thốn. Cứu 3–5 tráng, Ôn cứu 5 –10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là chỗ tiếp nối giữa phần thịt và phần cân của cơ chéo to của bụng, các cơ gian sườn 7, bên phải là gan, bên trái là lách hoặc dạ dầy.\nThần kinh vận động cơ là các nhánh của dây thần kinh gian sườn 7.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D7 hoặc D8.\nXương ức mềm do đó cần thận trọng khi châm nơi trẻ nhỏ."}]},{"id":577,"ten":"Nhĩ Bình Ngoại Tam Huyệt","sections":[{"h":"VỊ TRÍ","body":"Ở thuyền tai, có ba huyệt: phía trên, giữa và dưới đối bình tai kéo ngang ra."},{"h":"CHỦ TRỊ","body":"Trị amidal viêm cấp, tai ù, điếc, tai ngoài viêm, tai trong viêm, họng viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,2 – 0,5 thốn.N\nMJ"}]},{"id":578,"ten":"Nhĩ Bối Tĩnh Mạch Tam Điều","sections":[{"h":"VỊ TRÍ","body":"Ba nhánh tĩnh mạch ở sau vành tai."},{"h":"CHỦ TRỊ","body":"Trị kết mạc viêm, huyết áp cao, bệnh ngoài da."},{"h":"CHÂM CỨU","body":"Chích nặn ra 1 ít máu tươi."}]},{"id":579,"ten":"Nhĩ Hậu Phát Tế","sections":[{"h":"VỊ TRÍ","body":"Tại chân tóc phía sau tai, chỗ có một chỗ trũng nhỏ, có mạch đập."},{"h":"CHỦ TRỊ","body":"Trị lao hạch (loa lịch)"},{"h":"CHÂM CỨU","body":"Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút."}]},{"id":580,"ten":"Nhĩ Khổng Trung","sections":[{"h":"VỊ TRÍ","body":"Trong lỗ tai, ngay chỗ ngang với sống tai."},{"h":"CHỦ TRỊ","body":"Trị trúng phong, vàng da, bệnh về tai."},{"h":"CHÂM CỨU","body":"Thường dùng phép cứu.\nCứu theo cách sau: Dùng một cái ống, để vào lỗ tai, lấy bông gòn nhét chung quanh cho hơi thuốc không ra. Trên đầu ống để viên ngải to bằng hạt đậu, cứu 7 tráng. Đau bên phải cứu bên trái và ngược lại."}]},{"id":581,"ten":"Nhĩ Môn","sections":[{"h":"VỊ TRÍ","body":"Ở ngay phía trước rãnh trên bình tai, đầu trên chân bình tai, nơi cơ tai trước."},{"h":"CHỦ TRỊ","body":"Trị tai ù, điếc, tai giữa viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn, khi châm, há miệng ra hướng mũi kim xuống. Cứu 1 – 3 tráng. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ tai trước, xương thái dương.\nThần kinh vận động cơ là nhánh của dây thần kinh mặt\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V."}]},{"id":582,"ten":"Nhĩ Môn Hạ Quan Đinh Tự Thích","sections":[{"h":"VỊ TRÍ","body":"Huyệt Nhĩ Môn, Thính Cung và Thính Hội là một huyệt châm. Huyệt Hạ Quan đến huyệt Thính Cung là một huyệt châm. Hai nhóm huyệt này hợp thành một huyệt gọi chung là Nhĩ Môn Hạ Quan.\nCách châm có hình giống chữ Đinh.\nVì vậy được đặt tên như trên."},{"h":"CHỦ TRỊ","body":"Trị câm điếc, tai ù, điếc."},{"h":"CHÂM CỨU","body":"Từ huyệt Nhĩ môn, châm luồn dưới da đến huyệt Thính Cung, Thính Hội, rồi châm từ huyệt Hạ Quan ngang đến Thính Cung."}]},{"id":583,"ten":"Nhĩ Môn Tiền Mạch","sections":[{"h":"VỊ TRÍ","body":"Huyệt Nhĩ Môn đo lên và xuống 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị chứng Tỳ phong đưa lên họng làm không nói được."},{"h":"CHÂM CỨU","body":"Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút."}]},{"id":584,"ten":"Nhĩ Thùy","sections":[{"h":"VỊ TRÍ","body":"Tại giữa mặt trước của thùy tai."},{"h":"CHỦ TRỊ","body":"Trị miệng lở loét."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,1 thốn hoặc châm nặn máu."}]},{"id":585,"ten":"Nhĩ Thượng","sections":[{"h":"VỊ TRÍ","body":"Huyệt Nhĩ Tiêm đo thẳng lên 3 ngang ngón tay."},{"h":"CHỦ TRỊ","body":"Trị trẻ nhỏ bị động kinh."},{"h":"CHÂM CỨU","body":"Cứu."}]},{"id":586,"ten":"Nhĩ Tiêm","sections":[{"h":"VỊ TRÍ","body":"Trên mỏm tai, bóp tai lại huyệt ở trên chóp tai. Hoặc gấp vành tai về phía trước, huyệt là nơi cao nhất ở chỗ nhọn của 2 nửa vành tai gấp."},{"h":"CHỦ TRỊ","body":"Trị mắt có mộng, mắt hột, mắt lẹo, mắt có màng, kết mạc viêm, sốt cao."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,1 – 0,2 thốn, nặn ra một ít máu."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là sụn vành tai.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số 5."}]},{"id":587,"ten":"Nhị Bạch","sections":[{"h":"VỊ TRÍ","body":"Nếp gấp cổ tay đo lên 4 thốn, mỗi tay có 2 huyệt ngang nhau, một huyệt ở trong gân, giữa 2 gân (sau huyệt Gian Sử 1 thốn), còn huyệt khác ở ngoài gân về phía tay quay, ngang với huyệt trên."},{"h":"CHỦ TRỊ","body":"Trị trĩ, trực tràng sa, thần kinh tay trước đau."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn. Cứu 10 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là bờ trong, bờ ngoài gân cơ gan tay bé, dưới nữa là cơ dài gấp ngón cái, cơ gấp nông và sâu các ngón tay.\nThần kinh vận động cơ do các nhánh của dây thần kinh giữa và trụ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C6 và D1."}]},{"id":588,"ten":"Nhị Chỉ Thượng","sections":[{"h":"VỊ TRÍ","body":"Tại giữa đường nối 2 huyệt Nội Đình (Vi 44) và Hãm Cốc (Vi 43)"},{"h":"CHỦ TRỊ","body":"Trị phù thũng, thủy bệnh."},{"h":"CHÂM CỨU","body":"Cứu."}]},{"id":589,"ten":"Nhị Chùy Hạ","sections":[{"h":"VỊ TRÍ","body":"Dưới đốt sống lưng thứ 2."},{"h":"CHỦ TRỊ","body":"Trị bệnh tâm thần, động kinh, sốt rét."},{"h":"CHÂM CỨU","body":"Châm xiên, sâu 0,5 – 1,5 thốn."}]},{"id":590,"ten":"Nhị Gian","sections":[{"h":"VỊ TRÍ","body":"Huyệt ở chỗ lõm, phía trước và bờ ngoài khớp xương bàn và ngón trỏ, trên đường tiếp giáp da gan tay, mu tay."},{"h":"CHỦ TRỊ","body":"Trị ngón tay trỏ đau, bàn tay đau, răng đau, họng đau, vai đau, lưng đau, liệt mặt, sốt."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,1 – 0,3 thốn. Cứu 1 – 3 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là gân cơ gian cốt mu tay và xương .\nThần kinh vận động cơ là nhánh dây thần kinh trụ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C7."}]},{"id":591,"ten":"Nhị Lý Bán","sections":[{"h":"VỊ TRÍ","body":"Huyệt Túc Tam Lý (Vi 36) đo lên 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị trường vị viêm cấp tính."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1,5 – 2,5 thốn."}]},{"id":592,"ten":"Nhị Nhân Thượng Mã","sections":[{"h":"VỊ TRÍ","body":"Mu bàn tay, phía sau đầu xương bàn tay thứ 5, ngang phía trên huyệt Tiền cốc."},{"h":"CHỦ TRỊ","body":"Trị tiểu gắt, nước tiểu đỏ."},{"h":"CHÂM CỨU","body":"Cứu 7 tráng.N\nX"}]},{"id":593,"ten":"Nhị Phiến Môn","sections":[{"h":"VỊ TRÍ","body":"Lưng bàn tay, tại chỗ lõm giữa ngón tay thứ 3 và 4."},{"h":"CHỦ TRỊ","body":"Trị bệnh về mắt, sốt không có mồ hôi, ngứa."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,3 – 0,5 thốn. Cứu 5 – 10 phút.4\n,S"}]},{"id":594,"ten":"Nhị Phùng","sections":[{"h":"VỊ TRÍ","body":"Điểm giữa lóng thứ 1 và 2 của ngón tay thứ 1."},{"h":"CHỦ TRỊ","body":"Trị cam tích, trẻ nhỏ biếng ăn."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,1–0,2 thốn hoặc châm nặn ra ít máu hoặc nước vàng."}]},{"id":595,"ten":"Nhị Thập Chuỳ","sections":[{"h":"VỊ TRÍ","body":"Tại dưới gai đốt sống thắt lưng cùng 3."},{"h":"CHỦ TRỊ","body":"Trị nôn ra máu, chảy máu mũi, tiêu ra máu, băng huyết, các bệnh liên hệ đến huyết."},{"h":"CHÂM CỨU","body":"Nằm sấp, cứu 3–5 tráng.(\nSA"}]},{"id":596,"ten":"Nhiên Cốc","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm sát giữa bờ dưới xương thuyền, trên đường nối da gan chân và mu chân."},{"h":"CHỦ TRỊ","body":"Trị khớp bàn chân đau, Bàng quang viêm, tiểu đường, họng đau, kinh nguyệt rối loạn."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,8 – 1,2 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ dạng ngón cái, cơ gấp ngắn ngón cái, chỗ bám của gân cơ cẳng chân sau, dưới bờ dưới của xương thuyền.\nThần kinh vận động cơ là các nhánh của dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5."}]},{"id":597,"ten":"Nhiên Hậu","sections":[{"h":"VỊ TRÍ","body":"Huyệt Nhiên Cốc (Th 2) đo vào phía gót chân 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị bàn chân trong đau, bàn chân nóng."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 5 – 10 phút.06\n'O"}]},{"id":598,"ten":"Nhiếp Nhu","sections":[{"h":"VỊ TRÍ","body":"Khóe mắt ngoài (huyệt Đồng Tử Liêu – Đ.1) đo ra ngang 0,5 thốn rồi đo lên 0,2 thốn, ngang với thái dương."},{"h":"CHỦ TRỊ","body":"Trị các bệnh về mắt."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,3 – 0,4 thốn. Cẩn thận khi cứu.j\nF"}]},{"id":599,"ten":"Nhiệt Điểm","sections":[{"h":"VỊ TRÍ","body":"Tại viền trong chân trước đối vành tai, ngang với nếp trước của chân trên đối vành tai."},{"h":"CHỦ TRỊ","body":"Hạ sốt."}]},{"id":600,"ten":"Nhu Du","sections":[{"h":"VỊ TRÍ","body":"Huyệt ở phía sau lưng, chỗ lõm nơi đầu xương giáp vai hoặc là nơi gặp nhau của đường nếp nách sau kéo dài và chỗ lõm dưới sống vai."},{"h":"CHỦ TRỊ","body":"Trị khớp vai và cánh tay đau hoặc viêm, liệt 1/2 người, huyết áp cao."},{"h":"CHÂM CỨU","body":"Châm thẳng, mũi kim hơi hướng về phía trước, sâu 1 – 1,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 20 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ Delta, cơ dưới gai và cơ trên gai, bờ dưới gai, sống gai.\nThần kinh vận động cơ là các nhánh của dây mũ và dây trên gai.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D2."}]},{"id":601,"ten":"Nhu Hội","sections":[{"h":"VỊ TRÍ","body":"Ngay dưới mỏm vai 3 thốn, nằm ở bờ sau cơ delta."},{"h":"CHỦ TRỊ","body":"Trị vai và cánh tay đau, khớp xương vai sưng đau, các bệnh về mắt."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,8 – 1,2 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ sau – dưới của cơ Delta, khe giữa phần dài và phần rộng ngoài của cơ 3 đầu cánh tay, xương cánh tay.\nThần kinh vận động cơ là dây thần kinh mũ và các nhánh của dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C5."}]},{"id":602,"ten":"Nhu Thượng","sections":[{"h":"VỊ TRÍ","body":"Tại trung điểm của cơ tam giác."},{"h":"CHỦ TRỊ","body":"Trị chi trên liệt, vai đau, cánh tay đau."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 2 thốn."}]},{"id":603,"ten":"Nhũ Ảnh","sections":[{"h":"VỊ TRÍ","body":"Dùng một sợi dây đo chiều ngang 2 đầu vú, cắt lấy một nửa, đặt vào đầu vú rồi thả thẳng xuống, đụng đến đâu, đó là huyệt."},{"h":"CHỦ TRỊ","body":"Trị sốt rét."},{"h":"CHÂM CỨU","body":"Cứu 3 tráng, nam cứu bên trái, nữ cứu bên phải.z\n\nK"}]},{"id":604,"ten":"Nhũ Bàng","sections":[{"h":"VỊ TRÍ","body":"Đầu vú đo ngang ra mỗi bên 0,2 thốn."},{"h":"CHỦ TRỊ","body":"Trị ho đờm, suyễn, tức ngực, nôn mửa."},{"h":"CHÂM CỨU","body":"Dùng ngón tay giữa ấn hoặc vuốt 10 – 15 phút."}]},{"id":605,"ten":"Nhũ Căn","sections":[{"h":"VỊ TRÍ","body":"Ở giữa gian sườn 5, thẳng dưới đầu vú, cách đường giữa ngực 4 thốn."},{"h":"CHỦ TRỊ","body":"Trị sữa thiếu, tuyến vú viêm, ngực đau."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,8 thốn, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ ngực to, các cơ ngực bé, các cơ gian sườn 5, bờ trên xương sườn 6, bên phải là phổi, bên trái là mỏm tim.\nThần kinh vận động cơ là nhánh cơ ngực to, nhánh cơ ngực bé của đám rối thần kinh nách, dây thần kinh gian sườn 5.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D4 – D5."}]},{"id":606,"ten":"Nhũ Hạ","sections":[{"h":"VỊ TRÍ","body":"Đầu núm vú đo xuống 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị bụng đau, bụng đầy, hông sườn đau, sữa ít, ho lâu ngày, nôn mửa, bao tử đau, kinh bế."},{"h":"CHÂM CỨU","body":"Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."}]},{"id":607,"ten":"Nhũ Thượng","sections":[{"h":"VỊ TRÍ","body":"Đo 2 bên khóe miệng làm thành một thốn, lấy thốn đó đo từ đầu vú lên một thốn là huyệt."},{"h":"CHỦ TRỊ","body":"Trị bệnh ở vú, ngực đau."},{"h":"CHÂM CỨU","body":"Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút.1X\nb"}]},{"id":608,"ten":"Nhũ Trung","sections":[{"h":"VỊ TRÍ","body":"Khoảng gian sườn 4, ngay đầu vú."},{"h":"GIẢI PHẪU","body":"Dưới đầu vú là chùm tuyến vú, sau chùm tuyến vú là cơ ngực to, cơ ngực bé, các cơ gian sườn 4.\nThần kinh vận động cơ là dây thần kinh ngực to, dây thần kinh ngực bé và dây thần kinh gian sườn 4.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D4."}]},{"id":609,"ten":"Nhũ Tuyền","sections":[{"h":"VỊ TRÍ","body":"Ở bờ dưới cơ ngực lớn, trước lằn chỉ ngang hố nách."},{"h":"CHỦ TRỊ","body":"Trị thiếu sữa."},{"h":"CHÂM CỨU","body":"Nằm ngửa, đưa hai tay lên, dùng kim châm từ đầu trước lằn chỉ nách, dọc theo bờ dưới cơ ngực lớn, mũi kim hướng về huyệt Thiên đột. Lưu kim 20 phút, cứ 5 phút vê kim một lần."}]},{"id":610,"ten":"Niệu Đạo","sections":[{"h":"VỊ TRÍ","body":"Ở trên gờ đoạn đi lên của luân tai, ngang với huyệt Bàng Quang và hơi thấp hơn bờ dưới của nhánh dưới đối luân."},{"h":"CHỦ TRỊ","body":"Trị niệu đạo viêm, tiểu són, tiểu gắt, tiểu buốt, bí tiểu, đái dầm."}]},{"id":611,"ten":"Niệu Huyết","sections":[{"h":"VỊ TRÍ","body":"Khe đốt sống lưng – ngực 7 đo ngang ra 5 thốn."},{"h":"CHỦ TRỊ","body":"Trị tiểu ra máu."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Cứu 3 – 5 phút."}]},{"id":612,"ten":"Nội Chí Âm","sections":[{"h":"VỊ TRÍ","body":"Tại phía trong gốc móng ngón thứ 5 tay và chân, cách gốc móng 0,1 thốn."},{"h":"CHỦ TRỊ","body":"Trị trẻ nhỏ bị kinh phong, hôn mê, tạng táo."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,1 – 0,2 thốn hoặc châm ra ít máu."}]},{"id":613,"ten":"Nội Côn Lôn","sections":[{"h":"VỊ TRÍ","body":"Đỉnh mắt cá chân trong, đo vào 1 thốn (1 khoát ngón tay), ngay sát dưới huyệt Thái khê."},{"h":"CHỦ TRỊ","body":"Trị phiên vị (ăn vào lại nôn ra ngay)"},{"h":"CHÂM CỨU","body":"Cứu 3 tráng.X\n'"}]},{"id":614,"ten":"Nội Dương Trì","sections":[{"h":"VỊ TRÍ","body":"Tại giữa lằn chỉ của cổ tay (huyệt Đại Lăng – Tb 7) đo xuống 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị bàn tay lở do phong, xoang viêm, yết hầu đau, trẻ nhỏ bị động kinh."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn."}]},{"id":615,"ten":"Nội Đình","sections":[{"h":"VỊ TRÍ","body":"Nơi nối thân với đầu sau xương đốt 1 của ngón chân thứ 2, giữa kẽ ngón chân thứ 2 và thứ 3."},{"h":"CHỦ TRỊ","body":"Trị dạ dày đau, đầu đau, răng đau, ruột viêm, amidal viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng hoặc xiêm 0,3 – 0,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa các gân duỗi ngón 2 và 3 của cơ duỗi dài và cơ duỗi ngắn các ngón chân, cơ gian cốt mu chân 2, khe giữa xương đốt 1 ngón chân 2 và 3.\nThần kinh vận động cơ là các nhánh của dây thần kinh chầy trước và nhánh của dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5."}]},{"id":616,"ten":"Nội Giáp Trắc","sections":[{"h":"VỊ TRÍ","body":"Tại vách ngoài của xoắn mũi trước, bên trong xoang mũi trước."},{"h":"CHỦ TRỊ","body":"Trị mũi viêm dị ứng."},{"h":"CHÂM CỨU","body":"Nâng cánh mũi lên, châm xiên sâu 0,2 thốn."}]},{"id":617,"ten":"Nội Giáp Xa","sections":[{"h":"VỊ TRÍ","body":"Phía trong góc hàm dưới, nơi nhô cao của cơ hàm dưới."},{"h":"CHỦ TRỊ","body":"Trị răng đau, thần kinh tam thoa đau."},{"h":"CHÂM CỨU","body":"Châm xiên hướng xuống góc hàm dưới, sâu 1,5 – 2 thốn."}]},{"id":618,"ten":"Nội Hợp Cốc","sections":[{"h":"VỊ TRÍ","body":"Hơi nắm bàn tay lại, Huyệt ở giữa ngón trỏ và ngón cái, nơi có lằn chỉ."},{"h":"CHỦ TRỊ","body":"Trị cổ vẹo, cổ cứng."},{"h":"CHÂM CỨU","body":"Châm mũi kim hướng về phía huyệt Hợp Cốc, sâu 1 – 1,5 thốn."}]},{"id":619,"ten":"Nội Khỏa Tiêm","sections":[{"h":"VỊ TRÍ","body":"Ngay mỏm đầu dưới xương chày – mắt cá chân trong."},{"h":"CHỦ TRỊ","body":"Trị vọp bẻ, chuột rút cơ bắp, răng đau, cước khí."},{"h":"CHÂM CỨU","body":"Cứu."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là đầu dưới xương chày và xương gót chân.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L4 hoặc L5.G2\n24:"}]},{"id":620,"ten":"Nội Khỏa Tiền Hạ","sections":[{"h":"VỊ TRÍ","body":"Lấy điểm giữa phía dưới mắt cá chân trong đo ra phía trước một ngang ngón tay."},{"h":"CHỦ TRỊ","body":"Trị nôn ra thức ăn."},{"h":"CHÂM CỨU","body":"Cứu."}]},{"id":621,"ten":"Nội Kiên Ngung","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm giữa khớp vai (huyệt Kiên ngung) đo ra 1 thốn, phía ngoài bả vai."},{"h":"CHỦ TRỊ","body":"Trị liệt nửa người, khớp vai viêm."},{"h":"CHÂM CỨU","body":"Châm 0,5 – 0, 8 thốn. Cứu 3 – 7 tráng."}]},{"id":622,"ten":"Nội Minh","sections":[{"h":"VỊ TRÍ","body":"Đầu khóe mắt trong (huyệt Tình Minh – Bq 1) đo lên 0,2 thốn."},{"h":"CHỦ TRỊ","body":"Trị thần kinh thị giác teo, mắt lác, ra gió chảy nước mắt."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn."}]},{"id":623,"ten":"Nội Nghênh Hương","sections":[{"h":"VỊ TRÍ","body":"Ở trên lớp niêm mạc trong lỗ mũi."},{"h":"CHỦ TRỊ","body":"Trị kết mạc viêm, họng viêm, trúng nắng."},{"h":"CHÂM CỨU","body":"Châm nặn ra ít máu."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là sụn cánh mũi hoặc xương cuốn.\nNiêm mạc mũi chi phối bởi dây thần kinh sọ não số V."}]},{"id":624,"ten":"Nội Quan","sections":[{"h":"VỊ TRÍ","body":"Trên cổ tay 2 thốn, dưới huyệt Gian Sử (Tb 6) 1 thốn, giữa khe gân cơ gan tay lớn và bé."},{"h":"CHỦ TRỊ","body":"Trị hồi hộp, vùng trước tim đau, vùng ngực và hông sườn đau, dạ dày đau, nôn, nấc, mất ngủ, động kinh, hysteria."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 0,8 thốn. Cứu 3–5 tráng. Ôn cứu 5–10 phút.\nTrị bệnh đau ở phần trên, mũi kim hướng lên.\nTrị các ngón tay tê dại, mũi kim hơi hướng xuống 1 bên tay quay.\nTrị thần kinh suy nhược + mất ngủ, có thể châm xiên qua Ngoại Quan."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa gân cơ gan tay lớn, gân cơ gan tay bé, gân cơ gấp dài ngón tay cái, gân cơ gấp chung ngón tay nông và sâu, cơ sấp vuông, màng gian cốt quay và trụ.\nThần kinh vận động cơ là các nhánh của dây thần kinh giữa, các nhánh của dây thần kinh trụ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D1 hoặc C6.V!Y\nMắt mờ không thấy gì, nên châm huyệt Nhị Gian\" (Thông Huyền Chỉ Yếu Phú).\n\"Răng đau, lưng đau, cổ họng sưng đau, châm huyệt Nhị Gian + Dương Khê thì tật bệnh sẽ trốn đi nơi khác\" (Tịch Hoằng Phú).\n\"Sợ lạnh và lạnh run, châm Nhị Gian và Âm Khích, sẽ xua tà và làm thông khí\" (Bách Chứng Phú).\n\"Chứng đầu phong có phân ra thiên và chính, phân biệt bằng cách xem có đờm ẩm hay không. Nếu bệnh nhân có đờm ẩm, châm huyệt Phong Trì (Đ 20), nếu không có đờm ẩm thì châm huyệt Hợp Cốc\" (Ngọc Long Ca)"}]},{"id":625,"ten":"Nội Tất Nhãn","sections":[{"h":"VỊ TRÍ","body":"Tại chỗ lõm dưới xương bánh chè của cơ 4 đầu đùi ngang với khớp gối."},{"h":"CHỦ TRỊ","body":"Trị mặt trong đầu gối đau, đứng lên ngồi xuống khó khăn."},{"h":"CHÂM CỨU","body":"Châm sâu 0,5–0,8 thốn. Cứu 5–10 phút."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là hõm giữa xương bánh chè của cơ 4 đầu đùi, gân cơ may. Xương bánh chè, khe của khớp xương đùi và xương chày.\nThần kinh vận động cơ là các nhánh của dây thần kinh đùi."}]},{"id":626,"ten":"Nội Thái Xung","sections":[{"h":"VỊ TRÍ","body":"Tại giữa chỗ lõm phía trong, sát gân lớn, ngang với huyệt Thái Xung (C 3)"},{"h":"CHỦ TRỊ","body":"Trị sán khí, hô hấp không thông."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,1 thốn – Cứu 2 tráng.B0K\n!"}]},{"id":627,"ten":"Nội Tinh Minh","sections":[{"h":"VỊ TRÍ","body":"Tại góc khoé trong mắt, ở trên ống lệ."},{"h":"CHỦ TRỊ","body":"Trị võng mạc xuất huyết, thần kinh thị giác teo, kết mạc viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn.?'\n?"}]},{"id":628,"ten":"Nục Huyết Điểm","sections":[{"h":"VỊ TRÍ","body":"Ngay chính giữa chân tóc gáy, giữa khe gáy."},{"h":"CHỦ TRỊ","body":"Trị chảy máu cam."},{"h":"CHÂM CỨU","body":"Châm hơi xiên xuống dưới sâu 0,1 – 0,2 thốn.,\n3"}]},{"id":629,"ten":"Nữ Tất","sections":[{"h":"VỊ TRÍ","body":"Tại điểm giữa của xương gót chân."},{"h":"CHỦ TRỊ","body":"Trị thổ tả rút gân, cốt tào phong, hồi hộp, lợi răng viêm, bệnh tâm thần."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,2 – 0,3 thốn."}]},{"id":630,"ten":"Nựu Thương Huyệt","sections":[{"h":"VỊ TRÍ","body":"Huyệt nằm ở 1/4 trên và 3/4 dưới của đường nối huyệt Khúc Trì (Đtr 11) và Dương Trì (Ttu 4)"},{"h":"CHỦ TRỊ","body":"Trị chấn thương thắt lưng cấp tính."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1 – 2 thốn."}]},{"id":631,"ten":"Oai Linh","sections":[{"h":"VỊ TRÍ","body":"Tại cuối xương ngón tay cái và ngón trỏ, chỗ bờ dưới khung xương tròn của khớp bàn tay 1 và 2. Có 2 huyệt."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, hoa mắt, ù tai, trẻ nhỏ bị kinh phong cấp, mạn, mu bàn tay đau."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn.k\nMk"}]},{"id":632,"ten":"Ốc Ế","sections":[{"h":"VỊ TRÍ","body":"Ở khoảng gian sườn 2, trên đường thẳng qua đầu ngực, cách đường giữa ngực 4 thốn (ngang h.Tử Cung – Nh.19), nơi cơ ngực to, bờ trên cơ ngực bé."},{"h":"CHỦ TRỊ","body":"Trị suyễn, khí quản viêm, thần kinh liên sườn đau."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn, Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ ngực to, bờ trên cơ ngực bé, các cơ gian sườn 2, bờ trên xương sườn 3, trong sâu có phổi.\nThần kinh vận động cơ là nhánh cơ ngực to, nhánh cơ ngực bé của đám rối thần kinh nách, dây thần kinh gian sườn 2.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D2."}]},{"id":633,"ten":"Ôn Lưu","sections":[{"h":"VỊ TRÍ","body":"Chỗ sưng trên xương quay khi bàn tay nắm chặt lại, nằm trên đường nối Dương Khê (Đtr 5) – Khúc Trì (Đtr 11), cách Dương Khê 5 thốn."},{"h":"CHỦ TRỊ","body":"Trị cánh tay đau, vai đau, tuyến mang tai viêm, miệng viêm, lưỡi viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn, Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là gân cơ quay 1, cơ quay 2, cơ dạng dài ngón tay cái và xương quay.\nThần kinh vận động cơ là các nhánh của dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C6."}]},{"id":634,"ten":"Phách Hộ","sections":[{"h":"VỊ TRÍ","body":"Dưới gai đốt sống lưng 3 (D3) đo ngang ra 3 thốn, cách Phế Du (Bq.13) 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị suyễn, phế quản viêm, lao phổi, nôn mửa, màng ngực viêm, vai lưng đau."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 0,8 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ thang, cơ trám, cơ răng bé sau – trên, cơ chậu sườn – ngực, cơ gian sườn 3, bên trong là phổi.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số XI, nhánh đám rối cổ sâu, nhánh đám rối cánh tay, các nhánh của dây thần kinh gian sườn 3.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D3."}]},{"id":635,"ten":"Phát Tế","sections":[{"h":"VỊ TRÍ","body":"Phía ngoài đuôi lông mày thẳng lên 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, chóng mặt, hoa mắt, trẻ nhỏ bị kinh giật."},{"h":"CHÂM CỨU","body":"Châm luồn dưới da sâu 0,3 – 0,5 thốn. Cứu 1 – 3 tráng, Ôn cứu 5 – 10 phút.+\n7K"}]},{"id":636,"ten":"Phế Bát Hoa","sections":[{"h":"VỊ TRÍ","body":"Các huyệt Phế Du (Bq.13) + Cao Hoang (Bq.43) + Cách Du (Bq.17) + Đởm Du (Bq.19) hợp lại thành 8 huyệt."},{"h":"CHỦ TRỊ","body":"Trị suyễn, lao phổi, suy nhược."},{"h":"CHÂM CỨU","body":"Cách một ngày cứu một lần.g\n t"}]},{"id":637,"ten":"Phế Du","sections":[{"h":"VỊ TRÍ","body":"Dưới gai đốt sống lưng 3, đo ngang ra 1,5 thốn, ngang huyệt Thân Trụ (Đc."},{"h":"CHỦ TRỊ","body":"Trị lao phổi, phổi viêm, khí quản viêm, suyễn, mồ hôi tự ra, mồ hôi trộm."},{"h":"CHÂM CỨU","body":"Châm xiên về phía cột sống 0,3 – 0,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5–10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ thang, cơ trám, cơ răng cưa bé sau – trên, cơ gối cổ, cơ lưng dài, cơ cổ dài, cơ bán gai của đầu, cơ bán gai của cổ, cơ ngang sườn, phổi.\nThần kinh vận động cơ là nhánh dây thần kinh sọ não số XI, nhánh đám rối cổ sâu, nhánh của đám rối cánh tay, nhánh của dây thần kinh gian sườn, 3 nhánh của dây sống lưng 3.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D3."}]},{"id":638,"ten":"Phế Nhiệt Huyệt","sections":[{"h":"VỊ TRÍ","body":"Gai xương đốt sống lưng thứ 3 đo ra 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị khí quản viêm, màng ngực viêm, vai lưng đau."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 1 thốn."}]},{"id":639,"ten":"Phi Dương","sections":[{"h":"VỊ TRÍ","body":"Đỉnh ngoài mắt cá chân đo lên 7 thốn, ngang huyệt Thừa Sơn (Bq.57) 1 thốn. Nơi tiếp giáp giữa phần thịt và phần gân của bờ ngoài cơ sinh đôi ngoài."},{"h":"CHỦ TRỊ","body":"Trị vùng lưng và chân đau, khớp viêm do phong thấp, Bàng Quang viêm, Thận viêm, động kinh."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ ngoài chỗ tiếp nối giữa phần thịt với phần gân của cơ sinh đôi ngoài, cơ dép, cơ gấp dài ngón chân cái, cơ chày sau, màng gian cốt.\nThần kinh vận động cơ là các nhánh dây thần kinh chày sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S2 hoặc L5."}]},{"id":640,"ten":"Phiên Vị Huyệt","sections":[{"h":"VỊ TRÍ","body":"Có hai huyệt:\n1 Tại giữa chân vú (huyệt Nhũ căn) đo xuống 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị phiên vị (ăn vào là nôn ra)"},{"h":"CHÂM CỨU","body":"Cứu 5–7 tráng. Ôn cứu 3 – 5 phút."}]},{"id":641,"ten":"Phó Á Môn","sections":[{"h":"VỊ TRÍ","body":"Huyệt Á Môn (Đc.15) xuống 1 thốn, rồi đo ra mỗi bên 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị di chứng não."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn."}]},{"id":642,"ten":"Phong Long","sections":[{"h":"VỊ TRÍ","body":"Đỉnh mắt cá chân ngoài lên 8 thốn hoặc lấy huyệt ở điểm giữa nếp kheo chân và mắt cá chân ngoài."},{"h":"CHỦ TRỊ","body":"Trị ho đờm, chóng mặt, suyễn, khó thở, ngực trướng, chi dưới tê liệt, cước khí, đầu đau."},{"h":"CHÂM CỨU","body":"Châm thẳng, mũi kim hướng về phía trong, sâu 1 – 1,5 thốn. Cứu 5 – 7 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa cơ duỗi chung các ngón chân và cơ mác bên ngắn, ở sâu là cơ duỗi dài riêng ngón chân cái, xương mác.\nThần kinh vận động cơ là nhánh của dây thần kinh chầy trước và nhánh của dây thần kinh cơ–da.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5."}]},{"id":643,"ten":"Phong Môn","sections":[{"h":"VỊ TRÍ","body":"Dưới mỏm gai đốt sống lưng 2, ra ngang 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị cảm mạo, phế quản viêm, vùng lưng và vai đau, cổ gáy vẹo."},{"h":"CHÂM CỨU","body":"Châm xiên về phía cột sống 0,5 – 0,8 thốn. Cứu 3–5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ thang, cơ trám (hoặc cơ thoi), cơ răng bé sau – trên, cơ gối cổ, cơ lưng dài, cơ cổ dài, cơ đầu dài, cơ bán gai của đầu, cơ ngang sườn, bên trong là phổi.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số XI, nhánh đám rối cổ sâu, nhánh đám rối cánh tay, dây thần kinh gian sườn 2, nhánh của dây sống lưng 2.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D2."}]},{"id":644,"ten":"Phong Nham","sections":[{"h":"VỊ TRÍ","body":"Điểm giữa đoạn nối 2 huyệt Á Môn (Đc.15) và bờ dưới trái tai, xong đưa tới trước 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị bệnh tâm thần, thần kinh suy nhược, Hysteria, đầu đau, di chứng bệnh ở não."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1,5 – 2 thốn.[\nP"}]},{"id":645,"ten":"Phong Phi Huyệt","sections":[{"h":"VỊ TRÍ","body":"Có 3 huyệt:\nTừ huyệt Trung Quản (rốn thẳng lên 4 thốn), đo xuống 0,5 thốn (1 huyệt).\nTừ huyệt Trung Quản đo ngang ra 2 bên 1,5 thốn (2 huyệt)"},{"h":"CHỦ TRỊ","body":"Trị chứng phong phi không nói được, tay chân không thoải mái."},{"h":"CHÂM CỨU","body":"Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."}]},{"id":646,"ten":"Phong Phủ","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm giữa gáy và ở trên chân tóc gáy 1 thốn. Giữa khe của xương chẩm và đốt sống cổ thứ I. Khi cúi đầu, gân cơ thang nổi lên ở chỗ bám vào hộp sọ, khi ngửa đầu, chỗ khe xương lõm xuống, có thể sờ được đáy hộp sọ, huyệt ở chỗ lõm giữa 2 cơ thang, ngang với đáy hộp sọ."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, gáy cứng đau, lòi dom, tử cung sa, mũi nghẹt, trúng phong, hay quên, tai ù, mắt hoa, điên cuồng, người lạnh toát, tim đập hồi hộp."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn, không cứu."},{"h":"GIẢI PHẪU","body":"Dưới da là gân cơ thang, cơ bán gai hoặc cơ rối to, cơ thẳng sau đầu bé, màng chẩm–đội sau và ống hành tủy.\nThần kinh vận động cơ do ngành sau của 3 dây thần kinh sống cổ trên và nhánh của dây thần kinh sọ não số XI.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C3."}]},{"id":647,"ten":"Phong Quắc","sections":[{"h":"VỊ TRÍ","body":"Tại điểm nối phía trong thùy tai nhỏ với huyệt Á Môn (Đc.15) đo lên phía trước 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị thần kinh rối loạn, chậm nhớ, đầu đau, Hysteria, bệnh tâm thần."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 0,8 thốn. Cứu 5 – 10 phút.0Y\nD0"}]},{"id":648,"ten":"Phong Thị","sections":[{"h":"VỊ TRÍ","body":"Xuôi cánh tay thẳng xuống đùi, ép ngón tay vào bờ sau cơ căng cân đùi, huyệt ở đầu ngón tay giữa áp lên đùi, trên nếp nhượng chân 7 thốn, giữa gân cơ nhị đầu đùi và cơ rộng giữa."},{"h":"CHỦ TRỊ","body":"Trị chi dưới liệt, vùng lưng và chân đau, thần kinh tọa đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3–5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ sau cân đùi và cơ rộng ngoài bờ trước cơ 2 đầu đùi, cơ rộng giữa, xương đùi. Thần kinh vận động cơ là nhánh dây thần kinh mông trên, các nhánh dây thần kinh đùi và nhánh dây thần kinh hông. Da vùng huyệt chi phối bởi tiết đoạn thần kinh L2."}]},{"id":649,"ten":"Phong Trì","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm của bờ trong cơ ức–đòn–chũm và bờ ngoài cơ thang bám vào đáy hộp sọ."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, cổ gáy cứng, cảm mạo, chóng mặt, mắt hoa, tai ù, huyết áp cao, các bệnh ở não."},{"h":"CHÂM CỨU","body":"Châm thẳng, ngang với trái tai, hơi hướng xuống dưới, hướng mũi kim về mắt bên kia, sâu 0,5 – 1 thốn, hoặc châm xiên thấu Phong Trì bên kia."},{"h":"GIẢI PHẪU","body":"Dưới da là góc tạo nên bởi cơ thang và cơ ức – đòn – chũm, đáy là cơ gối đầu và cơ đầu dài, đáy hộp sọ.\nThần kinh vận động cơ là nhánh của dây thần kinh cổ 2, nhánh của dây thần kinh chẩm lớn và nhánh của dây thần kinh dưới chẩm. Da vùng huyệt chi phối bởi tiết đoạn thần kinh C3."}]},{"id":650,"ten":"Phong Xỉ Thống","sections":[{"h":"VỊ TRÍ","body":"Giữa lằn chỉ cổ tay đo lên 2,5 thốn (trên huyệt Nội Quan 0,5 thốn), giữa huyệt Nội Quan (Tb.6) và huyệt Gian Sử (Tb."},{"h":"CHỦ TRỊ","body":"Trị răng đau (phong xỉ đông thống)"},{"h":"CHÂM CỨU","body":"Cứu trong điều trị răng đau. Châm trong châm tê để mổ."},{"h":"GIẢI PHẪU","body":"Dưới da là khe cơ gan tay lớn và gân cơ gan tay bé, gân cơ gấp dài ngón tay, cơ gấp chung các ngón tay nông và sâu.\nThần kinh vận động cơ là các nhánh của dây thần kinh giữa và dây thần kinh trụ."}]},{"id":651,"ten":"Phù Bạch","sections":[{"h":"VỊ TRÍ","body":"Tại bờ trên chân vành tai, trong chân tóc 01 thốn. Hoặc lấy tỉ lệ 1/3 trên và 2/3 dưới của đoạn nối huyệt Thiên Xung (Đ.9) và Hoàn Cốt (Đ."},{"h":"CHỦ TRỊ","body":"Trị tai ù, điếc, răng đau, amygdale viêm."},{"h":"CHÂM CỨU","body":"Châm dưới da 0,3 – 0,5 thốn. Cứu 1 – 3 tráng. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là xương thái dương.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C2."}]},{"id":652,"ten":"Phù Đột","sections":[{"h":"VỊ TRÍ","body":"Trên cơ ức – đòn – chũm, trên đường ngang qua bờ trên sụn giáp trạng, ngang ra 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị bụng đau, tắc tiếng nói, suyễn, ho."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn, Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là cơ bám da cổ, bó ức và bó đòn của cơ ức – đòn – chũm, các cơ bậc thang, chỗ bám vào xương của cơ góc.\nThần kinh vận động cơ là dây thần kinh cơ da – cổ, nhánh ngoài của dây thần kinh sọ não số XI, các nhánh của đám rối thần kinh cổ sâu.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C3.\nKhông châm sâu quá, có thể đụng phổi."}]},{"id":653,"ten":"Phù Khích","sections":[{"h":"VỊ TRÍ","body":"Trên nhượng chân 1 thốn, ở trong góc tạo bởi cơ 2 đầu đùi và bờ ngoài cơ bán mạc."},{"h":"CHỦ TRỊ","body":"Trị bàng quang viêm, táo bón, Vị Trường viêm cấp tính, chi dưới liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là góc giữa 2 cơ bán mạc và cơ 2 đầu đùi, mặt sau đầu dưới xương đùi.\nThần kinh vận động cơ là nhánh của dây thần kinh hông.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S2."}]},{"id":654,"ten":"Phủ Xá","sections":[{"h":"VỊ TRÍ","body":"Xác định huyệt Xung Môn (Ty.12) đo lên 7 thốn, cách ngang đường giữa bụng 4 thốn, trên nếp bẹn, phía ngoài động mạch đùi, ở khe giữa 2 bó cơ đái – chậu."},{"h":"CHỦ TRỊ","body":"Trị ruột dư viêm, phần phụ viêm, đau do thoát vị."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa 2 bó của cơ đái – chậu –xương đùi.\nThần kinh vận động cơ là các ngành ngang của đám rối thắt lưng.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L1."}]},{"id":655,"ten":"Phụ Dương","sections":[{"h":"VỊ TRÍ","body":"Trên mắt cá chân ngoài (huyệt Côn Lôn – Bq.60), đo thẳng lên 3 thốn, ở khe giữa cơ dép và cơ mác bên ngắn."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, vùng thắt lưng đau, đùi đau, khớp mắt cá chân sưng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,8 – 1,2 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa cơ dép và cơ mác bên ngắn cơ gấp dài ngón chân cái, bờ dưới cơ chầy sau.\nThần kinh vận động cơ là nhánh của dây cơ – da và nhánh của dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S2.\nKhi cứu, nếu thấy sốt thì ngưng, hết sốt lại cứu tiếp."}]},{"id":656,"ten":"Phụ Phân","sections":[{"h":"VỊ TRÍ","body":"Dưới gai sống lưng 2, đo ra 3 thốn, cách ngang huyệt Phong Môn 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị vai và cổ lưng đau nhức, cánh tay tê cứng, khuỷu tay tê mỏi."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,5 – 0,8 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ thang, cơ nâng vai, cơ trám, cơ răng bé sau – trên, cơ chậu sườn – ngực, cơ gian sườn 2, bên trong là phổi.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số XI, nhánh của đám rối cổ sâu, nhánh của dây thần kinh chẩm lớn, nhánh của đám rối cánh tay, các nhánh của dây thần kinh gian sườn 2.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh"}]},{"id":657,"ten":"Phúc Ai","sections":[{"h":"VỊ TRÍ","body":"Tại giao điểm của đường thẳng ở đầu ngực và đường ngang rốn (huyệt Đại Hoành –Ty.15), từ đó đo lên 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị bụng đau, táo bón, lỵ, tiêu hóa kém."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 5 – 7 tráng, Ôn cứu 10 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ chéo to của bụng, cơ chéo bé của bụng, cơ ngang bụng, mạc ngang, phúc mạc, đại trường ngang, bờ gan hoặc bờ dưới lách.\nThần kinh vận động cơ là do 6 dây thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D8."}]},{"id":658,"ten":"Phúc Kết","sections":[{"h":"VỊ TRÍ","body":"Nơi gặp nhau của đường dọc qua đầu ngực và đường ngang qua rốn dưới rốn 01 thốn."},{"h":"CHỦ TRỊ","body":"Trị quanh rốn đau, đau do thoát vị, tiêu chảy."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ chéo to của bụng, mạc ngang, phúc mạc, đại trường lên hoặc xuống.\nThần kinh vận động cơ do 6 dây thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D12."}]},{"id":659,"ten":"Phúc Tứ Huyệt","sections":[{"h":"VỊ TRÍ","body":"Bốn huyệt quanh rốn, cách rốn 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị trường vị viêm cấp tính, lỵ."},{"h":"CHÂM CỨU","body":"Dùng kim tam lăng lể vào huyệt, sau khi lể thì dùng bầu giác giác hơi."}]},{"id":660,"ten":"Phúc Xoang","sections":[{"h":"VỊ TRÍ","body":"Bờ dưới gai đốt sống lưng 12 đo ra mỗi bên 0,3 thốn."},{"h":"CHỦ TRỊ","body":"Trị bụng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 3 – 3,5 thốn.5\n;"}]},{"id":661,"ten":"Phục Cơ Tòng","sections":[{"h":"VỊ TRÍ","body":"Tại giao điểm của đường thẳng từ đầu nếp nách trong kéo xuống và đường ngang rốn."},{"h":"CHỦ TRỊ","body":"Làm dãn cơ bụng, (thường dùng trong châm tê giải phẫu)"},{"h":"CHÂM CỨU","body":"Châm xiên dọc lề dưới xương sườn, hướng mũi kim lên."}]},{"id":662,"ten":"Phục Lưu","sections":[{"h":"VỊ TRÍ","body":"Giữa mắt cá chân trong và gân gót (huyệt Thái Khê (Th.3) đo thẳng lên 2 thốn, trong khe của mặt trước gân gót chân và cơ gấp dài riêng ngón cái."},{"h":"CHỦ TRỊ","body":"Trị lưng đau, chi dưới liệt, tiêu chảy, mồ hôi trộm, Thận viêm, tinh hoàn viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng hoặc xiên, sâu 0,8 – 1,2 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa bờ trên gót chân, mặt sau cơ gấp dài ngón chân cái, mặt sau đầu dưới xương chầy.\nThần kinh vận động cơ là các nhánh của dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L4."}]},{"id":663,"ten":"Phục Thố","sections":[{"h":"VỊ TRÍ","body":"Ở điểm cách góc trên phía ngoài xương bánh chè 6 thốn, bờ ngoài cơ thẳng trước, bờ trong cơ rộng ngoài. Hoặc bàn tay úp lên đầu gối, các ngón tay khép lại, để ngay giữa lằn cổ tay thứ nhất lên trên giữa đầu gối, đầu ngón tay giữa áp lên da chân ở đầu, nơi đó là huyệt."},{"h":"CHỦ TRỊ","body":"Trị chi dưới đau và liệt, nửa người liệt, khớp gối viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ ngoài cơ thẳng trước, bờ trong cơ rộng ngoài, cơ rộng giữa, xương đùi.\nThần kinh vận động cơ là các nhánh của dây thần kinh đùi.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L3."}]},{"id":664,"ten":"Phùng Tượng Cơ Vận Động Điểm","sections":[{"h":"VỊ TRÍ","body":"Lấy điểm nối giữa gai trên trước và bờ trên xương đầu gối làm chuẩn, huyệt ở 1/4 của đoạn này (tính từ trên xuống), ở phía dưới mông lớn."},{"h":"CHỦ TRỊ","body":"Trị di chứng bại liệt trẻ nhỏ, đầu gối lật vào bên trong."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn."}]},{"id":665,"ten":"Phượng Nhãn","sections":[{"h":"VỊ TRÍ","body":"Tại cuối lằn chỉ phía ngoài ngón tay của khớp ngón cái."},{"h":"CHỦ TRỊ","body":"Trị quáng gà, nôn mửa, ngực và bụng đầy, khớp ngón tay cái cứng, khó co xuống được."},{"h":"CHÂM CỨU","body":"Châm cạn 0,1 – 0,2 thốn."}]},{"id":666,"ten":"Quan Môn","sections":[{"h":"VỊ TRÍ","body":"Rốn lên 3 thốn (huyệt Kiến Lý – Nh.11), rồi ra ngang 2 bên mỗi bên 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị bụng sình, tiêu hóa bị rối loạn, ruột sôi, tiêu chảy, phù thũng."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ chéo to, cơ thẳng to, mạc ngang, phúc mạc, trong ổ bụng là đại tràng ngang.\nThần kinh vận động cơ là 6 dây thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D8."}]},{"id":667,"ten":"Quan Môn II","sections":[{"h":"VỊ TRÍ","body":"Giữa gốc của dương vật, đo ra 2 bên, mỗi bên 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị dương vật cương cứng không xẹp xuống được, bụng dưới đau xốc lên tim."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 thốn. Cứu 3 – 7 tráng.5\nJ["}]},{"id":668,"ten":"Quan Nghi","sections":[{"h":"VỊ TRÍ","body":"Bờ trên phía ngoài xương bánh chè đo lên 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị phụ nữ vùng âm đạo đau lan đến ngực, bụng dưới đau quặn, trong bụng bị hàn."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút.1\nPw"}]},{"id":669,"ten":"Quan Nguyên","sections":[{"h":"VỊ TRÍ","body":"Thẳng dưới rốn 3 thốn, trên bờ xương mu 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị bệnh về kinh nguyệt, đới hạ, vô sinh, di mộng tinh, liệt dương, bụng dưới đau, tiêu chảy, kiết tiểu gắt, buốt, tiểu bí, choáng, ngất, nâng cao sức đề kháng, bồi bổ cơ thể, hư tổn, suy nhược toàn thân."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 2 thốn. Cứu 10 – 20 phút trở lên."},{"h":"GIẢI PHẪU","body":"Huyệt ở trên đường trắng, sau đường trắng là mạc ngang, phúc mạc. Vào sâu có ruột non khi bàng quang bình thường và không có thai, có bàng quang khi bí tiểu tiện, có tử cung khi có thai.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D11 hoặc D12."}]},{"id":670,"ten":"Quan Nguyên Du","sections":[{"h":"VỊ TRÍ","body":"Dưới đốt sống thắt lưng 5, đo ngang ra 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị thắt lưng đau, tiêu chảy, bệnh về đường tiểu và sinh dục."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn. Cứu 5 – 7 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân ngực – thắt lưng của cơ lưng to, khối cơ chung của các cơ ở rãnh cột sống, xương sống.\nThần kinh vận động cơ là nhánh của đám rối cánh tay, dây thần kinh sống thắt lưng 5.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L4 hoặc L5."}]},{"id":671,"ten":"Quan Thố","sections":[{"h":"VỊ TRÍ","body":"Huyệt nằm ở giữa đường nối liền huyệt Bể Quan (Vi 31) và Phục Thố (Vi 32)"},{"h":"CHỦ TRỊ","body":"Trị dạ dày đau, ruột viêm, di chứng bại liệt trẻ nhỏ."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1,5 – 2 thốn.K\n6P"}]},{"id":672,"ten":"Quan Thốn","sections":[{"h":"VỊ TRÍ","body":"Đo 2 bên khóe miệng thành 1 khẩu thốn, lấy huyệt Quan Nguyên (Nh.6) làm chuẩn, đo ra 2 bên và xuống dưới, mỗi nơi một khẩu thốn, tổng cộng 3 huyệt."},{"h":"CHỦ TRỊ","body":"Trị di tinh, bụng dưới đau, kinh nguyệt không đều, đới hạ."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 0,8 thốn. Cứu 5 – 10 phút."}]},{"id":673,"ten":"Quan Xung","sections":[{"h":"VỊ TRÍ","body":"Ở bờ trong ngón tay áp út, cách chân móng 0,1 thốn."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, họng viêm, sốt cao."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,1 – 0,2 thốn hoặc châm nặn máu. Cứu 1 – 3 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là xương, ở giữa chỗ bám gân ngón đeo nhẫn của cơ gấp chung ngón tay sâu và cơ duỗi chung ngón tay, bờ trong của đốt 3 xương ngón tay đeo nhẫn.\nThần kinh vận động cơ là nhánh của dây thần kinh trụ và dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C8 hoặc D1."}]},{"id":674,"ten":"Quang Minh","sections":[{"h":"VỊ TRÍ","body":"Trên đỉnh mắt cá ngoài 5 thốn, gần bờ trước xương mác, trong khe duỗi chung các ngón chân và cơ mác bên ngắn."},{"h":"CHỦ TRỊ","body":"Trị các bệnh về mắt, chi dưới đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa cơ duỗi chung các ngón chân và cơ mác bên ngắn, bờ trước xương mác.\nThần kinh vận động cơ là nhánh của dây thần kinh chầy trước và nhánh của dây thần kinh cơ – da cẳng chân.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5."}]},{"id":675,"ten":"Quang Thái","sections":[{"h":"VỊ TRÍ","body":"Ép sát đỉnh tai vào đầu, từ đó đo ngang ra phía trước chừng 0,1 thốn."},{"h":"CHỦ TRỊ","body":"Trị tuyến mang tai viêm truyền nhiễm (quai bị)"},{"h":"CHÂM CỨU","body":"Cứu bằng bấc đèn. Sau khi xác định huyệt, dùng Bấc đèn nhúng vào dầu (phộng, mè...) cho cháy, thổi tắt lửa, dí nhanh vào huyệt, nghe tiếng xèo, rút nhanh bấc đèn ra. Nếu bệnh chưa bớt, có thể làm thêm một lần nữa."}]},{"id":676,"ten":"Quân Dần","sections":[{"h":"VỊ TRÍ","body":"Hai huyệt ở hai đầu ngón tay út."},{"h":"CHỦ TRỊ","body":"Trị kinh phong, động kinh."},{"h":"CHÂM CỨU","body":"Cột 2 ngón tay út lại với nhau, cứu 7 – 14 tráng."}]},{"id":677,"ten":"Quắc Trì","sections":[{"h":"VỊ TRÍ","body":"Tại giao điểm của đường nối chỗ cao nhất của xương chũm và đường chân tóc sau gáy, sát bên mang tai."},{"h":"CHỦ TRỊ","body":"Trị nhãn áp cao (Glaucoma)"},{"h":"CHÂM CỨU","body":"Châm thẳng, hướng về phía sau, sâu 0,5 – 0,8 thốn. Cứu 5 – 10 phút."}]},{"id":678,"ten":"Quy Lai","sections":[{"h":"VỊ TRÍ","body":"Rốn xuống 4 thốn (huyệt Trung Cực (Nh.3), rồi đo ra 2 bên mỗi bên 2 thốn."},{"h":"CHỦ TRỊ","body":"Không có kinh nguyệt, đau bụng kinh, phần phụ viêm, đau do thoát vị."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn hoặc hướng mũi kim đến nơi liên hợp của xương mu, Cứu 5 – 7 tráng, Ôn cứu 10 – 20 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ chéo to, bờ ngoài cơ thẳng to, mạc ngang, phúc mạc, trong ổ bụng là ruột non và tử cung khi có thai 3 – 4 tháng, đáy bàng quang khi đầy.\nThần kinh vận động cơ là 6 dây thần kinh gian sườn dưới và dây thần kinh bụng–sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D12."}]},{"id":679,"ten":"Quỷ Đương","sections":[{"h":"VỊ TRÍ","body":"Nắm tay lại, huyệt ở đầu góc trong ngón tay cái, tại khớp xương lóng bàn tay."},{"h":"CHỦ TRỊ","body":"Trị mắt đỏ đau, trẻ nhỏ bị tiêu chảy."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn."}]},{"id":680,"ten":"Quỷ Khốc","sections":[{"h":"VỊ TRÍ","body":"Tại 2 bên chân gốc móng ngón tay cái và ngón chân cái."},{"h":"CHỦ TRỊ","body":"Trị điên cuồng, bệnh tâm thần."},{"h":"CHÂM CỨU","body":"Cứu.7\n["}]},{"id":681,"ten":"Quỷ Môn","sections":[{"h":"VỊ TRÍ","body":"Giữa chân vú (Nhũ Căn – Vi.18) đo xuống 0,2 thốn."},{"h":"CHỦ TRỊ","body":"Trị kinh phong cấp."},{"h":"CHÂM CỨU","body":"Cứu."}]},{"id":682,"ten":"Quỷ Nhãn","sections":[{"h":"VỊ TRÍ","body":"Tại 2 bên gốc móng ngón chân cái (tức là 2 huyệt Ẩn Bạch)"},{"h":"CHỦ TRỊ","body":"Trị động kinh, bệnh tâm thần."},{"h":"CHÂM CỨU","body":"Cứu 3 – 7 tráng.;\n3"}]},{"id":683,"ten":"Quỷ Sàng","sections":[{"h":"VỊ TRÍ","body":"Dưới dái tai 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị bệnh ở tai, cổ gáy bị cứng, lưỡi răng đau, trúng phong."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3–0,5 thốn. Cứu 3 tráng."}]},{"id":684,"ten":"Quỷ Thành","sections":[{"h":"VỊ TRÍ","body":"Tại đầu 10 ngón tay, cách gốc móng 0,1 thốn."},{"h":"CHỦ TRỊ","body":"Trị hôn mê, thử quyết, sốt cao, trúng thử, động kinh, Hysteria, trẻ nhỏ bị kinh phong."},{"h":"CHÂM CỨU","body":"Châm nặn máu.-\nW7"}]},{"id":685,"ten":"Qũy Dương","sections":[{"h":"VỊ TRÍ","body":"Dưới mỏm gai đốt sống lưng thứ 12 đo ngang ra 6 thốn."},{"h":"CHỦ TRỊ","body":"Trị dạ dày loét, tá tràng loét."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 0,8 thốn.6\n!"}]},{"id":686,"ten":"Quyền Liêu","sections":[{"h":"VỊ TRÍ","body":"Huyệt ở dưới xương gò má, giao điểm của đường chân cánh mũi kéo ngang ra và bờ ngoài của mắt kéo thẳng xuống, dưới huyệt là bờ trước cơ cắn, nơi bám vào xương gò má."},{"h":"CHỦ TRỊ","body":"Trị liệt mặt, cơ mặt co giật, răng đau, dây thần kinh sinh ba đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn hoặc châm xiên 0,5 – 1 thốn. Không cứu."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ trước cơ cắn, chỗ bám vào xương gò má.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số V.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V.\nKhông châm sâu quá, không chếch mũi kim ngược lên vì dễ gây tổn thương gan hoặc lách."}]},{"id":687,"ten":"Quyền Tiêm","sections":[{"h":"VỊ TRÍ","body":"Tại điểm cao nhất của lưng xương bàn tay, lóng thứ 3, ngón giữa và ngón đeo nhẫn."},{"h":"CHỦ TRỊ","body":"Trị yết hầu đau, bệnh ở mắt."},{"h":"CHÂM CỨU","body":"Châm xiên hoặc cứu.R\ns"}]},{"id":688,"ten":"Quyết Âm Du","sections":[{"h":"VỊ TRÍ","body":"Dưới gai sống lưng 4, đo ngang ra 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị ngực đau tức, thần kinh suy nhược, thấp tim, ho, đỉnh đầu đau."},{"h":"CHÂM CỨU","body":"Châm xiên về phía đốt sống 0,5 – 0,8 thốn. Cứu 3 – 5 tráng, Ôn cứu 5–10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ thang, cơ trám, cơ răng bé sau – trên, cơ gối cổ, cơ lưng dài, cơ cổ dài, cơ bán gai của đầu, cơ bán gai của cổ, cơ ngang – gai, cơ ngang – sườn, phổi.\nThần kinh vận động cơ là nhánh của dây sọ não số XI, nhánh của đám rối cổ sâu, nhánh của đám rối cánh tay, nhánh của dây thần kinh gian sườn 4 và nhánh của dây sống lưng 4.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D4."}]},{"id":689,"ten":"Sán Khí Huyệt","sections":[{"h":"VỊ TRÍ","body":"Đo 2 bên khóe miệng người bệnh làm thành một đoạn, cắt đoạn đó ra 3 khúc, làm thành hình tam giác đều. Đem đỉnh của tam giác đó đặt ngay giữa rốn, 2 đỉnh ở phía dưới rốn là huyệt."},{"h":"CHỦ TRỊ","body":"Trị sán khí, thiên trụy."},{"h":"CHÂM CỨU","body":"Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút. Bệnh bên trái cứu bên phải và ngược lại."}]},{"id":690,"ten":"Sáp Hoa","sections":[{"h":"VỊ TRÍ","body":"Tại góc chân tóc trán đo lên 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị lở ngứa vùng đầu mặt, nửa đầu đau."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,3 – 0,5 thốn. Cứu 1 – 3 tráng, Ôn cứu 3 – 5 phút.'\n'¾"}]},{"id":691,"ten":"Sắc Quang","sections":[{"h":"VỊ TRÍ","body":"Tại bờ trước loa tai, dưới rãnh bình tai đo xuống khoảng 0,1 thốn."},{"h":"CHỦ TRỊ","body":"Trị chứng mù mầu (sắc manh)"},{"h":"CHÂM CỨU","body":"Châm xiên mũi kim hướng về phía sau gáy, sâu 1 thốn."}]},{"id":692,"ten":"Sơn Căn","sections":[{"h":"VỊ TRÍ","body":"Trên sống mũi, chính giữa đoạn nối 2 mi mắt trong."},{"h":"CHỦ TRỊ","body":"Trị mất ngủ, mũi viêm, mất hoặc rối loạn khứu giác."},{"h":"CHÂM CỨU","body":"Châm xiên, sâu 0,3 – 0,5 thốn.3\n4-"}]},{"id":693,"ten":"Suất Cốc","sections":[{"h":"VỊ TRÍ","body":"Gấp vành tai, huyệt ở ngay trên đỉnh vành tai, trong chân tóc 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị nửa đầu đau, chóng mặt, hoa mắt."},{"h":"CHÂM CỨU","body":"Châm luồn dưới da 0,3 – 0,5 thốn. Cứu 1 – 3 tráng. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ tai trên, cơ thái dương, xương thái dương.\nThần kinh vận động cơ là nhánh của dây thần kinh mặt, dây thần kinh sọ não số V.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh"}]},{"id":694,"ten":"Sùng Cốt","sections":[{"h":"VỊ TRÍ","body":"Dưới gai đốt xương sống cổ 6."},{"h":"CHỦ TRỊ","body":"Trị cảm mạo, sốt rét, cổ cứng, khí quản viêm, động kinh."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn."}]},{"id":695,"ten":"Suyễn Lục Huyệt","sections":[{"h":"VỊ TRÍ","body":"Gồm các huyệt:\nPhế Du (Bq.13) có 2 huyệt.\nQuyết Âm Du (Bq.14) có 2 huyệt.\nTâm Du (Bq.15) có 2 huyệt.\nTổng cộng là 6 huyệt.\nXem chi tiết ở từng huyệt."},{"h":"CHỦ TRỊ","body":"Trị suyễn, ho lâu ngày."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 0,8 thốn. Cứu 10–15 phút."}]},{"id":696,"ten":"Suyễn Tức","sections":[{"h":"VỊ TRÍ","body":"Trên gai đốt xương sống cổ 7 đo ra 0,5 – 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị ho, khí quản viêm, suyễn, phong mề đay, cổ cứng."},{"h":"CHÂM CỨU","body":"Châm thẳng, mũi kim hơi hướng tới phía xương sống, sâu 0,5 – 1 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ thang, cơ trám, cơ gối đầu, cơ gối cổ, cơ ngang gai, xương sống cổ 7 hoặc lưng 1.\nThần kinh vận động cơ là nhánh của dây thần kinh và các nhánh của đám rối cổ sâu.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C8.)\n5ka"}]},{"id":697,"ten":"Tả Du","sections":[{"h":"VỊ TRÍ","body":"Thẳng giữa vú xuống đến xương sườn chót bên trái."},{"h":"CHỦ TRỊ","body":"Trị bụng đau, bụng dưới đau dồn lên trên."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn. Cứu 5 – 10 phút."}]},{"id":698,"ten":"Tả Hữu Quan","sections":[{"h":"VỊ TRÍ","body":"Lỗ rốn đo lên 3 thốn, ra ngang hai bên mỗi bên 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị dạ dầy đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn.9\n)"}]},{"id":699,"ten":"Tả Nghi","sections":[{"h":"VỊ TRÍ","body":"Huyệt Nhũ Căn (Vi.18) đo ngang ra bên trái 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị tuyến vú viêm, màng ngực viêm, màng trong tim viêm, thần kinh liên sườn đau."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn.3\nQ:"}]},{"id":700,"ten":"Tả Quan","sections":[{"h":"VỊ TRÍ","body":"Rốn lên 3 thốn, ra ngang 2 bên, mỗi bên 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị dạ dày đau."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,5 – 1 thốn. Cứu 3 – 7 tráng.2\nK"}]},{"id":701,"ten":"Tam Âm Giao","sections":[{"h":"VỊ TRÍ","body":"Ở sát bờ sau – trong xương chày, bờ trước cơ gấp dài các ngón chân và cơ cẳng chân sau, từ đỉnh cao của mắt cá chân trong đo lên 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị cẳng chân và gót chân sưng đau, thần kinh suy nhược, liệt nửa người, tiểu bí, tiểu vặt, tinh hoàn viêm, di mộng tinh, liệt dương, kinh nguyệt rối loạn, bụng trướng, da viêm do thần kinh, mề đay phong ngứa."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 5–7 tráng, Ôn cứu 10–20 phút.\nCó thể châm xuyên sang huyệt Tuyệt Cốt (Đ 39).\nTrị bệnh ở chân: hướng mũi kim ra phía sau.\nTrị bệnh toàn thân: hướng mũi kim lên phía trên."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ sau – trong xương chầy, bờ trước cơ gấp dài các ngón chân và cơ cẳng chân sau.\nThần kinh vận động cơ là các nhánh của dây chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L4."}]},{"id":702,"ten":"Tam Dương Lạc","sections":[{"h":"VỊ TRÍ","body":"Trên lằn cổ tay 4 thốn, khe giữa xương quay và trụ, ở mặt sau cẳng tay."},{"h":"CHỦ TRỊ","body":"Trị cánh tay đau, điếc, mất tiếng nói."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,8 – 1,2 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa cơ duỗi chung ngón tay và cơ duỗi riêng ngón tay út, giữa chỗ bám của cơ duỗi dài riêng và cơ duỗi ngắn riêng ngón tay cái ở trên màng gian cốt.\nThần kinh vận động cơ là các nhánh của dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C7."}]},{"id":703,"ten":"Tam Giác Cứu","sections":[{"h":"VỊ TRÍ","body":"Lấy chiều dài của 2 khoé miệng bệnh nhân làm 1 thốn, rồi lấy rốn làm đỉnh hình tam giác đều, còn 2 góc kia cách đều rốn đỉnh. Ba đỉnh của hình tam giác là 3 huyệt."},{"h":"CHỦ TRỊ","body":"Trị ruột viêm mạn tính, dạ dày co thắt, thoát vị, vùng bụng đau nhức."},{"h":"CHÂM CỨU","body":"Cứu 5 – 7 tráng. Ở rốn: cứu cách muối."}]},{"id":704,"ten":"Tam Gian","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm, sau và ngoài khớp xương bàn – ngón trỏ, trên đường tiếp giáp da gan tay – mu tay."},{"h":"CHỦ TRỊ","body":"Trị ngón tay trỏ viêm, lưng bàn tay đau, mắt đau, răng hàm dưới đau, họng đau, thần kinh sinh ba đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ gian cốt mu tay, cơ khép ngón tay cái và xương.\nThần kinh vận động cơ là các nhánh của dây thần kinh trụ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C7."}]},{"id":705,"ten":"Tam Lý Ngoại","sections":[{"h":"VỊ TRÍ","body":"Cuối nếp gấp khuỷu tay xuống 2 thốn (huyệt Thủ Tam Lý (Đtr 10), từ huyệt này đo ra ngoài 1 khoát ngón tay."},{"h":"CHỦ TRỊ","body":"Trị chi trên liệt, tay bị chấn thương."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 2 thốn.l\n'0"}]},{"id":706,"ten":"Tam Môn","sections":[{"h":"VỊ TRÍ","body":"Giữa chỗ lõm phía bên trong sau khớp gốc ngón tay trỏ."},{"h":"CHỦ TRỊ","body":"Trị nhọt ở ngón tay."},{"h":"CHÂM CỨU","body":"Cứu 3 – 7 tráng.07\nO"}]},{"id":707,"ten":"Tam Thương","sections":[{"h":"VỊ TRÍ","body":"Gồm 3 huyệt: Lão Thương, Trung Thương và Thiếu Thương.\nLão Thương ở mé bên ngoài ngón cái cách gốc móng tay chừng 0,1 thốn.\nTrung Thương ở chính giữa trên lưng ngón tay cái, cách móng tay độ 0,1 thốn.\nThiếu Thương ở mé bên trong ngón cái cách gốc móng tay chừng 0,1 thốn."},{"h":"CHỦ TRỊ","body":"Trị cúm, amidal viêm, sốt cao, tuyến mang tai viêm (quai bị)"},{"h":"CHÂM CỨU","body":"Châm nặn máu."}]},{"id":708,"ten":"Tam Tiêu Du","sections":[{"h":"VỊ TRÍ","body":"Dưới gai sống thắt lưng 1, đo ngang ra hai bên 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị dạ dày đau, ruột viêm, thận viêm, thần kinh suy nhược, tiêu hóa kém, tiểu dầm, thắt lưng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn. Cứu 5–7 tráng. Ôn cứu 10–15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân ngực – thắt lưng của cơ lưng to, cơ răng bé sau – dưới, cơ lưng dài, cơ ngang gai, cơ gian mỏm ngang, cơ vuông thắt lưng, cơ đái – chậu.\nThần kinh vận động cơ là nhánh của đám rối cánh tay, nhung của dây sống thắt lưng 1, nhánh của đám rối thắt lưng.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh 4."}]},{"id":709,"ten":"Tam Trì","sections":[{"h":"VỊ TRÍ","body":"Gồm 3 huyệt:\nThượng Trì: trên huyệt Khúc Trì (Đtr 11) một thốn.\nKhúc Trì (Đtr 11): cuối nếp gấp khuỷu tay khi cong tay lại.\nHạ Trì: dưới huyệt Khúc Trì (Đtr 11) một thốn."},{"h":"CHỦ TRỊ","body":"Trị khuỷu tay đau, mũi viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1–1,5 thốn."}]},{"id":710,"ten":"Tán Tiếu","sections":[{"h":"VỊ TRÍ","body":"Tại giữa rãnh mũi – miệng, ngang với huyệt Nghênh Hương (Đtr 20)"},{"h":"CHỦ TRỊ","body":"Trị mũi nghẹt, lở ngứa vùng mặt và trán, cơ mặt co giật, liệt mặt."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn."}]},{"id":711,"ten":"Tâm Du","sections":[{"h":"VỊ TRÍ","body":"Dưới gai sống lưng 5, đo ngang ra 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị bệnh về tim, tâm thần phân liệt, động kinh, thần kinh suy nhược."},{"h":"CHÂM CỨU","body":"Châm xiên về cột sống 0,5 – 0,8 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ thang, cơ trám, cơ lưng dài, cơ bán gai của cổ, cơ ngang gai, cơ ngang sườn, vào trong là phổi.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số XI, nhánh đám rối cổ sâu, nhánh đám rối cánh tay, nhánh của dây thần kinh gian sườn 5 và nhánh dây sống lưng 5.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D5."}]},{"id":712,"ten":"Tâm Quý Điểm","sections":[{"h":"VỊ TRÍ","body":"Lòng bàn tay, tại đầu khớp xương bàn tay thứ 5, phía tay quay."},{"h":"CHỦ TRỊ","body":"Trị hồi hộp, kinh nguyệt ra nhiều, thống kinh."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,2 – 0,3 thốn."}]},{"id":713,"ten":"Tân Hướng Vĩ Châm","sections":[{"h":"VỊ TRÍ","body":"Gồm 06 huyệt trên mạch Đốc: Đại Chùy (Đc 14), Đào Đạo (Đc 13), Thân Trụ (Đc 12), Thần Đạo (Đc 11), Linh Đài (Đc 10), Chí Dương (Đc 9)"},{"h":"CHỦ TRỊ","body":"Trị động kinh, hysteria, bại liệt do não, thần kinh suy nhược, bệnh tâm thần, mụn nhọt, viêm da do thần kinh, khí quản viêm, suyễn, vai đau, lưng đau, thần kinh liên sườn đau, bệnh thuộc về Tỳ Vị."},{"h":"CHÂM CỨU","body":"Trước hết châm vào huyệt Đại Chùy, sau đó luồn kim xuyên qua các huyệt kia, cho đến huyệt Chí Dương."}]},{"id":714,"ten":"Tân Lặc Đầu","sections":[{"h":"VỊ TRÍ","body":"Ở 2 bên xương ức, giữa xương sườn 1 và 2 là một huyệt, giữa xương sườn 2 và 3 là một huyệt."},{"h":"CHỦ TRỊ","body":"Trị dây thần kinh liên sườn đau, khí quản viêm, suyễn."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,3 – 0,5 thốn. Cứu 3 – 7 tráng."}]},{"id":715,"ten":"Tân Minh","sections":[{"h":"VỊ TRÍ","body":"Tại bờ dưới sau chân vành tai, chính giữa nếp nhăn da phía sau trái tai."},{"h":"CHỦ TRỊ","body":"Trị võng mạc viêm, thần kinh thị giác viêm, giác mạc loét, giác mạc viêm, quáng gà."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 450, có thể châm xuyên đến mặt ngoài xương hàm, sâu 1 – 1,5 thốn.0I\nTP"}]},{"id":716,"ten":"Tân Minh II","sections":[{"h":"VỊ TRÍ","body":"Tại vùng trán, từ cuối chân mày ngoài đo lên 1 thốn rồi đo ra ngoài 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị võng mạc viêm, thần kinh thị giác viêm cấp, giác mạc loét, giác mạc viêm, màng kết mạc viêm."},{"h":"CHÂM CỨU","body":"Châm xiên, mũi kim hướng về phía trán, sâu 0,5 – 0,8 thốn.0N\na;"}]},{"id":717,"ten":"Tân Thức","sections":[{"h":"VỊ TRÍ","body":"Dưới gai đốt sống thứ 3 cổ đo ra 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị gáy cứng, sau đầu đau, họng đau, thanh quản viêm, ho."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn.+\n:D"}]},{"id":718,"ten":"Tất Bàng","sections":[{"h":"VỊ TRÍ","body":"Co đầu gối vào, huyệt ở tại cuối 2 nếp gấp phía trong và ngoài (2 huyệt) và trên dưới đầu gối (2 huyệt). Tổng cộng 4 huyệt."},{"h":"CHỦ TRỊ","body":"Trị lưng đau không thể cúi ngửa, chân đau không thể đứng lâu được."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 –10 phút."}]},{"id":719,"ten":"Tất Căn","sections":[{"h":"VỊ TRÍ","body":"Tại phía trong và ngoài chỗ lõm của đầu gối, bên ngoài huyệt Độc Tỵ."},{"h":"CHỦ TRỊ","body":"Trị đầu gối sưng đau, gối không co duỗi được, đi bộ khó."},{"h":"CHÂM CỨU","body":"Châm thảng sâu 0,5 thốn. Cứu 3 tráng.0E\n9o"}]},{"id":720,"ten":"Tất Căn II","sections":[{"h":"VỊ TRÍ","body":"Tại chỗ lõm dưới góc dưới – ngoài xương bánh chè và ở ngoài gân cơ D đầu đùi (h. Độc Tỵ) ra 0,2 thốn, gần sát xương."},{"h":"CHỦ TRỊ","body":"Trị đầu gối viêm, đầu gối cử động khó khăn."},{"h":"CHÂM CỨU","body":"Cứu 5–10 phút."}]},{"id":721,"ten":"Tất Hạ","sections":[{"h":"VỊ TRÍ","body":"Xác định đỉnh cao nhất của xương bánh chè, huyệt ở dưới bờ xương, trên dây chằng bánh chè."},{"h":"CHỦ TRỊ","body":"Trị bệnh ở khớp gối, bệnh tổ chức mềm quanh khớp."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn. Cứu 1 – 3 tráng. Ôn cứu 3 – 5 phút.[\n2È"}]},{"id":722,"ten":"Tất Ngấn","sections":[{"h":"VỊ TRÍ","body":"Tại phía trong và ngoài chỗ lõm của đầu gối, sát bên ngoài huyệt Tất nhãn."},{"h":"CHỦ TRỊ","body":"Trị đầu gối sưng đau, chân không co duỗi được, đi bộ khó."},{"h":"CHÂM CỨU","body":"Châm xiên, sâu 0,5 thốn. Cứu 3 tráng."}]},{"id":723,"ten":"Tất Ngoại","sections":[{"h":"VỊ TRÍ","body":"Tại cuối bên ngoài lằn nếp kheo chân, sát phía trước huyệt Ủy Dương (Bq 39)"},{"h":"CHỦ TRỊ","body":"Trị khớp gối đau, chi dưới bị lở loét."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1–1,5 thốn.M\n'à"}]},{"id":724,"ten":"Tất Nhãn","sections":[{"h":"VỊ TRÍ","body":"Tại 2 chỗ lõm 2 bên đầu gối."},{"h":"CHỦ TRỊ","body":"Trị đầu gối đau, cước khí, bắp chân sưng đau, liệt chi dưới."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn hoặc châm xiên Nội sang Ngoại Tất Nhãn."}]},{"id":725,"ten":"Tất Quan","sections":[{"h":"VỊ TRÍ","body":"Ở bờ sau dưới lồi cầu trong xương chầy, cách sau huyệt Âm Lăng Tuyền (Ty 9) một thốn."},{"h":"CHỦ TRỊ","body":"Trị khớp gối đau."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là phần trên cơ sinh đôi trong, cơ kheo, chỗ bám của gân cơ bán mạc vào mặt sau xương chầy.\nThần kinh vận động cơ là nhánh của dây thần kinh chầy sau và nhánh của dây thần kinh hông.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L3."}]},{"id":726,"ten":"Tất Thượng","sections":[{"h":"VỊ TRÍ","body":"Xác định đỉnh cao của xương bánh chè, huyệt ở trên bờ xương, trên dây chằng bánh chè."},{"h":"CHỦ TRỊ","body":"Trị khớp gối viêm, khớp gối đau nhức."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút."}]},{"id":727,"ten":"Tất Thượng Nhị Huyệt","sections":[{"h":"VỊ TRÍ","body":"Tại chỗ lõm trên hai bên xương đầu gối."},{"h":"CHỦ TRỊ","body":"Trị khớp gối viêm, khớp gối đau nhức."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 0,8 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút."}]},{"id":728,"ten":"Tề Hạ Lục Nhất","sections":[{"h":"VỊ TRÍ","body":"Dưới rốn 6 thốn rồi đo ra mỗi bên 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị bụng dưới đau."},{"h":"CHÂM CỨU","body":"Cứu 10 – 15 phút."}]},{"id":729,"ten":"Tề Thượng Hạ","sections":[{"h":"VỊ TRÍ","body":"Rốn đo lên và xuống 0,5 thốn, gồm 2 huyệt."},{"h":"CHỦ TRỊ","body":"Trị trẻ nhỏ não bị lõm xuống, hõm đầu không khít, bụng trướng, ruột sôi kêu, thủy thũng, sán khí, hạ lỵ, ruột viêm."},{"h":"CHÂM CỨU","body":"Châm 0,5 –1 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 15 phút."}]},{"id":730,"ten":"Tề Trung Tứ Biên","sections":[{"h":"VỊ TRÍ","body":"Lỗ rốn đo lên, xuống, bên phải, bên trái cách đều 1 thốn. Gồm 4 huyệt."},{"h":"CHỦ TRỊ","body":"Trị trường vị viêm cấp và mạn tính, dạ dày co thắt, phù thũng, tiêu hóa kém."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút hoặc cứu cách muối.G\nMW"}]},{"id":731,"ten":"Thạch Môn","sections":[{"h":"VỊ TRÍ","body":"Dưới rốn 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị bụng dưới quặn đau, tiêu chảy, tiểu đục, tiểu khó, băng huyết, rong huyết, kinh bế, ăn không tiêu, phù thũng."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1,5 thốn. Cứu 20 – 40 phút."},{"h":"GIẢI PHẪU","body":"Huyệt ở trên đường trắng. Sau đường trắng là mạc ngang, phúc mạc, vào sâu có ruột non khi không bí tiểu tiện hoặc không có thai. có bàng quang khi bí tiểu tiện vừa, có tử cung khi có thai trên 3 tháng.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D11.\nHuyệt ở bên PHẢI gọi là Hữu Quan, bên TRÁI gọi là Tả Quan."}]},{"id":732,"ten":"Thạch Quan","sections":[{"h":"VỊ TRÍ","body":"Rốn đo thẳng lên 3 thốn (huyệt Kiến Lý – Nh.11), đo ra ngang 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị dạ dày đau, thực đạo co thắt, táo bón, nấc cụt."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 5 – 7 tráng. Ôn cứu 10 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ chéo to của bụng, bờ trong cơ thẳng to, mạc ngang, phúc mạc, đại trường ngang.\nThần kinh vận động cơ là 6 nhánh thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D8."}]},{"id":733,"ten":"Thái Âm","sections":[{"h":"VỊ TRÍ","body":"Đỉnh mắt cá chân trong đo lên 8 thốn, huyệt ở dưới chỗ lõm."},{"h":"CHỦ TRỊ","body":"Trị cước khí."},{"h":"CHÂM CỨU","body":"Cứu 3 – 7 tráng."}]},{"id":734,"ten":"Thái Âm Kiều","sections":[{"h":"VỊ TRÍ","body":"Tại chỗ lõm ở bờ dưới mắt cá chân trong."},{"h":"CHỦ TRỊ","body":"Trị kinh nguyệt không đều, tử cung xuất huyết chức năng, tử cung sa, phụ nữ không có thai."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn."}]},{"id":735,"ten":"Thái Ất","sections":[{"h":"VỊ TRÍ","body":"Rốn lên 2 thốn (huyệt Hạ Quản – Nh.10), đo ngang ra 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị dạ dầy đau, thoát vị ruột, tâm thần phân liệt, tiểu nhiều."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ chéo to, cơ thẳng to, mạc ngang, phúc mạc, trong ổ bụng là ruột non.\nThần kinh vận động cơ là 6 dây thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D9."}]},{"id":736,"ten":"Thái Bạch","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm phía sau dưới đầu xương bàn chân thứ 1, nằm trên đường tiếp giáp lằn da gan chân – mu chân ở bờ trong bàn chân."},{"h":"CHỦ TRỊ","body":"Trị khớp chân ngón cái sưng đau, dạ dày đau, bụng trướng, táo bón, nôn mửa, tiêu chảy, phù thũng."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ dạng ngón chân cái và cơ gấp ngắn ngón cái, gân cơ gấp dài ngón chân cái, mặt dưới đùng trước xương bàn chân 1.\nThần kinh vận động cơ là các nhánh của dây chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5.\nNếu ngộ châm gây ra nôn mửa, tiêu chảy, mạch nhảy loạn nhịp, dùng huyệt Túc Tam Lý (Vi.36) hoặc Tam Âm Giao (Ty 6) để giải cứu. Châm 2 huyệt giải này cần vê kim nhiều lần để gây đắc khí, đồng thời lay động, kích thích cán kim khoảng 20 phút là được (Danh Từ Huyệt Vị Châm Cứu)"}]},{"id":737,"ten":"Thái Dương","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm phía sau lông mày nơi có đường mạch xanh của Thái dương. Hoặc phía sau điểm giữa đoạn nối đuôi lông mày và đuôi mắt ước 1 tấc, nơi chỗ hõm sát cạnh ngoài mỏm ổ mắt xương gò má đè vào có cảm giác ê tức có khi thấy rõ mạch máu nổi lên."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, nửa đầu đau, cảm mạo, liệt mặt, bệnh mắt, thần kinh sinh ba đau."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn, tại chỗ có cảm giác căng tức.\nTrị Thiên đầu thống có thể châm ngang, luồn mũi kim ra đến huyệt Suất Cốc dài 1 – 2 thốn, khi châm có cảm giác căng tức lan đến 2 mang tai.\nTrị liệt dây thần kinh 7 (liệt mặt) có thể hướng mũi kim xuống huyệt Giáp Xa (Vi 6), sâu chừng 3 thốn, có cảm giác căng tức có khi lan tới vùng lưỡi.\nKhi điều trị viêm kết mạc cấp tính hoặc nhức đầu có thể châm nặn ra một ít máu."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là cân và cơ thái dương, xương thái dương.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số V.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V."}]},{"id":738,"ten":"Thái Khê","sections":[{"h":"VỊ TRÍ","body":"Tại trung điểm giữa đường nối bờ sau mắt cá trong và mép trong gân gót, khe giữa gân gót chân ở phía sau."},{"h":"CHỦ TRỊ","body":"Trị răng đau, họng đau, chi dưới liệt, kinh nguyệt rối loạn, Bàng quang viêm, Thận viêm, tiểu dầm, di tinh."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn hoặc có thể thấu tới Côn Lôn (Bq 60).\nKhi trị bệnh ở gót chân thì hướng mũi kim xuống.\nCứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa gân gót chân ở sau, gân cơ gấp dài ngón chân cái, gân cơ gấp chung các ngón chân và gân cơ cẳng chân sau, ở trước mặt trong–sau đầu dưới xương chầy.\nThần kinh vận động cơ là các nhánh của dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5."}]},{"id":739,"ten":"Thái Uyên","sections":[{"h":"VỊ TRÍ","body":"Trên lằn chỉ ngang cổ tay, nơi chỗ lõm trên động mạch tay quay, dưới huyệt là rãnh mạch tay quay."},{"h":"CHỦ TRỊ","body":"Trị ngực đau, lưng và vai đau, quanh khớp cổ tay đau, ho suyễn."},{"h":"CHÂM CỨU","body":"Châm thẳng, từ mặt trong lòng bàn tay, hướng mũi kim tới mặt phía lưng bàn tay, sâu 0,3 – 0,5 thốn, Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là rãnh mạch quay. Rãnh ở đoạn này cấu tạo bởi gân cơ dạng dài và gân cơ duỗi ngắn ngón tay cái (ở ngoài). Gân cơ gang tay to và gân cơ gấp chung nông các ngón tay (ở trong). Gân cơ gấp dài ngón tay cái và xương thuyền (ở đáy).\nThần kinh vận động cơ là các nhánh của dây thần kinh giữa và dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C6."}]},{"id":740,"ten":"Thái Xung","sections":[{"h":"VỊ TRÍ","body":"Sau khe giữa ngón chân 1 và 2, đo lên 1,5 thốn, huyệt ở chỗ lõm tạo nên bởi hai đầu xương ngón chân 1 và 2. Hoặc sờ dọc theo khoảng gian đốt xương bàn chân 1, tìm xác định góc tạo nên bởi 2 đầu xương bàn chân 1 và 2, lấy huyệt ở góc này."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, chóng mặt, động kinh, đau do thoát vị, băng lậu, tuyến vú viêm, các bệnh về mặt, phù thũng."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5–1 thốn, có thể châm thấu Dũng Tuyền (Th.1). Cứu 3–5 tráng, ôn cứu 5–10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là gân cơ duỗi dài riêng ngón cái, cơ duỗi ngắn các ngón chân, cơ gian cốt mu chân, khe giữa các đầu sau của các xương bàn chân 1 và 2.\nThần kinh vận động cơ là các nhánh của dây thần kinh chày trước và nhánh của dây thần kinh chày sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5."}]},{"id":741,"ten":"Thanh Lãnh Uyên","sections":[{"h":"VỊ TRÍ","body":"Co khuỷu tay lại, huyệt ở trên khớp khuỷu tay 2 thốn, trên huyệt Thiên Tỉnh (Ttu 10) 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị vai và cánh tay đau, bệnh về mắt."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,8 – 1,2 thốn. Cứu 3– 7 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là gân cơ 3 đầu cánh tay, đầu dưới xương cánh tay.\nThần kinh vận động cơ là các nhánh của dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D6."}]},{"id":742,"ten":"Thanh Linh","sections":[{"h":"VỊ TRÍ","body":"Ở phía trên đầu nếp gấp khuỷu tay 3 thốn, ở rãnh giữa cơ nhị đầu cánh tay, cơ cánh tay trước."},{"h":"CHỦ TRỊ","body":"Trị vùng hông sườn đau, vai và cánh tay đau."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là rãnh cơ 2 đầu trong, cơ cánh tay trước, vách lên cơ trong, cơ rộng trong, xương cánh tay.\nThần kinh vận động cơ là các nhánh của dây thần kinh cơ – da và nhánh của dây quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D2."}]},{"id":743,"ten":"Thành Cốt","sections":[{"h":"VỊ TRÍ","body":"Phía ngoài khớp gối, điểm cao nhất của đỉnh trên khớp xương đùi phía ngoài."},{"h":"CHỦ TRỊ","body":"Trị thắt lưng đau, khớp gối viêm."},{"h":"CHÂM CỨU","body":"Châm nông hoặc châm nặn ra máu."}]},{"id":744,"ten":"Thân Bát Tà","sections":[{"h":"VỊ TRÍ","body":"Gồm 4 huyệt: Khúc Trạch (Tb.3) + Kiên Tỉnh (Đ.21) + Phế Du (Bq 13) + Phong Môn (Bq 12)"},{"h":"CHỦ TRỊ","body":"Trị các khớp xương đau nhức."},{"h":"CHÂM CỨU","body":"Xem từng huyệt."}]},{"id":745,"ten":"Thân Giao","sections":[{"h":"VỊ TRÍ","body":"Thẳng rốn xuống chạm vào đường nếp ngang trên mu."},{"h":"CHỦ TRỊ","body":"Trị tử cung sa, tiểu bí, tiểu gắt, táo bón."},{"h":"CHÂM CỨU","body":"Cứu."}]},{"id":746,"ten":"Thân Mạch","sections":[{"h":"VỊ TRÍ","body":"Nơi rãnh thẳng từ đầu nhọn mắt cá ngoài xuống 0,5 thốn (gấp duỗi bàn chân để tìm gân cơ)"},{"h":"CHỦ TRỊ","body":"Trị đầu đau, chóng mặt, khớp mắt cá viêm, động kinh."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là gân cơ mác bên dài và gân cơ mác bên ngắn, chỗ bám của cơ duỗi ngắn các ngón chân, rãnh cơ mác của mặt ngoài xương gót chân.\nThần kinh vận động cơ là các nhánh của dây thần kinh cơ – da và dây thần kinh chầy trước.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S1."}]},{"id":747,"ten":"Thân Trụ","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm dưới đầu mỏm gai đốt sống lưng 3."},{"h":"CHỦ TRỊ","body":"Trị lưng cứng đau, sợ hãi, hồi hộp, hay quên, ho, trẻ nhỏ co giật, sốt kèm sợ lạnh, uốn ván, chắp lẹo."},{"h":"CHÂM CỨU","body":"Châm chếch lên, luồn dưới mỏm gai, hướng vào khoảng gian đốt sống lưng 3–4, sâu 0,3–1 thốn. Cứu 10–15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là gân cơ thang, gân cơ trám (hoặc cơ thoi), cơ gối cổ, cơ gai dài của lưng, cơ ngang – gai, dây chằng trên gai, dây chằng gian gai, dây chằng vàng, ống sống .\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số XI, nhánh của đám rối cổ, các nhánh 2 thần kinh sống.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D3."}]},{"id":748,"ten":"Thần Đạo","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm dưới đầu mỏm gai đốt sống lưng 5."},{"h":"CHỦ TRỊ","body":"Trị lưng đau cứng, sợ hãi, hồi hộp, hay quên, ho, trẻ hay co giật, sốt kèm sợ lạnh."},{"h":"CHÂM CỨU","body":"Châm chếch lên, luồn dưới mỏm gai, hướng vào khoảng gian đốt sống lưng 5 – 6, sâu 0,3 – 1 thốn. Cứu 10 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là gân cơ thang, cơ gai dài của lưng, cơ ngang gai, dây chằng trên gai, dây chằng gian gai, dây chằng vàng, ống sống.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số XI, nhánh đám rối cổ sâu và các nhánh của dây thần kinh sống.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh"}]},{"id":749,"ten":"Thần Đình","sections":[{"h":"VỊ TRÍ","body":"Ở sau chân tóc trán 0,5 thốn. Nơi người trán hói, lấy ở huyệt Ấn Đường thẳng lên 3,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, mũi nghẹt, mũi chảy máu, động kinh, tim đập hồi hộp, mắt đau đỏ, chảy nước mắt, mắt có màng."},{"h":"CHÂM CỨU","body":"Châm luồn kim dưới da, sâu 0,2 – 0,5 thốn. Cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân sọ dưới cân sọ là xương sọ.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V."}]},{"id":750,"ten":"Thần Đường","sections":[{"h":"VỊ TRÍ","body":"Dưới gai đốt sống lưng 5, đo ngang 3 thốn, cách huyệt Tâm Du (Bq 15) 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị các bệnh về tim, hen suyễn, khí quản viêm, vai lưng đau."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 0,8 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 –15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ thang, cơ trám, cơ chậu – sườn – ngực, cơ gian sườn 5, vào trong là phổi.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số XI, nhánh của đám rối cổ sâu, nhánh đám rối cánh tay, nhánh thần kinh sống lưng 5 và dây thần kinh gian sườn 5.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D5."}]},{"id":751,"ten":"Thần Giác","sections":[{"h":"VỊ TRÍ","body":"Chéo tay qua vai phía đối diện, bắp tay chạm vào cằm, đầu ngón tay giữa chạm vào lưng ở đâu đó là huyệt."},{"h":"CHỦ TRỊ","body":"Trị mụn lẹo, mắt lẹo, vai lưng đau."},{"h":"CHÂM CỨU","body":"Lể hoặc dùng kim tam lăng chích nặn ra máu."}]},{"id":752,"ten":"Thần Khuyết","sections":[{"h":"VỊ TRÍ","body":"Chính giữa lỗ rốn."},{"h":"CHỦ TRỊ","body":"Trị bụng và quanh rốn đau, bệnh hệ sinh dục ngoài, bệnh về kinh nguyệt, ruột viêm cấp và mạn, kích ngất vì ruột dính, trực trường sa, lỵ mạn tính, trúng phong thể thoát, tay chân lạnh toát, bất tỉnh, bệnh thuộc hư hàn, chân dương hư (cứu có tác dụng hồi dương)"},{"h":"CHÂM CỨU","body":"Cấm châm.\nThường cứu cách muối, cách gừng hoặc thuốc tán (đã chế sẵn) 20 – 200 phút. Trường hợp cần cấp cứu hồi dương thì cứu cho đến khi nào thấy chân tay ấm mới thôi."},{"h":"GIẢI PHẪU","body":"Huyệt ở trên đường trắng ở chỗ có thừng tĩnh mạch rốn và dây chằng treo gan (dây chằng liềm) dính ở trên. Thừng động mạch rốn và ống niệu rốn dính ở dưới. Giữa là túi Meckel. Vào sâu là phúc mạc, ruột non hoặc tử cung khi có thai 7 – 8 tháng.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh tiểu không châm sâu.\nTheo sách Châm Cứu Đại Thành: Phụ nữ không nên châm cứu huyệt này vì sợ cả đời không thể có thai (Thạch Môn châm cứu ưng tu nữ tử chung thân dựng bất thành)"}]},{"id":753,"ten":"Thần Lý","sections":[{"h":"VỊ TRÍ","body":"Lật môi xuống, huyệt ở giữa niêm mạc môi dưới."},{"h":"CHỦ TRỊ","body":"Trị hoàng đản, ôn dịch, cấm khẩu, miệng hôi, hàm sưng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,1 – 0,2 thốn hoặc dùng kim Tam lăng chích ra máu./\n;C"}]},{"id":754,"ten":"Thần Môn","sections":[{"h":"VỊ TRÍ","body":"Ở phía xương trụ, nằm trên lằn chỉ cổ tay, nơi chỗ lõm sát bờ ngoài gân cơ trụ trước và góc ngoài bờ trên xương trụ."},{"h":"CHỦ TRỊ","body":"Trị hay mơ, mất ngủ, hồi hộp, động kinh, Hysteria, hay quên."},{"h":"CHÂM CỨU","body":"Châm thẳng, hơi chếch qua phía xương trụ (ngón út), sâu 0,3 – 0,5 thốn. Cứu 1 – 3 tráng, Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là gân cơ trụ trước, xương đậu và xương tháp.\nThần kinh vận động cơ là nhánh của dây thần kinh trụ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D1."}]},{"id":755,"ten":"Thần Phong","sections":[{"h":"VỊ TRÍ","body":"Ở khoảng gian sườn 4, ngang huyệt Đản Trung (Nh 17), cách đường giữa ngực 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị thần kinh gian sườn đau, phế quản viêm."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ ngực to, các cơ gian sườn 4, cơ ngang ngực 4, sâu bên trong bên phải là phổi, bên trái là tim.\nThần kinh vận động cơ là dây thần kinh ngực to của đám rối thần kinh nách và dây thần kinh gian sườn 4.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D3 hoặc D4."}]},{"id":756,"ten":"Thần Phủ","sections":[{"h":"VỊ TRÍ","body":"Tại ngay chính giữa chấn thủy (Cưu Vĩ)"},{"h":"CHỦ TRỊ","body":"Trị tim đau."},{"h":"CHÂM CỨU","body":"Châm luồn kim dưới da, sâu 0,3 – 0,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút.(\n\nP"}]},{"id":757,"ten":"Thần Tàng","sections":[{"h":"VỊ TRÍ","body":"Ở khoảng gian sườn 2, cách đường giữa ngực 2 thốn, ngang huyệt Tử Cung (Nh 19)"},{"h":"CHỦ TRỊ","body":"Trị ho, nôn mửa, thần kinh gian sườn đau."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ ngực to, các cơ gian sườn 2, vào sâu hơn có phổi, bên trái có động mạch chủ, bên phải có tĩnh mạch chủ trên.\nThần kinh vận động cơ là dây ngực to của đám rối thần kinh nách và dây thần kinh gian sườn 2.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D2."}]},{"id":758,"ten":"Thần Thụ","sections":[{"h":"VỊ TRÍ","body":"Trên phía ngoài huyệt Dương Khê (Đtr.5) 1 ngang ngón tay."},{"h":"CHỦ TRỊ","body":"Trị răng đau."},{"h":"CHÂM CỨU","body":"Cứu.:\n2"}]},{"id":759,"ten":"Thận Du","sections":[{"h":"VỊ TRÍ","body":"Dưới gai sống thắt lưng 2, đo ngang ra 1,5 thốn, ngang huyệt Mệnh Môn (Đc 4)"},{"h":"CHỦ TRỊ","body":"Trị Thận viêm, tiểu dầm, thắt lưng đau, điếc, tai ù, tiêu chảy mạn tính, kinh nguyệt rối loạn, liệt dương, di mộng tinh."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Cứu 5–7 tráng. Ôn cứu 10 – 20 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân ngực – thắt lưng của cơ lưng to, cơ răng bé sau – dưới, cơ lưng dài, cơ ngang gai, cơ gian mỏm ngang, cơ vuông thắt lưng, cơ đái – chậu.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L1 hoặc L2."}]},{"id":760,"ten":"Thận Hệ","sections":[{"h":"VỊ TRÍ","body":"Lấy lòng bàn tay đặt vào đầu gối, úp bàn tay xuống đùi, ngón tay giữa chạm vào đùi ở đâu, đó là huyệt Phục Thố (Vi 32), rồi đo xuống 1 thốn là huyệt."},{"h":"CHỦ TRỊ","body":"Trị tiểu đường, chi dưới liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1,5 – 2 thốn."}]},{"id":761,"ten":"Thận Nhiệt Huyệt","sections":[{"h":"VỊ TRÍ","body":"Gai đốt sống lưng thứ 7 đo ra 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị đường tiểu bị viêm, thận viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn."}]},{"id":762,"ten":"Thận Tích","sections":[{"h":"VỊ TRÍ","body":"Dưới gai đốt sống thắt lưng thứ 2 đo ra 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị tủy sống viêm, dây chằng 2 bên dọc cột sống viêm, chi dưới liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1,5 – 2 thốn."}]},{"id":763,"ten":"Thập Tam Qủy Huyệt","sections":[{"h":"VỊ TRÍ","body":"Gồm 13 huyệt:\nTên huyệt\tQủy Danh\nẨn Bạch (Ty.1)\tQuỷ Lũy\nĐại Lăng (Tb.7)\tQuỷ Tâm\nGiáp Xa (Vi 6)\tQuỷ Sàng\nHải Tuyền\tQuỷ Phong\nKhúc Trì (Đtr.11)\tQuỷ Cự\nLao Cung (Tb.8)\tQuỷ Quật\nNgọc Môn\tQuỷ Tàng\nNhân Trung (Đc 26)\tQuỷ Cung\nPhong Phủ (Đc 16)\tQuỷ Chẩm\nThân Mạch (Bq 62)\tQuỷ Lộ\nThiếu Thương (P.11)\tQuỷ Tín\nThừa Tương (Nh 24)\tQuỷ Thị\nThượng Tinh (Đc 23)\tQuỷ Đường"},{"h":"CHỦ TRỊ","body":"Trị bệnh tâm thần, điên cuồng."},{"h":"CHÂM CỨU","body":"Xem từng huyệt."}]},{"id":764,"ten":"Thập Thất Chùy Hạ","sections":[{"h":"VỊ TRÍ","body":"Tại chỗ lõm dưới gai xương thắt lưng thứ 5."},{"h":"CHỦ TRỊ","body":"Trị lưng và lưng cùng đau, thần kinh tọa đau, rong huyết chức năng, thống kinh, bệnh ở hậu môn, liệt trẻ con, liệt do ngoại thương."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 1,5 – 2 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút.,\nE"}]},{"id":765,"ten":"Thập Tuyên","sections":[{"h":"VỊ TRÍ","body":"Ở đỉnh cao nhất giữa đầu 10 ngón tay."},{"h":"CHỦ TRỊ","body":"Trị sốt cao, kích ngất, hôn mê, say nắng, động kinh, Hysteria, đầu ngón tay tê."},{"h":"CHÂM CỨU","body":"Châm cạn, hoặc châm nặn ra tí máu.\nCấp cứu: châm cạn chừng 0,1 thốn, vê kim mạnh, rút kim.\nTrị họng viêm, amidal viêm cấp: có thể châm nặn ra máu."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là đầu đốt cuối của các xương ngón tay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C6, C7, C8 và D1."}]},{"id":766,"ten":"Thập Vương","sections":[{"h":"VỊ TRÍ","body":"Ở lưng 10 ngón tay, chính giữa bờ móng tay và vùng da chừng 0,1 thốn. Hai tay gồm 10 huyệt."},{"h":"CHỦ TRỊ","body":"Trị say nắng, cảm mạo, trường vị viêm cấp tính."},{"h":"CHÂM CỨU","body":"Châm nặn ra một ít máu."}]},{"id":767,"ten":"Thất Cảnh Chùy Bàng","sections":[{"h":"VỊ TRÍ","body":"Gai đốt xương sống thứ 6 đo ra mỗi bên 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị họng viêm, thanh quản viêm, amidal viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 1 thốn."}]},{"id":768,"ten":"Thất Miên","sections":[{"h":"VỊ TRÍ","body":"Dưới bàn chân, điểm giữa của vùng gót chân."},{"h":"CHỦ TRỊ","body":"Trị gót chân đau, mất ngủ."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn."}]},{"id":769,"ten":"Thỉ Tố","sections":[{"h":"VỊ TRÍ","body":"Tại giữa chỗ lõm của nách – sườn đo xuống 2 thốn, trên huyệt Uyên Dịch (Đ.22) 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị hông sườn đầy trướng, thần kinh gian sườn đau, lưng đau lan đến bụng."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,3 – 0,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 3 – 5 phút. V\nJq"}]},{"id":770,"ten":"Thiểm Điện","sections":[{"h":"VỊ TRÍ","body":"Chót xương cụt đo ngang ra mỗi bên 6 thốn."},{"h":"CHỦ TRỊ","body":"Trị đau thần kinh toạ, liệt chi dưới."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 3 – 4 thốn."}]},{"id":771,"ten":"Thiểm Yêu","sections":[{"h":"VỊ TRÍ","body":"Giữa điểm nối huyệt Khúc trì và Thủ tam lý, bờ ngoài xương quay đo ra 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị lưng bị chấn thương cấp."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 2 thốn.N\nv"}]},{"id":772,"ten":"Thiên Cù Bàng Huyệt","sections":[{"h":"VỊ TRÍ","body":"Huyệt Thiên Đột (Nh 22) đo ra 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị bướu cổ."},{"h":"CHÂM CỨU","body":""}]},{"id":773,"ten":"Thiên Dũ","sections":[{"h":"VỊ TRÍ","body":"Ở phía ngoài cổ, bờ sau và trong gai xương chũm, bờ sau cơ ức đòn chũm, nơi góc hàm dưới. Hoặc lấy nếp sau gáy làm chuẩn, huyệt ở 1/3 ngoài của đường nối huyệt Thiên Trụ (Bq 12) và Thiên Dung (Ttr."},{"h":"CHỦ TRỊ","body":"Trị cổ gáy cứng, tai điếc."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Cứu 1 – 3 tráng. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ sau cơ ức – đòn – chũm, cơ gối đầu, cơ đầu dài.\nThần kinh vận động cơ là nhánh của nhánh của đám rối cổ sâu, nhánh thần kinh chẩm lớn, nhánh thần kinh dưới chẩm.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C3."}]},{"id":774,"ten":"Thiên Dung","sections":[{"h":"VỊ TRÍ","body":"Ở phía sau góc xương hàm dưới, bờ trước cơ ức – đòn – chũm, phía dưới cơ hai thân."},{"h":"CHỦ TRỊ","body":"Trị tai ù, điếc, họng đau, amidal viêm, mất tiếng nói."},{"h":"CHÂM CỨU","body":"Châm thẳng, hướng mũi kim tới phía gốc (cuống) lưỡi, sâu 1 – 1,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ trước cơ ức – đòn – chũm, bờ sau của góc xương hàm dưới, phía dưới cơ 2 thân.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số XI, nhánh đám rối cổ sâu, dây thần kinh sọ não số XI.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C2 hoặc C3."}]},{"id":775,"ten":"Thiên Đỉnh","sections":[{"h":"VỊ TRÍ","body":"Nơi gặp nhau của bờ sau bó đòn cơ ức – đòn chũm và đường ngang qua giữa cổ, cách tuyến giáp 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị họng viêm, amidal viêm, lao hạch."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ bám da cổ, bờ sau cơ ức – đòn – chũm, các cơ bậc thang.\nThần kinh vận động cơ là dây thần kinh cơ da cổ, nhánh ngoài của dây thần kinh sọ não số XI, các nhánh của đám rối cổ sâu.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C3."}]},{"id":776,"ten":"Thiên Đột","sections":[{"h":"VỊ TRÍ","body":"Giữa chỗ lõm trên bờ trên xương ức."},{"h":"CHỦ TRỊ","body":"Trị họng đau, mất tiếng đột ngột, ợ, nấc, ho suyễn."},{"h":"CHÂM CỨU","body":"Châm kim qua da 0,2 – 0,5 thốn rồi hướng mũi kim theo mặt sau xương ức Cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Huyệt ở trước khí quản và thực quản, ở trong góc tạo nên bởi bờ trong của cơ ức – đòn – chũm, bờ trong của 2 cơ ức – đòn – móng và bờ trong của cơ ức – giáp trạng.\nThần kinh vận động cơ do các nhánh của dây thần kinh XI và XII.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh"}]},{"id":777,"ten":"Thiên Khê","sections":[{"h":"VỊ TRÍ","body":"Ở khoảng gian sườn 4, cách đường giữa bụng 6 thốn (ngang huyệt Đản Trung (Nh 17), từ đầu ngực đo ra 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị ho, ngực đau, thần kinh gian sườn đau, sữa thiếu."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ dưới cơ ngực to, phần gân cơ chéo to của bụng và cơ răng cưa to, các cơ gian sườn 5. Vào trong là phổi.\nThần kinh vận động cơ là dây thần kinh ngực to và dây thần kinh gian sườn 5.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D4.\nChâm huyệt này, nếu lỡ ngộ châm sinh ra hôn mê như chết, dùng huyệt Trường Cường (Đc 1) để giải: châm sâu 1,5 thốn, kích thích mạnh (Danh Từ Huyệt Vị Châm Cứu)"}]},{"id":778,"ten":"Thiên Lịch","sections":[{"h":"VỊ TRÍ","body":"Cách huyệt Dương Khê 3 thốn, trên đường nối huyệt Dương Khê (Đtr.5) và Khúc Trì (Đtr."},{"h":"CHỦ TRỊ","body":"Trị cẳng tay đau, cánh tay đau, amidal viêm, liệt mặt, chảy máu cam."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ duỗi ngắn ngón tay cái, cơ dạng dài ngón tay cái.\nThần kinh vận động cơ do các nhánh của dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C6."}]},{"id":779,"ten":"Thiên Liêu","sections":[{"h":"VỊ TRÍ","body":"Tại trung điểm của đoạn nối huyệt Đại Chùy (Đc 14) và bờ ngoài phía sau mỏm cùng vai, hoặc trung điểm của đoạn nối từ huyệt Kiên Tỉnh (Đ.21) và Khúc Viên (Ttr.13), nằm ở hố trên gai xương bả vai."},{"h":"CHỦ TRỊ","body":"Trị vai và khớp vai đau, cổ gáy nhức mỏi."},{"h":"CHÂM CỨU","body":"Châm thẳng, hơi hướng mũi kim tới vùng bả vai, sâu 0,5 – 0,8 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ thang, cơ trên sống và cơ góc.\nThần kinh vận động cơ là nhánh dây thần kinh sọ não số XI, nhánh đám rối cổ sâu, nhánh của dây thần kinh trên vai.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C4.\nKhông châm sâu."}]},{"id":780,"ten":"Thiên Linh","sections":[{"h":"VỊ TRÍ","body":"Cuối nếp nhăn của nách trước, đo lên 1 thốn rồi hướng vào phía trong chừng 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị bệnh tâm thần, vai và cánh tay đau."},{"h":"CHÂM CỨU","body":"Châm mũi kim hướng xiên ra ngoài sâu 2 – 3 thốn.U\n("}]},{"id":781,"ten":"Thiên Phủ","sections":[{"h":"VỊ TRÍ","body":"Ở bờ trong bắp cánh tay trong, dưới nếp nách trước 3 thốn nơi bờ ngoài cơ 2 đầu cánh tay, trên huyệt Xích Trạch 6 thốn."},{"h":"CHỦ TRỊ","body":"Trị suyễn, ho, chảy máu cam, cánh tay trong đau."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ ngoài cơ 2 đầu cánh tay, chỗ bám của cơ cánh tay trước và cơ Delta, xương cánh tay.\nThần kinh vận động cơ do các nhánh của dây thần kinh mũ và dây cơ – da.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C5."}]},{"id":782,"ten":"Thiên Song","sections":[{"h":"VỊ TRÍ","body":"Ở phía sau cơ ức – đòn – chũm, sau huyệt Phù Đột (Đtr.18) 0,5 thốn, cách củ hầu 3,5 thốn, ngang huyệt Liêm Tuyền (Nh 23)"},{"h":"CHỦ TRỊ","body":"Trị cổ gáy cứng, họng viêm, tai ù, điếc."},{"h":"CHÂM CỨU","body":"Châm thẳng, hướng mũi kim đến vùng gốc (cuống) lưỡi, sâu 0,5 – 1 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ sau cơ ức – đòn – chũm, cơ nâng vai và các cơ bậc thang.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số XI, các nhánh của đám rối cổ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh"}]},{"id":783,"ten":"Thiên Thính","sections":[{"h":"VỊ TRÍ","body":"Dưới huyệt An Miên 2 đo xuống 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị điếc."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1,5 thốn.(\ns"}]},{"id":784,"ten":"Thiên Thông","sections":[{"h":"VỊ TRÍ","body":"Dùng một sợi dây đo từ trên mũi đến chân tóc trán, xong lấy ½ dây đó đo từ trên chân tóc kéo lên đến điểm tận cùng của dây là huyệt. Cách đường chân tóc trước 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, gáy cứng, tai ù, điếc, cổ vẹo loa lịch [lao hạch]"},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 1 thốn. Cứu điếu ngải 3 – 5 phút."}]},{"id":785,"ten":"Thiên Tỉnh","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm trên đầu mỏm khuỷu xương trụ, trên khớp khuỷu một thốn, nơi gân cơ tam đầu cánh tay."},{"h":"CHỦ TRỊ","body":"Trị khớp khuỷu tay và tổ chức phầm mềm quanh khớp bị viêm, tim đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là gân cơ 3 đầu cánh tay, đầu dưới xương cánh tay.\nThần kinh vận động cơ là các nhánh của dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C6.\nKhông châm sâu vì có thể chạm phổi và tim."}]},{"id":786,"ten":"Thiên Tông","sections":[{"h":"VỊ TRÍ","body":"Dưới hố giữa xương gai bả vai hoặc kéo đường ngang qua mỏm gai đốt sống lưng 4 gặp chỗ kéo đường dầy nhất của gai sống vai."},{"h":"CHỦ TRỊ","body":"Trị bả vai đau, cánh tay đau."},{"h":"CHÂM CỨU","body":"Châm thẳng hoặc xiên ra 4 phía, sâu 0,5 – 1 thốn, Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là cơ dưới vai, xương bả vai.\nThần kinh vận động cơ là nhánh của dây trên vai. Da vùng huyệt chi phối bởi tiết đoạn thần kinh D2.\nKhông châm sâu vì có thể đụng phổi."}]},{"id":787,"ten":"Thiên Trì","sections":[{"h":"VỊ TRÍ","body":"Ngang đầu ngực, cách 1 thốn, ở khoảng gian sườn 4, dưới hố nách 3 thốn, giữa huyệt Thiên Khê (Ty.18) và huyệt Nhũ Trung (Vi 17)"},{"h":"CHỦ TRỊ","body":"Trị ngực đầy tức, vùng tim đau tức, lao hạch, vùng dưới nách đau."},{"h":"CHÂM CỨU","body":"Châm xiên, hướng mũi kim ra ngoài, sâu 0,3 – 0,5 thốn. Ôn cứu 5–10 phút."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là cơ ngực to, cơ ngực bé, cơ răng cưa to, cơ chéo to của bụng, các cơ gian sườn, phổi.\nThần kinh vận động cơ là các nhánh của đám rối thần kinh nách và dây thần kinh gian sườn 4.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D4."}]},{"id":788,"ten":"Thiên Trụ","sections":[{"h":"VỊ TRÍ","body":"Ở vùng gáy, dưới u lồi chẩm phía ngoài, ngang huyệt Á Môn (Đc 15) ra 1,3 thốn, ở bờ ngoài cơ thang."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ ngoài cơ thang, cơ bán gai của đầu, cơ thẳng sau nhỏ và to của đầu, cơ chéo dưới của đầu.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số XI, các nhánh của dây thần kinh chẩm lớn và đám rối cổ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C3."}]},{"id":789,"ten":"Thiên Tuyền","sections":[{"h":"VỊ TRÍ","body":"Dưới đầu nếp nách trước, cách 2 thốn, giữa 2 cơ phần ngắn và cơ phần dài của cơ nhị đầu cánh tay."},{"h":"CHỦ TRỊ","body":"Trị ngực đau, tim nhói đau, lưng đau, mặt trong cánh tay đau, ho."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5–1 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa phần dài và phần ngắn của cơ 2 đầu cánh tay, chỗ bám của cơ cánh tay trước, mặt trước xương cánh tay.\nThần kinh vận động cơ là các nhánh của dây thần kinh cơ – da.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D2."}]},{"id":790,"ten":"Thiên Xu","sections":[{"h":"VỊ TRÍ","body":"Từ rốn đo ngang ra 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị trường Vị viêm cấp và mạn tính, cơ bụng liệt, ký sinh trùng đường ruột, ruột thừa viêm, ruột tắc, tiêu chảy, kiết lỵ, táo bón."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1,5 thốn. Cứu 5 – 7 tráng. Ôn cứu 10 – 20 phút."}]},{"id":791,"ten":"Thiên Xung","sections":[{"h":"VỊ TRÍ","body":"Sau huyệt Suất Cốc 0,5 thốn, ở trên và sau tai, trong chân tóc 2 thốn, vùng cơ tai trên."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, động kinh, lợi răng sưng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Cứu 1 – 3 tráng. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ tai trên, xương thái dương.\nThần kinh vận động cơ là nhánh của dây thần kinh mặt.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C2.Ò\nY()"}]},{"id":792,"ten":"Thiệt Hạ","sections":[{"h":"VỊ TRÍ","body":"Ở cuối 2 bên rìa lưỡi."},{"h":"CHỦ TRỊ","body":"Trị hoàng đản."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,1 – 0,2 thốn."}]},{"id":793,"ten":"Thiệt Trụ","sections":[{"h":"VỊ TRÍ","body":"Đẩy lưỡi lên, huyệt ở trên nếp hãm lưỡi phía dưới lưỡi, huyệt nơi giao giới ngã tư."},{"h":"CHỦ TRỊ","body":"Trị lưỡi sưng, tiểu đường."},{"h":"CHÂM CỨU","body":"Châm nặn ra máu."}]},{"id":794,"ten":"Thiếu Dương Duy","sections":[{"h":"VỊ TRÍ","body":"Phía sau mắt cá trong đo lên một thốn. Giữa huyệt Thái Khê (Th.3) và Phục Lưu (Th."},{"h":"CHỦ TRỊ","body":"Trị cước khí, lở loét mạn tính ở chi dưới, chi dưới liệt."},{"h":"CHÂM CỨU","body":"Châm xiên, sâu 0,5 – 1 thốn.W\n:"}]},{"id":795,"ten":"Thiếu Hải","sections":[{"h":"VỊ TRÍ","body":"Co tay lại, huyệt nằm ở cuối đầu nếp gấp khuỷu tay, mặt trong cánh tay, cách mỏm trên lồi cầu trong 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị cánh tay và bàn tay tê, khớp khuỷu và tổ chức mềm quanh khớp khuỷu đau, thần kinh suy nhược, vùng trước tim đau."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là chỗ bám vào xương của khối cơ trên ròng rọc, mặt trước mỏm trên ròng rọc (hoặc mỏm trên lồi cầu trong), xương cánh tay, phía trong khớp khủy.\nThần kinh vận động cơ là các nhánh của dây thần kinh da cánh tay và dây thần kinh trụ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D1."}]},{"id":796,"ten":"Thiếu Phủ","sections":[{"h":"VỊ TRÍ","body":"Trong lòng bàn tay, giữa xương bàn tay thứ 4 và 5, huyệt nằm trên đường văn của lòng bàn tay."},{"h":"CHỦ TRỊ","body":"Trị lòng bàn tay nóng, hồi hộp, thấp tim, tiểu dầm, tiểu không thông, nhịp tim không đều."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn. Cứu 1 – 3 tráng, Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân gan tay giữa, cơ giun, bờ trong gân gấp ngón 4 của cơ gấp chung nông và sâu, cơ gian cốt gan tay và gian cốt mu tay, bờ trong đầu dưới xương bàn tay 4.\nThần kinh vận động cơ là các nhánh của dây thần kinh giữa và dây trụ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D1."}]},{"id":797,"ten":"Thiếu Thương","sections":[{"h":"VỊ TRÍ","body":"Tại bờ ngoài ngón tay cái, cách góc móng tay 0,1 thốn về phía tay quay. Hoặc huyệt nằm ở nơi gặp nhau tiếp giáp da gan – mu tay và đường ngang qua góc chân móng ngón tay cái."},{"h":"CHỦ TRỊ","body":"Trị sốt, amidal viêm, trúng gió, hôn mê, động kinh, khó thở."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,1 – 0,2 thốn hoặc châm xiên hoặc dùng kim tam lăng châm nặn ra máu."},{"h":"GIẢI PHẪU","body":"Dưới da là xương, huyệt ở dưới chỗ bám của gân cơ duỗi dài ngón tay cái. Thần kinh vận động cơ là nhánh của dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C6."}]},{"id":798,"ten":"Thiếu Trạch","sections":[{"h":"VỊ TRÍ","body":"Cạnh góc trong chân móng tay út cách 0,1 thốn trên đường tiếp giáp da gan tay – mu tay."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, mắt đau, tuyến vú viêm, sữa thiếu."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,1 – 0,2 thốn. Cứu 1 – 3 tráng, Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là giữa chỗ bám gân ngón 5 của cơ gấp chung sâu các ngón tay và gân ngón út của cơ duỗi chung các ngón tay, bờ trong của đốt 3 xương ngón tay 5.\nThần kinh vận động cơ là nhánh của dây thần kinh trụ và thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D1."}]},{"id":799,"ten":"Thiếu Xung","sections":[{"h":"VỊ TRÍ","body":"Ở ngón tay út phía tay quay, cách chân góc móng tay út 0,1 thốn, trên đường tiếp giáp da gan tay – mu tay."},{"h":"CHỦ TRỊ","body":"Trị hồi hộp, trúng phong hôn mê, sốt cao, động kinh."},{"h":"CHÂM CỨU","body":"Châm sâu 0,1 – 0,2 thốn. Cứu 2 – 3 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là giữa chỗ bám của gân ngón 5, cơ gấp chung sâu các ngón tay và gân ngón út, cơ duỗi chung các ngón tay, bờ ngoài của đốt 3 xương ngón tay út.\nThần kinh vận động cơ là nhánh của dây thần kinh trụ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D1.\nKhông châm sâu vì có thể đụng phổi."}]},{"id":800,"ten":"Thính Cung","sections":[{"h":"VỊ TRÍ","body":"Khi há miệng, huyệt ở chỗ lõm phía trước bình tai, sau lồi cầu xương hàm dưới."},{"h":"CHỦ TRỊ","body":"Trị tai ù, điếc, tai giữa viêm, tai ngoài viêm."},{"h":"CHÂM CỨU","body":"Hơi há miệng, châm thẳng, sâu 0,8 – 1,5 thốn. Cứu 1 – 3 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ sau tuyến mang tai, bờ sau lồi cầu xương hàm dưới.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh sọ não số V.\nPhế chủ, Đại Trường khách. Thái âm nhiều khí ít huyết, ngực tức, lòng bàn tay nóng, ho suyễn, vùng Khuyết Bồn khó chịu, họng khô, đổ mồ hôi, phía trước vai và 2 vú đau, đờm kết ở ngực, hụt hơi, sở sinh bệnh tìm huyệt gì? Bảo rằng Thái Uyên + Thiên Lịch” (Thập Nhị Kinh Chứng Trị Chủ Khách Nguyên Lạc)"}]},{"id":801,"ten":"Thính Hội","sections":[{"h":"VỊ TRÍ","body":"Phía trước rãnh bình tai, ở chỗ lõm khi há miệng, bờ sau tuyến mang tai, dưới huyệt Thính Cung (Ttr."},{"h":"CHỦ TRỊ","body":"Trị tai ù, điếc, tai giữa viêm, liệt mặt, khớp hàm dưới viêm."},{"h":"CHÂM CỨU","body":"Hơi há miệng, châm thẳng, mũi kim hơi hướng xuống dưới, sâu 0,5 – 1 thốn. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ sau tuyến mang tai, bờ dưới mỏm tiếp xương thái dương, sau lồi cầu xương hàm dưới.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V.\nHàn nhiệt không ra mồ hôi, trong ngực đầy tức, nóng nảy, chọn huyệt Thiên Liêu làm chủ” (Giáp Ất Kinh)"}]},{"id":802,"ten":"Thốn Bình","sections":[{"h":"VỊ TRÍ","body":"Ở lưng bàn tay, chính giữa nếp chỉ tay đo lên 1 thốn, rồi đo ngang ra phía tay quay 0,4 thốn."},{"h":"CHỦ TRỊ","body":"Trị tim suy, kích ngất."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn."}]},{"id":803,"ten":"Thốn Nhiêu","sections":[{"h":"VỊ TRÍ","body":"Mặt ngoài cẳng tay, từ lằn chỉ cổ tay đo lên cẳng tay 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị điên cuồng."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 2,5 thốn."}]},{"id":804,"ten":"Thông Cốc","sections":[{"h":"VỊ TRÍ","body":"Rốn đo lên 5 thốn (huyệt Thượng Quản (Nh 13) ra ngang 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị nôn mửa, tiêu chảy, bụng đau, thần kinh liên sườn đau, hồi hộp."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 10 – 20 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ chéo to của bụng, bờ trong cơ thẳng to, mạc ngang, phúc mạc, dạ dày.\nThần kinh vận động cơ là 6 nhánh dây thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D7.\nCấm cứu (Giáp Ất Kinh)"}]},{"id":805,"ten":"Túc Thông Cốc","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm phía trước khớp xương bàn và ngón chân 5, bờ ngoài bàn chân, nơi tiếp giáp lằn da gan chân – mu chân."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, chóng mặt, động kinh, tiêu hóa kém."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là chỗ bám của gân cơ dạng ngón chân thứ 5, đầu sau đốt thứ nhất xương ngón chân thứ 5.\nThần kinh vận động cơ là các nhánh của dây thần kinh chày sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S1."}]},{"id":806,"ten":"Thông Cốc III","sections":[{"h":"VỊ TRÍ","body":"Giữa đầu núm vú xuống 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị tim đau đột ngột, sườn trên đau."}]},{"id":807,"ten":"Thông Lý","sections":[{"h":"VỊ TRÍ","body":"Mặt trước trong cẳng tay, trên nếp gấp cổ tay 1 thốn (huyệt Thần Môn – Tm.7), khe giữa gân cơ trụ trước và cơ gấp chung nông các ngón tay."},{"h":"CHỦ TRỊ","body":"Trị khớp cổ tay và cánh tay đau, hồi hộp, mất ngủ, lưỡi co cứng, mất tiếng nói đột ngột, nhịp tim chậm, tâm thần phân liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 0,8 thốn. Cứu 1 – 3 tráng, Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa gân cơ trụ trước và gân cơ gấp chung sâu các ngón tay, cơ gấp vuông, xương trụ.\nThần kinh vận động cơ là các nhánh của dây thần kinh giữa và dây trụ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D1."}]},{"id":808,"ten":"Thông Lý II","sections":[{"h":"VỊ TRÍ","body":"Khe ngón chân út đo lên phía mu bàn chân 1 thốn, sát khe xương ngón út, gần huyệt Địa ngũ hội."},{"h":"CHỦ TRỊ","body":"Trị bạch đái, kinh nguyệt ra nhiều."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,2 thốn. Cứu 7 tráng."}]},{"id":809,"ten":"Thông Thiên","sections":[{"h":"VỊ TRÍ","body":"Ngay sau huyệt Thừa Quang (Bq 6) 1,5 thốn, hoặc huyệt Bá Hội (Đc 20) ra ngang 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị thiên đầu thống, mũi viêm."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn. Cứu 1 – 3 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân sọ, xương sọ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C2."}]},{"id":810,"ten":"Thông Thiên Châm","sections":[{"h":"VỊ TRÍ","body":"Các huyệt Thần đình, Thượng tinh, Tín hội, Tiền đỉnh, Bá hội của mạch Đốc làm thành một nhóm huyệt."},{"h":"CHỦ TRỊ","body":"Trị cảm, đầu đau, chóng mặt, váng đầu, chóng mặt do rối loạn tiền đình, suy nhược thần kinh, hysteria, động kinh, bệnh tâm thần, xuất huyết não, nghẽn mạch máu não, rối loạn nhịp tim, táo bón, sa trực trường, sa tử cung."},{"h":"CHÂM CỨU","body":"Châm huyệt Thần đình luồn dưới da đến qua Bá hội một ít là được."}]},{"id":811,"ten":"Thông Thiên Châm Đối Phong Thích","sections":[{"h":"VỊ TRÍ","body":"Từ huyệt thượng tinh đến Bá hội là một huyệt, từ huyệt Cường gian đến Bá hội là một huyệt. Hai huyệt này hợp lại thành một nhóm huyệt."},{"h":"CHỦ TRỊ","body":"Trị đầu đau kinh niên."},{"h":"CHÂM CỨU","body":"Châm huyệt Thượng tinh, luồn dưới da lên đến Bá hội. Từ Cường gian cũng châm luồn kim đến Bá hội."}]},{"id":812,"ten":"Thốt Điên","sections":[{"h":"VỊ TRÍ","body":"Tại chỗ lõm dưới gốc của âm hành."},{"h":"CHỦ TRỊ","body":"Trị tự nhiên bị điên."},{"h":"CHÂM CỨU","body":"Cứu."}]},{"id":813,"ten":"Thốt Phúc Thống Điểm","sections":[{"h":"VỊ TRÍ","body":"Bốn chung quanh rốn, cách rốn 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị bụng đau cấp."},{"h":"CHÂM CỨU","body":"Cứu 3 tráng."}]},{"id":814,"ten":"Thủ Chưởng Hậu Bạch Nhục Tế Huyệt","sections":[{"h":"VỊ TRÍ","body":"Tại phía sau, mặt ngoài lằn chỉ cổ tay, giữa ranh giới thịt trắng."},{"h":"CHỦ TRỊ","body":"Trị hoắc loạn chuyển gân."},{"h":"CHÂM CỨU","body":"Cứu 3 – 5 tráng, ôn cứu 5 – 15 phút."}]},{"id":815,"ten":"Thủ Chưởng Hậu Tý Gian Huyệt","sections":[{"h":"VỊ TRÍ","body":"Tại mặt trước tay, trên lằn chỉ cổ tay 5 thốn. Duỗi bàn tay ra sẽ hiện lên chỗ lõm ở cánh tay."},{"h":"CHỦ TRỊ","body":"Trị đinh nhọt, mụn nhọt."}]},{"id":816,"ten":"Thủ Đại Chỉ Giáp Hậu","sections":[{"h":"VỊ TRÍ","body":"Nắm tay lại, huyệt ở đầu góc trong ngón tay cái, tại khớp xương lóng bàn tay."},{"h":"CHỦ TRỊ","body":"Trị quáng gà."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,1 – 0,2 thốn. Hoặc dùng kim tam lăng châm nặn ra ít máu. Cứu 3 – 5 tráng hoặc ôn cứu 5 – 10 phút.N\nt"}]},{"id":817,"ten":"Thủ Khỏa Cốt","sections":[{"h":"VỊ TRÍ","body":"Mu tay, tại bên ngoài điểm cao nhất của khớp cổ tay."},{"h":"CHỦ TRỊ","body":"Trị răng hàm trên và dưới đau, 10 đầu ngón tay co rút."},{"h":"CHÂM CỨU","body":"Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút.\n5\n7:"}]},{"id":818,"ten":"Thủ Kim Môn","sections":[{"h":"VỊ TRÍ","body":"Từ nếp chỉ cổ tay phía lòng bàn tay, chính giữa nếp chỉ đo lên 3,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị lao hạch cổ."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn.I\nK"}]},{"id":819,"ten":"Thủ Nghịch Chú","sections":[{"h":"VỊ TRÍ","body":"Cổ tay trong đo lên 6 thốn."},{"h":"CHỦ TRỊ","body":"Trị điên cuồng, cười, khóc, hysteria, mặt trước cánh tay đau."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút."}]},{"id":820,"ten":"Thủ Ngũ Lý","sections":[{"h":"VỊ TRÍ","body":"Huyệt ở sát bờ xương cánh tay, trên nếp gấp khuỷu (Khúc Trì – Đtr.11), 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị khuỷu tay đau, cánh tay đau, lao hạch cổ, phúc mạc viêm, phổi viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 2 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là phần rộng ngoài của cơ 3 đầu cánh tay, vách liên cơ ngoài.\nThần kinh vận động cơ là nhánh của dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C5."}]},{"id":821,"ten":"Thủ Tam Lý","sections":[{"h":"VỊ TRÍ","body":"Dưới huyệt Khúc Trì (Đtr.11) 2 thốn, trên đường nối Khúc Trì (Đtr.11) và Dương Khê (Đtr."},{"h":"CHỦ TRỊ","body":"Trị vai và cánh tay đau, chi trên liệt, dạ dầy viêm loét, liệt nửa người."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,8 – 2 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 20 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ sau cơ ngửa dài, cơ ngửa ngắn và xương quay.\nThần kinh vận động cơ là các nhánh của dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C6."}]},{"id":822,"ten":"Thủ Tam Quan","sections":[{"h":"VỊ TRÍ","body":"Mu bàn tay, gồm 3 huyệt cổ tay:\nTrung quan: Giữa lằn chỉ cổ tay đo lên 1 thốn (dưới huyệt Ngoại quan 1 thốn).\nXích quan: huyệt Trung quan đo ngang về phía ngón tay cái (xương quay) 1 khoát ngón tay.\nNhiêu quan: huyệt Trung quan đo ngang về phía ngón út (xương trụ) 1 khoát ngón tay."},{"h":"CHỦ TRỊ","body":"Trị cổ tay đau."},{"h":"CHÂM CỨU","body":"Cứu 3 – 7 tráng.0BMG\ng"}]},{"id":823,"ten":"Thủ Tâm","sections":[{"h":"VỊ TRÍ","body":"Tại giữa lòng bàn tay, thẳng huyệt Đại Lăng (Tb.7) xuống."},{"h":"CHỦ TRỊ","body":"Trị điên cuồng, động kinh."},{"h":"CHÂM CỨU","body":"Cứu."}]},{"id":824,"ten":"Thủ Thái Dương Huyệt","sections":[{"h":"VỊ TRÍ","body":"Tại sau đỉnh bờ ngoài ngón tay út 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị mũi nghẹt."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,1 – 0,3 thốn."}]},{"id":825,"ten":"Thủ Trung Bình","sections":[{"h":"VỊ TRÍ","body":"Mặt trong bàn tay, huyệt ở ngón giữa, ngay giữa lằn chỉ tay của ngón và bàn."},{"h":"CHỦ TRỊ","body":"Trị xoang miệng viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,2 – 0,3 thốn."}]},{"id":826,"ten":"Thủ Túc Tủy Khổng","sections":[{"h":"VỊ TRÍ","body":"Gồm hai huyệt là huyệt Uyển Cốt (Ttr 4) ở cổ tay và huyệt Côn Lôn (Bq 60) ở gót chân."},{"h":"CHỦ TRỊ","body":"Trị liệt nửa người, mông đau, đùi đau."},{"h":"CHÂM CỨU","body":"Cứu 100 tráng.0V\n'."}]},{"id":827,"ten":"Thủ Tủy Huyệt","sections":[{"h":"VỊ TRÍ","body":"Tại giữa phía sau đỉnh xương cổ tay."},{"h":"CHỦ TRỊ","body":"Trị liệt nửa người."},{"h":"CHÂM CỨU","body":"Cứu."}]},{"id":828,"ten":"Thủ Tứ Huyệt","sections":[{"h":"VỊ TRÍ","body":"Tại đầu ngón tay cái, đầu móng ngón tay giữa (phía tay quay), cách móng tay khoảng 1 thốn, mỗi tay 2 huyệt."},{"h":"CHỦ TRỊ","body":"Trị trường vị viêm cấp, kiết lỵ."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,1 – 0,2 thốn hoặc chích nặn ra máu."}]},{"id":829,"ten":"Thúc Cốt","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm phía sau đầu nhỏ của xương bàn chân 5, nơi tiếp giáp da gan chân – mu chân."},{"h":"CHỦ TRỊ","body":"Đầu đau, chóng mặt, phía ngoài bàn chân đau, động kinh."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ dạng ngón chân thứ 5, đầu trước xương bàn chân 5.\nThần kinh vận động cơ là nhánh của dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S1. phận sinh dục tự nhiên đau, tiểu dầm chọn Thiếu Phủ (Tm.8), thoái vị bẹn: chọn Thiếu Phủ” (Thần Cứu Kinh Luân)"}]},{"id":830,"ten":"Thủy Đạo","sections":[{"h":"VỊ TRÍ","body":"Rốn xuống 3 thốn (huyệt Quan Nguyên – Nh.4), đo ngang ra 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị bàng quang viêm, dịch hoàn viêm, thận viêm, tiểu bí, phù nề."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 5 – 7 tráng. Ôn cứu 10 – 20 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ chéo to, cơ thẳng to, mạc ngang, phúc mạc. Trong ổ bụng là ruột non và tử cung khi có thai 4 – 6 tháng, bàng quang khi bị bí tiểu.\nThần kinh vận động cơ là 6 dây thần kinh gian sườn cùng và dây thần kinh bụng – sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D12."}]},{"id":831,"ten":"Thủy Đột","sections":[{"h":"VỊ TRÍ","body":"Tại bờ trước cơ ức – đòn – chũm, giữa huyệt Nhân Nghênh (Vi.9) và Khí Xá (Vi.11), dưới sụn giáp trạng."},{"h":"CHỦ TRỊ","body":"Trị họng đau, hen suyễn."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 1 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ trước cơ ức – đòn – chũm, khe giữa các cơ va – móng, ức – móng, ức giáp, vào sâu có bó mạch thần kinh cảnh, cơ cổ dài, cơ bậc thang trước.\nThần kinh vận động cơ là các nhánh của dây thần kinh sọ não số XI và số XII, các nhánh của đám rối thần kinh cổ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C3."}]},{"id":832,"ten":"Thủy Phân","sections":[{"h":"VỊ TRÍ","body":"Lỗ rốn thẳng lên 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị bụng sôi, bụng và quanh rốn đau, phù thũng, cổ trướng."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 1,5 thốn. Cứu trên 20 phút."},{"h":"GIẢI PHẪU","body":"Huyệt ở trên đường trắng. Sau đường trắng là mạc ngang, phúc mạc, vào sâu là tụy tạng và tá tràng hoặc tử cung khi có thai 8 – 9 tháng.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D10."}]},{"id":833,"ten":"Thủy Tuyền","sections":[{"h":"VỊ TRÍ","body":"Thẳng dưới huyệt Thái Khê (Th.3) 1 thốn, trên xương gót chân, bờ sau gân gấp dài ngón chân cái."},{"h":"CHỦ TRỊ","body":"Trị kinh nguyệt rối loạn, tử cung sa, tiểu khó, cận thị, gót chân đau, thống kinh."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ sau gân gấp dài ngón chân cái, chỗ bám của cơ dạng ngón cái và gân gót chân, rãnh gót của xương gót chân.\nThần kinh vận động cơ là các nhánh của dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5."}]},{"id":834,"ten":"Thứ Liêu","sections":[{"h":"VỊ TRÍ","body":"Nơi lỗ xương thiêng 2, điểm giữa cạnh dưới của gai chậu sau trên và Đốc Mạch."},{"h":"CHỦ TRỊ","body":"Trị vùng thắt lưng và xương cùng chậu đau, tử cung viêm, dịch hoàn sưng, xích bạch đới."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân của cơ lưng to, khối cơ chung của các cơ ở rãnh cột sống, lỗ cùng 2.\nThần kinh vận động cơ là nhánh của đám rối cánh tay, nhánh của dây thần kinh sống cùng 2.\nDa vùng huyệt chi phối vở tiết đoạn thần kinh"}]},{"id":835,"ten":"Thử Hề","sections":[{"h":"VỊ TRÍ","body":"Trong rãnh bụng – đùi, phía ngoài điểm giữa của động mạch đùi đo ngang ra ngoài 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị háng nổi hạch do viêm, chi dưới vùng háng bị yếu."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1, 5 – 2 thốn.\t0Z\n6c"}]},{"id":836,"ten":"Thử Vĩ","sections":[{"h":"VỊ TRÍ","body":"Chính giữa gót chân, bờ trên phía trong của xương gót chân."},{"h":"CHỦ TRỊ","body":"Trị lao hạch (loa lịch – tràng nhạc)"},{"h":"CHÂM CỨU","body":"Cứu 1 tráng. Bệnh bên phải cứu châm bên trái và ngược lại."}]},{"id":837,"ten":"Thừa Cân","sections":[{"h":"VỊ TRÍ","body":"Ở trung điểm nối 2 huyệt Thừa Sơn (Bq.57) và Hợp Dương (Bq."},{"h":"CHỦ TRỊ","body":"Trị chân đau, vai lưng đau cứng, vùng thắt lưng đau, chi dưới liệt, vọp bẻ."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa cơ sinh đôi ngoài và trong, cơ dép, cơ chầy sau, màng gian cốt.\nThần kinh vận động cơ là các nhánh của dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S2."}]},{"id":838,"ten":"Thừa Khấp","sections":[{"h":"VỊ TRÍ","body":"Dưới đồng tử 0,7 thốn, ở chỗ gặp nhau của bờ dưới xương ổ mắt với đường dọc chính giữa mắt."},{"h":"CHỦ TRỊ","body":"Trị kết mạc viêm, cận thị, viễn thị, thần kinh thị giác viêm, thần kinh thị giác teo, giác mạc viêm."},{"h":"CHÂM CỨU","body":"Bảo người bệnh ngước mắt nhìn lên trên, dùng một ngón tay đặt lên mi dưới, đẩy nhãn cầu lên, châm mũi kim chếch xuống dưới, dựa theo ổ mắt, sâu 0,1 – 1 thốn, Không vê kim, Không cứu."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ vòng mi (giữa phần ổ mắt và phần mi của cơ này), ở sâu là cơ thẳng dưới, cơ chéo bé của mắt và nhãn cầu.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số VII và các nhánh của dây thần kinh sọ não số III.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V.\nKhông châm khi có thai nhiều tháng."}]},{"id":839,"ten":"Thừa Linh","sections":[{"h":"VỊ TRÍ","body":"Sau huyệt Chính Dinh 1,5 thốn, trên đường nối huyệt Đầu Lâm Khấp (Đ.15) và Phong Trì (Đ."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, mũi nghẹt."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân sọ, xương đỉnh sọ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C2.]-?!2Thiên Ngũ Loạn ghi: “Nếu tà khí ở đầu, thủ huyệt Thiên Trụ (Bq 10) + Đại Trữ (Bq 11), nếu không giảm, châm thêm huyệt Vinh + huyệt Du của kinh Túc Thái Dương huyệt Thông Cốc (Bq 66) và Thúc Cốt (Bq 65)]” (Linh Khu 34, 19)"}]},{"id":840,"ten":"Thừa Mãn","sections":[{"h":"VỊ TRÍ","body":"Trên rốn 5 thốn, cách đường giữa bụng 2 thốn, ngang huyệt Thượng Quản (Nh."},{"h":"CHỦ TRỊ","body":"Trị dạ dầy viêm cấp và mạn tính, dạ dầy đau, ruột sôi, đau do thoát vị."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ chéo to, cơ thẳng to, mạc ngang, phúc mạc. Bên phải là gan, bên trái là dạ dầy.\nThần kinh vận động cơ là 6 dây thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D7."}]},{"id":841,"ten":"Thừa Mạng","sections":[{"h":"VỊ TRÍ","body":"Giữa gân gót và đỉnh mắt cá chân trong (huyệt Thái Khê) đo lên 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị động kinh, bệnh tâm thần, phù thũng chi dưới."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn."}]},{"id":842,"ten":"Thừa Phò","sections":[]},{"id":843,"ten":"Thừa Phù","sections":[{"h":"VỊ TRÍ","body":"Điểm giữa nếp mông."},{"h":"CHỦ TRỊ","body":"Trị thần kinh tọa đau, chi dưới liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 2 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ dưới cơ mông to, bờ trong cơ 2 đầu đùi, bờ ngoài cơ bán gân, bờ ngoài cơ bán mạc, cơ khép lớ và cơ khép bé.\nThần kinh vận động cơ là các nhánh của dây thần kinh hông và các nhánh của dây thần kinh bịt.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S2."}]},{"id":844,"ten":"Thừa Quang","sections":[{"h":"VỊ TRÍ","body":"Ngay sau trên huyệt Ngũ Xứ 1,5 thốn, cách tuyến giữa đầu 1,5 thốn, ngang huyệt Tiền Đình (Đc."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, chóng mặt, cảm mạo."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn, Không cứu – Nếu cần cứu, cần cẩn thận vì dễ bỏng."},{"h":"GIẢI PHẪU","body":"Dưới da là cân sọ, xương sọ.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V.b ¼."}]},{"id":845,"ten":"Thừa Sơn","sections":[{"h":"VỊ TRÍ","body":"Ở giữa đường nối huyệt Ủy Trung và gót chân, dưới Ủy Trung 8 thốn, ngay chỗ lõm giữa 2 khe cơ sinh đôi ngoài và trong."},{"h":"CHỦ TRỊ","body":"Trị cơ bắp chân co rút, thần kinh tọa đau, chi dưới liệt, gót chân đau, trĩ, trực trường sa."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3–5 tráng. Ôn cứu 5–10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là góc giữa cơ sinh đôi ngoài và trong, cơ dép, góc giữa cơ gấp dài các ngón chân và cơ gấp dài ngón chân cái, cơ chầy sau, màng gian cốt.\nThần kinh vận động cơ là các nhánh của dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S2.\nĐây là huyệt Tề Thượng Hạ hợp với huyệt Hoang Du."}]},{"id":846,"ten":"Thừa Tương","sections":[{"h":"VỊ TRÍ","body":"Ở đáy chỗ lõm, chính giữa và dưới môi dưới, trên đường bổ dọc giữa hàm dưới."},{"h":"CHỦ TRỊ","body":"Trị miệng méo, mặt sưng, răng đau, lợi răng sưng, chảy nước miếng, đột nhiên mất tiếng, điên cuồng."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,2 – 0,5 thốn. Cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Huyệt ở giữa 2 cơ vuông cằm, dưới bờ dưới cơ vòng môi, trên bờ trên cơ chòm râu cằm.\nThần kinh vận động cơ là các nhánh cổ – mặt của dây thần kinh sọ não số VII.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V.[M3LBd,TL5"}]},{"id":847,"ten":"Thực Đậu","sections":[{"h":"VỊ TRÍ","body":"Ở giữa gian sườn 5, cách đường giữa bụng 6 thốn."},{"h":"CHỦ TRỊ","body":"Trị thần kinh gian sườn đau, dạ dày đau, tiểu bí."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 05 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là phần gân cơ chéo to của bụng, cơ răng cưa to, các cơ gian sườn 6. Vào trong là phổi.\nThần kinh vận động cơ là dây thần kinh gian sườn 6.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D5."}]},{"id":848,"ten":"Thực Quan","sections":[{"h":"VỊ TRÍ","body":"Rốn đo lên 3 thốn (huyệt Kiến Lý – Nh.11), đo ra 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị tiêu hóa kém, dạ dày viêm, ruột viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn."}]},{"id":849,"ten":"Thực Thương","sections":[{"h":"VỊ TRÍ","body":"Rốn đo lên 4 thốn (huyệt Trung Quản – Nh.12), rồi đo ra 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị dạ dày đau, dạ dày sa, dạ dày loét."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1–1,5 thốn."}]},{"id":850,"ten":"Thực Thương Danh Cứu","sections":[{"h":"VỊ TRÍ","body":"Huyệt ở lòng bàn chân, tại khớp xương bàn chân thứ hai."},{"h":"CHỦ TRỊ","body":"Trị ợ hơi, bụng đầy, bụng đau, nôn mửa."},{"h":"CHÂM CỨU","body":"Cứu 30 tráng."}]},{"id":851,"ten":"Thương Bạch","sections":[{"h":"VỊ TRÍ","body":"Xác định huyệt Thiếu Thương (P.11) và Ẩn Bạch (Ty.1), Thương Bạch là 2 huyệt này."},{"h":"CHỦ TRỊ","body":"Trị động kinh, bệnh tâm thần."},{"h":"CHÂM CỨU","body":"Dùng dây cột 2 ngón tay cái và 2 ngón chân cái lại, dùng ngải cứu bỏ trên 2 huyệt chung 1 mồi ngải rồi cứu. Cứu mỗi nơi 3 tráng."}]},{"id":852,"ten":"Thương Dương","sections":[{"h":"VỊ TRÍ","body":"Huyệt ở góc ngoài chân móng ngón tay trỏ cách khoảng 1mm."},{"h":"CHỦ TRỊ","body":"Trị ngón tay trỏ đau, tê, răng đau, hàm đau, họng đau, thần kinh mặt đau do rối loạn ở kinh cân, tai ù, điếc, sốt cao mê sảng, mắt đau nhức."},{"h":"CHÂM CỨU","body":"Châm xiên hoặc thẳng, sâu 0,1 – 0,2 thốn. Cứu 1 – 3 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là phía ngoài chỗ bám gân duỗi ngón trỏ của cơ duỗi chung các ngón tay, bờ ngoài đốt 3 xương ngón tay trỏ.\nThần kinh vận động cơ là nhánh của dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C7."}]},{"id":853,"ten":"Thương Khâu","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm phía dưới – trước mắt cá chân trong, bờ trên gân cơ cẳng chân sau, sát khe khớp gót – sên – thuyền."},{"h":"CHỦ TRỊ","body":"Trị cước khí, chân đau, dạ dày viêm, ruột viêm, tiêu hóa kém."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn hoặc châm xiên tới huyệt Giải Khê, sâu 1 – 1,5 thốn. Cứu 1 – 3 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ trên gân cơ cẳng chân sau, sát khe khớp sên – thuyền.\nThần kinh vận động cơ là nhánh của dây chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L4 hoặc"}]},{"id":854,"ten":"Thương Khúc","sections":[{"h":"VỊ TRÍ","body":"Trên rốn 2 thốn, cách đường giữa bụng 0,5 thốn, huyệt Hạ Quản (Nh.10) ra ngang 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị bụng đau do thoát vị, dạ dày đau, biếng ăn."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 5 – 7 tráng. Ôn cứu 10 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ chéo to của bụng, bờ trong cơ thẳng to, mạc ngang, phúc mạc, đại tràng ngang.\nThần kinh vận động cơ là 6 nhánh dây thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D9."}]},{"id":855,"ten":"Thượng Bát Phong","sections":[{"h":"VỊ TRÍ","body":"Bờ sau của khớp xương bàn chân 1 và 5, giữa 2 khớp. Tất cả hai chân gồm 8 huyệt. (Trong đó có 6 huyệt: Hành gian, Hãm Cốc, Địa Ngũ Hội)"},{"h":"CHỦ TRỊ","body":"Trị đầu đau, răng đau, dạ dày đau, kinh nguyệt không đều, sốt rét, rắn cắn, mu bàn chân đau, ngón chân sưng, thần kinh đầu ngón chân viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1,5 thốn. Cứu 3 tráng. Ôn cứu 5 – 15 phút."}]},{"id":856,"ten":"Thượng Bát Tà","sections":[{"h":"VỊ TRÍ","body":"Úp bàn tay, giữa các chỗ lõm ở bờ sau xương bàn tay thứ 1 – 5."},{"h":"CHỦ TRỊ","body":"Trị bệnh khớp ở bàn tay, các ngón tay tê, đầu nhức, gáy đau, răng đau, họng đau, rắn cắn."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3–0,5 thốn. Không cứu."}]},{"id":857,"ten":"Thượng Cự Hư","sections":[{"h":"VỊ TRÍ","body":"Dưới mắt gối ngoài (Độc Tỵ) 6 thốn, phía ngoài xương mác một khoát ngón tay, dưới huyệt Túc Tam Lý (Vi.36) 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị bụng đau, tiêu chảy, ruột thừa viêm, liệt chi dưới."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 7 tráng, Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ ngoài cơ cẳng thân trước, bờ trong cơ duỗi chung các ngón chân, khe giữa xương chầy và xương mác.\nThần kinh vận động cơ là các nhánh của dây thần kinh chầy trước.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5."}]},{"id":858,"ten":"Thượng Đô","sections":[{"h":"VỊ TRÍ","body":"Tại khe ngón tay 2 và 3."},{"h":"CHỦ TRỊ","body":"Trị bàn tay sưng đỏ đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,8 – 1 thốn. Cứu 5 tráng."}]},{"id":859,"ten":"Thượng Hạ Tự Cứu","sections":[{"h":"VỊ TRÍ","body":"Gồm có 6 huyệt:\nMệnh Môn (Đc.4) và 2 bên Giáp Tích (gọi là Thượng Tự Cứu).\nYêu Dương Quan (Đc.3) và 2 bên Giáp Tích (gọi là Hạ Tự Cứu)"},{"h":"CHỦ TRỊ","body":"Trị lưng đau, bụng lạnh, chân đau nhức, chân tê, bệnh ở bộ phận sinh dục."},{"h":"CHÂM CỨU","body":"Cứu 10 – 15 phút. Có thể châm."}]},{"id":860,"ten":"Thượng Liêm","sections":[{"h":"VỊ TRÍ","body":"Trên đường nối huyệt Khúc Trì (Đtr.11) và Dương Khê, cách Khúc Trì 3 thốn, ở bờ sau cơ ngửa dài, bờ ngoài cơ ngửa ngắn."},{"h":"CHỦ TRỊ","body":"Trị vai lưng đau, chi trên liệt, ruột sôi, bụng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ sau cơ ngửa dài, bờ ngoài cơ quay 1, cơ ngửa ngắn và xương quay.\nThần kinh vận động cơ do các nhánh của dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C6.Mx\"7'5BN:2"}]},{"id":861,"ten":"Thượng Liêm Tuyền","sections":[{"h":"VỊ TRÍ","body":"Ngay chính giữa dưới hàm, nơi chỗ sũng giữa bờ hàm dưới và xương lưỡi."},{"h":"CHỦ TRỊ","body":"Trị nói không rõ, câm, chảy nước miếng, xoang miệng viêm, họng viêm cấp tính."},{"h":"CHÂM CỨU","body":"Châm xiên, hướng tới phía gốc lưỡi sâu 1 – 1,5 thốn, hoặc luồn kim dưới da, châm xiên qua phải hoặc trái sâu 1 – 1,5 thốn."}]},{"id":862,"ten":"Thượng Liêu","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm ở xương thiêng thứ 1, trung điểm của gai chậu sau – trên và Đốc Mạch."},{"h":"CHỦ TRỊ","body":"Trị thắt lưng cùng và vùng xương chậu đều đau, kinh nguyệt rối loạn, tử cung viêm, bệnh có xuất huyết, bệnh về đường tiểu và sinh dục, thần kinh suy nhược."},{"h":"CHÂM CỨU","body":"Châm thẳng ngay vào lỗ cùng thứ I, sâu 1 – 1,5 thốn. Cứu 5 – 7 tráng, Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân của cơ lưng to, khối cơ chung của các cơ rãnh cột sống, lỗ cùng 1.\nThần kinh vận động cơ là nhánh của đám rối cánh tay, nhánh của dây thần kinh sống cùng 1.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S1."}]},{"id":863,"ten":"Thượng Ngạc","sections":[{"h":"VỊ TRÍ","body":"Tại giữa ngấn vòm hàm răng trên, chỗ da trắng – đỏ."},{"h":"CHỦ TRỊ","body":"Trị hoàng đản."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,1 – 0,2 thốn hoặc dùng kim tam lăng châm cho ra máu."}]},{"id":864,"ten":"Thượng Ngân Lý","sections":[{"h":"VỊ TRÍ","body":"Chính giữa niêm mạc môi trên."},{"h":"CHỦ TRỊ","body":"Trị hoàng đản."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,1 – 0,2 thốn hoặc châm ra máu."}]},{"id":865,"ten":"Thượng Nghênh Hương","sections":[{"h":"VỊ TRÍ","body":"Tại chỗ tận cùng của rãnh trên nếp mũi – má."},{"h":"CHỦ TRỊ","body":"Trị mũi viêm dị ứng, các bệnh về mũi, mi mắt đau."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn.4\n-\n2."}]},{"id":866,"ten":"Thượng Nội Đình","sections":[{"h":"VỊ TRÍ","body":"Khe ngón chân thứ 2 và 3 đo lên 3 thốn, gần kẽ xương bàn ngón 2 và 3."},{"h":"CHỦ TRỊ","body":"Trị dạ dầy viêm loét, tá tràng viêm loét, dạ dầy viêm cấp."},{"h":"CHÂM CỨU","body":"Châm thẳng hoặc xiên sâu 0,3– 0,5 thốn. Cứu 5 – 10 phút.F\n;n"}]},{"id":867,"ten":"Thượng Quan","sections":[{"h":"VỊ TRÍ","body":"Ở phía trước tai, bờ trên xương gò má, xác định huyệt Hạ Quan kéo thẳng lên, đến chỗ lõm bờ sau chân tóc mai."},{"h":"CHỦ TRỊ","body":"Trị liệt mặt, tai ù, điếc, răng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ tai trước, cơ thái dương, xương thái dương. Thần kinh vận động cơ là nhánh của dây thần kinh mặt, nhánh dây thần kinh sọ não số V.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V."}]},{"id":868,"ten":"Thượng Quản","sections":[{"h":"VỊ TRÍ","body":"Trên lỗ rốn 5 thốn, dưới huyệt Cự Khuyết (Nh.14) 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị dạ dầy đau, nôn mửa, kinh giật, tim đập mạnh."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1,5 thốn. Cứu 10 – 30 phút."},{"h":"GIẢI PHẪU","body":"Huyệt ở trên đường trắng. Sau đường trắng là mạc ngang, phúc mạc. Sau thành bụng là hậu cung mạc nối và phần ngang của dạ dầy.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D7."}]},{"id":869,"ten":"Thượng Tinh","sections":[{"h":"VỊ TRÍ","body":"Trên đường dọc giữa đầu, chính giữa đoạn nối huyệt Bá Hội (Đc.20) và Ấn Đường."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, chảy nước mũi, chảy máu cam, điên cuồng, mắt đỏ, mắt đau."},{"h":"CHÂM CỨU","body":"Châm luồn kim dưới da sâu 0,2 – 0,5 thốn. Cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân sọ, dưới cân sọ là xương sọ.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V."}]},{"id":870,"ten":"Thượng Vị","sections":[{"h":"VỊ TRÍ","body":"Rốn đo lên 2 thốn (huyệt Kiến lý) đo ngang ra 2 bên 1,5 thốn, ngang với đáy thấp nhất mà dạ dày sa xuống."},{"h":"CHỦ TRỊ","body":"Trị dạ dày sa xuống."},{"h":"CHÂM CỨU","body":"Châm xiên luồn dưới da đến rốn.0j\nK"}]},{"id":871,"ten":"Tích Bối Ngũ Huyệt","sections":[{"h":"VỊ TRÍ","body":"Gồm 5 huyệt: một huyệt ở đốt xương sống thứ nhất, một huyệt ở xương cùng thứ 5, một huyệt ở giữa lưng đo từ huyệt thứ nhất đến giữa lưng rồi cắt dây đo đó làm 2 làm thành hình tam giác đều, đỉnh đặt tại giữa lưng, 2 đỉnh còn lại là 2 huyệt Cộng chung là 5 huyệt."},{"h":"CHỦ TRỊ","body":"Trị trẻ nhỏ suy dinh dưỡng, bệnh tâm thần, điên cuồng, kinh phong."},{"h":"CHÂM CỨU","body":"Cứu 3 – 5 tráng."}]},{"id":872,"ten":"Tích Cốt Giải Trung","sections":[{"h":"VỊ TRÍ","body":"Thẳng đầu vú vòng ra sau lưng chạm cột sống chỗ nào, đó là huyệt."},{"h":"CHỦ TRỊ","body":"Trị ho, ho ra máu, suy nhược, sốt cơn."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn. Cứu 5 – 10 phút."}]},{"id":873,"ten":"Tích Lương Trung Anh","sections":[{"h":"VỊ TRÍ","body":"Dưới gai đốt sống thắt lưng thứ 2 đo ra 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị tủy sống viêm, dây chằng 2 bên dọc cột sống viêm, liệt chi dưới."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1,5 – 2 thốn."}]},{"id":874,"ten":"Tích Phùng","sections":[{"h":"VỊ TRÍ","body":"Dưới gai xương sống lưng thứ 1 đến dưới gai xương sống thắt lưng thứ 5, dưới mỗi gai đo ra 4,5 thốn. Tất cả 17 cặp huyệt, tổng cộng cả bên phải và trái là 34 huyệt."},{"h":"CHỦ TRỊ","body":"Trị cột sống viêm, tủy sống viêm."},{"h":"CHÂM CỨU","body":"Châm xiên, sâu 0,3 – 0,7 thốn."}]},{"id":875,"ten":"Tích Tam Huyệt","sections":[{"h":"VỊ TRÍ","body":"Có 3 huyệt:\n1.\tTừ huyệt Á Môn đo xuống 1 thốn xong đo ra 0,5 thốn.\n2.\tKhe đốt sống ngực 1.\n3.\tKhe đốt thắt lưng 2."},{"h":"CHỦ TRỊ","body":"Trị cột sống viêm, màng tủy sống viêm, thần kinh vai lưng đau, các chứng bệnh tủy sống khác."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 1 thốn. Cứu 3 tráng."}]},{"id":876,"ten":"Tích Trung","sections":[{"h":"VỊ TRÍ","body":"Tại chỗ lõm ngay dưới đầu mỏm gai đốt sống lưng 11."},{"h":"CHỦ TRỊ","body":"Trị cột sống lưng đau, nấc, nôn ra máu, cơn đau dạ dầy, da vàng, tiêu chảy, lòi dom, động kinh."},{"h":"CHÂM CỨU","body":"Châm chếch kim lên trên, luồn dưới mỏm gai, hướng vào khoảng gian đốt sống lưng 11 – 12, sâu 0,3 – 1 thốn. Cứu 10 – 30 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là chỗ bám của gân cơ thang, cân ngực – thắt lưng của cơ lưng to, cơ răng bé sau – dưới, cơ gai dài của lưng, cơ ngang gai, dây chằng trên gai, dây chằng gian gai, dây chằng vàng, ống sống.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số XI, nhánh đám rối cổ sâu và các nhánh của dây thần kinh sống.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D8."}]},{"id":877,"ten":"Tích Tụ Bỉ Khối","sections":[{"h":"VỊ TRÍ","body":"Dưới gai xương thắt lưng 2 (huyệt Mệnh Môn) đo ra mỗi bên 4 thốn."},{"h":"CHỦ TRỊ","body":"Trị tích tụ, bỉ khối, dạ dày co thắt, no hơi, ruột đau co thắt, sôi ruột, tiêu hóa không tốt, màng ngực viêm, kinh bế."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn, Cứu 7 tráng."}]},{"id":878,"ten":"Tiền Cốc","sections":[{"h":"VỊ TRÍ","body":"Huyệt ở chỗ lõm nơi khớp xương ngón tay thứ 5 về phía xương trụ, khi nắm tay lại huyệt ở trước lằn chỉ tay ngón út và bàn, nơi tiếp giáp da gan và mu tay."},{"h":"CHỦ TRỊ","body":"Trị cánh tay đau, ngón tay tê, mắt đau, tai ù, sốt cao, tiểu nóng đỏ."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là chỗ bám của cơ dạng ngón thứ 5 và cơ gấp ngắn ngón 5, bờ trong đầu trên đốt thứ nhất xương ngón 5.\nThần kinh vận động cơ là các nhánh của dây thần kinh trụ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D1."}]},{"id":879,"ten":"Tiền Đỉnh","sections":[{"h":"VỊ TRÍ","body":"Trên đường dọc giữa đầu, phía trước huyệt Bá Hội (Đc.20) 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị đỉnh đầu đau, váng đầu, chảy nước mũi, kinh giật, hoa mắt."},{"h":"CHÂM CỨU","body":"Châm luồn kim dưới da sâu 0,2 – 0,8 thốn. Cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân sọ, dưới cân sọ là xương sọ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C2."}]},{"id":880,"ten":"Tiền Hậu Ẩn Châu","sections":[{"h":"VỊ TRÍ","body":"Giữa lòng bàn chân (huyệt Dũng Tuyền) đo tới phía trước và phía sau 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị huyết áp cao, lòng bàn chân đau, trẻ nhỏ bị động kinh."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn.N\n;"}]},{"id":881,"ten":"Tiền Khổng","sections":[{"h":"VỊ TRÍ","body":"Lấy đường nối đầu vú và rốn, kéo ra đến đầu xương sườn là huyệt."},{"h":"CHỦ TRỊ","body":"Trị hoàng đản."},{"h":"CHÂM CỨU","body":"Cứu 3 – 5 tráng hoặc Ôn cứu 5 – 10 phút."}]},{"id":882,"ten":"Tiền Phát Tế","sections":[{"h":"VỊ TRÍ","body":"Huyệt Thái Dương đo lên 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị mụn nhọt ở vùng đầu mặt."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn. Cứu 1 – 3 tráng. Ôn cứu 5 – 10 phút."}]},{"id":883,"ten":"Tiện Độc Huyệt","sections":[{"h":"VỊ TRÍ","body":"Duỗi cánh tay, ở mặt ngoài – trước cánh tay, từ lằn chỉ cổ tay đo lên 4 thốn. Khi gấp bàn tay ra phía sau, ở cánh tay có chỗ lõm, huyệt ở vùng lõm đó."},{"h":"CHỦ TRỊ","body":"Trị chứng tiện độc (tiêu ra mủ máu."},{"h":"CHÂM CỨU","body":"Cứu 3 tráng."}]},{"id":884,"ten":"Tiếp Tích","sections":[{"h":"VỊ TRÍ","body":"Dưới gai đốt sống lưng thứ 12."},{"h":"CHỦ TRỊ","body":"Trị lỵ."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,5 – 1 thốn. Cứu 5 – 7 tráng."}]},{"id":885,"ten":"Tiết Tức","sections":[{"h":"VỊ TRÍ","body":"Tại chỗ lõm cách dưới núm vú thẳng xuống một xương sườn."},{"h":"CHỦ TRỊ","body":"Trị trẻ nhỏ bụng bị đầy, hơi thở ngắn."},{"h":"CHÂM CỨU","body":"Ôn cứu 2 – 3 phút.9\n'Y"}]},{"id":886,"ten":"Tiết Văn","sections":[{"h":"VỊ TRÍ","body":"Tại giữa nếp trong của khớp ngón chân cái."},{"h":"CHỦ TRỊ","body":"Trị động kinh (kết hợp với huyệt Độc Âm)"},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,2 – 0,3 thốn, Cứu 3 – 7 tráng."}]},{"id":887,"ten":"Tiệt Hạ","sections":[{"h":"VỊ TRÍ","body":"Dưới tiết đoạn cột sống bị tổn thương, các huyệt trên mạch Đốc đó đều có thể chọn dùng được."},{"h":"CHỦ TRỊ","body":"Trị bại liệt theo tiết đoạn."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1,5 – 2 thốn."}]},{"id":888,"ten":"Tiệt Ngược","sections":[{"h":"VỊ TRÍ","body":"Đầu vú thẳng xuống 4 thốn."},{"h":"CHỦ TRỊ","body":"Trị sốt rét, ngực và sườn đau."},{"h":"CHÂM CỨU","body":"Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."}]},{"id":889,"ten":"Tiệt Than Hoãn Kính Điểm","sections":[{"h":"VỊ TRÍ","body":"Là những huyệt chủ yếu trị liệt chi dưới do tổn thương tủy sống."}]},{"id":890,"ten":"Tiêu Khối Huyệt","sections":[{"h":"VỊ TRÍ","body":"Tại đầu nếp nách trước."},{"h":"CHỦ TRỊ","body":"Trị vùng vú sưng cứng."},{"h":"CHÂM CỨU","body":"Châm xiên lên, sâu 1–1,5 thốn."}]},{"id":891,"ten":"Tiêu Lạc","sections":[{"h":"VỊ TRÍ","body":"Ở giữa đoạn nối huyệt Thanh Lãnh Uyên (Ttu.11) và Nhu Hội (Ttu.13), trên khớp khuỷu tay 5 thốn, khe giữa phần ngoài và phần rộng ngoài của cơ tam đầu cánh tay."},{"h":"CHỦ TRỊ","body":"Trị cánh tay đau, cổ gáy cứng, đầu đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,8 – 1 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa phần dài và phần rộng ngoài (Xoay cánh tay ra trước sẽ làm hiện rõ khe của phần dài và rộng ngoài của cơ 3 đầu cánh tay).\nThần kinh vận động cơ là các nhánh của dây thần kinh quay."}]},{"id":892,"ten":"Tiêu Lịch Huyệt","sections":[{"h":"VỊ TRÍ","body":"Từ huyệt Đại Chùy (Đc.14) đo ngang ra 2 bên mỗi bên 0,5 khẩu thốn."},{"h":"CHỦ TRỊ","body":"Trị loa lịch (lao hạch)"},{"h":"CHÂM CỨU","body":"Cứu 3 – 7 tráng."}]},{"id":893,"ten":"Tiểu Chỉ Trảo Văn","sections":[{"h":"VỊ TRÍ","body":"Mu tay, tại giữa chân gốc móng các ngón tay."},{"h":"CHỦ TRỊ","body":"Trị họng đau."},{"h":"CHÂM CỨU","body":"Châm nặn máu."}]},{"id":894,"ten":"Tiểu Chỉ Tiêm","sections":[{"h":"VỊ TRÍ","body":"Tại đầu ngón tay thứ 5."},{"h":"CHỦ TRỊ","body":"Trị hoàng đản, ho gà, sán khí."},{"h":"CHÂM CỨU","body":"Châm sâu 0,1 – 0,2 thốn. Cứu 3 – 7 tráng."}]},{"id":895,"ten":"Tiểu Chỉ Tiêm","sections":[{"h":"VỊ TRÍ","body":"Tại đầu ngón chân thứ 5."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, chóng mặt, dạ dầy đau lâu năm."},{"h":"CHÂM CỨU","body":"Cứu 5 – 10 phút.=\n,3"}]},{"id":896,"ten":"Tiểu Chỉ Tiết","sections":[{"h":"VỊ TRÍ","body":"Mu bàn tay, trên đỉnh cao phần dưới khớp xương ngón tay thứ 5 (khớp cuối)"},{"h":"CHỦ TRỊ","body":"Trị dạ dầy đau lâu năm."},{"h":"CHÂM CỨU","body":"Cứu 10 – 15 phút.CK\nd"}]},{"id":897,"ten":"Tiểu Chỉ Trung Tiết","sections":[{"h":"VỊ TRÍ","body":"Đầu ngoài lằn chỉ cuối ngón tay thứ 5."},{"h":"CHỦ TRỊ","body":"Trị trẻ nhỏ suy dinh dưỡng, bướu cổ."},{"h":"CHÂM CỨU","body":"Châm nặn máu hoặc nước vàng."}]},{"id":898,"ten":"Tiểu Cốt Không","sections":[{"h":"VỊ TRÍ","body":"Huyệt tại chỗ cao giữa mặt sau khớp đốt 1 và 2 của ngón tay thứ 5."},{"h":"CHỦ TRỊ","body":"Trị bệnh mắt, họng đau, khớp ngón tay đau."},{"h":"CHÂM CỨU","body":"Cứu."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là gân duỗi ngón út, khe khớp đốt ngón tay út 1 và 2.\nThần kinh vận động cơ là nhánh dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C8 hoặc D1."}]},{"id":899,"ten":"Tiểu Hải","sections":[{"h":"VỊ TRÍ","body":"Co khuỷu tay, huyệt ở giữa mỏm khuỷu và mỏm trên ròng rọc đầu dưới xương cánh tay, nơi tận cơ 3 đầu cánh tay."},{"h":"CHỦ TRỊ","body":"Trị cơ vai co rút, cẳng tay co rút, khuỷu tay đau, thần kinh trụ đau, Hysteria, tâm thần phân liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ 3 đầu cánh tay, rãnh ròng rọc – khuỷu của mặt sau đầu dưới xương cánh tay (ở trong là mỏm trên ròng rọc của xương cánh tay, có gân cơ trụ trước và gân cơ gấp chung sâu các ngón tay bám gần nhất, ở ngoài là mỏm khuỷu của xương trụ, có gân cơ 3 đầu cánh tay bám).\nThần kinh vận động cơ là các nhánh của dây thần kinh trụ và dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D1.\nTại chỗ có cảm giác căng tê tức hoặc tê giật lan ra đầu ngón chân."}]},{"id":900,"ten":"Tiểu Nhi Cam Lỵ","sections":[{"h":"VỊ TRÍ","body":"Chót xương cụt lên 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị trẻ nhỏ suy dinh dưỡng, kiết lỵ lâu ngày."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,3 – 0,5 thốn. Cứu 5 –10 phút.Y\n."}]},{"id":901,"ten":"Tiểu Nhi Cứu Phích","sections":[{"h":"VỊ TRÍ","body":"Giữa gai đốt sống thắt lưng thứ 2 và 3."},{"h":"CHỦ TRỊ","body":"Trị tiêu hóa kém."},{"h":"CHÂM CỨU","body":"Cứu 20 tráng.(\n'"}]},{"id":902,"ten":"Tiểu Nhi Giáng Suyễn","sections":[{"h":"VỊ TRÍ","body":"Tại đầu ngón tay thứ 5, sát đầu móng."},{"h":"CHỦ TRỊ","body":"Trị ho, suyễn."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,1 – 0,2 thốn hoặc châm ra máu. Cứu 5 – 10 phút."}]},{"id":903,"ten":"Tiểu Nhi Kê Hung Huyệt","sections":[{"h":"VỊ TRÍ","body":"Giữa xương sườn 2, 3, 4, cách đường giữa ngực 2,5 thốn. Tất cả gồm 6 huyệt."},{"h":"CHỦ TRỊ","body":"Trị trẻ nhỏ ngực bị nhô ra, ngực rùa."},{"h":"CHÂM CỨU","body":"Cứu 3 tráng."}]},{"id":904,"ten":"Tiểu Nhi Thụy Kinh","sections":[{"h":"VỊ TRÍ","body":"Đầu ngoài nếp gấp khuỷu tay (huyệt Khúc Trì) lên 0,3 thốn."},{"h":"CHỦ TRỊ","body":"Trị ngủ hay bị giật mình, ngủ không yên, khuỷu tay đau."},{"h":"CHÂM CỨU","body":"Cứu 10 – 15 phút.d;\n89"}]},{"id":905,"ten":"Tiểu Nhi Thực Giản","sections":[{"h":"VỊ TRÍ","body":"Cuối xương ức lên 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị trẻ nhỏ điên cuồng."},{"h":"CHÂM CỨU","body":"Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."}]},{"id":906,"ten":"Tiểu Nhi Tiêu Hoá Bất Lương Điểm","sections":[{"h":"VỊ TRÍ","body":"Lòng bàn tay, giữa lằn chỉ ngang khớp ngón thứ 1 của ngón tay giữa."},{"h":"CHỦ TRỊ","body":"Trị tiêu hoá rối loạn nơi trẻ nhỏ."},{"h":"CHÂM CỨU","body":"Cứu 3 – 5 tráng. Ôn cứu 3 – 5 phút."}]},{"id":907,"ten":"Tiểu Thiên Tâm","sections":[{"h":"VỊ TRÍ","body":"Ngửa bàn tay, từ giữa lằn chỉ cổ tay đo thẳng xuống lòng bàn tay 1,5 thốn."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 2 – 3 thốn.K\nF"}]},{"id":908,"ten":"Tiểu Trường Du","sections":[{"h":"VỊ TRÍ","body":"Dưới đốt xương thiêng 1, đo ngang 1,5 thốn, chỗ lõm giữa gai chậu sau – trên và xương cùng."},{"h":"CHỦ TRỊ","body":"Trị thắt lưng đau, xương cùng chậu đau, ruột viêm, bạch đới."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân của cơ lưng to, khối cơ chung của các cơ ở rãnh cột sống, xương cùng.\nThần kinh vận động cơ là nhánh của đám rối cánh tay, nhánh của dây thần kinh sống cùng 1.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5 hoặc S1."}]},{"id":909,"ten":"Tín Hội","sections":[{"h":"VỊ TRÍ","body":"Trên đường dọc giữa đầu, chính giữa thóp trước, phía trước huyệt Bá Hội (Đc.20) 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, chảy nước mũi, hoa mắt."},{"h":"CHÂM CỨU","body":"Châm luồn kim dưới da, sâu 0,2 – 0,5 thốn. Cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân sọ, dưới cân sọ là thóp trước hoặc vết tích của thóp trước.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C2 hoặc thần kinh sọ não số V.\nThiên Thích Yêu Thống ghi: “Lưng đau như gãy, không thể cúi ngửa, châm huyệt túc Thái dương [Bát Liêu, gồm các huyệt đôi Thượng Liêu, Trung Liêu, Thứ Liêu, Hạ Liêu]” (Tố Vấn 41, 20)"}]},{"id":910,"ten":"Tinh Linh","sections":[{"h":"VỊ TRÍ","body":"Mu bàn tay, chỗ giáp của ngón tay thứ tư và thứ năm đo xuống 0,5 thốn, chỗ lõm phía trụ gân cơ duỗi ngón tay thứ 4."},{"h":"CHỦ TRỊ","body":"Trị chấn thương thắt lưng cấp, đầu đau, chết đuối, đàm chận làm cho khó thở, động kinh, mu bàn tay sưng đỏ, mu bàn tay đau nhức."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn."}]},{"id":911,"ten":"Tinh Minh","sections":[{"h":"VỊ TRÍ","body":"Cách đầu trong góc mắt 0,1 thốn."},{"h":"CHỦ TRỊ","body":"Trị các bệnh về mắt, thần kinh mặt liệt."},{"h":"CHÂM CỨU","body":"Bảo người bệnh nhắm mắt, châm thẳng sâu 0,5 – 1 thốn. Không vê kim – Không cứu."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ vòng miệng dưới, chỗ bám của cơ tháp, cơ mày, trên chỗ bám của cơ nâng mũi và môi trên. Chỗ xương hàm trên tiếp khớp với xương trán. Trong ổ mắt có cơ thẳng trong.\nThần kinh vận động cơ là các nhánh của dây thần kinh mặt và nhánh dưới dây thần kinh sọ não số III.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V."}]},{"id":912,"ten":"Tinh Quang","sections":[{"h":"VỊ TRÍ","body":"Khóe mắt trong đo thẳng lên 0,3 thốn."},{"h":"CHỦ TRỊ","body":"Trị sắc manh (mắt không nhìn thấy mầu, mắt bị rối loạn về mầu sắc)"},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,5 – 1 thốn."}]},{"id":913,"ten":"Tinh Tinh","sections":[{"h":"VỊ TRÍ","body":"Trên huyệt Khúc Trạch (Tb 3) khoảng 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị hôn mê, phía trên cánh tay đau, đơn độc."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn.,\n-"}]},{"id":914,"ten":"Tọa Cốt Bộ","sections":[{"h":"VỊ TRÍ","body":"Khe xương cùng đo ra 2,2 thốn rồi đo xuống 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị rối loạn vận động chi dưới, di chứng liệt nơi trẻ nhỏ, thần kinh tọa đau."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 2 – 3 thốn.03\nN?"}]},{"id":915,"ten":"Toàn Tri","sections":[{"h":"VỊ TRÍ","body":"Ngang bờ trên sụn giáp (huyệt Thiên Song – Ttr.16) xuống 2 thốn, ở bờ sau cơ ức – đòn – chũm."},{"h":"CHỦ TRỊ","body":"Trị thần kinh cổ đau, cơ vùng cổ cứng, liệt nửa người."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,8 – 1 thốn. Cứu 5 –10 phút."}]},{"id":916,"ten":"Toàn Trúc","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm đầu trong chân mày, thẳng trên góc mắt trong."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, mắt đau, liệt mặt."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,3 – 0,5 thốn.\nTrị bệnh về mắt, châm xiên hướng xuống đến huyệt Tinh Minh (Bq.1) .\nTrị đầu đau, mặt liệt, châm xuyên đến huyệt Ngư Yêu.\nTrị thần kinh hố mắt trên đau, châm xiên hướng mũi kim ra phía ngoài.\nTrị đau ở trước Ấn Đường, châm luồn kim dưới da, 2 thân kim chéo nhau ở giữa Ấn Đường.\nKhông cứu."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ trán, cơ mày, cơ tháp và bờ cơ vòng mi.\nThần kinh vận động cơ là các nhánh của dây thần kinh mặt.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V."}]},{"id":917,"ten":"Tố Liêu","sections":[{"h":"VỊ TRÍ","body":"Ở cuối (chỗ đầu nhọn) của sống mũi."},{"h":"CHỦ TRỊ","body":"Trị mũi nghẹt, mũi chảy máu, mũi viêm, thịt dư ở mũi."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,1 – 0,2 thốn. Không cứu. Có thể châm xiên mũi kim từ chóp mũi chếch lên trên sâu 0,5 – 1 thốn."},{"h":"GIẢI PHẪU","body":"Dưới da là ngành ngang sụn cánh mũi, chỗ tiếp khớp của góc dưới – trước sụn lá mía và sụn cánh mũi.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh sọ não số V."}]},{"id":918,"ten":"Trạch Điền Hợp Cốc","sections":[{"h":"VỊ TRÍ","body":"Tại hố lào (nghiêng bàn tay, gần cổ tay sẽ hiện rõ chỗ trũng là hố lào), ngay sát dưới huyệt Dương Khê (Đtr."},{"h":"CHỦ TRỊ","body":"Trị mắt đỏ, mắt đau do chấn thương, cổ tay đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,1 – 0,3 thốn. Cứu 5 – 10 phút."}]},{"id":919,"ten":"Trạch Hạ","sections":[{"h":"VỊ TRÍ","body":"Huyệt Xích Trạch (P.5) đo xuống 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị răng đau, phía trước cánh tay đau, trĩ."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn.(\n,"}]},{"id":920,"ten":"Trạch Tiền","sections":[{"h":"VỊ TRÍ","body":"Dưới huyệt Xích Trạch (P.5) 1 thốn, hơi xiên ra phía trong, thẳng đường với ngón tay giữa."},{"h":"CHỦ TRỊ","body":"Trị bướu cổ, chi trên tê cứng."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn.[\nM"}]},{"id":921,"ten":"Trấp Hoa","sections":[{"h":"VỊ TRÍ","body":"Ngay giữa chân tóc trán (huyệt Tiền Phát Tế) đo ra 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, mắt đau, chóng mặt."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,3 – 0,5 thốn. Cẩn thận khi cứu.=\n!"}]},{"id":922,"ten":"Trật Biên","sections":[{"h":"VỊ TRÍ","body":"Ngang lỗ xương cùng thứ 4, cách Đốc Mạch 3 thốn, cách Trung Lữ Du 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị thần kinh tọa đau, chi dưới liệt và tê đau, bệnh ở phần hậu môn, sinh dục."},{"h":"CHÂM CỨU","body":"Thẳng khi trị dây thần kinh hông đau.\nThẳng, hướng mũi kim ra ngoài thấu huyệt Hoàn Khiêu (Đ.30) hoặc Khiêu Dược trị cơ mông yếu hoặc teo.\nXiên vào trong để trị bệnh ở cơ quan sinh dục.\nXiên xuống dưới vào trong trị bệnh ở hậu môn.\nCứu 3 – 7 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là cơ mông to, bờ dưới cơ tháp. Bên dưới là dây thần kinh mông dưới của tiết đoạn thần kinh thắt lưng 4 – 5, thần kinh cùng 1 – 2, nơi bắt đầu của thần kinh da đùi sau của tiết đoạn thần kinh cùng 1 – 3 và dây thần kinh hông của tiết đoạn thần kinh thắt lưng 4 cùng 3.\nThần kinh vận đọng cơ là nhánh của dây thần kinh mông trên, nhánh của đám rối cùng.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L4 và L5.\nSách Giáp Ất ghi không được cứu.\nSách Y Học Nhập Môn ghi cấm châm lẫn cứu."}]},{"id":923,"ten":"Trĩ Sang Huyệt","sections":[{"h":"VỊ TRÍ","body":"Giữa đốt xương cụt đo xuống 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị trĩ lở loét."},{"h":"CHÂM CỨU","body":"Cứu 3 – 5 tráng."}]},{"id":924,"ten":"Trị Chuyển Cân","sections":[{"h":"VỊ TRÍ","body":"Điểm giữa bờ trên mắt cá chân trong."},{"h":"CHỦ TRỊ","body":"Trị bắp chân bị co rút cơ, thắt lưng đau, khớp đau."},{"h":"CHÂM CỨU","body":"4L"}]},{"id":925,"ten":"Trị Lung Tân","sections":[{"h":"VỊ TRÍ","body":"Ở phía sau góc xương hàm dưới, bờ trước cơ ức – đòn – chũm, phía dưới cơ hai thân."},{"h":"CHỦ TRỊ","body":"Trị điếc."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ trước cơ ức – đòn – chũm, bờ sau của góc xương hàm dưới, phía dưới cơ 2 thân.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số XI, nhánh đám rối cổ sâu, dây thần kinh sọ não số XI.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C2 hoặc C3.DS\n[q:"}]},{"id":926,"ten":"Trị Não","sections":[{"h":"VỊ TRÍ","body":"Chính giữa đốt cổ 2 và 3."},{"h":"CHỦ TRỊ","body":"Trị bệnh ở não."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1–1,5 thốn."}]},{"id":927,"ten":"Trị Não II","sections":[{"h":"VỊ TRÍ","body":"Chính giữa đốt cổ 3 và 4."},{"h":"CHỦ TRỊ","body":"Trị bệnh ở não."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn."}]},{"id":928,"ten":"Trị Não III","sections":[{"h":"VỊ TRÍ","body":"Chính giữa đốt cổ 4 và 5."},{"h":"CHỦ TRỊ","body":"Trị bệnh ở não."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn."}]},{"id":929,"ten":"Trị Não IV","sections":[{"h":"VỊ TRÍ","body":"Chính giữa đốt cổ 5 và 6."},{"h":"CHỦ TRỊ","body":"Trị bệnh ở não."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn."}]},{"id":930,"ten":"Trị Não V","sections":[{"h":"VỊ TRÍ","body":"Chính giữa đốt cổ 6 và 7."},{"h":"CHỦ TRỊ","body":"Trị bệnh ở não."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn."}]},{"id":931,"ten":"Trị Não Tùng Tuyến Yếu Huyệt","sections":[{"h":"VỊ TRÍ","body":"Có tất cả 8 huyệt:\nTừ đường chính giữa gáy đo vào phía chân tóc gáy 0,5 thốn, là một huyệt.\nGiữa gai xương cổ 2 và 3 là một huyệt.\nGiữa gai xương cổ 3 – 4, 5 – 6 và 6 – 7 mỗi nơi một huyệt.\nGiữa gai đốt sống cổ 1 – 2 là một huyệt."},{"h":"CHỦ TRỊ","body":"Trị trở ngại tăng trưởng đại não."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,3 – 0,5 thốn."}]},{"id":932,"ten":"Triếp Cân","sections":[{"h":"VỊ TRÍ","body":"Trước huyệt Uyên Dịch 1 thốn, ngang giữa xương sườn thứ 5."},{"h":"CHỦ TRỊ","body":"Trị suyễn, nôn mửa, nuốt chua."},{"h":"CHÂM CỨU","body":"Châm xiên, sâu 0,5 – 0,8 thốn. Ôn cứu 5 –10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là chỗ bám của cơ răng cưa to, bờ dưới cơ ngực to, các cơ gian sườn 4, bên trong là phổi.\nThần kinh vận động cơ là các nhánh của đám rối thần kinh nách và dây thần kinh gian sườn 4."}]},{"id":933,"ten":"Trọc Dục","sections":[{"h":"VỊ TRÍ","body":"Gai xương sống lưng 10 đo ra 2,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị ăn uống không ngon, bệnh thuộc gan mật, Hysteria."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,5 – 1 thốn.'\n6H"}]},{"id":934,"ten":"Trúc Tân","sections":[{"h":"VỊ TRÍ","body":"Trên huyệt Thái Khê (Th.3) 5 thốn, sau bờ trong xương chày 2 thốn, khe giữa gân gót chân và cơ dép."},{"h":"CHỦ TRỊ","body":"Trị cơ bắp chân co rút, thắt lưng đau, động kinh, tâm thần phân liệt, Thận viêm, tiểu bí."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa gân gót chân và cơ dép, cơ duỗi dài các ngón chân, cơ chầy sau, màng gian cốt.\nThần kinh vận động cơ là các nhánh của dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L4."}]},{"id":935,"ten":"Trúc Trượng","sections":[{"h":"VỊ TRÍ","body":"Trên gai xương thắt lưng thứ 3."},{"h":"CHỦ TRỊ","body":"Trị ruột viêm, lao ruột, sa trực trường, trĩ, di chứng sau khi viêm não, di chứng liệt trẻ nhỏ."},{"h":"CHÂM CỨU","body":"Cứu."}]},{"id":936,"ten":"Trung Áp","sections":[{"h":"VỊ TRÍ","body":"Rốn đo xuống 4 thốn (huyệt Trung cực) ra ngang 2 bên mỗi bên 0,2 thốn."},{"h":"CHỦ TRỊ","body":"Trị tử cung sa."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 0,7 thốn."}]},{"id":937,"ten":"Trung Bình","sections":[{"h":"VỊ TRÍ","body":"Tại giữa lằn chỉ thứ 2 ngón tay giữa."},{"h":"CHỦ TRỊ","body":"Trị vòm miệng viêm."},{"h":"CHÂM CỨU","body":"Cứu 1 – 3 tráng. Ôn cứu 3 – 5 phút."}]},{"id":938,"ten":"Trung Chỉ Tiết","sections":[{"h":"VỊ TRÍ","body":"Mu tay, tại chỗ lõm giữa đường chỉ khớp 1 ngón tay giữa."},{"h":"CHỦ TRỊ","body":"Trị răng đau."},{"h":"CHÂM CỨU","body":"Cứu 7 tráng.F9\n)"}]},{"id":939,"ten":"Trung Chú","sections":[{"h":"VỊ TRÍ","body":"Trên huyệt Hoành Cốt 4 thốn, dưới rốn 1 thốn, cách tuyến giữa bụng 0,5 thốn, ngang huyệt Âm Giao (Nh."},{"h":"CHỦ TRỊ","body":"Trị bụng dưới đau, kinh nguyệt rối loạn, táo bón."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ chéo to của bụng, bờ trong cơ thẳng to, mạc ngang, phúc mạc, ruột non hoặc bàng quang khi bí tiểu tiện vừa, tử cung khi có thai 6 – 7 tháng.\nThần kinh vận động cơ là 6 nhánh dây thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D10."}]},{"id":940,"ten":"Trung Chử","sections":[{"h":"VỊ TRÍ","body":"Trên mu tay, giữa ngón tay xương bàn tay thứ 4 và thứ 5, trong chỗ lõm trên kẽ ngón tay 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị tai ù, điếc, đầu đau, họng đau, chi trên liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa gân duỗi ngón thứ 2 của cơ duỗi chung ngón tay và cơ duỗi riêng ngón tay thứ 5, cơ gian cốt mu tay, cơ gian cốt gan tay, cơ giun, bờ trong đầu dưới xương bàn tay 4.\nThần kinh vận động cơ là các nhánh của dây thần kinh quay và dây thần kinh trụ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C8 hoặc D1."}]},{"id":941,"ten":"Trung Củ","sections":[{"h":"VỊ TRÍ","body":"Há miệng, huyệt ở phía trong miệng, dưới góc xương hàm."},{"h":"CHỦ TRỊ","body":"Trị trúng phong lưỡi cứng không nói được, lưỡi khô."},{"h":"CHÂM CỨU","body":"Châm nặn máu."}]},{"id":942,"ten":"Trung Cực","sections":[{"h":"VỊ TRÍ","body":"Thẳng dưới rốn 4 thốn hoặc trên bờ xương mu 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị kinh không đều, thống kinh, di tinh, tiểu dầm, tiểu bí, liệt dương, xuất tinh sớm, bạch đới, hố khung chậu viêm, đường tiểu viêm nhiễm, sinh dục viêm nhiễm, phù thũng, thần kinh tọa đau, thận viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 2 thốn. Cứu 15 – 20 phút."},{"h":"GIẢI PHẪU","body":"Huyệt ở trên đường trắng, sau đường trắng là mạc ngang và phúc mạc. Vào sâu có ruột non khi bàng quang rỗng và không có thai; có bàng quang khi căng nước tiểu; có tử cung khi có thai.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L1 hoặc D12."}]},{"id":943,"ten":"Trung Đình","sections":[{"h":"VỊ TRÍ","body":"Chỗ 2 bờ sườn gặp nhau thành một góc nhọn (nơi người không có mũi ức), trên đường dọc giữa xương ức."},{"h":"CHỦ TRỊ","body":"Trị ngực tức, ợ, nấc."},{"h":"CHÂM CỨU","body":"Châm luồn kim dưới da hướng về phía bụng, sâu 0,3 – 1 thốn. Cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Huyệt ở trước khớp thân xương ức và mũi ức hoặc góc 2 bờ sườn gặp nhau. Có gân cơ ngực to (bó ức và bó các cơ thẳng to), cân cơ thẳng to bám vào xương.\nThần kinh vận động cơ do đám rối thần kinh nách và các dây thần kinh gian sườn.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D5."}]},{"id":944,"ten":"Trung Đô","sections":[{"h":"VỊ TRÍ","body":"Ở bờ sau xương chày, trên mắt cá trong 7 thốn."},{"h":"CHỦ TRỊ","body":"Trị kinh nguyệt rối loạn, đau do thoát vị, các khớp chi dưới đau."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là mặt trên – trong của xương chày.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L4."}]},{"id":945,"ten":"Trung Độc","sections":[{"h":"VỊ TRÍ","body":"Xác định huyệt Phong Thị (Đ.31) đo thẳng xuống 2 thốn, trên lằn nhượng chân 5 thốn, bờ sau cân cơ đùi, bờ trước cơ nhị đầu đùi."},{"h":"CHỦ TRỊ","body":"Trị thần kinh tọa đau, liệt nửa người, đùi đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 2 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ sau cân đùi và cơ rộng ngoài, bờ trước cơ 2 đầu đùi, cơ rộng giữa, xương đùi.\nThần kinh vận động cơ là nhánh day thần kinh mông trên, các nhánh dây thần kinh đùi và nhánh dây thần kinh hông.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L3.[30=[p2Châm đắc khí, tại chỗ có cảm giác căng tức, có khi như điện giật tê xuống chi dưới."}]},{"id":946,"ten":"Trung Khôi","sections":[{"h":"VỊ TRÍ","body":"Đỉnh cao nhất khớp đốt 2 và 3 ngón tay giữa, mặt sau bàn tay."},{"h":"CHỦ TRỊ","body":"Trị nôn mửa, nấc cụt, thực đạo co thắt, chảy máu mũi."},{"h":"CHÂM CỨU","body":"Cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là gân dưới ngón giữa của cơ duỗi chung các ngón tay. Khe khớp đốt xương 2, 3 của ngón tay giữa.\nThần kinh vận động cơ do nhánh của dây quay."}]},{"id":947,"ten":"Trung Không","sections":[{"h":"VỊ TRÍ","body":"Gai thắt lưng 5 đo ra 3,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị tổn thương tổ chức mềm ở vùng thắt lưng."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1,5 – 2 thốn."}]},{"id":948,"ten":"Trung Khu","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm dưới đầu mỏm gai đốt sống lưng 10."},{"h":"CHỦ TRỊ","body":"Trị cột sống đau, dạ dầy đau, mắt nhìn kém."},{"h":"CHÂM CỨU","body":"Châm kim chếch lên, luồn dưới mỏm gai hướng vào khoảng gian đốt sống lưng 10 – 11, sâu 0,3 – 1 thốn. Cứu 10 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là gân cơ thang, cân ngực – thắt lưng của cơ lưng to, cơ gai dài của lưng, cơ ngang gai, dây chằng trên gai, dây chằng gian gai, dây chằng vàng, ống sống.\nThần kinh vận động cơ là nhánh của dây thần kinh sọ não số XI, nhánh đám rối cổ sâu và các nhánh của dây thần kinh sống.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D8."}]},{"id":949,"ten":"Trung Liêu","sections":[{"h":"VỊ TRÍ","body":"Nơi lỗ xương thiêng 3, điểm giữa huyệt Trung Lữ Du (Bq.29) và Đốc Mạch."},{"h":"CHỦ TRỊ","body":"Trị bệnh thuộc về cơ quan sinh dục, vùng thắt lưng và xương cùng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân của cơ lưng to, khối cơ chung của các cơ ở rãnh cột sống, xương cùng.\nThần kinh vận động cơ là nhánh của đám rối cánh tay, nhánh của dây thần kinh sống cùng 3.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S3."}]},{"id":950,"ten":"Trung Lữ Du","sections":[{"h":"VỊ TRÍ","body":"Ngang đốt xương thiêng 3, cách đường giữa lưng 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị thần kinh tọa đau, thắt lưng và xương cùng đau, ruột viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 5 – 7 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân của cơ lưng to, khối cơ chung của các cơ rãnh cột sống, xương cùng.\nThần kinh vận động cơ là nhánh của đám rối cánh tay, nhánh của dây thần kinh sống cùng 3.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S2 hoặc S3."}]},{"id":951,"ten":"Trung Nhiêu","sections":[{"h":"VỊ TRÍ","body":"Co tay lại, mặt ngoài cẳng tay, mé trong lằn chỉ cổ tay (hướng xương trụ) đo thẳng lên 4 thốn."},{"h":"CHỦ TRỊ","body":"Trị điên."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 2 thốn."}]},{"id":952,"ten":"Trung Phong","sections":[{"h":"VỊ TRÍ","body":"Ở phía trước bờ dưới mắt cá trong 1 thốn, nơi chỗ lõm ở bờ trong gân cơ chày trước, khe khớp xương sên và xương gót, giữa huyệt Giải Khê (Vị) và Thương Khâu (Tỳ)"},{"h":"CHỦ TRỊ","body":"Trị vùng bụng dưới đau, thoát vị (sán khí), tiểu không được, dương vật đau, di tinh, gan viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ trong gân cơ chầy trước, khe khớp của xương sên và xương gót.\nThần kinh vận động cơ là nhánh của dây thần kinh chày trước.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5."}]},{"id":953,"ten":"Trung Phủ","sections":[{"h":"VỊ TRÍ","body":"Dưới cuối ngoài xương đòn gánh khoảng 01 thốn, hoặc giữa xương sườn 1 và 2, cách đường giữa ngực 06 thốn."},{"h":"CHỦ TRỊ","body":"Trị ho, hen suyễn, ngực đau, vai, lưng đau, viêm khí quản, lao phổi."},{"h":"CHÂM CỨU","body":"Châm thẳng hoặc xiên hướng kim ra ngoài, lên trên, sâu 05 – 1 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ ngực to, cơ ngực bé, cơ răng cưa to, các cơ gian sườn 2.\nThần kinh vận động cơ là dây thần kinh ngực to, dây thần kinh ngực bé, dây thần kinh răng to của đám rối thần kinh nách và dây thần kinh gian sườn 2.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C4."}]},{"id":954,"ten":"Trung Quản","sections":[{"h":"VỊ TRÍ","body":"Lỗ rốn thẳng lên 4 thốn hoặc lấy ở điểm giữa của đoạn thẳng nối rốn – và đường gặp nhau của 2 bờ sườn."},{"h":"CHỦ TRỊ","body":"Trị dạ dầy đau, ợ chua, nôn mửa, ăn không tiêu, đầy hơi, bụng trướng, kiết lỵ, tiêu chảy, huyết áp cao, thần kinh suy nhược."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 2 thốn, có thể hướng mũi kim xuyên sang 4 huyệt quanh đó bằng cách luồn kim dưới thịt. Cứu 10 – 30 phút."},{"h":"GIẢI PHẪU","body":"Huyệt ở trên đường trắng. Sau đường trắng là mạc ngang, phúc mạc. Sau thành bụng là phần ngang của dạ dày.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D8.\nChâm đắc khí, có cảm giác tê đau hướng lên gốc mũi, vùng xoang mũi."}]},{"id":955,"ten":"Trung Suyễn","sections":[{"h":"VỊ TRÍ","body":"Cuối đốt sống lưng thứ 5 ra ngang 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị suyễn, khí quản viêm, ngực đau, lưng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 0,8 thốn. Cứu 5 – 10 phút.,\n."}]},{"id":956,"ten":"Trung Tuyền","sections":[{"h":"VỊ TRÍ","body":"Ở lưng bàn tay, huyệt ở giữa 2 huyệt Dương Khê (Đtr.5) và Dương Trì (Ttu."},{"h":"CHỦ TRỊ","body":"Trị khí quản viêm, suyễn, trắng giác mạc, dạ dày đau, bệnh thuộc tổ chức mềm ở khớp cổ tay."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là góc giữa gân cơ duỗi dài chung các ngón tay và gân cơ duỗi dài riêng ngón tay cái, gân cơ quay 2, khe khớp xương cổ tay (ngửa tay lên xuống để tìm chỗ sũng của 2 gân).\nThần kinh vận động cơ do các nhánh của dây quay."}]},{"id":957,"ten":"Trung Xung","sections":[{"h":"VỊ TRÍ","body":"Tại điểm giữa của đầu ngón tay giữa."},{"h":"CHỦ TRỊ","body":"Trị hôn mê, kích ngất, sốt cao, tim đau quặn."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,1 – 0,2 thốn hoặc châm xuất huyết. Cứu 1– 3 tráng. Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là chỗ bám của gân ngón giữa, cơ gấp chung ngón tay sâu, đầu đốt 3 xương ngón tay giữa.\nThần kinh vận động cơ là nhánh của dây thần kinh giữa.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C7 hoặc C8."}]},{"id":958,"ten":"Trúng Ác Huyệt","sections":[{"h":"VỊ TRÍ","body":"Phía sau vú 3 thốn, từ đầu vú ra ngang về phía sườn 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị chứng ngũ thi, bụng đau, hông sườn đau, thần kinh gian sườn đau."},{"h":"CHÂM CỨU","body":"Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."}]},{"id":959,"ten":"Trúng Phong Bất Ngữ","sections":[{"h":"VỊ TRÍ","body":"Có 2 huyệt:\nDưới đốt sống lưng thứ 2.\nDưới đốt sống lưng thứ 5."},{"h":"CHỦ TRỊ","body":"Trị trúng phong không nói được."},{"h":"CHÂM CỨU","body":"Châm xiên luồn dưới da, sâu 0,3 – 0,5 thốn. Cứu 5 – 10 phút."}]},{"id":960,"ten":"Trúng Phong Thất Huyệt","sections":[{"h":"VỊ TRÍ","body":"Gồm 7 huyệt:\nBá Hội (Đc.20), Hợp Cốc (Đtr.4), Khúc Trì (Đtr.11), Phong Thị (Đ.31), Phong Trì (Đ.20), Thái Xung (C.3), Túc Tam Lý (Vi."},{"h":"CHỦ TRỊ","body":"Trị và đề phòng các loại trúng phong (tai biến mạch máu não)"},{"h":"CHÂM CỨU","body":"Xem từng huyệt."}]},{"id":961,"ten":"Truyền Thi Cứu","sections":[{"h":"VỊ TRÍ","body":"Huyệt Giải Khê (Vi.41) đo lên 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị lao phổi (truyền thi)"},{"h":"CHÂM CỨU","body":"Cứu 3 – 7 tráng, nam bên trái, gái bên phải."}]},{"id":962,"ten":"Trực Cốt","sections":[{"h":"VỊ TRÍ","body":"Đầu vú thẳng xuống 1 thốn (Phụ nữ kéo đầu vú xuống là huyệt)"},{"h":"CHỦ TRỊ","body":"Trị ôn ngược, ho lâu không khỏi."},{"h":"CHÂM CỨU","body":"Cứu 3 – 7 tráng."}]},{"id":963,"ten":"Trường Cường","sections":[{"h":"VỊ TRÍ","body":"Ở chỗ lõm sau hậu môn và trước đầu xương cụt 0,3 thốn."},{"h":"CHỦ TRỊ","body":"Trị trực tràng sa, trĩ, tiêu ra máu, cột sống đau, tiểu đục, tiểu khó, điên cuồng."},{"h":"CHÂM CỨU","body":"Châm thẳng vào bờ giữa xương cụt và trực tràng, sâu 0,3 – 1 thốn. Cứu 10 – 30 phút."},{"h":"GIẢI PHẪU","body":"Huyệt ở trên đường thớ hậu môn – xương cụt, có cơ thắt ngoài hậu môn và cơ nâng hậu môn (phần thắt) bám vào đường thớ này. Vào sâu là khoang dưới phúc mạc.\nThần kinh vận động cơ do nhánh đáy chậu của dây thần kinh thẹn trong.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S5.\nBệnh nhân có cảm giác tê như điện giật hoặc bủn rủn thì lập tức rút kim ra.MTÊN HUYỆT\nHuyệt có tác dụng trị bệnh về não, vì vậy gọi là Trị Não Huyệt."},{"h":"VỊ TRÍ","body":"Chính giữa đốt cổ 6 và 7."},{"h":"CHỦ TRỊ","body":"Trị bệnh ở não."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn."}]},{"id":964,"ten":"Trường Di","sections":[{"h":"VỊ TRÍ","body":"Rốn đo xuống 4 thốn (huyệt Trung Cực – Nh.3), xong đo ra 2,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị dương vật đau, dịch hoàn viêm, kinh nguyệt không đều, phần phụ viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn.C\nI"}]},{"id":965,"ten":"Trường Nhiễu","sections":[{"h":"VỊ TRÍ","body":"Rốn đo xuống 4 thốn (Trung Cực – Nh.3) đo ngang ra 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị táo bón."},{"h":"CHÂM CỨU","body":"Cứu.;\n\n,"}]},{"id":966,"ten":"Trường Phong","sections":[{"h":"VỊ TRÍ","body":"Gai đốt thắt lưng thứ 2 đo ra 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị tiểu dầm, bệnh thuộc Trường Vị, di tinh."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn."}]},{"id":967,"ten":"Trường Thâu Cơ Vận Động Điểm","sections":[{"h":"VỊ TRÍ","body":"Tại ¼ trong rãnh bụng đùi đo xuống 3 thốn, phía trong cơ may."},{"h":"CHỦ TRỊ","body":"Trị di chứng bại liệt trẻ nhỏ (Khớp gối lật ra ngoài)"},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 2 thốn."}]},{"id":968,"ten":"Trửu Chùy","sections":[{"h":"VỊ TRÍ","body":"Rốn đo xuống 4 thốn (huyệt Trung Cực – Nh.3), xong đo ra 2,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị dương vật đau, dịch hoàn viêm, kinh nguyệt không đều, phần phụ viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn.C\nI"}]},{"id":969,"ten":"Trửu Du","sections":[{"h":"VỊ TRÍ","body":"Phía sau cùi trỏ, co tay để tìm huyệt. Huyệt ở giữa mỏm khuỷu và mắt trên lồi ngoài xương cánh tay."},{"h":"CHỦ TRỊ","body":"Trị khớp khuỷu trỏ đau."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 thốn."}]},{"id":970,"ten":"Trửu Liêu","sections":[{"h":"VỊ TRÍ","body":"Từ huyệt Khúc Trì (Đtr.11) đo xiên lên ra ngoài 01 thốn, ở bờ ngoài đầu xương cánh tay."},{"h":"CHỦ TRỊ","body":"Trị khuỷu tay đau, lồi cầu xương cánh tay viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng hoặc xiên theo bờ trước xương cánh tay, sâu 0,5 – 1,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là rãnh giữa cơ 3 đầu cánh tay (phần rộng ngoài) và chỗ bám của cơ ngửa dài, cơ quay 1 và xương cánh tay. Thần kinh vận động cơ là nhánh của dây thần kinh quay. Da vùng huyệt chi phối bởi tiết đoạn thần kinh C5."}]},{"id":971,"ten":"Trửu Tiêm","sections":[{"h":"VỊ TRÍ","body":"Khi co tay, huyệt nằm trên đỉnh nhọn của mỏm lồi cùi chỏ xương trụ."},{"h":"CHỦ TRỊ","body":"Trị lao hạch cổ, đinh nhọt."},{"h":"CHÂM CỨU","body":"Cứu 10 – 20 phút."}]},{"id":972,"ten":"Tụ Tuyền","sections":[{"h":"VỊ TRÍ","body":"Trên lưỡi, đẩy lưỡi ra, huyệt ở chỗ lõm giữa lưỡi."},{"h":"CHỦ TRỊ","body":"Trị cơ lưỡi liệt, lưỡi có rêu, hen, suyễn, ho và ho lâu ngày không khỏi."},{"h":"CHÂM CỨU","body":"Châm nhanh, sâu 0,1 – 0,2 thốn. Châm cho ra ít máu (trị lưỡi sưng).\nCứu cách Gừng 5 – 7 phút, cứu xong nhai nhỏ miếng Gừng rồi nuốt với một ngụm nước chè (trị ho, hen suyễn)"},{"h":"GIẢI PHẪU","body":"Dưới huyệt là cơ lưỡi trên, vách lưỡi, cơ móng – lưỡi, cơ ngang lưỡi, cơ cằm – lưỡi.\nThần kinh vận động cơ là các nhánh của dây thần kinh sọ não số V.\nNiêm mạc vùng huyệt chi phối bởi tiết đoạn thần kinh sọ não số V."}]},{"id":973,"ten":"Túc Chủng","sections":[{"h":"VỊ TRÍ","body":"Trên gân gót chân, chỗ thịt giáp da trắng và đỏ, dưới huyệt Nữ Tất một ít."},{"h":"CHỦ TRỊ","body":"Trị hoắc loạn thổ tả, vàng da, thắt lưng đau, các loại độc do lạnh, nắng gây ra."},{"h":"CHÂM CỨU","body":"Cứu 3 – 10 tráng.0K\nQt"}]},{"id":974,"ten":"Túc Đại Chỉ Hoành Văn","sections":[{"h":"VỊ TRÍ","body":"Ở giữa đường chỉ ngang của khớp ngón chân cái."},{"h":"CHỦ TRỊ","body":"Trị ngất, lâm lịch, dịch hoàn viêm, thoái vị, thắt lưng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,1 – 0,2 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."}]},{"id":975,"ten":"Túc Ích Thông","sections":[{"h":"VỊ TRÍ","body":"Tại đầu nhỏ xương mác đo xuống 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị điếc, giun chui ống mật."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1,5 – 2 thốn."}]},{"id":976,"ten":"Túc Khiếu Âm","sections":[{"h":"VỊ TRÍ","body":"Bên ngoài ngón chân thứ 4, cách góc móng chân chừng 0,1 thốn. Huyệt trên đường tiếp giáp da gan chân – mu chân."},{"h":"CHỦ TRỊ","body":"Trị hen suyễn, màng ngực viêm, đầu đau, họng sưng, tai ù."},{"h":"CHÂM CỨU","body":"Châm xiên 0,1 – 0,2 thốn hoặc châm xuất huyết. Cứu 1 – 3 tráng, Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là xương ngón chân.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S1."}]},{"id":977,"ten":"Túc La","sections":[{"h":"VỊ TRÍ","body":"Bờ trên – trong khớp gối (huyệt Đại Luân) đo lên 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị kinh nguyệt không đều, đùi gối đau nhức."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 2 – 3 thốn.9\n-E"}]},{"id":978,"ten":"Túc Lâm Khấp","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm phía trước khớp xương bàn – ngón chân thứ 4 – 5."},{"h":"CHỦ TRỊ","body":"Trị sữa ít, tuyến vú viêm, kinh nguyệt rối loạn, bàn chân đau, tai ù, điếc."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Cứu 1 – 3 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ ngoài gân duỗi ngón chân thứ 5 của cơ duỗi chung các ngón chân, cơ gian cốt mu chân, khe giữa các đầu sau của các xương bàn chân 4 và 5.\nThần kinh vận động cơ là các nhánh của dây thần kinh chầy trước và nhánh của dây thần kinh chầy sau.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S1."}]},{"id":979,"ten":"Túc Minh","sections":[{"h":"VỊ TRÍ","body":"Bờ trên – trong khớp gối (huyệt Đại Luân) đo lên 2 khoát ngón tay."},{"h":"CHỦ TRỊ","body":"Trị khớp gối viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 2 – 3 thốn.C\n9"}]},{"id":980,"ten":"Túc Ngũ Lý","sections":[{"h":"VỊ TRÍ","body":"Ở bờ trong đùi, huyệt Âm Liêm (C.11) đo xuống 1 thốn, hoặc dưới nếp nhăn của bẹn 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị vùng bụng dưới đau, tiểu dầm, tiểu bí, ghẻ lở vùng bìu dái."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 2 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa cơ lược và cơ khép nhỡ, cơ khép bé và các cơ bịt.\nThần kinh vận động cơ là các nhánh của dây thần kinh bịt.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L2."}]},{"id":981,"ten":"Túc Tam Lý","sections":[{"h":"VỊ TRÍ","body":"Dưới mắt gối ngoài 3 thốn, phía ngoài xương mác khoảng 1 khoát ngón tay, nơi cơ cẳng chân trước, khe giữa xương chày và xương mác.\nHoặc úp lòng bàn tay vào giữa đầu gối, đầu ngón tay giữa chạm vào xương ống chân (xương chầy), từ đó hơi xịch ra phía ngoài một ít là huyệt.\nDưới lõm ngoài xương bánh chè (Độc Tỵ) 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị dạ dày đau, nôn mửa, tiêu hóa kém, táo bón, ruột viêm, chi dưới yếu liệt, bệnh thuộc hệ tiêu hóa, kích ngất, cơ thể suy nhược, thần kinh suy nhược."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn, cứu 5 – 10 tráng hoặc nhiều hơn, Ôn cứu 10 – 30 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ cẳng chân trước, chỗ bám các thớ gân cơ 2 đầu đùi, khe giữa xương chầy và xương mác, màng gian cốt.\nThần kinh vận động cơ là nhánh của dây thần kinh hông to, nhánh của dây thần kinh chầy trước.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh\n,\ngOq]2Xương ức rất mềm, nhất là trẻ nhỏ, vì vậy khi châm không được để kim thẳng góc với mặt da vì có thể xuyên qua xương vào bên trong. Châm vào xương sẽ gây cảm giác đau buốt.\nHuyệt này trở nên mẫn cảm (đau) đối với những người đang bị gan viêm truyền nhiễm (Châm Cứu Học Từ Điển)"}]},{"id":982,"ten":"Túc Tâm","sections":[{"h":"VỊ TRÍ","body":"Lòng bàn chân, từ huyệt Dũng Tuyền (Th.1) đo xuống phía gót chân một thốn."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, gót chân đau, rong kinh."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1,5 thốn."}]},{"id":983,"ten":"Túc Thái Âm Thái Dương Huyệt","sections":[{"h":"VỊ TRÍ","body":"Đỉnh mắt cá chân trong và ngoài đo ra phía sau 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị sinh đẻ khó, nhau thai không ra."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 thốn. Cứu 3 tráng."}]},{"id":984,"ten":"Túc Thiếu Dương Huyệt","sections":[{"h":"VỊ TRÍ","body":"Tại mu bàn chân, đường chính giữa khớp bàn chân thứ hai, phía trên khớp ngón chân 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị chứng Đởm bị thực, động kinh, trong bụng khó chịu."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,1 – 0,2 thốn. Cứu tùy theo số tuổi.0Z\n7w"}]},{"id":985,"ten":"Túc Trung Bình","sections":[{"h":"VỊ TRÍ","body":"Huyệt Túc Tam Lý (Vi.36) đo xuống 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị bệnh tâm thần, liệt chi dưới."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 2 – 3 thốn."}]},{"id":986,"ten":"Túc Tủy Khổng","sections":[{"h":"VỊ TRÍ","body":"Tại sau mắt cá chân ngoài 1 thốn (tại chỗ lõm giữa mắt cá chân ngoài và gân gót – tức huyệt Côn Lôn)"},{"h":"CHỦ TRỊ","body":"Trị liệt nửa người."},{"h":"CHÂM CỨU","body":"Cứu.f\nN"}]},{"id":987,"ten":"Tuyền Âm","sections":[{"h":"VỊ TRÍ","body":"Giữa xương háng đo ra mỗi bên 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị sán khí, dịch hoàn viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."}]},{"id":988,"ten":"Tuyền Cơ","sections":[{"h":"VỊ TRÍ","body":"Ở điểm gặp nhau của đường dọc giữa xương ức và đường ngang qua bờ trên khớp ức – sườn thứ 1."},{"h":"CHỦ TRỊ","body":"Trị ngực đau, ho suyễn."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 1 thốn. Cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là đầu trên xương ức.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C3."}]},{"id":989,"ten":"Tuyền Môn","sections":[{"h":"VỊ TRÍ","body":"Từ đầu trên âm hộ kéo ngang ra đụng vào nếp háng là huyệt."},{"h":"CHỦ TRỊ","body":"Trị phụ nữ không có con, xích bạch đới, kinh nguyệt không đều, bế kinh."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn. Cứu 1 – 3 tráng. Ôn cứu 5 – 10 phút.;\nHD"}]},{"id":990,"ten":"Tuyền Sinh Túc","sections":[{"h":"VỊ TRÍ","body":"Gân gót chân, huyệt ở chính giữa trên gân lớn, bờ trên xương gót chân."},{"h":"CHỦ TRỊ","body":"Trị thực đạo co thắt, bệnh ở não, thắt lưng đau, sinh đẻ khó."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,2 – 0,3 thốn."}]},{"id":991,"ten":"Tuyệt Dựng","sections":[{"h":"VỊ TRÍ","body":"Rốn đo xuống 2,3 thốn (tức huyệt Thạch Môn [Nh.5) đo xuống 0,3 thốn)"},{"h":"CHỦ TRỊ","body":"Trị trẻ nhỏ bị tiêu chảy, phụ nữ muốn không thụ thai."},{"h":"CHÂM CỨU","body":"Cứu.n\n6]"}]},{"id":992,"ten":"Tứ Bạch","sections":[{"h":"VỊ TRÍ","body":"Ngay giữa mi dưới thẳng xuống 1 thốn, chỗ lõm dưới hố mắt, bờ dưới cơ vòng mi."},{"h":"CHỦ TRỊ","body":"Trị liệt mặt, thần kinh mặt co rút, đầu đau, giun chui ống mật."},{"h":"CHÂM CỨU","body":"Châm thẳng hoặc xiên. Trị thần kinh tam thoa đau, có thể châm xiên từ dưới hướng ra phía ngoài, lên trên, sâu 0,3 – 0,5 thốn. Không cứu."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ dưới cơ vòng mi (phần ổ mắt), trên chỗ bám của cơ gò má (một cơ thuộc cơ vuông môi trên), chỗ tiếp khớp của xương gò má với xương hàm trên.\nThần kinh vận động cơ là các nhánh của dây thần kinh sọ não số V.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V."}]},{"id":993,"ten":"Tứ Độc","sections":[{"h":"VỊ TRÍ","body":"Ở mặt sau cẳng tay, dưới khớp khuỷu 5 thốn, giữa khe xương trụ và xương quay."},{"h":"CHỦ TRỊ","body":"Trị điếc, răng đau, cánh tay đau."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là khe giữa cơ duỗi chung ngón tay và cơ duỗi riêng ngón tay út, cơ dạng dài ngón cái, màng gian cốt.\nThần kinh vận động cơ là các nhánh của dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C7.\nThiên Thích Ngược Luận: “Bệnh sốt rét, phát từ Can, sắc mặt tái xanh, hay thở dài như người sắp chết, nên thích Túc Quyết Âm (h. Trung Phong) cho ra máu” (Tố Vấn 36, 9)"}]},{"id":994,"ten":"Tứ Hoa","sections":[{"h":"VỊ TRÍ","body":"Gồm 2 huyệt Cách Du (Bq.17) và 2 huyệt Đởm Du (Bq.19), tất cả 4 huyệt."},{"h":"CHỦ TRỊ","body":"Trị khí quản viêm, suyễn, phế khí thũng, lao phổi."},{"h":"CHÂM CỨU","body":"Cứu.G\n3["}]},{"id":995,"ten":"Tứ Hoa Lục Huyệt","sections":[{"h":"VỊ TRÍ","body":"Gồm Tứ Hoa Huyệt + Khí Hải (Nh.6) và Trường Cường (Đc."},{"h":"CHỦ TRỊ","body":"Trị ngũ lao, thất thương, khí huyết hư tổn, ngũ tâm phiền nhiệt, cốt chưng, gầy yếu, mỏi mệt, ho đờm, suyễn."},{"h":"CHÂM CỨU","body":"Cứu. Lúc đầu cứu 7 hoặc 14 hoặc 21 tráng cho đến 100 tráng.:\nmh"}]},{"id":996,"ten":"Tứ Lý","sections":[{"h":"VỊ TRÍ","body":"Xác định huyệt Túc Tam Lý (Vi.36), đo xuống 1 – 1,5 thốn, từ xương mác đo ra chừng 2 khoát ngón tay."},{"h":"CHỦ TRỊ","body":"Trị di chứng liệt trẻ nhỏ."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn."}]},{"id":997,"ten":"Tứ Mãn","sections":[{"h":"VỊ TRÍ","body":"Rốn đo xuống 2 thốn (huyệt Thạch Môn [Nh.5]) ra ngang 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị tử cung xuất huyết, bạch đới, kinh nguyệt không đều, tiêu chảy."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ chéo to của bụng, bờ trong cơ thẳng to mạc ngang, phúc mạc, ruột non hoặc bàng quang khi bí tiểu ít, tử cung khi có thai 5 – 6 tháng.\nThần kinh vận động cơ là 6 nhánh thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D11."}]},{"id":998,"ten":"Tứ Phùng","sections":[{"h":"VỊ TRÍ","body":"Đốt giữa của 4 ngón tay. Điểm giữa lằn chỉ gấp mặt trước của khớp đốt 1, 2 của các ngón tay 2, 3, 4, 5."},{"h":"CHỦ TRỊ","body":"Trị ho gà, trẻ nhỏ tiêu hóa kém, cam tích, khớp ngón tay viêm, giun ở ruột."},{"h":"CHÂM CỨU","body":"Dùng kim Tam lăng châm nặn ra máu hoặc nước vàng."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là gân cơ gấp chung các ngón tay, khe khớp đốt 1 và 2 của ngón tay\nThần kinh vận động cơ do các nhánh của dây thần kinh giữa và thần kinh trụ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C7 và C8.h\nL3NK8"}]},{"id":999,"ten":"Tứ Thần Thông","sections":[{"h":"VỊ TRÍ","body":"Xác định huyệt Bá Hội, rồi đo tới trước và sau (trên Đốc mạch) và 2 bên phải trái mỗi đoạn 1 thốn. Tất cả gồm 4 huyệt."},{"h":"CHỦ TRỊ","body":"Trị đỉnh đầu đau, đầu căng thẳng, thần kinh suy nhược, động kinh."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,5–1 thốn."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là cân sọ, xương đỉnh.\nDa vùng huyệt chi phối bởi tiết đoạn C2.w\nB!"}]},{"id":1000,"ten":"Từ Cung","sections":[{"h":"VỊ TRÍ","body":"Huyệt Hoành Cốt (Th.11) đo ngang ra 2,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị tiêu chảy, lỵ, kinh nguyệt không đều."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 – 1 thốn. Cứu 5 – 7 tráng. Ôn cứu 10 – 15 phút."}]},{"id":1001,"ten":"Tử Cung","sections":[{"h":"VỊ TRÍ","body":"Ở điểm gặp nhau của đường dọc giữa xương ức và đường ngang qua giữa 2 khớp ức – sườn 4."},{"h":"CHỦ TRỊ","body":"Trị ngực đau, suyễn, nôn mửa."},{"h":"CHÂM CỨU","body":"Châm luồn kim dưới da, sâu 0,3 – 1 thốn. Cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là xương ức.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D2."}]},{"id":1002,"ten":"Tử Cung II","sections":[{"h":"VỊ TRÍ","body":"Rốn xuống 4 thốn (huyệt Trung Cực – Nh.3) đo ra 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị tử cung sa, kinh nguyệt không đều, thống kinh, hố khung chậu viêm, đàn bà không mang thai, thận viêm, thận sa, thận lớn, bàng quang viêm, dịch hoàn viêm, ruột thừa viêm."},{"h":"CHÂM CỨU","body":"Châm thẳng hoặc ngang, tới liên hợp xương mu sâu 1,5 – 2,5 thốn."}]},{"id":1003,"ten":"Tử Cung Cảnh","sections":[{"h":"VỊ TRÍ","body":"Xác định vùng cổ tử cung, chọn 12 điểm quanh đó để châm."},{"h":"CHỦ TRỊ","body":"Trị cổ tử cung viêm mạn tính."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,5 thốn, kích thích xong rút kim ra, không vê kim."}]},{"id":1004,"ten":"Tử Cung Xuất Huyết Điểm","sections":[{"h":"VỊ TRÍ","body":"Từ đỉnh xương cụt đo thẳng lên thắt lưng 5 thốn làm điểm chuẩn, từ đó đo ra hai bên, mỗi bên 2,5 thốn, thành hai huyệt. Từ điểm chuẩn lại đo lên 1 thốn, làm thành một điểm, từ đó lại đo ra ngang hai bên mỗi bên 2,5 thốn, thành hai điểm nữa. Tổng cộng có 6 điểm."},{"h":"CHỦ TRỊ","body":"Trị băng huyết, rong kinh, thắt lưng đau."},{"h":"CHÂM CỨU","body":"Cứu 7 – 15 tráng."}]},{"id":1005,"ten":"Tử Hộ","sections":[{"h":"VỊ TRÍ","body":"Giữa rốn xuống 3 thốn (huyệt Quan Nguyên (Nh.4), đo ngang ra về bên phải 2 thốn."},{"h":"CHỦ TRỊ","body":"Trị bạch đới, không thụ thai."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn. Cứu 15 – 50 tráng. Ôn cứu 20 – 30 phút."}]},{"id":1006,"ten":"Tử Trường","sections":[{"h":"VỊ TRÍ","body":"Rốn xuống 4 thốn (Trung Cực (Nh.3) đo ra 3,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị tử cung sa."},{"h":"CHÂM CỨU","body":"Châm 1,2 – 1,5 thốn. Cứu 5–10 tráng."}]},{"id":1007,"ten":"Ty Trúc Không","sections":[{"h":"VỊ TRÍ","body":"Tại chỗ lõm bên ngoài đuôi lông mày, ấn vào có cảm giác ê tức, bờ ngoài cơ vòng mi."},{"h":"CHỦ TRỊ","body":"Trị đầu đau, các bệnh về mắt."},{"h":"CHÂM CỨU","body":"Châm ngang, mũi kim có thể thấu Ngư Yêu, sâu 0,5 – 1 thốn. Không cứu."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ ngoài cơ vòng mi và phần bám vào da cung mày của cơ trán, xương trán.\nThần kinh vận động cơ là các nhánh của dây thần kinh mặt.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V.\nDa vùng huyệt chi phối bởi dây thần kinh sọ não số V."}]},{"id":1008,"ten":"Tý Nhu","sections":[{"h":"VỊ TRÍ","body":"Huyệt ở đầu cuối của cơ tam giác cánh tay, trên đường nối huyệt Khúc Trì (Đtr.11) và Kiên Ngung (Đtr."},{"h":"CHỦ TRỊ","body":"Trị vai đau, cánh tay đau, liệt chi trên, bệnh mắt."},{"h":"CHÂM CỨU","body":"Châm thẳng hoặc châm vào bờ sau – trước xương cánh tay, sâu 1 – 1,5 thốn. Khi bị bệnh về mắt, hướng mũi kim xiên lên phía giữa cơ Delta.\nCứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là đỉnh cơ Delta, bờ ngoài cơ 2 đầu cánh tay, chỗ bám của cơ cánh tay trên vào xương, phía sau là phần rộng ngoài của cơ 3 đầu cánh tay, xương cánh tay.\nThần kinh vận động cơ là nhánh của dây thần kinh mũ, các nhánh của dây thần kinh cơ da và nhánh của dây thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh w22"}]},{"id":1009,"ten":"Tý Thạch Tử Đầu","sections":[{"h":"VỊ TRÍ","body":"Huyệt Thái Uyên (P.9) đo ngang ra mặt sau cổ tay 3 thốn. Ngay sát huyệt Dương Trì (Ttu."},{"h":"CHỦ TRỊ","body":"Trị hoàng đản."},{"h":"CHÂM CỨU","body":"Cứu 5 – 7 tráng."}]},{"id":1010,"ten":"Tý Trung","sections":[{"h":"VỊ TRÍ","body":"Xác định giữa nếp gấp cổ tay trong và nếp gấp cánh tay – cẳng tay.\nDưới huyệt Tứ Độc (Ttu.9) 1 thốn, giữa 2 xương tay quay và xương trụ."},{"h":"CHỦ TRỊ","body":"Trị chi trên bị liệt hoặc co giật, thần kinh cánh tay trước đau, Hysteria."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,3 – 0,5 thốn. Có thể châm xuyên qua phía bên kia.0.CE\nKÌ"}]},{"id":1011,"ten":"Tỳ Bà Huyệt","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm ngay bên dưới huyệt Kiên Tỉnh (Đ."},{"h":"CHỦ TRỊ","body":"Trị vùng vai đau, chi trên liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."}]},{"id":1012,"ten":"Tỳ Du","sections":[{"h":"VỊ TRÍ","body":"Dưới gai sống lưng 11, đo ngang ra 1,5 thốn, ngang huyệt Tích Trung (Đc."},{"h":"CHỦ TRỊ","body":"Trị dạ dày viêm loét, dạ dầy đau, tiêu chảy mạn tính, gan viêm, sốt sét, bệnh xuất huyết mạn tính, phong ngứa, cơ bụng liệt."},{"h":"CHÂM CỨU","body":"Châm xiên về cột sống 0,5– 0,8 thốn. Cứu 5–7 tráng. Ôn cứu 10 – 20 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân ngực – thắt lưng của cơ lưng to, cơ răng bé sau – dưới, cơ lưng dài, cơ bán gai của ngực, cơ ngang gai, cơ ngang sườn, tuyến thượng thận.\nThần kinh vận động cơ là nhánh đám rối cánh tay, nhánh dây thần kinh gian sườn 11 và nhánh của dây sống lưng 11.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D11."}]},{"id":1013,"ten":"Tỳ Hoành","sections":[{"h":"VỊ TRÍ","body":"Đốt sống lưng thứ 11 ra ngang 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị tay chân bị nóng lạnh, lưng đau không cúi ngửa được, bụng đầy, nôn mửa, cơ thể vàng, lưỡi cứng."},{"h":"CHÂM CỨU","body":"Cứu.(\ndk"}]},{"id":1014,"ten":"Tỳ Nhiệt Huyệt","sections":[{"h":"VỊ TRÍ","body":"Gai xương sống lưng thứ 6 đo ra 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị gan viêm, tụy tạng viêm, lách sưng lớn."}]},{"id":1015,"ten":"Tỵ Giao Át Trung","sections":[{"h":"VỊ TRÍ","body":"Tại nơi cao nhất của xương mũi, hơi lên phía ngoài một ít, giữa chỗ lõm."},{"h":"CHỦ TRỊ","body":"Trị động kinh, trúng phong, mặt có cảm giác như trùng bò, trúng phong đột ngột, ngủ nhiều, hay quên, cấm khẩu, bất tỉnh, hoàng đản, cấp hoàng, bát chủng đại phong."},{"h":"CHÂM CỨU","body":"Cứu hoặc châm luồn dưới da, sâu 0,3–0,5 thốn."}]},{"id":1016,"ten":"Tỵ Hoàn","sections":[{"h":"VỊ TRÍ","body":"Cánh mũi hơi xếch lên phía trên, huyệt ở chỗ lõm. Trên đường biên giữa cánh mũi và vùng má, ngang điểm giữa cánh mũi."},{"h":"CHỦ TRỊ","body":"Trị mặt và trán có mụn nhọt lở loét, tửu tra tỵ."},{"h":"CHÂM CỨU","body":"Châm luồn dưới da sâu 0,3–0,5 thốn hoặc dùng kim tam lăng châm cho ra máu.v\n1K"}]},{"id":1017,"ten":"Tỵ Lưu","sections":[{"h":"VỊ TRÍ","body":"Chính giữa lỗ mũi (huyệt ở trung điểm của cánh mũi và trụ mũi). Điểm giữa vào đường thẳng ngang nhân trung kéo ra và đường thẳng giữa lỗ mũi xuống."},{"h":"CHỦ TRỊ","body":"Trị trúng phong, mũi viêm, mũi nghẹt, chảy nước mũi, liệt mặt, thần kinh sinh ba đau."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,3 – 0,5 thốn."}]},{"id":1018,"ten":"Tỵ Tiếu","sections":[{"h":"VỊ TRÍ","body":"Xác định huyệt Nghênh Hương kéo xuống, huyệt nằm ở giữa rãnh mũi – miệng."},{"h":"CHỦ TRỊ","body":"Trị mũi viêm, liệt mặt, mặt co giật."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,3 – 0,5 thốn."}]},{"id":1019,"ten":"Tỵ Trụ","sections":[{"h":"VỊ TRÍ","body":"Tại 2 bên cạnh chân viền dưới cánh mũi, điểm thấp nhất của chân cánh mũi."},{"h":"CHỦ TRỊ","body":"Trị chảy nước mũi."},{"h":"CHÂM CỨU","body":"Cứu 7 tráng.0J\nY"}]},{"id":1020,"ten":"U Môn","sections":[{"h":"VỊ TRÍ","body":"Trên rốn 6 thốn, cách đường giữa bụng 0,5 thốn, ngang huyệt Cự Khuyết (Nh 14)"},{"h":"CHỦ TRỊ","body":"Trị ngực đau, nôn mửa, tiêu chảy, ợ hơi, dạ dầy co thắt."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Cứu 5 – 7 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân cơ chéo to của bụng, bờ trong cơ thẳng to, mạc ngang, phúc mạc, gan.\nThần kinh vận động cơ là 6 nhánh thần kinh gian sườn dưới và dây thần kinh bụng – sinh dục.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D6.\nThiên Quyết Bệnh ghi: “Tai bị điếc, châm huyệt ở ngón tay áp út (Quan Xung (Ttu.1))... Trước hết chọn huyệt ở tay, sau đó chọn huyệt ở chân Túc Khiếu Âm” (Linh Khu 28, 26)"}]},{"id":1021,"ten":"Uy Linh","sections":[{"h":"VỊ TRÍ","body":"Mu bàn tay, tại điểm giữa của xương bàn tay thứ hai và thứ ba, chỗ lõm phía tay quay gân cơ duỗi ngón tay thứ hai."},{"h":"CHỦ TRỊ","body":"Trị chấn thương thắt lưng cấp, đầu đau, chết đuối, đàm chận làm cho khó thở, động kinh, mu bàn tay sưng đỏ, mu bàn tay đau nhức."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn."}]},{"id":1022,"ten":"Ủy Dương","sections":[{"h":"VỊ TRÍ","body":"Ở đầu ngoài nếp nhượng chân, mặt sau lồi cầu ngoài xương đùi, giữa 2 gân cơ nhị đầu đùi và cơ gan chân."},{"h":"CHỦ TRỊ","body":"Trị lưng đau, cơ bắp chân bị co thắt, thận viêm, tiểu ra dưỡng trấp."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là góc giữa 2 gân cơ 2 đầu đùi và cơ gan chân gầy, mặt sau lồi cầu ngoài xương đùi.\nThần kinh vận động cơ là nhánh của dây thần kinh hông và nhánh của dây hông kheo ngoài.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L3."}]},{"id":1023,"ten":"Ủy Trung","sections":[{"h":"VỊ TRÍ","body":"Ngay giữa lằn chỉ ngang nếp nhượng chân."},{"h":"CHỦ TRỊ","body":"Trị khớp gối viêm, cơ bắp chân co rút, vùng lưng và thắt lưng đau, thần kinh tọa đau, liệt chi dưới, trúng nắng."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn – khi trị chấn thương cấp ở vùng thắt lưng, dùng kim tam lăng chích nặn ra máu."},{"h":"GIẢI PHẪU","body":"Dưới da là chính giữa vùng chám kheo, khe khớp gối.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S2."}]},{"id":1024,"ten":"Ủy Trung Đinh Tự Thích","sections":[{"h":"VỊ TRÍ","body":"Từ huyệt Ủy Dương châm thẳng đến Khúc Tuyền là một huyệt, Ủy Trung là một huyệt, hai huyệt này tạo thành một nhóm huyệt."},{"h":"CHỦ TRỊ","body":"Trị liệt chi dưới, di chứng bại liệt trẻ nhỏ, chân tê."},{"h":"CHÂM CỨU","body":"Từ huyệt Ủy Dương, châm xiên kim về huyệt Khúc Tuyền, châm thẳng một kim ở huyệt Ủy Trung, sâu 1 thốn.0y\n7g"}]},{"id":1025,"ten":"Uyên Dịch","sections":[{"h":"VỊ TRÍ","body":"Dưới nếp nách trước 3 thốn, ở khoảng gian sườn 4, bờ trước cơ lưng to."},{"h":"CHỦ TRỊ","body":"Trị màng ngực viêm, thần kinh gian sườn đau, hạch nách sưng."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 0,8 thốn. Ôn cứu 3–5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ trước cơ lưng to, cơ răng cưa to, các cơ gian sườn 4, phổi.\nThần kinh vận động cơ là các nhánh của đám rối thần kinh nách và dây thần kinh gian sườn 4.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D4."}]},{"id":1026,"ten":"Uyển Cốt","sections":[{"h":"VỊ TRÍ","body":"Phía bờ trong bàn tay, nơi chỗ lõm giữa xương móc và xương bàn tay 5, trên đường tiếp giáp da gan tay, mu tay."},{"h":"CHỦ TRỊ","body":"Trị khớp khuỷu tay, cổ tay, ngón tay viêm, đầu đau, tai ù, nôn mửa, tiểu đường.\nChâm trong những trường hợp tay không sức, không cầm được đồ vật (Biển Thước Tâm Thư)"},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn. Cứu 3 – 5 tráng, ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ da gan tay, cơ dạng ngón út, chỗ lõm giữa đầu trên xương bàn tay 5 và xương tháp, đáy chỗ lõm là xương móc.\nThần kinh vận động cơ là các nhánh của dây thần kinh trụ.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D1."}]},{"id":1027,"ten":"Ưng Song","sections":[{"h":"VỊ TRÍ","body":"Ở khoảng gian sườn 3, trên đường thẳng qua đầu ngực, cách đường giữa ngực 4 thốn (ngang huyệt Ngọc Đường – Nh.18), nơi cơ ngực to."},{"h":"CHỦ TRỊ","body":"Trị thần kinh liên sườn đau, tuyến vú viêm, suyễn, ho, sôi ruột, tiêu chảy."},{"h":"CHÂM CỨU","body":"Châm xiên 0,3 – 0,5 thốn, cứu 3 – 5 tráng, ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ ngực to, cơ ngực bé, các cơ gian sườn 3, bờ trên xương sườn 4, bên trong có phổi và tim ở bên trái.\nThần kinh vận động cơ là nhánh ngực to, nhánh ngực bé của đám rối thần kinh nách, dây thần kinh gian sườn 2 – 3.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D3."}]},{"id":1028,"ten":"Vân Môn","sections":[{"h":"VỊ TRÍ","body":"Bờ dưới xương đòn gánh, nơi chỗ lõm ngang cơ ngực to, giữa cơ Delta, nơi có gian sườn 1, cách đường ngực 06 thốn, trên huyệt Trung Phủ 1,6 thốn."},{"h":"CHỦ TRỊ","body":"Trị ho, suyễn, ngực đầy tức, lưng đau."},{"h":"CHÂM CỨU","body":"Châm thẳng hoặc xiên, sâu 0,5 – 1 thốn. Cứu 3 – 5 tráng, Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là rãnh Delta ngực, cơ ngực to, cơ Delta, cơ dưới đòn, cơ răng cưa to và các cơ gian sườn 1.\nThần kinh vận động cơ là dây thần kinh ngực to, dây thần kinh mũ, dây thần kinh dưới đòn, dây thần kinh răng to của đám rối thần kinh nách và dây thần kinh gian sườn 1.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C4."}]},{"id":1029,"ten":"Vết Vị Trường Điểm","sections":[{"h":"VỊ TRÍ","body":"Ngửa bàn tay, điểm giữa nếp gấp cổ tay (huyệt Đại Lăng) và giữa lòng bàn tay (huyệt Lao Cung)"},{"h":"CHỦ TRỊ","body":"Trị khó tiêu, bao tử loét, ruột viêm cấp và mạn tính, giun chui ống mật."}]},{"id":1030,"ten":"Vĩ Cốt Bàng","sections":[{"h":"VỊ TRÍ","body":"Xác định huyệt Hội Âm (Nh.1), rồi đo ra 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị đại tiểu tiện không tự chủ do bại liệt."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 2 – 3 thốn."}]},{"id":1031,"ten":"Vĩ Cùng Cốt","sections":[{"h":"VỊ TRÍ","body":"Đỉnh xương cùng lên 1 thốn, ra ngang 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị lưng đau, xương cùng đau, táo bón, tiểu bí, trĩ."},{"h":"CHÂM CỨU","body":"Cứu 3 – 5 tráng. Ôn cứu 5 – 10 phút.\n-\n5g"}]},{"id":1032,"ten":"Vĩ Thúy","sections":[{"h":"VỊ TRÍ","body":"Đỉnh xương cùng thẳng lên 3 thốn, huyệt ở chỗ lõm."},{"h":"CHỦ TRỊ","body":"Trị trẻ nhỏ cam tích, tiêu hóa không tốt, bụng đau, hạ lỵ, thoát giang."},{"h":"CHÂM CỨU","body":"Châm luồn dưới da sâu 0,5 – 1 thốn. Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút.3\nHI"}]},{"id":1033,"ten":"Vị Du","sections":[{"h":"VỊ TRÍ","body":"Dưới gai sống lưng 12, đo ngang ra 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị dạ dày đau, dạ dày viêm, dạ dày loét, dạ dày sa, no hơi, nôn mửa, tiêu chảy mạn tính, cơ bụng liệt."},{"h":"CHÂM CỨU","body":"Châm xiên về phía cột sống, sâu 0,5 – 08 thốn. Cứu 3–5 tráng. Ôn cứu 5–10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân ngực-thắt lưng của cơ lưng to, cơ răng bé sau – dưới, cơ lưng dài, cơ ngang gai, cơ gian mỏm ngang, cơ vuông thắt lưng, cơ đái – chậu.\nThần kinh vận động cơ là nhánh của đám rối cánh tay, nhánh dây thần kinh gian sườn 1, nhánh dây sống lưng 12, nhánh của đám rối thắt lưng.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D12."}]},{"id":1034,"ten":"Vị Lạc","sections":[{"h":"VỊ TRÍ","body":"Rốn đo lên 1,2 thốn (huyệt Thủy Phân (Nh.9) đo lên 0,2 thốn) rồi đo ngang ra 4 thốn."},{"h":"CHỦ TRỊ","body":"Trị dạ dày đau, dạ dày sa."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 1,5 thốn."}]},{"id":1035,"ten":"Vị Nhiệt Huyệt","sections":[{"h":"VỊ TRÍ","body":"Gai xương sống thứ 4 đo ra 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị nôn mửa, lợi răng sưng, dạ dày đau."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 1 thốn."}]},{"id":1036,"ten":"Vị Quản Hạ Du","sections":[{"h":"VỊ TRÍ","body":"Gai sống lưng thứ 8 đo ngang ra 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị tiểu đường, bệnh dạ dầy, thần kinh liên sườn đau."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 1 thốn."}]},{"id":1037,"ten":"Vị Thư","sections":[{"h":"VỊ TRÍ","body":"Nơi giao giới của cơ cùng thắt lưng, tương đương với gai xương thắt lưng thứ 2 đo ra 4,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị dạ dày đau, dạ dày co thắt, dạ dày loét."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 2 thốn."}]},{"id":1038,"ten":"Vị Thương","sections":[{"h":"VỊ TRÍ","body":"Dưới gai sống lưng 12, đo ngang ra 3 thốn, cách Vị Du 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị dạ dày đau, táo bón, nôn mửa, cột sống lưng đau, bụng đau."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 0,8 thốn. Cứu 5 – 7 tráng. Ôn cứu 10 – 20 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ lưng to, cơ răng cưa bé sau – dưới, cơ chậu sườn – thắt lưng, cơ vuông thắt lưng, Thận.\nThần kinh vận động cơ là nhánh đám rối cánh tay, nhánh dây sống lưng 12.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D11."}]},{"id":1039,"ten":"Xích Huyệt","sections":[{"h":"VỊ TRÍ","body":"Xác định huyệt Toàn Cơ (Nh.21) xong đo ra 1 thốn."},{"h":"CHỦ TRỊ","body":"Trị ho, suyễn, thần kinh liên sườn đau."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,5 – 1 thốn.2\n("}]},{"id":1040,"ten":"Xích Nhiêu","sections":[{"h":"VỊ TRÍ","body":"Mặt lưng cánh tay, chính giữa nếp nhăn lằn chỉ cổ tay đo lên 6 thốn."},{"h":"CHỦ TRỊ","body":"Trị chi trên liệt, bệnh tâm thần."},{"h":"CHÂM CỨU","body":"Châm thẳng xuyên qua da mặt tay bên kia.\nE\n\""}]},{"id":1041,"ten":"Xích Trạch","sections":[{"h":"VỊ TRÍ","body":"Gấp nếp khuỷu tay lại, huyệt ở chỗ lõm bờ ngoài gân cơ nhị đầu cánh tay, bờ trong phần trên cơ ngửa dài, cơ cánh tay trước."},{"h":"CHỦ TRỊ","body":"Trị khuỷu tay sưng đau, cánh tay sưng đau, ho, suyễn, họng viêm, amidal viêm, ho ra máu."},{"h":"CHÂM CỨU","body":"Châm thẳng 0,5 – 1 thốn. Ôn cứu 5 – 10 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ ngoài gân cơ 2 đầu cánh tay, rãnh 2 đầu ngoài, bờ trong gân trên cơ ngửa dài, cơ cánh tay trước và khớp khủy.\nThần kinh vận động cơ là các nhánh của thần kinh cơ – da và thần kinh quay.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh C6."}]},{"id":1042,"ten":"Xuất Khí Huyệt","sections":[{"h":"VỊ TRÍ","body":"Xác định huyệt Nhiên Cốc (Th.2) rồi đo lui ra sau 0,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị ung thư thực đạo thời kỳ cuối làm no hơi ở trường vị."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,5 – 1 thốn."}]},{"id":1043,"ten":"Xung Dương","sections":[{"h":"VỊ TRÍ","body":"Nơi cao nhất của mu bàn chân, có động mạch đập, trên huyệt Nội Đình 5 thốn, nằm giữa huyệt Nội Đình và Giải Khê, bờ trong gân cơ duỗi ngón thứ 2 và cơ duỗi ngắn ngón cái."},{"h":"CHỦ TRỊ","body":"Trị mu bàn chân đau, liệt chi dưới, răng đau, lợi răng viêm, bệnh tâm thần."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 0,3 – 0,5 thốn, Ôn cứu 3 – 5 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là bờ trong gân cơ duỗi ngón 2 của cơ duỗi chung các ngón chân, cơ duỗi ngắn ngón cái, sau khớp chêm – thuyền.\nThần kinh vận động cơ là các nhánh của dây thần kinh chày trước.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L5."}]},{"id":1044,"ten":"Xung Môn","sections":[{"h":"VỊ TRÍ","body":"Ở ngoài động mạch đùi, trên khớp xương mu (huyệt Khúc Cốt – Nh.2), cách đường giữa bụng ngang ra 3,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị dịch hoàn viêm, đau do thoát vị, màng tử cung viêm, tiểu bí."},{"h":"CHÂM CỨU","body":"Châm thẳng 1 – 1,5 thốn. Cứu 3 – 5 tráng, Ôn cứu 10 – 20 phút."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là bờ ngoài bó mạch thần kinh đùi, khe giữa cơ chậu và cơ lược, cơ bịt ngoài, cơ sinh đôi dưới.\nThần kinh vận động cơ là các ngành ngang của đám rối thắt lưng, nhánh của dây thần kinh cơ – da. Các nhánh của dây thần kinh bịt.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L1.\nChâm đắc khí có cảm giác căng tức bụng dưới hoặc tê lan tới bộ phận sinh dục."}]},{"id":1045,"ten":"Y Hy","sections":[{"h":"VỊ TRÍ","body":"Dưới gai sống lưng 6, đo ngang 3 thốn, cách huyệt Đốc Du 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị màng tim viêm, suyễn, thần kinh liên sườn đau, nấc cụt, nôn mửa, chóng mặt."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 0,8 thốn. Cứu 3 – 5 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ thang, cơ lưng to, cơ trám, cơ chậu – sườn – ngực, cơ gian sườn 6, vào trong là phổi.\nThần kinh vận động cơ là các nhánh của dây thần kinh sọ não số XI, nhánh đám rối cổ sâu, nhánh đám rối cánh tay, nhánh dây sườn 6 và nhánh dây sống lưng 6.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh cung hư hàn, trọc khí ngưng trệ, hạ tiêu Xung mạch, Nhâm mạch tức là tử cung không được dinh dưỡng cho nên vật tanh hôi luôn đi xuống: lấy Bổ Cung Hoàn, Giao Ngải Thang làm chủ trị. Trường hợp nặng, cứu Bào Môn + Tử Hộ, mỗi huyệt 30 tráng, không những khỏi bệnh mà còn có nhiều con” (Biển Thước Tâm Thư)"}]},{"id":1046,"ten":"Y Lung","sections":[{"h":"VỊ TRÍ","body":"Xác định huyệt Ế Phong (Ttr.17) xong đo lên 0,5 thốn, huyệt ở chỗ lõm."},{"h":"CHỦ TRỊ","body":"Trị tai ù, điếc, câm điếc."},{"h":"CHÂM CỨU","body":"Châm xiên, hơi hướng xuống dưới tới trước sâu 1,5 – 2 thốn."}]},{"id":1047,"ten":"Ý Xá","sections":[{"h":"VỊ TRÍ","body":"Dưới gai sống lưng 11, đo ngang ra 3 thốn, cách huyệt Tỳ Du 1,5 thốn."},{"h":"CHỦ TRỊ","body":"Trị bệnh về gan mật, dạ dày đau, khó tiêu, nôn mửa, lưng đau."},{"h":"CHÂM CỨU","body":"Châm xiên 0,5 – 0,8 thốn. Cứu 5 – 7 tráng. Ôn cứu 10 – 20 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cơ lưng to, cơ răng cưa bé sau – dưới, cơ chậu sườn – ngực, cơ gian sườn 11, Thận.\nThần kinh vận động cơ là nhánh của đám rối cánh tay, nhánh của dây gian sườn 11.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D10."}]},{"id":1048,"ten":"Yến Khẩu","sections":[{"h":"VỊ TRÍ","body":"Ở 2 bên khoé miệng, huyệt nằm giữa nơi tiếp giáp thịt đỏ và trắng của khoé miệng."},{"h":"CHỦ TRỊ","body":"Trị liệt mặt, thần kinh sinh ba đau, trẻ nhỏ bị động kinh, tiểu bí, táo bón."},{"h":"CHÂM CỨU","body":"Châm xiên sâu 0,5 – 1 thốn.R\nM"}]},{"id":1049,"ten":"Yêu Căn","sections":[{"h":"VỊ TRÍ","body":"Gai xương cùng thứ 1 đo ra 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị bệnh ở khớp cùng chậu, bệnh ở chi dưới."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 3 thốn."}]},{"id":1050,"ten":"Yêu Du","sections":[{"h":"VỊ TRÍ","body":"Tại chỗ lõm dưới mỏm gai đốt sống cùng 4 hoặc ở chính giữa đường nối 2 lỗ cùng 4."},{"h":"CHỦ TRỊ","body":"Trị vùng xương cùng đau, lưng đau, cột sống đau, tiểu đục, kinh nguyệt không đều."},{"h":"CHÂM CỨU","body":"Châm luồn kim vào ống xương cùng, sâu 0,5 – 0,8 thốn, hướng mũi kim chếch lên trên. Cứu 15 – 40 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân ngực – thắt lưng của cơ lưng to, cân của khối cơ chung ở rãnh cột sống, dây chằng cùng – cụt và mỏm gai đốt sống cùng cụt.\nThần kinh vận động cơ là các nhánh thần kinh sống.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh S5."}]},{"id":1051,"ten":"Yêu Dương Quan","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm dưới mỏm gai đốt sống thắt lưng 4 – 5, ngang với mào chậu."},{"h":"CHỦ TRỊ","body":"Trị vùng thắt lưng cùng đau nhức, liệt chi dưới, kinh nguyệt không đều, di tinh, liệt dương, ruột viêm mạn, hông sườn đau, thần kinh hông đau."},{"h":"CHÂM CỨU","body":"Châm kim chếch lên, luồn dưới mỏm gai, hướng về khoảng gian đốt thắt lưng 4 – 5, sâu 0,3 – 1,5 thốn. Cứu 10 – 20 phút."},{"h":"GIẢI PHẪU","body":"Dưới da là cân ngực – thắt lưng của cơ lưng to, chỗ bám của cân khối cơ chung rãnh cột sống, cơ ngang – gai, dây chằng trên gai, dây chằng gian gai, dây chằng vàng, ống sống.\nThần kinh vận động cơ là các nhánh dây thần kinh sống lưng.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh D12.\nChâm Đắc khí, có cảm giác tê căng lan tới trước cánh tay hoặc lên tới khuỷu tay."}]},{"id":1052,"ten":"Yêu Kỳ","sections":[{"h":"VỊ TRÍ","body":"Dưới gai đốt sống cùng thứ 2."},{"h":"CHỦ TRỊ","body":"Trị động kinh."},{"h":"CHÂM CỨU","body":"Châm xiên lên sâu 2 – 2,5 thốn."}]},{"id":1053,"ten":"Yêu Mục","sections":[{"h":"VỊ TRÍ","body":"Huyệt Thận Du (Bq.23) xuống 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị tiêu khát, tiểu nhiều."},{"h":"CHÂM CỨU","body":"Cứu 3 – 7 tráng. Ôn cứu 5 – 15 phút."}]},{"id":1054,"ten":"Yêu Nghi","sections":[{"h":"VỊ TRÍ","body":"Gai xương thắt lưng thứ 4 đo ra 3 thốn."},{"h":"CHỦ TRỊ","body":"Trị tổn thương tổ chức mềm vùng thắt lưng, bệnh phụ khoa."},{"h":"CHÂM CỨU","body":"Châm thẳng sâu 1 – 2 thốn."}]},{"id":1055,"ten":"Yêu Nhãn","sections":[{"h":"VỊ TRÍ","body":"Nằm sấp thẳng 2 chân, bảo người bệnh thẳng cao 2 tay hơi nghiêng mình đi 1 ít sẽ có chỗ lõm ở 2 bên thắt lưng, ngang với chỗ lõm ở đốt sống thắt lưng thứ 4.\nHuyệt ở dưới đốt sống lưng 16 đo ra 3,8 thốn. (Có sách lấy trên gai đốt sống xương thắt lưng thứ 3 đo ra 3 – 4 thốn, ở chỗ lõm)"},{"h":"CHỦ TRỊ","body":"Trị tổn thương tổ chức mềm vùng thắt lưng, thận sa, dịch hoàn viêm, bệnh phụ khoa."},{"h":"CHÂM CỨU","body":"Châm thẳng hoặc ngang sâu 1,5 – 2,5 thốn. Cứu 5 – 7 tráng. Ôn cứu 5 – 15 phút."},{"h":"GIẢI PHẪU","body":"Dưới huyệt là bản gân cơ lưng to, cơ lưng dài, cơ ngang gai, cơ gian mỏm ngang, cơ vuông thắt lưng, cơ đái – chậu.\nThần kinh vận động cơ do nhánh của đám rối cánh tay, dây sống lưng 3 và nhánh của đám rối thắt lưng.\nDa vùng huyệt chi phối bởi tiết đoạn thần kinh L4.I\nSQrd2Trị chứng tỳ hoành: tay chân bị nóng lạnh, lưng đau không cúi ngửa được, bụng đầy, nôn mửa, cơ thể vàng, lưỡi cứng, cứu tại đốt sống lưng thứ 11 ra 2 bên phải trái mỗi bên 1,5 thốn, cứu mỗi huyệt 7 tráng” (Thiên Kim Phương)"}]},{"id":1056,"ten":"Yêu Thống","sections":[{"h":"VỊ TRÍ","body":"Ở lưng bàn tay nơi giao tiếp của xương bàn tay 2 và 3."},{"h":"CHỦ TRỊ","body":"Trị bệnh ở đầu, chấn thương ở tứ chi và vùng thắt lưng."},{"h":"CHÂM CỨU","body":"Châm xiên tới phía khớp cổ tay, sâu 1 – 1,5 thốn."}]},{"id":1057,"ten":"Yêu Thống II","sections":[{"h":"VỊ TRÍ","body":"Ở lưng bàn tay nơi giao tiếp của xương bàn tay 3 và 4."},{"h":"CHỦ TRỊ","body":"Trị chấn thương ở tứ chi, vùng ngực."},{"h":"CHÂM CỨU","body":"Châm xiên tới phía khớp cổ tay, sâu 1 – 1,5 thốn."}]},{"id":1058,"ten":"Yêu Thống III","sections":[{"h":"VỊ TRÍ","body":"Ở lưng bàn tay, nơi giao tiếp của xương bàn tay 4 và 5."},{"h":"CHỦ TRỊ","body":"Trị chấn thương ở tứ chi, vùng thắt lưng."},{"h":"CHÂM CỨU","body":"Châm xiên tới phía khớp cổ tay, sâu 1 – 1,5 thốn."}]},{"id":1059,"ten":"Tất Dương Quan","sections":[{"h":"VỊ TRÍ","body":"Chỗ lõm phía trên – ngoài đầu gối, nơi khe giữa mỏm trên lồi cầu ngoài xương đùi và gân cơ nhị đầu đùi; trên huyệt Dương Lăng Tuyền (Đ 34) khoảng 3 thốn. Dễ xác định khi gập gối."},{"h":"CHỦ TRỊ","body":"Trị khớp gối sưng đau, gân cơ vùng gối co rút, đau thần kinh toạ, chi dưới tê bại."},{"h":"CHÂM CỨU","body":"Châm thẳng, sâu 0,8 – 1 thốn. Cứu 3 – 5 tráng, ôn cứu 5 – 10 phút."}]}]};
